\title{The role of dimensionality in the magnetic properties of CeIn$_3$ nanowires}


\author{M. H. Carvalho,$^{1,2}$, D. Zau$^1$, A. P. Reyes{$^{3}$}, R. Cong{$^{3}$}, S. D. House{$^{4}$}, H. P. Pizzi{$^{1}$}, J. Thompson{$^{2}$}, A. M. Caffer{$^{1}$}, D.S. Passos{$^{1}$}, R. C. Santos{$^{1}$}, G. S. Freitas{$^{2}$}, K. R. Pirota{$^{1}$}, R. R. Urbano{$^{1}$}, P. J. G. Pagliuso$^{1,2}$}



