\begin{defn}
    The \textbf{naive filtered smash product} is defined by 
\begin{equation}(X \Smash Y)(r):= X( r)\Smash Y(r) \end{equation}
On morphisms, it is given simply by the levelwise smash product for morphisms.
\end{defn}

Note that this is simply the quotient of the naive product by the naive wedge;  $(X \Smash Y)(r)=(X\times Y)(r)/(X \vee Y)(r) $. 
\begin{defn}
    We define the \textbf{filtered smash product} $\bar{\Smash}$ by:

    \begin{equation}
        (X \bar{\Smash}Y)(r):= (X \bar{\times} Y)(r)/X \vee Y= \bigcup_{s+t=r} X(s) \Smash Y(t).
    \end{equation}
\end{defn}
On morphisms, we take the product of morphisms $f\bar{\times}f'$, then look to the induced map on the quotient space.
\begin{prop}
    The filtered smash product commutes with shifting:
   \begin{equation}
       \ss^a(X \bar{\Smash}Y) = \ss^aX \bar{\Smash}Y = X \bar{\Smash} \ss^a Y.
   \end{equation} 
   \begin{proof}
       This is a simple calculation:
       \begin{align*}
           (X\bar{\Smash} \ss^aY)(r)=& \bigcup_{s+t=r}X(s) \Smash \ss^aY(t)\\
           =& \bigcup_{s+t=r}X(s) \Smash Y(t-a)\\
           =& \bigcup_{s} X(s) \Smash Y((r-a)-s)\\
           =& \bigcup_{s+t=r-a}X(s) \Smash Y(t)\\
           =& (X\bar{\Smash}Y)(r-a)\\
           =& \ss^{a}(X\bar{\Smash}Y)(r)
       \end{align*}
       And similarly it is easy to verify $\ss^a (X \bar{\Smash}Y)= \ss^a X \bar{\Smash}Y$.
   \end{proof}
\end{prop}


The properties of these smash products will soon be explored more, and will be key to proving Theorem \ref{Mainiso}.


\subsection{Homotopy}

Given a filtered space $X$ we define its \textbf{filtered cylinder} to be the filtered space with
\begin{equation}\text{Cyl}(X)(r):= \text{Cyl}\big(X(r)\big)\end{equation}
Note this can be viewed as $X \times I$ where $I$ has the \textbf{trivial filtration}:
\begin{equation*}
    I(r):=
        [0,1]\hspace{8pt} \forall r\in \R.
\end{equation*}

We similarly define the \textbf{reduced filtered cylinder} by
\begin{equation}\text{Cyl}_*(X)(r):= \text{Cyl}_*\big(X(r)\big).\end{equation}

This can be viewed as $X \Smash I_+ $ with $I_+$ having the trivial filtration (where the subscript denotes adjoining of a disjoint basepoint).


\begin{defn}
Let $f,g:X \to Y$ be morphisms with shift $\lceil f \rceil = \lceil g \rceil = a$, we define a \textbf{ homotopy} from $f$ to $g$, to be a map 
\begin{equation}h:\text{Cyl}_*(X) \to Y\end{equation}

such that 
\begin{equation}\begin{tikzcd} X \arrow[r,"i_0"]\arrow[dr,swap,"f"]& \text{Cyl}_*(X) \arrow[d,"h"]& X\arrow[l,swap,"i_1"]\arrow[dl,"g"]\\
& Y &\end{tikzcd}\end{equation}
commutes, where $i_0,i_1$ are the obvious inclusion maps of shift zero. In particular $\lceil h \rceil = a$.

\end{defn}


\begin{rmk}
This defines an equivalence relation, $\sim_a$, on $\text{Hom}(X,Y)(a)$, we denote 
\begin{equation}[X,Y](a):=\text{Hom}(X,Y)(a)/\sim_a\end{equation}
\end{rmk}


\begin{defn}
    We call two filtered spaces $X$ and $X'$ \textbf{$r$-filtered homotopy equivalent}, if there exist maps $f:X \to X'$ and $g:X' \to X$ with $\lceil f\rceil=r=-\lceil g \rceil$ such that $f\circ g \sim 1_{X'}$ and $g \circ f \sim 1_X$. Note that we will sometimes refer to a $0$-homotopy equivalence simply as a homotopy equivalence or filtered homotopy equivalence.
\end{defn}


Consider the $k$-sphere with filtration concentrated at $0\in \R$ so that 
\begin{equation}
    S^k(r):=\begin{cases}
        S^k & r\geq 0\\
        * & r<0
    \end{cases}
\end{equation}
We will call this the \textbf{zero filtration on $S^k$}. We define the \textbf{$k$-th filtered homotopy group} of a filtered space $X$ to be 
\begin{equation}\pi_k^r(X):=[S^k,X](r)\end{equation}


\begin{rmk}
By the definition of filtration $(S^k)( r)$, it can easily be verified that 
\begin{equation*}\pi_k^r(X)=[S^k,X](r)=\pi_k(X(r)).\end{equation*}
Indeed, $[S^k,X](r)$ are homotopy classes of maps from $S^k$ to $X$ with shift $r$. Such maps are given by families

\begin{equation*}
    \begin{tikzcd}
        S^k(b)\ar[r,"f(b)"] & X(b+r)\\
        S^k(a)\ar[u,"i_{a,b}^{S^k}"] \ar[r,"f(a)"]& X(a+r)\ar[u,swap,"i_{a+r,b+r}^X"]
    \end{tikzcd}
\end{equation*}
For all $0\leq a\leq b$ we have $i_{a,b}^{S^k}=1_{S^k}$, hence such a map $f$ is given by
\begin{equation*}
    \begin{tikzcd}
        & X(b+r)\\
        S^k\ar[r,swap,"f(a)"]\ar[ur,"f(b)"]& X(a+r)\ar[u,swap,"i_{a+r,b+r}^X"]
    \end{tikzcd}
\end{equation*}
Since $i_{a,b}^X$ are inclusions we have $\text{Im}(f(a))=\text{Im}(f(b))$ inside of the total space $X$. A homotopy (in the filtered setting) from such an $f$ to some $f'$ (with $f'$ also of shift $r$) is a map $h:\text{Cyl}_*(S^k) \to X $, which explicitly is a family of maps

\begin{equation*}
  \begin{tikzcd}  \text{Cyl}_*(S^k)(b)\ar[r,"h(b)"] & X(b+r)\\
    \text{Cyl}_*(S^k)(a)\ar[u,"i_{a,b}^{\text{Cyl}_*(S^k)}"]\ar[r,"h(a)"] & X(a+r)\ar[u,"i_{a+r,b+r}^X"]
    \end{tikzcd}
\end{equation*}
Again, when $0\leq a\leq b$ we realise that $i_{a,b}^{\text{Cyl}_*(S^k)}=1_{\text{Cyl}_*(S^k)}$. Which implies the following
\begin{equation*}
  \begin{tikzcd}  
  & X(b+r)\\
    \text{Cyl}_*(S^k)\ar[ur,"h(b)"]\ar[r,"h(a)"] & X(a+r)\ar[u,swap,"i_{a+r,b+r}^X"]
    \end{tikzcd}
\end{equation*}
and hence $\text{Im}(h(a))=\text{Im}(h(b))$ inside of the total space $X$. Putting this all together, we see that two (filtered) morphisms $f,f':S^k \to X$ are homotopic iff there is a homotopy between the limiting maps $\lim_a f(a): S^k \to X(\infty)=X$ and $\lim_a f'(a):S^k \to X(\infty)=X$ given by $\lim_a h(a)$.
\end{rmk}


We will want to work with filtrations that are suitably `nice', we therefore restrict our attention to pairs $(X,\ff_X)$ where the filtration $\ff_X$ has the additional property that:
\begin{itemize} \label{assump}
    \item For all $k\in \N$, there exist countably many $r\in \R$ such that for any $\epsilon>0$ we have  $\pi_k^r(X) \neq \pi_k^{r-\epsilon}(X)$.
\end{itemize}

This property tells us that the homotopy type of the filtered space can only change at countably many points. We refer to these points as \textbf{spectral points} of the filtration and denote the set of spectral points of a filtered space by $\text{Spec}(X)$. From now on we will assume our filtered spaces to have this additional property and refer to $\ff \text{Top}_*$ as the category consisting of objects with this additional assumption.





\begin{defn}
We denote the \textbf{suspension} of a filtered space $X$ to be $\S X$, defined by
\begin{equation}\S X(r):= \S \big(X(r)\big)\end{equation}
This can be seen to be given by $\S X= S^1 \Smash X$ with $S^1$ having trivial filtration.
\end{defn}
Note that suspension of the trivially filtered $k$-sphere $S^k$, gives the trivially filtered $(k+1)$-sphere, $S^{k+1}$. Similarly, suspension of a $k$-sphere with zero filtration will give the $(k+1)$-sphere with zero filtration (after identifying $\S * \simeq *$). 
\begin{rmk}
    Given a general filtered space $X$, we may define a corresponding \textbf{cut off} filtered space  $\text{Cut}_a(X)$, given by
    \begin{equation}
     \text{Cut}_a(X)(r):=   \begin{cases}
            X(r) & r\geq a\\
            * & r<a
        \end{cases}
    \end{equation}
    The zero filtration on any given space can thus be thought of as the cut off at $a=0$ of the trivial filtration. 
\end{rmk}

\begin{prop}
    Denote by $S^1_0$, the zero filtered $1$-sphere, and by $S^1_\infty$ the trivially filtered sphere, let $X$ be any filtered space, then 
    \begin{equation}
        S_\infty^1 \Smash X \simeq S^1_0 \bar{\Smash} X. 
    \end{equation}
are zero homotopy equivalent.
\begin{proof}
    Notice that we have the following
    \begin{align*}
     (S^1_0 \bar{\times} X)(r) =& \bigcup_{t}S^1(t)\times X(r-t)\\
     =&
         S^1 \times X(r) \cup * \times X
    \end{align*}
    Indeed, when $t<0$, $S^1_0(t)=*$. Thus 
    \begin{equation*}
        (S^1_0\bar{\Smash}X)(r)=S^1 \times X(r) \cup * \times X/(S^1 \vee X)
    \end{equation*}
    But this is clearly equivalent to $S^1 \times X(r)/S^1 \vee X(r)= S^1\Smash X(r)$.
\end{proof}
\end{prop}
Thus, we can think of suspension in terms of either $\Smash$ or $\bar{\Smash}$. A similar statement holds for higher spheres.

