\subsection{Filtered CW-complexes and weighted Euler characteristic}
In order to construct homotopical notions in the filtered setting we need to understand what a filtered CW complex should be and what filtered weak homotopy equivalences are. 

\begin{defn}
A \textbf{filtered CW complex} is a filtered space $X$ such that the levelsets are all sub-CW-complexes and the inclusion maps are cellular inclusions. A morphism of filtered CW complex is a morphism of filtered topological spaces such that each level is cellular.
\end{defn}

\begin{rmk}
    We refer to the cells in the subcomplex $X_0$ of some filtered CW complex as \textbf{eternal cells}, and the subcomplex itself as the \textbf{eternal subcomplex}. This is because the cells are never created, they exist for all $X(r)$.  One can think of a filtered CW complex $X$ to be filtered relative to the eternal subcomplex. 
\end{rmk}

\begin{lemma}[Filtered CW approximation]\label{CWspacefilt}
Given any filtered space $X\in \ff \text{Top}_*$, there exists a filtered CW space $\bar{X}$ and a map $f: \bar{X} \to X$ of shift zero, such that $f(r): \bar{X}( r) \to X(r)$ is a weak equivalence for all $r$, and moreover the following homotopy commutes for all $r \leq s$
\begin{equation}
    \begin{tikzcd}
        \bar{X}(s)\ar[r,"f(s)"] & X(s)\\
        \bar{X}(r)\ar[r,"f(r)"]\ar[u,"i_{r,s}^{\bar{X}}"] & X(r).\ar[u,"i^X_{r,s}"]
    \end{tikzcd}
\end{equation}

\end{lemma}

The proof of this lemma relies on the following known result (see \cite{Ma1} Chapter 10, section 6):

\begin{lemma}
    Given a pair $(X,A)$ and a CW approximation of $A$, $\bar{A}\xrightarrow{\alpha_A} A$, then there exists a CW approximation of $X$, $\bar{X}\xrightarrow{\alpha_X} X$ such that $\bar{A}$ is a subcomplex of $\bar{X}$ and $\alpha_X$ restricts to $\alpha_A$ on $\bar{A}$.
\end{lemma}

\begin{proof}[Proof of Lemma \ref{CWspace}]
We will build such an $\bar{X}$, as follows: Firstly, we may assume by the assumption \ref{assump} that $\text{Spec}(\ff_X)=\{r_i:i\in \N\}$. Set $r_0:=\lfloor X \rfloor >-\infty$ such that $X(r)=X_0$ for all $r<r_0
$. Chose some $\bar{X}(r):=\overline{X_0}$ for all $r<r_0$. We now apply the above lemma to the pair $(X(r_0),X(r))$ for all $r<r_0$, to obtain a homotopy commutative diagram
\begin{equation*}
    \begin{tikzcd}
        \bar{X}(r_0)\ar[r,"\alpha(r_0)"] & X(r_0)\\
       \bar{X}(r)=\overline{X_0}\ar[r,"\alpha(r)"]\ar[u,"i_{r,r_0}^{\bar{X}}"] & X(r)\ar[u,swap,"i^X_{r,r_0}"]
    \end{tikzcd}
\end{equation*}

We then set the approximations $(\bar{X}(r)\xrightarrow{\alpha(r)} X(r)):=(\bar{X}(r_0) \xrightarrow{\alpha(r_0)} X(r_0))$ for all $r\in [r_0,r_1)$, and take $i_{r,s}^{\bar{X}}$ to be the identity for all $r,s\in [r_0,r_1)$. Next we apply the above lemma iteratively over each $r_i\in \text{Spec}(\ff_x)$, to obtain diagrams

\begin{equation*}
    \begin{tikzcd}
       \bar{X}(r_{i+1}) \ar[r,"\alpha(r_{i+1})"]&X(r_{i+1}) \\
        \bar{X}(r)\ar[r,"\alpha(r_{i-1})"]\ar[u,"i_{r,r_{i+1}}^{\bar{X}}"]& X(r)\ar[u,swap,"i_{r,r_{i+1}}^X"] 
    \end{tikzcd}
\end{equation*}

with $r\in [r_i,r_{i+1})$ and approximations $(\bar{X}(r)\xrightarrow{\alpha(r)} X(r))=(\bar{X}(r_{i})\xrightarrow{\alpha(r_i)} X(r_i))$. Setting $i_{r,s}^{\bar{X}}$ to be the identity for all $r<s\in [r_{i+1},r_{i+2})$. Finally assume $r<s \in \R$ with $r\in [r_i,r_{i+1})$ and $s\in [r_j,r_{j+1})$, we set 
\begin{equation*}
    i_{r,s}^{\bar{X}}:=i_{r_{j-1},r_{j}}^{\bar{X}}\circ \hdots \circ i_{r_{i+1},r_{i+2}}^{\bar{X}}\circ i_{r,r_{i+1}}^{\bar{X}}
\end{equation*}
Thus, $(\bar{X},\bar{\ff})$ is the desired filtered CW complex.
\end{proof}

\begin{rmk}
The filtered CW complex formed is not unique, but is unique up to filtered homotopy equivalence.
\end{rmk}
\begin{defn}
To every cell of the filtered CW complex $a\subset X$ we can associate a \textbf{cell size} $w(a)\in \text{Spec}(\ff) \cup \{-\infty\}$ given 
    \begin{equation}
        w(a)=\inf\{r_i: a \subset X(r_i)\}
    \end{equation}
    where $w(a)=-\infty$ if $a$ is an eternal cell.
\end{defn}




\begin{rmk}
    Given two filtered CW complexes $X$ and $Y$ the product $X\bar{\times}Y$ is a filtered CW complex with one $k$-cell $c=a\times b$ for every $l$-cell, $a$, and $m$-cell, $b$, in $X$ and $Y$ respectively, such that $l+m=k$. Furthermore, the induced filtration is such that $X \bar{\times} Y(r)$ consists of all cells $a \times b$ such that 
    \begin{equation}
        w(a\times b)= w(a) + w(b) \leq r.
    \end{equation}
\end{rmk}

\begin{prop}
    The smash product $\bar{\Smash}$ on filtered CW-complexes is distributive over the wedge:
    \begin{equation}
        A \bar{\Smash}(X \vee Y) = (A \bar{\Smash} X )\vee (A \bar{\Smash} Y)
    \end{equation}
    Indeed on the total space we know the usual smash product of spaces is distributive over usual wedge product. Thus, we just need to check that the filtrations are equivalent, but this is clear. A cell $c$ in $A \bar{\Smash}(X \vee Y)$ is either a cell of the form $a \Smash x$ or $a \Smash y$ for some cells $a \subset A$, $x\subset X$ and $y\subset Y$. We may assume it to be of the form $a \Smash x$. The weight of this cell is thus given by $w(a \Smash x)= w(a \times x)=w(a)+w(b)$. Note that if $a$ or $x$ is eternal, then we treat $-\infty +k=-\infty$, i.e., $a \times x$ is eternal. The filtration on $(A \bar{\Smash}X) \vee (A \bar{\Smash}Y)$ is such that a cell belonging to the component of $A \bar{\Smash}X$ will have weight $w(a \bar{\Smash}x)=w(a \times x)=w(a)+w(x)$. Thus the filtrations on the two (total) CW complexes agree.
\end{prop}



\begin{rmk}\label{sizeofsmashmorphism}
    If $f: X \to Y$ and $f':X' \to Y'$ are morphisms of filtered CW complexes, then 
    \begin{align*}
        w\big( (f\bar{\Smash} f')(a \bar{\Smash}b)\big) = w(a)+\lceil f\rceil + w(b) + \lceil f' \rceil= w(a\times b) + \lceil f \rceil + \lceil f' \rceil 
    \end{align*}
    Thus $\lceil f \bar{\Smash}f'\rceil = \lceil f \rceil + \lceil f' \rceil$.
\end{rmk}





\begin{defn}
   Given a filtered CW complex $\bar{X}$, its \textbf{size polynomial} is given by
    \begin{equation}
       \lambda( \bar{X})_{\text{CW}}:=\sum_{a\in \text{Cells}_*(X)} t^{w(a)} 
    \end{equation}
 Where $\text{Cells}_*(X)$ denotes the cells of $X$ without including the basepoint $*$. 
Furthermore, we consider the derivative 

\begin{equation}
  \Lambda_{\text{CW}}(\bar{X}):=  \frac{d}{dt}\big(\lambda_{\text{CW}}(\bar{X})\big)=\sum_{a\in \text{Cells}_*(\bar{X})}w(a) \cdot t^{w(a)-1}
\end{equation}

\end{defn}

\begin{rmk}
    If $a\in \text{Cells}_*(X)$ is such that $w(a)=-\infty$, i.e., $a\in X(r)$ for all $r\in \R$, then we set $t^{-\infty}=0$, i.e., do not include this cell in the count. 
\end{rmk}


Evaluation at $t=1$ of the size polynomial gives the number of cells in $\bar{X}$ (excluding the basepoint), which we denote by 
 \begin{equation}
|\bar{X}|_0=\text{ev}_{t=1}\big(\lambda_{\text{CW}}(X)\big)
 \end{equation}
 and evaluation at $t=1$ of its derivative gives the weighted count of cells denoted by:

\begin{equation}
|\bar{X}|=\text{ev}_{t=1}\big(\Lambda_{\text{CW}}(X)\big).
\end{equation}

For a general filtered space $X$ we define
    \begin{align}
        |X|_0&:=\inf\{|\bar{X}|_0:\bar{X} \text{ is a filtered CW approximation of } X\}\\
        |X|&:=\inf\{|\bar{X}|:\bar{X} \text{ is a filtered CW approximation of } X\}.
    \end{align}

\begin{eg}
    Take $S^k$ to be the filtered $k$-sphere with filtration given by
    \begin{equation*}
        S^k(r)=\begin{cases}
            * & r<t\\
            S^k & r\geq t
        \end{cases}
    \end{equation*}
    then $|S^k|_0=1$ and  $|S^k|=t$ as we can view $S^k$ as the CW complex with a zero-cell (the basepoint) and one $k$-cell which attaches at level $t$. 
\end{eg}




