The size polynomial and, in turn, its derivative depend on the `filtered cell decomposition'. We will see, however, that there is a weighted version of the Euler characteristic that is a filtered homotopy invariant. Note that a similar object has been studied previously by various authors (for example see \cite{DG} and \cite{HL}).



\begin{defn}
    Given a filtered CW complex, we define its \textbf{Euler polynomial} as 

    \begin{equation}
        \hat{\chi}_{\text{CW}}(X)= \sum_{a\in \text{Cells}_*(X)} (-1)^{|a|}\cdot t^{w(a)}
    \end{equation}
    where $t$ is some formal variable and $|c|$ denotes the dimension of the cell $c$. 
\end{defn}

\begin{rmk}
    Again, we treat cells $a\in \text{Cells}_*(X)$ with $w(a)=-\infty$ to contribute $t^{-\infty}=0$ to this count. We can think of this as a Euler characteristic relative to the `eternal' cells of the filtered complex. 
\end{rmk}
\begin{rmk}
    Evaluation of $\hat{\chi}_{\text{CW}}(X)$ at $t=1$ is precisely the Euler characteristic of (the total space) $X$, minus $1$, as we do not include the basepoint:
    \begin{equation}\text{ev}_{t=1}\big( \hat{\chi}_{\text{CW}}(X)\big)=\chi(X)-1
    \end{equation}
    Note that this is often referred to as the reduced Euler characteristic. Moreover, if we set \begin{equation}
 \hat{\chi}_{\text{CW}}^{\leq r}(X):=\sum_{a\in \text{Cells}_*(X)\text{ with } w(a) \leq r}(-1)^{|a|}\cdot t^{w(a)}
    \end{equation}
    then $\hat{\chi}_{\text{CW}}^{\leq r}(X)$ evaluated at $t=1$ recovers $\chi(X(r))-1$.
\end{rmk}
\begin{prop}\label{propeul}
    If $X\simeq X'$ are two filtered CW complexes, then $\chi^{\leq r}_{\text{CW}}(X)=\chi^{\leq r}_{\text{CW}}(X')$.
    \begin{proof}
        By assumption, the homotopy type of filtration levels can only change at finitely many points, and if $X\simeq X'$, then $\text{Spec}(X)=\text{Spec(X')}$. Furthermore, for each $s\in \R$ we have $X(r)\simeq X'(r)$, hence 
        \begin{equation*}
   \text{ev}_{t=1}\big(\hat{\chi}^{\leq r}_{\text{CW}}(X)\big)=\chi(X(r))-1=\chi(X'(r))-1=\big(  \text{ev}_{t=1}\hat{\chi}^{\leq r}_{\text{CW}}(X)\big).
        \end{equation*}
        Set $D^{\leq r}(X,X'):=\hat{\chi}^{\leq r}_{\text{CW}}(X)-\hat{\chi}^{\leq r}_{\text{CW}}(X')$, then $\text{ev}_{t=1}D^{\leq r}(X,X')=0$. If we assume that $D^{\leq r}(X,X')\neq 0$, then there must exist some $\pm c \cdot  t^s$ term (for $s\leq r$). But this would imply that $\text{ev}_{t=1}\hat{\chi}^{\leq s}_{\text{CW}}(X) \neq \text{ev}_{t=1}\hat{\chi}^{\leq s}_{\text{CW}}(X')$, i.e., $\chi(X(s)) \neq \chi(X'(s))$ and thus $X(s)$ is not homotopy equivalent to $ X'(s)$, which gives a contradiction.
    \end{proof}
\end{prop}

\begin{rmk}
    By taking an $r$ large enough we find $\hat{\chi}_\text{CW}(X)= \hat{\chi}_\text{CW}(X')$ for $X \simeq X'$.
\end{rmk}
We can take the derivative of $\hat{\chi}^{\leq r}_\text{CW}$, to form the \textbf{weighted Euler polynomial} giving 
\begin{equation}
   \hat{\mathcal{W}}^{\leq r}_{\text{CW}}(X):= \frac{d}{dt}\big( \hat{\chi}^{\leq r}_\text{CW}(X)\big)= \sum_{a \in \text{Cells}_*(X) \text{ with } w(a)\leq r}(-1)^{|a|}\cdot w(a) \cdot t^{w(a)-1}
\end{equation}
by proposition \ref{propeul}, $\hat{\mathcal{W}}_\text{CW}^{\leq r}$  is an invariant of the filtered homotopy type of $X$. Furthermore, the value

\begin{equation}
    \mathcal{W}^{\leq r}(X):=\text{ev}_{t=1} \mathcal{W}_\text{CW}^{\leq r}(X) =\sum_{a \in \text{Cells}_*(X) \text{ with } w(a)\leq r} (-1)^{|a|}\cdot w(a)
\end{equation}

is a filtered homotopy invariant for all $r\in \R$. By taking an $r$ large enough, we obtain $\mathcal{W}(X)$ that we will refer to as the \textbf{weighted Euler characteristic} of $X$. 



\begin{eg}
    Consider the filtered torus with height function as described in example \ref{torus example}. Then we find 
    \begin{equation*}
        \hat{\mathcal{W}}_\text{CW}(T)= -at^{a-1}-bt^{b-1}+ct^{c-1}
    \end{equation*}
\begin{equation*}
      \mathcal{W}(T)= c-(a+b)
\end{equation*}
\end{eg}



\begin{defn}
    Given two filtered CW-complexes with homotopy equivalent total space, we define their \textbf{matching number} as follows: First we consider $\hat{\chi}_{\text{CW}}(X)+\hat{\chi}_{\text{CW}}(X')$, then we take mod-$2$, to obtain some polynomial equivalent to something of the form $\sum_i t^{r_i}$, i.e., make every coefficient $+1$ .We then evaluate this polynomial over $\Z$ at $t=1$, and divide by two. I.e.
    \begin{equation}
        \text{Match}(X_,X'):=\frac{1}{2}\text{ev}^\Z_{t=1}\big(\hat{\chi}_{\text{CW}}(X)- \hat{\chi}_{\text{CW}}(X')\mod 2\big)
    \end{equation}
\end{defn}


\begin{rmk}
    The matching number for two filtrations on a CW complex, say $X$ and $X'$ (with equivalent total spaces), is independent of filtered homotopy equivalence. That is, if $X\simeq \bar{X}$ and $X'\simeq \bar{X}'$, then 
    \begin{equation*}
        \text{Match}(X,X') = \text{Match}(\bar{X},\bar{X}').
    \end{equation*}
This follows from $\hat{\chi}_{\text{CW}}$ being a filtered homotopy invariant.
\end{rmk}
The matching number is calculating (half) the number of `mismatched' cells in the two filtrations of the total space. We can think of this as a function $\text{Match}:\text{Filt}_h(X) \times \text{Filt}_h(X) \to \Z$ from the set of pairs of filtration on $X$ up to filtered homotopy equivalence. Note that 
\begin{equation*}
\text{ev}^\Z_{t=1}\big(\hat{\chi}_{\text{CW}}(X)+ \hat{\chi}_{\text{CW}}(X')\mod 2\big) \in 2\Z
\end{equation*}
This can be seen from $\chi(X)=\chi(X')$ hence the difference $\hat{\chi}_\text{CW}(X)-\hat{\chi}_{\text{CW}}(X')$ must have an equal number of terms with $+1$ coefficient as $-1$ coefficient, thus an even number of terms.


\begin{lemma}
    Assume $f,f':M \to \R$ are two bounded, Morse functions on a compact manifold $M$. Set, $M_f$ and $M_{f'}$ to be (some choice of) filtered CW-complexes approximating the filtered space induced from the sub-level sets of $f$ and $f'$ respectively. If $\sup_{x\in M} |f(x)-f'(x)|< \epsilon $ then 

    \begin{equation}\frac{|\mathcal{W}(X_f)-\mathcal{W}(X_{f'})|}{\text{Match}(X_f,X_{f'})}<\epsilon
    \end{equation}


    \begin{proof}
        First note that $\chi_\text{CW}(X_f)= \chi_{\text{CW}}(X_{f'})$ as the topology of the total space does not change. Thus we have 
        \begin{equation*}
            \text{ev}_{t=1}\big(\hat{\chi}_{\text{CW}}(X_f)\big)= \text{ev}_{t=1}\big(\hat{\chi}_{\text{CW}}(X_f)\big)
        \end{equation*}
Therefore, the difference polynomial $D(X_f,X_{f'})$ evaluated at $t=1$ gives zero. Therefore, in general $D(X_f,X_{f'})$ takes the following form 

\begin{equation*}
    D(X_f,X_{f'})=\sum_{i=1,\hdots, n} t^{a_i} - t^{b_i}
\end{equation*}
Calculating its derivative we have
\begin{equation*}
    \frac{d}{dt}D(X_f,X_{f'})= \sum_{i=1\hdots, n} a_i \cdot t^{a_i-1}- b_i \cdot t^{b_i-1} 
\end{equation*}
And evalutating at $t=1$ we obtain 
\begin{equation*}
  |\mathcal{W}(X_f)-\mathcal{W}(X_{f
'})|= |\text{ev}_{t=1}\big(  \frac{d}{dt}D(X_f,X_{f'})\big)|= |\sum_{i=1\hdots, n} a_i - b_i|\leq \sum_{i=1\hdots, n}|a_i-b_i|
\end{equation*}
We can choose to order the $a_i$s and $b_i$s such that $|a_i-b_i|< \epsilon$ for every $i$. Hence we have

\begin{equation*}
     |\mathcal{W}(X_f)-\mathcal{W}(X_{f
'})|\leq \sum_{i=1\hdots, n}|a_i-b_i| \leq n\cdot \epsilon
\end{equation*}

But we realise $n$ is exactly $\text{Match}(X_f,X_{f'})$, thus we obtain the result.

    \end{proof}


\end{lemma}







\begin{prop}\label{propwedge}
    The weighted Euler polynomial is additive with respect to $\vee$: 
    \begin{align}
     \hat{\chi}_{\text{CW}}(X \vee Y)=&  \hat{\chi}_{\text{CW}}(X) +  \hat{\chi}_{\text{CW}}(Y)
    \end{align}
    \begin{proof}
       This is an easy computation. We have $\text{Cells}_*(X \vee Y)= \text{Cells}_*(X) \cup \text{Cells}_*(Y)$ thus 
        \begin{align*}
        \hat{\chi}_{\text{CW}}(X \vee Y)&= \sum_{a\in \text{Cells}_*(X \vee Y)} (-1)^{|a|}\cdot t^{w(a)}\\
        &=\sum_{a\in \text{Cells}_*(X)} (-1)^{|a|}\cdot t^{w(a)} + \sum_{b\in \text{Cells}_*(Y)} (-1)^{|b|}\cdot t^{w(b)}\\
        &= \hat{\chi}_{\text{CW}}(X)+ \hat{\chi}_{\text{CW}}(Y).
        \end{align*}

    \end{proof}
\end{prop}


  \begin{rmk}
         The collection of $k$-cells in $X \times Y$ is the collection of products of $l$-cells in $X$ with $m$-cells in $Y$, with $l+m=k$. Assume $a$ is such an $l$-cell of $X$ and $b$ is a $m$-cell of $Y$, then 
        \begin{equation}
            w(a \times b)= \max\{w(a),w(b)\}
        \end{equation}
        Indeed, $a\times b$ is a $k$-cell of $(X \times Y)(r)$ iff $a$ is an $l$-cell of $X(r)$ and $b$ is an $m$-cell of $Y(r)$ hence $r\geq \max\{w(a),w(b)\}$. It follows that 
        \begin{align*}
            \hat{\chi}_{\text{CW}}(X \times Y)=& \sum_{a\times b\in \text{Cells}_*(X)\times \text{Cells}_*( Y)} (-1)^{|a \times b|}\cdot t^{\max\{w(a),w(b)\}}\\
            =&\sum_{a\in \text{Cells}_*(X)}(-1)^{|a|}\sum_{b\in \text{Cells}_*(Y)}(-1)^{|b|}\cdot t^{\max\{w(a),w(b)\}}.
        \end{align*}
    And 
        \begin{align*}
           \hat{ \mathcal{W}}(X \times Y)=&\frac{d}{dt}\sum_{a\in \text{Cells}_*(X)}(-1)^{|a|}\sum_{b\in \text{Cells}_*(Y)}(-1)^{|b|}\cdot t^{\max\{w(a),w(b)\}}\\
            =& \sum_{a\in \text{Cells}_*(X)}(-1)^{|a|}\sum_{b\in \text{Cells}_*(Y)}(-1)^{|b|}\cdot \max\{w(a),w(b)\}\cdot t^{\max\{w(a),w(b)\}-1}
            \end{align*}

    In general we can say much about the relations of $\mathcal{W}(X \times Y)$ with $\mathcal{W}(X)$ and $\mathcal{W}(Y)$. However, if we replace $\times$ with $\bar{\times}$ we have the following results.
        \end{rmk}

\begin{prop}
    $\hat{\chi}_{\text{CW}}(X \bar{\times} Y)=\hat{\chi}_{\text{CW}}(X) \cdot \hat{\chi}_{\text{CW}}(Y)$.
    \begin{proof}
         Again the collection of $k$-cells in $X \bar{\times} Y$ is the collection of $a \times b$-cells where $a$ is an $l$-cell, $b$ is an $m$-cell and $k=l+m$. Now however the weight of such cells is given by
       \begin{equation}
           w(a\times b)=w(a)+w(b)
       \end{equation}

      Cells of the form $* \times b$ and $a \times *$ are eternal and thus do not contribute to the count. Thus we obtain

      \begin{align*}
          \hat{\chi}_{\text{CW}}(X \bar{\times} Y) = &\sum_{a\in \text{Cells}_*(X)}\sum_{b\in \text{Cells}_*(Y)}(-1)^{|a|+|b|}\cdot t^{w(a)+w(b)}\\
          =& \sum_{a\in \text{Cells}_*(X)}\sum_{b\in \text{Cells}_*(Y)}(-1)^{|b|}\cdot t^{w(b)} \cdot (-1)^{|a|} \cdot t^{w(a)}\\
          =&\big( \sum_{a\in \text{Cells}_*(X)} (-1)^{|a|} \cdot t^{w(a)}\big) \cdot \big(\sum_{b\in \text{Cells}_*(Y)}(-1)^{|b|}\cdot t^{w(b)} \big)\\
         =& \hat{\chi}_{\text{CW}}(X) \cdot \hat{\chi}_{\text{CW}}(Y)
      \end{align*}

    \end{proof}
\end{prop}

\begin{cor}
    The weighted Euler characteristic and classical Euler characteristic satisfy:
    \begin{equation}
        \mathcal{W}(X \bar{\times} Y) =\mathcal{W}(X)\cdot \chi(Y) + \mathcal{W}(Y) \cdot \chi(X).
    \end{equation}
    \begin{proof}
      Using the previous proposition we have:
       \begin{align*}
           \hat{\mathcal{W}}(X \bar{\times} Y)= &\frac{d}{dt} \hat{\chi}_{\text{CW}}(X \bar{\times} Y)= \frac{d}{dt}\big(\hat{\chi}_{\text{CW}}(X) \cdot \hat{\chi}_{\text{CW}}(Y)\big)\\
           =& \frac{d}{dt}\hat{\chi}_{\text{CW}}(X) \cdot \hat{\chi}_{\text{CW}}(Y)+ \hat{\chi}_{\text{CW}}(X) \cdot  \frac{d}{dt}\hat{\chi}_{\text{CW}}(Y)\\
           =& \hat{\mathcal{W}}_{\text{CW}}(X) \cdot \hat{\chi}_{\text{CW}}(Y)+ \cdot \hat{\chi}_{\text{CW}}(X)\cdot \hat{\mathcal{W}}_{\text{CW}}(Y).
       \end{align*}
    \end{proof}
\end{cor}

\begin{rmk}
    The above result implies that   $\mathcal{W}(X \bar{\times} Y) =\mathcal{W}(X)\cdot \chi(Y) + \mathcal{W}(Y) \cdot \chi(X)$.
\end{rmk}
\begin{cor}\label{corsmash}

 We have the following identities:
    \begin{align}
        \hat{\chi}_{\text{CW}}(X \bar{\Smash} Y)= &\hat{\chi}_{\text{CW}}(X) \cdot \hat{\chi}_{\text{CW}}(Y)\\
      \hat{\mathcal{W}}_{\text{CW}}(X\bar{\Smash}Y)  =& \hat{\chi}_{\text{CW}}(X) \cdot \hat{\mathcal{W}}_{\text{CW}}(Y)+ \hat{\chi}_{\text{CW}}(Y)\cdot \hat{\mathcal{W}}_{\text{CW}}(X)
    \end{align}

\begin{proof}
    By definition $X\bar{\Smash}Y(r)= (X\bar{\times} Y)(r)/X \vee Y$, thus we have $\text{Cells}_*(X \Smash Y)= \text{Cells}_*(X \times Y) \setminus \text{Cells}(X \vee Y)$. But note that all cells in $X \vee Y$ are eternal, and so do not contribute to the count. Hence we obtain the same count as for $\bar{\times}$. 

\end{proof}

\end{cor}
\begin{rmk}

Finally we remark that we have equalities:
\begin{align}
     \chi(X \bar{\Smash} Y)= &\chi(X) \cdot \chi(Y)\\
      \mathcal{W}(X\bar{\Smash}Y)  =& \chi(X) \cdot \mathcal{W}(Y)+ \chi(Y)\cdot \mathcal{W}(X).
\end{align}

\end{rmk}
\subsection{A filtered loop-suspension adjunction}
Given two filtered spaces $X$ and $Y$, we can form a new filtered space $\text{Map}(X,Y)$ given by letting 
\begin{equation}\text{Map}(X,Y)( r):=\{f:X \to Y | \lceil f \rceil =r\}\end{equation}
be the subspace $\text{Map}(X,Y)\in \text{Top}_*$, of maps with shift $r$. Notice this is indeed a filtered topological space, as any morphism of shift $r$ can be viewed as a morphism of shift $s>r$ via inclusion. In particular, we have inclusions

\begin{equation}
    i_{r,s}^{\text{Map}(X,Y)}:\text{Map}(X,Y)(r) \to \text{Map}(X,Y)(s)
\end{equation}
given by pushing $f$ forward under the filtration maps of $Y$. Note this defines a filtered topological space in the sense of definition \ref{filttopdef}.
\begin{defn}
We define the \textbf{loop space} $\Omega X$ of a filtered space $X$ to be 
\begin{equation}\Omega(X):=\text{Map}(S^1_0,X)\end{equation}
where $S^1_0$ is $S^1$ with the zero filtration.
\end{defn}

\begin{rmk}
A map of shift $r$, from $S^1_0$ with the zero filtration, into any filtered space is uniquely determined by $f(0):S^1(0) \to X(r)$ as the following must commute
\begin{equation*}
    \begin{tikzcd}
    & X(s)\\
        S^1 \ar[ru,"f(s-r)"]\ar[r,swap,"f(0)"]& X(r)\ar[u,"i_{r,s}"]\\
    \end{tikzcd}
\end{equation*}
hence 
\begin{equation}\Omega(X)( r)=\text{Map}(S^1, X(r))= \Omega(X(r)).\end{equation}
\end{rmk}
\begin{prop}
There is an adjunction 
\begin{equation}\text{Map}(\S X,Y)(r) \simeq \text{Map}(X,\Omega Y)( r)\end{equation}

\begin{proof}
An element of $\text{Map}(\S X,Y)( r)$ is a family of maps
\begin{equation*}f(t):(\S X)( t)\to Y( t+r)\end{equation*}
which by definition of filtered suspension is a family of maps
\begin{equation*}
f(t): \S (X( t)) \to Y( t+r)\end{equation*}
by the usual loop-suspension adjunction we have that this is equivalent to a collection of maps
\begin{equation*}
\bar{f}(t): X(t) \to \Omega(Y( t+r))\end{equation*}
and so a collection of maps
\begin{equation*}\bar{f}( t): X( t) \to (\Omega Y)(t+r).\end{equation*}
Furthermore, one finds 

\begin{equation*}
    \begin{tikzcd}
        X(s)\ar[r,"\bar{f}(s)"] & (\Omega Y)(s+r) \\
        X(t)\ar[r,"\bar{f}(t)"]\ar[u,"i_{t,s}^X"] & (\Omega Y)(r+t)\ar[u,swap,"i_{t+r,s+r}^{\Omega Y}"]
    \end{tikzcd}
\end{equation*}
commutes for all $s\geq t$. Indeed, recall that the usual loop-suspension adjunction $\text{Hom}(\S X,Y) \simeq \text{Hom}(X, \Omega Y)$ is given by $\phi: (f:\S X \to Y) \mapsto (\phi(f): X \to \text{Map}(S^1,Y))$ with $(\phi(f)(x))(\tau):= f(x,\tau)$, where we identify $\S X$ with $S^1_0 \bar{\Smash} X$. We therefore find
\begin{align*}
   ( i_{t+r,s+r}^{\Omega Y} \circ \bar{f}(t))(x)(\tau)=&(i_{t+r,s+r}^{\Omega Y} \circ \phi(f(t)))(x)(\tau)\\
   =&i^Y_{t+r,s+r}\circ \phi(f(t))(x)(\tau)\\
   =& i^Y_{t+r,s+r} \circ (f(t))(x,\tau)\\
   =&(f(s))(x,\tau) \circ i^X_{t,s}\\
   =& \phi(f(s))(x)(\tau) \circ i^X_{t,s}\\
   =& \bar{f}(s) \circ i_{t,s}^X.
\end{align*}
Hence $\bar{f}$ defines a filtered morphism, and so we have said adjunction.
\end{proof}
\end{prop}







\section{Filtered stable homotopy}

In general homotopy classes of maps $[X,Y]$ between two topological spaces need not form a group. Though, if $Y$ is an H-group or if $X$ is a co-H-group then there exists a natural group structure. In particular, if $X\simeq \S X'$ is a suspension space or if $Y \simeq \Omega Y'$ is a loop space then $[X,Y]$ carries a natural group structure, as supsensions are co-H-groups and loop spaces are H-groups. In the setting of filtered spaces, it follows that $[X,Y]$ carries a persistence group structure (persistence module with each level forming a group rather than module) if $X\simeq \S X'$ is a filtered suspension space or if $Y \simeq \Omega Y'$ is a filtered loop space. Moreover, $[X,Y]$ can be seen to be a filtered Abelian group, i.e., persistence $\Z$-module  if $X\simeq \S^2 X'$ or $Y\simeq \Omega^2 Y'$. Thus if we want to study filtered spaces via the techniques of persistence categories, then we should pass to stable homotopy. 

There is a morphism of filtered CW complexes (and general filtered spaces) we call the \textbf{filtered pinch map}:

\begin{equation}
    \S X \to \S X \vee \S X
\end{equation}
simply given levelwise by the usual pinch map:

\begin{equation*}
    \S X \simeq \text{Cone}\big( X \xrightarrow{i_1} \text{Cone}(X\xrightarrow{i_0} \text{Cyl}(X))) \xrightarrow{\text{pinch}} \S X \vee \S X
\end{equation*}
with $i_{(-)}$ being the inclusion of $X$ into $\text{Cyl}(X)$ along $\{(-)\}\times X$, and $\text{pinch}$ being the projection to the quotient of $\text{Cyl}(X)$ by identifying $\{\frac{1}{2}\}\times X$ with the basepoint. In the filtered setting this map can be seen to have zero shift.

Given two filtered morphisms of equal shift $f,f': \S X \to Y$ we can form their \textbf{filtered concatenation}: 
\begin{equation}
    f+ f': \S X \to Y
\end{equation}
with shift $\lceil f+f'\rceil=\lceil f\rceil = \lceil f' \rceil$. It is given by the composition:
\begin{equation}
    f+f' := \S X \xrightarrow{\text{pinch}}\S X \vee \S X \xrightarrow{f\vee f'} Y.
\end{equation}
i.e., the levelwise concatenation. It follows from the levelwise co-H-group structure on $\S X$ that $[\S X,Y](r):=\text{Hom}_{\ff \text{Top}_*}(\S X,Y)(r)/\sim$, the $r$-th level of the morphism of filtered spaces up to filtered homotopy, is a group. And moreover, since $\S^2 X$ has an Abelian co-H-group structure, $[\S^2 X,Y](r)$ is an Abelian group. Notice that there exist group morphisms 

\begin{equation*}
    (i_{r,s})_*:[\S ^2X ,Y](r) \to [\S^2 X,Y](s)
\end{equation*}
induced by the filtered morphism maps. Thus we can view $[\S^2X,Y]$ as a persistence module (in $\text{Mod}_\Z$). In this set up we naturally obtain a \text{filtered Freudenthal suspension theorem}: For large enough $n\in \Z$ we have an isomorphism of (Abelian) groups:

\begin{equation}
    \S: [\S^n X ,\S^n Y](r) \to [\S^{n+1}X, \S^{n+1}Y](r) .
\end{equation}


If we stabilise our filtered topological category via $\S^\infty$ we will therefore obtain a persistence category. In the remainder of this section we consider a persistence version of the Spanier-Whitehead category of CW-complexes, given by stabilising the category of filtered CW complexes. We show that it is a triangulated persistence category, and explore what the fragmentation metrics defined on TPCs are calculating.
\subsection{A persistence Spanier-Whitehead category}


Given two filtered CW complexes $X$ and $Y$ we can define Abelian groups, 

\begin{equation}
    \pp\text{SW}(X,Y)(r):=\text{Colim}_{n\geq 0}[\S^n X , \S^n Y](r).
\end{equation}

for every $r\in \R$. Given $r<s$ we obtain induced group morphisms 

\begin{equation}
    (i_{r,s}^{SW})*:\pp\text{SW}(X,Y)(r) \to \pp\text{SW}(X,Y)(s)
\end{equation}


More generally, we define:

\begin{equation}
    \pp\text{SW}((X,k)(Y,l))(r):=\text{Colim}_{n>k,l}[\S^{n+k}X,\S^{n+l}Y](r)
\end{equation}
and obtain a persistence module in Abelian groups $\{\pp\text{SW}((X,k),(Y,l)),i_{r,s}^{\pp\text{SW}}\}$. 


We define the \textbf{persistence Spanier-Whitehead category} $\pp \text{SW}$, to be the category with objects pairs $(X,k)$ with $X$ a filtered CW complex and $k\in \Z$. The hom-sets are persistence modules given by $\pp\text{SW}((X,k),(Y,l))$. This category comes with natural shift functors for all $a\in \R$, $\ss^a:\pp \text{SW} \to \pp \text{SW}$ given by

\begin{equation}
    \ss^a(X,k)=(\ss^a X,k)
\end{equation}
recalling that $(\ss^a X)(r)=X(r-a)$. There are also functors $[n]:\pp \text{SW} \to \pp \text{SW}$ given by
\begin{equation}
    [n](X,k):= (X,k+n).
\end{equation}

There is a canonical inclusion: $\iota:\text{Ho}\ff \text{Top}_*^{CW} \to \pp \text{SW}$, given by

\begin{equation*}
    \iota(X) = (X,0)
\end{equation*}
and with 
\begin{equation*}
    \iota(f:X \to Y):=\text{Colim}_n(\S^n f):(X,0) \to (Y,0).
\end{equation*}
Note that this restricts to an inclusion $\iota_0:(\text{Ho}\ff \text{Top}_*^{CW})_0 \to (\pp \text{SW})_0$
\begin{theorem}
The category $\pp \text{SW}$ is a triangulated persistence category with shift functors $\ss$ and triangulated functor $[1]$.
\end{theorem}



\begin{proof}
   The usual Spanier-Whitehead category is triangulated, with exact trianlges being triangles

   \begin{equation}
       \begin{tikzcd}
           (X,k)\ar[r,"f"] & (Y,l)\ar[r,"g"] & (Z,m)\ar[r,"h"] & [1](X,k)
       \end{tikzcd}
   \end{equation}
   which, up to some even suspension, are isomorphic to the image of a cofiber sequence under $\iota$, i.e., for some $n\in 2\Z$ there is an isomorphism of triangles
    \begin{equation}
       \begin{tikzcd}
           {[n]}(X,k)\ar[r,"{[n]f}"]\ar[d,"\cong"] & {[n]}(Y,l)\ar[r,"{[n]g}"]\ar[d,"\cong"]  & {[n]}(Z,m)\ar[r,"{[n]h}"] \ar[d,"\cong"] & {[n+1]}(X,k)\ar[d,"\cong"] \\
           (X',0)\ar[r,"\iota_0(f')"] & (Y',0)\ar[r,"\iota_0(i)"] & (\text{Cone}(f'),0)\ar[r,"\iota_0(j)"] & {[1]}(X',0)
       \end{tikzcd}
   \end{equation}

   We prove the statement in two parts:
   \begin{enumerate}
       \item[Part 1:] $(\pp \text{SW})_0$ is triangulated.  

    This will follow directly from the usual Spanier-Whitehead category being triangulated. In fact there is a general construction for `the Spanier-Whitehead category of $(\mathcal{H},\S)$' for a pointed model category $\mathcal{H}$ with suspension $\S$ (see \cite{De}) which is always triangulated. The category $(\text{Top}_*^{\pp SW})_0$ can be seen to be precisely the Spanier-Whitehead category of $((\ff\text{Top}_*)_0,\S)$. Indeed, by choice of filtration on mapping cones and suspensions being taken levelwise, we see that requirements to define the Spanier-Whitehead category of $((\ff \text{Top}_*)_0,\S)$ are satisfied, and hence it is a well defined triangulated category. Note furthermore $[1]$ commutes with $\ss^a$ for all $a\in \R$ by simply realising $\ss^a[1](X,k)=(\ss^a X,k+1)$


    \item[Part 2:] $\eta_r^{(X,k)}:(X,k) \to \ss^{-r}(X,k)$ has $r$-acyclic cone.
    By definition 
    \begin{equation*}
    [(X,k),\ss^{-r}(X,k)](0):= \text{Colim}[\S^{n+k}X,\S^{n+k}\ss^{-r}X](0)
    \end{equation*}
    We realise that the map $\eta_r^{(X,k)}$ is induced by $\eta_r^{\S^kX}:\S^kX \to \ss^{-r} \S^kX $ in $\ff \text{Top}_*$. Which levelwise is given by the natural inclusions
    \begin{equation*}
        \eta_{r}^{\S^k X}(t):\S^k X(t) \to \S^k \ss^{-r}X(t)=\S^k X(t+r)
    \end{equation*}
    The cone of this map in $\ff\text{Top}_*$ is, up to (zero) homotopy equivalence, given by 
    \begin{equation*}
        \text{Cone}(\eta_r^{\S^k X})(t)= \S^{k}X(t+r)/\S^{k}X(t).
    \end{equation*}
We find that the maps 
\begin{equation*}
    \eta_r^{\text{Cone}(\eta_r^{\S^k X})}(s):\text{Cone}(\eta_r^{\S^k X})(s) \to \ss^{-r}\text{Cone}(\eta_r^{\S^k X})(s)=\text{Cone}(\eta_r^{\S^k X})(s+r)
\end{equation*}
are simply given by the inclusions

\begin{equation*}
    \S^{k}X(s+r)/\S^{k}X(s) \to \S^{k}X(s+2r)/\S^{k}X(s+r)
\end{equation*}
which one sees are naturally nullhomotopic. In particular, after passing back to stable homotopy one finds that 
\begin{equation*}
    \eta_r^{\text{Cone}(\eta_{r}^{(X,k)})}=0.
\end{equation*}
i.e., $\text{Cone}(\eta_r^{(X,k)})$ is $r$-acyclic.
\end{enumerate}


\end{proof}


\begin{lemma}
    There is an equivalence of triangulated categories $\Phi: \text{SW} \to \pp \text{SW}_\infty$, with $ \text{SW}$ being the usual Spanier-Whitehead category of (finite) CW-complexes.
    \begin{proof}
        In the limit category $\pp \text{SW}_\infty$ any two filtered CW complexes with total space become isomorphic. Indeed, by assumption $-\infty<\lfloor X \rfloor \leq \lceil X \rceil < +\infty$. Assume $X$ and $X'$ are filtered spaces with $X(\infty)=X'(\infty)$, then in $\pp SW$ we can find an isomorphism $f: (X,n) \to (X,n)$ given by $[n] \iota(f': X \to  X')$, with $f'\in \text{Hom}_{\ff \text{Top}_*}(X,X')(\lceil X'\rceil - \lfloor X \rfloor)$ being induced by the equality $X(\lceil X'\rceil)= X'(\lceil X' \rceil) $. $[n]f$ has shift $\lceil X'\rceil - \lfloor X \rfloor$ but in the limit $\pp\text{SW}_\infty$ gives an isomorphism $(X,n) \cong (X',n)$. We can therefore define a functor $\Phi: \text{SW} \to \pp \text{SW}_\infty$, given by
        \begin{equation*}
            \Phi((X,n))(r)=\begin{cases}
            (X,n) & r\geq 0\\
            (*,n) & r<0
            \end{cases}
        \end{equation*}
        Clearly this is essentially surjective. If we denote $(X,n)$ to be such that $(X,n)(r)=(X,n)$ for $r\geq 0$ and trivial for $r<0$, and similarly for $(X',n')$, then in $\pp\text{SW}$ we have $\text{Hom}_{\pp \text{SW}}((X,n),(X',n'))(0)=\text{Hom}_{\pp \text{SW}}((X,n),(X',n'))(r)=\text{Hom}_{\text{SW}}((X,n),(X',n'))$ for all $r\geq 0$. Thus we have full faithfullness.
    \end{proof}

\end{lemma}

\subsection{Strict exact triangles}\label{strictexactsub}
Before proceeding to discuss the associated (pseudo) metrics induced by this TPC structure it is worth understanding what form strict exact triangles take in $\pp \text{SW}_0$. Recall a triangle in $\pp \text{SW}_0$ 
 \begin{equation}
       \begin{tikzcd}
           (X,k)\ar[r,"f"] & (Y,l)\ar[r,"g"] & (Z,m)\ar[r,"h"] & [1](X,k)
       \end{tikzcd}
   \end{equation}
is exact if there exists an $n\in 2\Z$ and a zero-isomorphism of triangles 


 \begin{equation}\label{isooftri}
       \begin{tikzcd}
           {[n]}(X,k)\ar[r,"{[n]f}"]\ar[d,"\cong"] & {[n]}(Y,l)\ar[r,"{[n]g}"]\ar[d,"\cong"]  & {[n]}(Z,m)\ar[r,"{[n]h}"] \ar[d,"\cong"] & {[n+1]}(X,k)\ar[d,"\cong"] \\
           (X',0)\ar[r,"\iota_0(f')"] & (Y',0)\ar[r,"\iota_0(i)"] & (\text{Cone}(f'),0)\ar[r,"\iota_0(j)"] & {[1]}(X',0)
       \end{tikzcd}
   \end{equation}

where the lower triangle is the image of a cofibre sequence in $(\ff \text{Top}_*)_0$. In $\pp \text{SW}_0$ a triangle 
\begin{equation}\label{triang}
       \begin{tikzcd}
           (X,k)\ar[r,"f"] & (Y,l)\ar[r,"g"] & (Z,m)\ar[r,"h"] & \ss^{-r}[1](X,k)
       \end{tikzcd}
   \end{equation}

is strict exact of weight $r$ if there exists a commutative diagram


\begin{equation}
       \begin{tikzcd}
          & & \ss^r(Z',m')\ar[d,"\psi"]\ar[dr,"\ss^rh"]\\
          (X,k)\ar[r,"f"] & (Y,l)\ar[r,"\bar{g}"]\ar[rd,"g"] & (Z',m')\ar[d,"\phi"]\ar[r,"\bar{h}"] &{[1]}(X,k)\\
           & & (Z,m)\ar[r,"h"] & \ss^{-r}[1](X,k)
       \end{tikzcd}
   \end{equation}

with central line being an exact triangle and $\phi$ an $r$-isomorphism (with $\phi \circ \psi =\eta_r$). Assuming the central triangle is exact via the isomorphism in \ref{isooftri}, then consider

\begin{equation}
    \begin{tikzcd}
    (X',0)\ar[d,"\cong"] \ar[r,"\iota_0(f')"]&\ar[d,"\cong"] (Y',0)\ar[rr,"\iota_0(i)"] && \ar[d,"\cong"](\text{Cone}(f'),0) \ar[r,"\iota_0(j)"]& {[1]}(X',0)\ar[d,"\cong"]\\
        {[n]}(X,k) \ar[r,"{[n]f}"] & {[n]}(Y,l)\ar[drr,"{[n](\phi \circ \bar{g})}"] \ar[rr,"{[n] \bar{g}}"]&& {[n]}(Z',m')\ar[d,"{[n]\phi}"]\ar[r,"{[n]\bar{h}}"] & {[n+1]}(X,k)\\
        & && {[n]}(Z,m) \ar[r,"{[n]h}"]& \ss^{-r}{[n+1]}(X,k)
    \end{tikzcd}
\end{equation}
Thus, the triangle \ref{triang}, being strict exact of weight $r$ implies that there exists an $n\in 2\Z$ and a commutative diagram 


\begin{equation}\label{stricttri}
    \begin{tikzcd}
        & && \ss^r[n](Z,m)\ar[d,"\vartheta"]\ar[dr,"\ss^r\varepsilon"] &\\
        (X',0) \ar[r,"\iota_0(f')"]&\ar[drr,swap,"\varphi \circ \iota_0(i)"] (Y',0)\ar[rr,"\iota_0(i)"] && (\text{Cone}(f'),0) \ar[d,"\varphi"]\ar[r,"\iota_0(j)"]& {[1]}(X',0)\\
       {} &{} && {[n]}(Z,m)\ar[r,"\varepsilon"] & \ss^{-r}{[1]}(X',0)
    \end{tikzcd}
\end{equation}
with $\varphi$ being an $r$-isomorphism (and $\varphi \circ \vartheta =\eta_r$). 

\begin{prop}
  If $\alpha:(A,m) \simeq_r (B,l)$ is an $r$-isomorphism, then there exists some $A'$ and $B'\in \ff\text{Top}_*$, and an $n\in 2\Z$ such that there is a $\iota_0(\beta):(A',0) \simeq_r (B',0)$ and the following commutes
    \begin{equation}
        \begin{tikzcd}
            {[n]}(A,m)\ar[r,"\cong"] \ar[d,"{[n]\alpha}"]& (A',0)\ar[d,"\iota_0(\beta)"] \\
            {[n]}(B,l)\ar[r,"\cong"] & (B',0)
        \end{tikzcd}
    \end{equation}
    \begin{proof}
        By definition of $r$-isomorphism there must exist some $\alpha: (A,m) \to (B,l)$ such that there is an exact triangle

        \begin{equation*}
            \begin{tikzcd}
                (A,m) \ar[r,"\alpha"]& (B,l) \ar[r]& (K,k)\ar[r] & {[1]}(A,m)
            \end{tikzcd}
        \end{equation*}
        with $\eta_r^{(K,k)}=0$. Thus there is some $n\in 2\Z$ and an isomorphism of triangles
         \begin{equation*}
            \begin{tikzcd}
               {[n]} (A,m) \ar[d,"\cong"]\ar[r,"{[n]\alpha}"]& {[n]}(B,l) \ar[d,"\cong"]\ar[r]& {[n]}(K,k)\ar[r]\ar[d,"\cong"] & {[n+1]}(A,m)\ar[d,"\cong"]\\
                (A',0)\ar[r,"\iota_0(\beta)"]  & (B',0)\ar[r,"\iota_0(i)"] & (K',0)\ar[r,"\iota_0(j)"] & [1](A',0) 
            \end{tikzcd}
        \end{equation*}
        Thus the leftmost square is the desired commutative square. It is easy to show that $\iota_0(\beta)$ is an $r$-isomorphism. Since $(K,k)$ is $r$-acyclic $[n](K,k)$ must also be $r$-acyclic. Thus $(K',0)$ is zero isomorphic to an $r$-acyclic object. Denoting this isomorphism by $f:[n](K,k) \to (K',0)$ we find 
        \begin{equation*}
            \eta_r^{(K',0)}= f \circ f^{-1} \circ \eta_r^{(K',0)}= f \circ \eta_r^{[n](K,k)} \circ \ss^r f^{-1}=0
        \end{equation*}
        meaning that $(K',0)$ is $r$-acyclic and thus $\iota_0(\beta)$ is an $r$-isomorphism.
    \end{proof}
\end{prop}

The preceding result implies that we can replace (after possibly choosing larger $n$) the diagram in \ref{stricttri} with a (zero) isomorphic diagram of the form 





\begin{equation}\label{stricttri2}
    \begin{tikzcd}
        & && \ss^r(C,0)\ar[d,"\vartheta"]\ar[dr,"\ss^r\varepsilon"] &\\
        (X',0) \ar[r,"\iota_0(f')"]&\ar[drr,swap,"\varphi \circ \iota_0(i)"] (Y',0)\ar[rr,"\iota_0(i)"] && (\text{Cone}(f'),0) \ar[d,"\varphi"]\ar[r,"\iota_0(j)"]& {[1]}(X',0)\\
       {} &{} && (C,0)\ar[r,"\varepsilon"] & \ss^{-r}{[1]}(X',0)
    \end{tikzcd}
\end{equation}


In particular if a triangle in $\pp \text{SW}_0$ is strict exact of weight $r$, then after suitably many even suspensions it is zero isomorphic to a strict exact triangle of weight $r$ which is the image of a cofiber sequence in $(\ff \text{Top}_*)_0$. The converse can be easily be verified.  





\subsection{Fragmentation distances and sizes}
The TPC structure on $\pp \text{SW}$ allows us to construct fragmentation (pseudo) metrics on the class of objects. Furthermore these metrics can be pulled back via the functor $i:\ff \text{Top}_* \to \pp \text{SW}$ to metrics on $\ff \text{Top}_*$. Let $\ff$ be a family of objects in $\ff\text{Top}_*$ and let $X,Y$ also be objects of $\ff \text{Top}_*$, then we define the fragmentation distance on $\ff\text{Top}_*$

\begin{equation}
d_{\ff\text{Top}_*}^\ff(X,Y):=\inf \big\{d^{\bar{\ff}}_{{\pp\text{SW}}}((\bar{X},0),(\bar{Y},0)): \bar{X} \simeq X, \bar{Y} \simeq Y\big\}
\end{equation}
Here, $d_{\pp\text{SW}}^{(-)}$ is the associated fragmentation metric induced by the TPC structure on $\pp \text{SW}$, $\bar{X}$ is a filtered CW approximation of $X$, and $\bar{\ff}:=\{(\bar{F},0):F\in \ff\}$. The choice of family $\ff$ is key to the definition of these metrics, indeed two different choices and induce completely different metrics. Thus we wish to choose a `nice' family which allows for distances that are comparable to previously defined distances. Recall that we define the filtered $k$ sphere at level $0$ by $S^k$, it is given by
\begin{equation*}
    S^k(t):=\begin{cases}
        * & t<0\\
        S^k & t\geq 0
    \end{cases}
\end{equation*}
We define the family $
\mathbb{S}:=\{ S^k: k\in \N\}$ and set $d_\mathbb{S}:=d^{\mathbb{S}}_{\ff \text{Top}_*}$. The idea here is that this family will allow one to generate any CW complex via attaching cones. The `size' of these attaching cones induces the distances we wish to study. These fragmentation metrics also induce a notion of size of a filtered topological space, we define the size of a filtered space $X$ to be:

\begin{equation*}
    |X|_{\mathbb{S}}:=d_{\mathbb{S}}(*,X).
\end{equation*}

\begin{prop}
    The size $|X|_{\mathbb{S}}$ is finite. 
    \begin{proof}
    By assumption, each filtration step $X(r)$ is equivalent to a finite CW-complex. Furthermore, the set $\text{Spec}(X)$ is also finite and the filtration stablises. Thus we can construct $X$ out of finitely many attaching cones. In particular, the image of each of these cone sequences in $\pp \text{SW}$ give exact triangles $\Delta_i$ each with finite weight. Hence we can bound $|X|_{\mathbb{S}}$ by $\sum_i^n w(\Delta_i)<\infty$ .


    \end{proof}
\end{prop}
\begin{prop}
    The distance $d_{\mathbb{S}}(X,Y)$ is finite. 
    \begin{proof}
        This will follow from $|X|_\mathbb{S}$ and $|Y|_{\mathbb{S}}$ both being finite. Indeed, we can attach enough cones to $X$ to such that the resulting space is contractible. We then attach cones to to build $Y$. We see that $d_\mathbb{S}(X,Y)\leq |X|_\mathbb{S}+|Y|_\mathbb{S}$.
    \end{proof}
\end{prop}


\begin{lemma}\label{weightsumcrit}
    Let $X$ be a compact connected smooth manifold, and $f:X \to \R$ be non-negative, bounded, Morse. Let $X_f$ be the filtered space corresponding to the sub-level sets of $f$, then \begin{equation}|X_f|_\mathbb{S}\leq \sum_{x\in\text{Crit}(f)} f(x).\end{equation}
    \begin{proof}
        The homotopy type of $X$ will only change as we pass over critical points of $f$, it is a well known result of Morse theory that, if $x\in \text{Crit}(f)$ is such that the submanifold $f^{-1}[f(x)-\epsilon,f(x)+\epsilon]$ contains only $x$ as a critical point, then $f^{-1}\{\leq f(x)+\epsilon\}$ is homotopy equivalent to $f^{-1}\{\leq f(x)-\epsilon\}$ with a cell attached. The dimension of this cell depends on the index of $x$ as a critical point. More generally, if there are many (isolated) critical points all with the same critical value, then $f^{-1}\{\leq f(x)+\epsilon\}$ is homotopy equivalent to $f^{-1}\{\leq f(x)- \epsilon\}$ with a cell attached for each critical point. We can view these cell attachments as mapping cone sequences (in $\text{Top}_*$)
        \begin{equation*}
            S^k \xrightarrow{\phi} X(f(x)-\epsilon) \to X(f(x)+\epsilon) \to S^{k+1}.
        \end{equation*}
        Note that $\text{Cone}(S^k)\cong D^{k+1}$ are homeomorphic. Thus we build a filtered CW-approximation $\bar{X}_f$ to $X_f$ as follows: Start with $\bar{X}_f^0=*$, at the first critical value of $f$ (assume this to be $r_1\in \R$) we need to attach cells of some dimension, say $k_1$. We need to attach a cell for every $x\in \text{Crit}(f)$ such that $f(x)=r_1$. Assume there are $n_1$ such cells and label them $\{x_1^{r_1},\hdots, x_{n_1}^{r_1}\}$. We iteratively attach each cell to the basepoint $*$, via cofiber sequences
        \begin{align*}
          &  S^{k-1} \xrightarrow{\phi_1^{r_1}} * \to S^k \to S^k\\
       &   \vdots\\
         & S^{k-1} \xrightarrow{ \phi_{n_1}^{r_1}} (\bar{X}_f^{0})_{n_1-1} \to  (\bar{X}_f^{0})_{n_1} \to S^k  
        \end{align*}
         Where $(\bar{X}_f^{0})_{a}$ denotes the constructed space after $a$ cell attachments. The shift of each map $\phi^{r_1}_a$ is $r_1$ and so 
         \begin{equation*}
             (\bar{X}_f^{0})_{a}(r)\simeq\begin{cases}
                 (\bar{X}_f^0)_a & r\geq r_1\\
                 * & r<r_1
             \end{cases}
         \end{equation*}
         (note the abuse of notation identifying the space constructed with the filtered space constructed). Each of these sequences induce strict exact triangles of weight $r_1$ in $\pp \text{SW}_0$ given by

         \begin{equation*}
             (S^{k-1},0) \xrightarrow{\iota\big((\eta_{0,-r_1})\circ \phi_a^{r_1}\big)} \ss^{-r_1}\big((\bar{X}_f)^0_a,0\big) \to \ss^{-r_1}\big((\bar{X}_f)^0_{a+1},0\big) \to \ss^{-r_1}[1](S^k,0).
         \end{equation*}
         Indeed notice that at filtration level $r$ we have triangles
          \begin{equation*}
             (S^{k-1}(r),0) \xrightarrow{\iota\big((\eta_{0,-r_1})\circ \phi_a^{r_1}\big)} \big((\bar{X}_f)^0_a(r+r_1),0\big) \to \big((\bar{X}_f)^0_{a+1}(r+r_1),0\big) \to [1](S^k(r+r_1),0).
         \end{equation*}
         Hence we have $|(\bar{X}_f^0)_{n_1}|_\mathbb{S}\leq n_1 \cdot r_1$. We then iterate this process over each critical value of $f$ to obtain filtered CW-complexes $(\bar{X}_f)^{r_m}_{n_m}$ with 

         \begin{equation*}|(\bar{X}_f)^{r_m}_{n_m}|_\mathbb{S}\leq n_1 \cdot r_1 + \hdots + n_m \cdot r_m=\sum_{x \in \text{Crit}(f):f(x)\leq r_m} f(x)
         \end{equation*}
         Since we assume $f$ is bounded, then we obtain
         \begin{equation*}
             |X_f|_\mathbb{S}\leq |\bar{X}_f|_\mathbb{S}= \sum_{x \in \text{Crit}(f)} f(x)
         \end{equation*}
    \end{proof}


\end{lemma}
\begin{rmk}
    If we allow for attachings of multiple cells at once, i.e., we consider a family $\mathbb{S}_\vee=\{\bigvee_{i=1,\hdots,n}S^k_i : k\in \N\}$ and its associated pseudometric. Then we find that 
    \begin{equation}
        |X_f|_{\mathbb{S}_\vee}\leq \sum_{r\in \text{CritVal}(f)} r
    \end{equation}
    where CritVal denotes the set of critical values of $f$. That is, $r\in \text{CritVal}(f)$ if $r=f(x)$ for some $x\in \text{Crit}(f)$. This follows from realising that we can attach all cells at each critical value at once. Hence, we have only one exact triangle for each critical value.
\end{rmk}

Given two $C^0$-close Morse functions on a manifold $f,f':M\to \R$, they need not be close with respect to the fragmentation metric $d_\mathbb{S}$. Indeed, $d_\mathbb{S}$ counts `the weighted sum of critical points', so if one were to perturb $f$ to $f'$ adding in many more critical points though keeping $f'$ $C^0$-close, then the distance via $d_\mathbb{S}$ can be arbitrarily large. This can be seen in the following example.

\begin{eg}
    Let $S^2_h:=(S^2,h)$ be the filtered two sphere with filtration given by the height function, $h:S^2 \to \R$ with critical points at $h(N)=1$ and $h(S)=0$ where $N,S$ are the north and south poles respectively. This filtered space can be seen to be weakly equivalent to 
    \begin{equation*}
        S^2_h(r)\simeq\begin{cases}
            * & r<1\\
            S^2 & r\geq 1
        \end{cases}
    \end{equation*}
    Note $|S^2_h|=1$.
    Denote by $S^2_{h'}:=(S^2,h')$ where $h'$ is the height function on the two sphere which has critical points at $N_1$, $N_2$ $M$ and $S$ with $h(N_1)=h(N_2)=1$, $h(M)=\frac{1}{2}$ and $h(S)=0$. We see that this filtered space is given (up to weak equivalence) by
    \begin{equation*}
        S^2_{h'}(r)\simeq\begin{cases}
            * & r< \frac{1}{2}\\
            S^1 & \frac{1}{2}\leq r < 1\\
            S^2 & r\geq 1
        \end{cases}
    \end{equation*}
    and note $|S^2_{h'}|=\frac{5}{2}$. Firstly we consider persistence homology of the two filtered spaces, we find

    \begin{equation*}
        H_*(S^2_h)(r)=\begin{cases}
            \R\langle a_0 \rangle & r<1\\
            \R \langle a_0 \rangle\oplus \R \langle a_2 \rangle& r\geq 1
        \end{cases} \hspace{20pt} H_*(S^2_{h'})(r)=\begin{cases}
            \R\langle b_0\rangle & r< \frac{1}{2}\\
            \R \langle b_0 \rangle \oplus \R \langle b_1 \rangle & \frac{1}{2}\leq r < 1\\
            \R \langle b_0 \rangle \oplus \R \langle b_2 \rangle & r\geq 1
        \end{cases}
    \end{equation*}
    The corresponding barcodes are given by:

    And the interleaving distance between these two persistence modules can be calculated to be $d_{\text{int}}( H_*(S^2_h), H_*(S^2_{h'}))=\frac{1}{4}$.  Now we wish to calculate the distance between these two filtered spaces using $d_{\mathbb{S}}$. We will build $S^2_{h'}$ out of $S^2_h$ and $\mathbb{S}$. Firstly, consider the map $\varphi:S^0 \to S^2_h$ with shift $\frac{1}{2}$ given by $ x\mapsto *$. One finds that the mapping cone is given by (up to homotopy)
    \begin{equation*}
        \text{Cone}(\varphi)(r)=\begin{cases}
            * & r< \frac{1}{2}\\
            S^1 & \frac{1}{2} \leq r <1\\
            S^1 \vee S^2 & r\geq 1
        \end{cases}
    \end{equation*}
    Next we look to the map $\psi:S^1 \to \text{Cone}(\varphi)$ of shift $1$, where $\psi(r)$ is the trivial map for $r<0$ and the inclusion into the copy of $S^1$ for $r\geq 0$. The map will `fill in' the copy of $S^1$, so that we have

    \begin{equation*}
        \text{Cone}(\psi)(r)= \begin{cases}
            * & r< \frac{1}{2}\\
            S^1 & \frac{1}{2}\leq r < 1\\
            S^2 & r\geq 1
        \end{cases}
    \end{equation*}


Consider in $\pp \text{SW}_\infty$ exact triangles, 
\begin{equation*}
        \begin{tikzcd}
           (S^0,0)\ar[r,"{[\iota(\varphi)]}"] & (S^2_h,0)\ar[r] & (\text{Cone}({[\iota(\varphi)]}),0)\ar[r] & {[1]}(S^0,0) \\
           (S^1,0)\ar[r,"{[\iota(\psi)]}"] & (\text{Cone}({[\iota(\varphi)]}),0) \ar[r]& (S^2_{h'},0)\ar[r] & {[1]}(S^1,0)
        \end{tikzcd}
    \end{equation*}
    One can calculate the sum of their weights to be be (less than or equal to) $\frac{3}{2}=1+\frac{1}{2}$.
\end{eg}

An interesting aspect of working with stable homotopy means that spaces that are not homotopy equivalent can be stably equivalent. A straight forward example of this is the torus $T=S^1 \times S^1$ and the space given by $S^1 \vee S^1 \vee S^2$, this follows from $\S(X \times Y) \simeq \S X \vee \S Y \vee \S(X \Smash Y)$ and $\S(X \vee Y) \simeq \S X \vee \S Y$. In the setting of filtered spaces this means that some filtered spaces $X,Y$ that are not filtered homotopy equivalent, can have $d_\ss(X,Y)=0$.



\begin{eg}
 If we take trivial filtrations on $T:=S^1 \times S^1$ and $T':=S^1 \vee S^1 \vee S^2$ spaces so that
    \begin{equation*}
        T(r)=\begin{cases}
            * & r<0\\
            T & r\geq 0
        \end{cases} \hspace{20pt} T'(r)=\begin{cases}
            * & r<0 \\
            T' & r\geq 0
        \end{cases}
    \end{equation*}
  Then there is an exact triangle in $\pp \text{SW}_0$ given by
  \begin{equation*}
      0 \to (T,0) \xrightarrow{\cong} (T',0) \to 0
  \end{equation*}
  with the isomorphism given by levelwise isomorphisms between $\S T(r) $ and $\S T'(r)$. Hence, we find $d_\mathbb{S}(T,T')=0$.
\end{eg}


Recall the definition of linearisation via strict exact triangles in the zero level category of a TPC, an object $X\in \cc$ has linearisation $L=(F_1,\hdots,F_n)$ if $X$ is an iterated weighted cone over the objects $F_i$, i.e., there is a sequence of strict exact triangles $\cc_0$

\begin{equation*}\begin{tikzcd}[ampersand replacement =\&]
    \Delta_1 : \& F_1\ar[r] \& 0 \ar[r] \& X_1\ar[r]  \& \ss^{-r_1}TF_1\\
    \Delta_2 : \& F_2 \ar[r] \& X_1 \ar[r] \& X_2 \ar[r] \& \ss^{-r_2}TF_2\\
    \vdots \& \& \vdots \& \vdots\\
    \Delta_n: \& F_n\ar[r]  \& X_{n-1} \ar[r] \& X' \ar[r] \& \ss^{-r_n}TF_n                    
\end{tikzcd}\end{equation*}
Here, $X'$ is zero-isomorphic to $X$. Denote by $\text{Lin}^\ff(X)$ the set of linearisations of $X$ with $F_i\in \ff$. The weight of such a linearisation we will denote by $w(L)$ and is given by the sum of the weights of the triangles, i.e., $w(L)=r_1 +\hdots + r_n$.
\begin{defn}
 Define a function $\lambda_X^\ff:\text{Lin}^\ff(X) \to \Lambda$ given by 

\begin{equation}
    \lambda_X^\ff(L):=\sum_{F_i\in L} t^{r_i}.
\end{equation}
\end{defn}


\begin{rmk}
    We can evaluate $\lambda^\ff_X$ at values of $t$ via a function $ev_{t=\alpha}:\Lambda \to \R$. Note that $\text{ev}_{t=1}(\lambda^\ff_X(L))$ is simply the number of elements of the linearisation $L$. Thus,
    \begin{equation}
        \inf\big\{ \text{ev}_{t=1}(\lambda_X^\ff(L)): L\in \text{Lin}^\ff(X)\big\}
    \end{equation}
    gives a count of the smallest amount of iterated cones needed to construct $X$ from the family $\ff$.
\end{rmk}


We call $L=(F_1,\hdots,F_n)$ a linearisation of $X\in \ff\text{Top}_*$ if $\iota(L):=(\iota(F_1), \hdots, \iota(F_n))$ is a linearisation of $\iota(X)$ in $\pp\text{SW}$, and similarly write $\text{Lin}^\ff(X)$ as the set of linearisations of $X$ with $F_i\in \ff$. We will consider the functions $\lambda_X^\mathbb{S}:\text{Lin}^\mathbb{S}(X) \to \Lambda$.
\begin{prop}
    Let $f:M \to \R$ be a non-negative, bounded Morse function, then there exists a linearisation $L\in \text{Lin}^\mathbb{S}(X_f)$ with 

    \begin{equation}
   \text{ev}_{t=1}( \lambda_{X_f}^\mathbb{S}(L))=\#\text{Crit}(f)
    \end{equation}
    \begin{proof}
        This linearisation is exactly the one given in the proof of Lemma \ref{weightsumcrit}, we are attaching one cell for each critical point.
    \end{proof}
\end{prop}


Consider also the derivative of $\lambda^\ff_X$ given by

\begin{equation}
    \frac{d}{dt}\lambda_X^\ff(L)= \sum_{F_i\in L}r_i\cdot t^{r_i-1}
\end{equation}
Evaluation at $t=0$ then gives
\begin{equation}
    \text{ev}_{t=0}\big( \frac{d}{dt}\lambda_X^\ff(L)\big)=\sum_{F_i\in \ff} r_i= w(L).
\end{equation}

Thus we find that, for the linearisation given in Lemma \ref{weightsumcrit}, we have:

\begin{prop}
Let $f:M \to \R$ be a non-negative, bounded Morse function, then there exists a linearisation $L\in \text{Lin}^\mathbb{S}(X_f)$ with 
\begin{equation}
     \text{ev}_{t=0}\big( \frac{d}{dt}\lambda_{X_f}^\mathbb{S}(L)\big)=\sum_{x\in \text{Crit(f)}}f(x)
\end{equation}
\end{prop}
\begin{rmk}
   We note that we can rewrite the size of an object in a TPC via linearisation in $\ff$ by:
    \begin{equation}
    |X|_\ff:=d^\ff(0,X)= \inf\big\{ \text{ev}_{t=1}\big( \frac{d}{dt}\lambda_X^\ff(L)\big): L\in \text{Lin}^\ff(X)\big\}.
    \end{equation}
\end{rmk}





We can also define a `weighted version' of the Euler characteristic.

\begin{defn}
    Given a filtered space $X\in \ff \text{Top}_*$, with CW-approximation $\bar{X}$, and an $L\in \text{Lin}^\mathbb{S}(\bar{X})$ we define the \textbf{Euler Polynomial of $X$ relative $L$}:
    \begin{equation}
        \chi^\mathbb{S}_{X}(L):= \sum_{S^{k_i}\in L}(-1)^{k_i+1}\cdot  t^{r_i} 
    \end{equation}
\end{defn}

Notice that
\begin{align*}
    \text{ev}_{t=1}\big( \chi_{X}^\mathbb{S}(L)\big)=&\sum_{S^{k_i}\in L}(-1)^{k_i+1}\\
    =&\sum_k (-1)^{k+1} \cdot \#(S^{k}\in L)
\end{align*}
where $\#(S^k\in L)$ denotes the number of times $S^k$ appears in the linearisation $L$. We also have the derivative:
\begin{equation}
   \mathcal{W}^\mathbb{S}_X(L):= \frac{d}{dt}\big(\chi_{X}^\mathbb{S}(L)\big)=\sum_{S^{k_i}\in L}(-1)^{k_i+1}\cdot r_i\cdot t^{r_i-1}
\end{equation}
which evaluated at $t=1$, gives

\begin{align}\label{eulweight}
     \text{ev}_{t=1}\big( \mathcal{W}^\mathbb{S}_X(L)\big)=&\sum_{S^{k_i}\in L} (-1)^{k_i+1}\cdot r_i.
\end{align}




\begin{lemma}
$\chi_X^\mathbb{S}$ recovers $\hat{\chi}_{\text{CW}}(X)$, thus is independent of linearisation.

\begin{proof}
    A general $L\in \text{Lin}^\mathbb{S}(X)$ is a sequence of strict exact triangles

    \begin{equation*}
      \begin{tikzcd}[ampersand replacement =\&]
    \Delta_1 : \& (S^{k_1},0)\ar[r,"f_1"] \& (*,0) \ar[r] \& \ss^{-r_1}[1](S^{k_1},0) \ar[r]  \& \ss^{-r_1}[1](S^{k_1},0)\\
    \Delta_2 : \& (S^{k_2},0) \ar[r,"f_2"] \& \ss^{-r_1}[1](S^{k_1},0) \ar[r] \& (X_2,n_2) \ar[r] \& \ss^{-r_2}[1](S^{k_2},0)\\
    \vdots \& \& \vdots \& \vdots\\
    \Delta_m: \& (S^{k_m},0)\ar[r,"f_n"]  \& (X_{m-1},n_{m-1}), \ar[r] \& (X_m,n_m) \ar[r] \& \ss^{-r_n}[1](\ss^{k_m},0)                    
\end{tikzcd}
    \end{equation*}

After suitably large even suspension, each of these strict exact triangles are zero isomorphic to strict exact triangles in the image of $\iota_0$. Thus we can replace this sequence with a sequence of triangles with each $n_i=0$, and with $X'_m\simeq X$, i.e., we replace the linearisation $L$ with some $L'$:

 \begin{equation*}
      \begin{tikzcd}[ampersand replacement =\&]
   (S^{k_1+2l_1},0)\ar[r,"\iota_0(f'_1)"] \& (*,0) \ar[r] \& \ss^{-r_1}[1](S^{k_1+2l_1},0) \ar[r]  \& \ss^{-r_1}[1](S^{k_1+2l_1},0)\\
 (S^{k_2+2l_2},0) \ar[r,"\iota_0(f'_2)"] \& \ss^{-r_1}[1](S^{k_1+2l_1},0) \ar[r] \& (X'_2,0) \ar[r] \& \ss^{-r_2}[1](S^{k_2+2l_2},0)\\
  \& \vdots \& \vdots\\
  (S^{k_m+2l_m},0)\ar[r,"\iota_0(f'_m)"]  \& (X'_{m-1},0), \ar[r] \& (X'_m,0) \ar[r] \& \ss^{-r_n}[1](\ss^{k_m+2l_m},0)                    
\end{tikzcd}
    \end{equation*}

As we are suspending an even number of times, the value of 
\begin{equation*}
    (-1)^{k_i+1}=(-1)^{k_i+1+2l}
\end{equation*}
furthermore because we are replacing with zero isomorphic strict exact triangles the value of each $r_i$ will remain the same. Hence, the value of $\chi_X^\mathbb{S}(L')=\chi_X^\mathbb{S}(L)$. Now we notice that 
\begin{equation*}
    \chi_X^\mathbb{S}(L')= \hat{\chi}_\text{CW}(X')
\end{equation*}
But this is simply $\hat{\chi}_{\text{CW}}(X)$ as $X \simeq X'$. 
\end{proof}
\end{lemma}


\begin{rmk}
 Evaluation at $t=1$ of $\chi_X^\mathbb{S}$ recovers the Euler characteristic of the total space $X$:
    \begin{equation}
\text{ev}_{t=1}\big(\chi_{X}^\mathbb{S}\big)=\chi(X)
    \end{equation}

\end{rmk}

\begin{rmk}
    We can also define \begin{equation}
 (\chi^\mathbb{S}_X)^{\leq r}(L):=      \sum_{S^{k_i}\in L \text{ with }r_i\leq r}(-1)^{k_i+1}t^{r_i} 
    \end{equation}

    which will be independent of $L$ and recover $\hat{\chi}^{\leq r}_{\text{CW}}(X)$, and similarly for $(\mathcal{W}^\mathbb{S}_X)^{\leq r}(L)$.
\end{rmk}

\begin{cor}
    The derivative $\mathcal{W_X^\mathbb{S}}$ recovers $\hat{\mathcal{W}}(X)$, and is also independent of $L$.
\end{cor}

\begin{rmk}
    One could choose to work with the limit category $\pp \text{SW}_\infty$ and define a Euler polynomial and weighted Euler polynomial. In this setting, we must replace the criteria of the terminal object $(X_m,0)$ in the sequence of exact triangles to not be isomorphic to the object whose polynomials we calculate $X$, but must be actually equal to $X$. This is due to isomorphisms in $\pp \text{SW}_\infty$ not necessarily being images of zero-isomorphisms in $\pp \text{SW}_0$. 
\end{rmk}

\subsection{K-group}
The Euler characteristic of (pointed) CW complexes induces an isomorphism of rings $\chi: K(\text{SW}) \to \Z$, this is due to $S^0$ generating $\text{SW}$ as a triangulated category and realising that if $[(X,m)]\in K(\text{SW})$ then $[(X,m)]=(-1)^m(\chi(X)-1)[(S^0,0)]$. We briefly explore how this argument extends to a ring isomorphism $K(\pp \text{SW}_0)\to \Lambda$. 

The $K$-group of $\cc_0$ for some TPC $\cc$, has a natural $\Lambda_P$-module structure, given by $[\ss^{r}A]=t^r\cdot [A]$ We show that $\bar{\Smash}$ extends to $\pp \text{SW}$ and descends to a $\Lambda_P$ product structure on $K(\pp \text{SW}_0)$. More precisely we show

\begin{lemma}
    In $K(\pp \text{SW}_0)$ the smash product, defined by 
    \begin{align}
       (X,n) \bar{\Smash} (Y,m):= (X\bar{\Smash} Y,n+ m)&
    \end{align}
    induces a product
    \begin{equation}[(X,n)]\cdot [(Y,m)]:=[(X,n)\bar{\Smash}(Y,m)]
    \end{equation}
     making $K(\pp \text{SW}_0)$ an $\Lambda_P$-algebra.
\begin{proof}
    To prove this statement, we use a result of \cite{BCZ2} (Lemma 3.3.5 and show that $\bar{\Smash}$ defines a TPC tensor structure on $\pp \text{SW}$ (see definition 3.3.1 of \cite{BCZ2}). We show that $\bar{\Smash}$ satisfies each of the properties:

    \begin{itemize}
        \item[(i)] Take $(A,a)\in \pp\text{SW}$, if $f\in \text{Hom}_{\pp \text{SW}}\big((X,n), (Y,m)\big)(r) $, then 

        \begin{equation*}1_{(A,a)}  \bar{\Smash}(i_{r,s}(f))=i_{r,s}(1_{(A,a)} \bar{\Smash}f)\in \text{Hom}_{\pp \text{SW}}\big( (A \bar{\Smash} X,a+n), (A\bar{\Smash}Y,a+m) \big)(r)
        \end{equation*}
        Indeed, the filtrations in $\pp \text{SW}$ is induced by the filtrations in $\ff \text{Top}^{\text{CW}}_*$. Thus this follows by remark \ref{sizeofsmashmorphism}.


    \item[(ii)] $A\bar{\Smash} (-)$ restricts to a triangulated functor on $\pp \text{SW}_0$. By definition, a triangle in $\pp \text{SW}_0$ is triangulated if after some even number of suspensions it is isomorphic to the image of a cofiber sequence from $\ff \text{Top}_*^{\text{CW}}$. Thus, it is enough to check that $\bar{\Smash}$ in $\ff \text{Top}_*^{\text{CW}}$ sends cofiber sequences to cofiber sequences. Consider a sequence 
    \begin{equation*}
        \begin{tikzcd}
            X\ar[r,"f"] & Y\ar[r]& \text{Cone}(f) \ar[r]&\S X
        \end{tikzcd}
    \end{equation*}
    Applying $A \bar{\Smash}(-)$ we have
      \begin{equation*}
        \begin{tikzcd}
           A \bar{\Smash} X\ar[r,"  1_A \bar{\Smash}f"] &   A \bar{\Smash}Y\ar[r]&   A \bar{\Smash}\text{Cone}(f) \ar[r]&  A \bar{\Smash}\S X.
        \end{tikzcd}
    \end{equation*}

    We must show that $\text{Cone}(1_A \bar{\Smash} f)\simeq A \bar{\Smash}\text{Cone}(f)$. By definition, we have $\text{Cone}(1_  A \bar{\Smash} f)(t)=\text{Cone}\big( ( 1_  A \bar{\Smash}f)(t)\big)$. We then find
    \begin{align*}
        \text{Cone}\big((1_A \bar{\Smash} f)(t)\big)=& \bigcup_{s+l=t} \text{Cone}\big( 1_A(s) \Smash f(l)\big)\\
        =& \bigcup_{s+l=t}\text{Cone}(1_{A(s)}\Smash f(l)\big)\\
        =& \bigcup_{s+l=t}A(s) \Smash \text{Cone}(f(l))\\
        =& A \bar{\Smash} \text{Cone}(f).
    \end{align*}
Furthermore, $\bar{\Smash}$ can be seen to be additive on $\pp \text{SW}_0$ by distributivity over $\vee$.
    \item[(iii)] Finally, we check that $[1]((A,a)\bar{\Smash} (X,n)) \simeq [1] (A,a) \bar{\Smash} (X,n) \simeq (A,a) \bar{\Smash} [1]( X,n)$. This is equivalent to 
    \begin{equation*}
        \big(\S (A\bar{\Smash} X),a+n\big)\simeq \big(\S A \bar{\Smash}X, a+n\big)\simeq \big(A \bar{\Smash}\S X,a+n\big).
    \end{equation*}
    Thus again, it is enough to check that in $\ff \text{Top}_*^{\text{CW}}$ we have
    \begin{equation*}
        \S (A\bar{\Smash} X)\simeq \S A \bar{\Smash}X\simeq A \bar{\Smash}\S X
    \end{equation*}
    But this is clear, as $\S(-)= S^1_0 \bar{\Smash}(-)$.
    \end{itemize}


\end{proof}

\end{lemma}





\begin{theorem}\label{ktheorylem}
    The weighted Euler polynomial $\hat{\chi}_{\text{CW}}$, induces an isomorphism of $\Lambda_P$-algebras $\mathcal{X}: K(\pp \text{SW}_0) \to \Lambda_P$, with 

    \begin{equation}
        \mathcal{X}: [(X,n)]\mapsto (-1)^n \cdot \hat{\chi}_{\text{CW}}(X).
    \end{equation}


\end{theorem}

This result is a persistence version of a known result in stable homotopy theory:

\begin{lemma}[Theorem 4.5.6 \cite{Mo}]
    There is a ring isomorphism $\chi:K(\text{SW}) \cong \Z $ given by 
    \begin{equation*}
    \chi([(X,n)])=(-1)^n\cdot \chi(X).
    \end{equation*}
\end{lemma}
Here, $\chi(X)$ is the reduced Euler characteristic. The proof comes from noticing that $[(X,n)]=(-1)^n\cdot \chi(X) \cdot [(S^0,0)]$. The proof of Theorem \ref{ktheorylem} follows in a similar manner:



\begin{proof}[Proof of Theorem \ref{ktheorylem}]
    Firstly, we claim that $[(X,n)]=(-1)^n \cdot \hat{\chi}_{\text{CW}}(X) \cdot [(S^0_0,0)]$. Let $S^k_t$ denote the filtered CW-complex given by 
    \begin{equation*}
        S^k_l(r):=\begin{cases}
            S^k & r\geq l\\
            * & r< l
        \end{cases}
    \end{equation*}
   We find that:

    \begin{align*}
        [(S^k_l,0)]=[\ss^l( S^k_0,0)]=&t^l \cdot [(S^k_0,0)]\\
        =&(-1)^k \cdot t^l \cdot [(S^0_0,0)]
    \end{align*}
    where the last equality follows from the exact triangle

    \begin{equation*}
        (S^{k-1}_0,0) \to * \to (S^k_0,0) \to (S^k_0,0)
    \end{equation*}
  giving $[(S^{k-1}_0,0)]=-[(S^k_0,0)]$, i.e., in general $[(X,n)]=-[(X,n+1)]$ in $K(\pp \text{SW}_0)$. Any filtered CW complex is formed by attaching of spheres $S^k_l$ via cofiber sequences in $(\ff \text{Top}_*)_0$, thus we have a sequence of exact triangles in $\pp \text{SW}_0$ of the form

  \begin{equation*}
      \begin{tikzcd}
          \bigvee_{i\in I_0} (S^0_{l_i},0) \ar[r]& (X_0,0)\ar[r] & (X_1,0)\ar[r] &  \bigvee_{i\in I_0} (S^0_{l_i},1)\\
            \bigvee_{i\in I_1} (S^1_{l_i},0)\ar[r] & (X_1,0) \ar[r]& (X_2,0)\ar[r] & \bigvee_{i\in I_1} (S^1_{l_i},1)\\
            \vdots & & & \\
              \bigvee_{i\in I_{n-1}} (S^{n-1}_{l_i},0) \ar[r]& (X_{n-1},0)\ar[r] & (X,0)\ar[r] &  \bigvee_{i\in I_{n-1}} (S^{n-1}_{l_i},1)
      \end{tikzcd}
  \end{equation*}
  Where $X_0$ is the `filtered zero-skeleton'. Implying that in $K(\pp \text{SW}_0)$ we have 
  \begin{align*}
      [(X,0)]=& [(X_{n-1},0)]-\big( (-1)^{n-1}\cdot [(S^0_0,0)]\sum_{i\in I_{n-1}} t^{l_i}\big)\\
      =&\big([(X_{n-2},0)]-\big( (-1)^{n-2}\cdot [(S^0_0,0)]\sum_{i\in I_{n-2}} t^{l_i}\big) - \big( (-1)^{n-1}\cdot [(S^0_0,0)]\sum_{i\in I_{n-1}} t^{l_i}\big)\\
      =& \hdots\\
      =& \sum_j \sum_{i \in I_j}(-1)^j \cdot t^{l_i} \cdot [(S^0_0,0)]\\
      =&\hat{\chi}_{\text{CW}}(X) \cdot [(S^0,0)].
  \end{align*}

  Finally, as $[(X,n)]=-[(X,n+1)]$, we obtain the general form:
  \begin{equation*}
      [(X,n)]=(-1)^n \cdot \hat{\chi}_{\text{CW}}(X) \cdot [(S^0_0,0)].
  \end{equation*}

From the results of proposition \ref{propwedge} and corollary \ref{corsmash} we see that $\mathcal{X}$ induces a ring morphism. Furthermore, as $\hat{\chi}_{\text{CW}}(\ss^l X)=t^l \cdot \hat{\chi}_{\text{CW}}(X)$, (something that is easy to verify) we find that $\hat{\chi}$ induces a morphism of $\Lambda_P$-algebras. Moreover, this is an isomorphism as $K(\pp \text{SW}_0)$ as a $\Lambda_P$-algebra is one dimensional with generator $[(S^0_0,0)]$ and $\mathcal{X}[(S^0_0,0)]=1$, generates $\Lambda_P$.
\end{proof}








\subsection{Filtered Spectra}
The Spanier-Whitehead category can be seen to be a subcategory of the stable homotopy category. There are various equivalent (in homotopy) constructions of this category, the most simple of which is given by sequential spectra. The constructions of this paper can be seen to extend to this setting. One can define a category of filtered spectra similarly to that of filtered topological spaces. i.e., a \textbf{filtered spectrum} is a spectrum $(X,\sigma)$ equipped with a filtration $\ff$ consisting of an $\R$-indexed family of subspectra.
\begin{equation}
\ff=\{X(r): X(r)\xhookrightarrow{i_r} X\}_{r\in \R} \end{equation}
where $i_r$ is the canonical inclusion map.
This family should satisfy:
\begin{enumerate}
\item The $n$-th level space of $X$, should be a filtered space with $X(r)_n=X_n(r)$.
    \item For all $r\in \R_{}$ for all $n\in \N$, we have $i_r(*_{(X(r))_n})=*_{X_n}$, i.e., they have a common basepoint.
    \item  For all $s<r$ we have $X(s) \subset X(r)$, we denote the inclusion map $i_{s,r}$.
    \item There exists an $r_0\in \R$ such that for all $r< r_0$ we have $X(r)=X'$, i.e., the filtration is stabilises below to some spectrum $X'$.


    \item There exists an $r_1\in \R$ such that for all $r>r_1$ we have $X(r)=X$, i.e., the filtration stabilises above to $X$ which we refer to as the \text{total spectrum}.
    \item The homotopy type of $X(r)$ can only change at finitely many $r$, we call this set $\text{Spec}(X)$.


\end{enumerate}
We can define morphisms of filtered spectra to be an $\R$-indexed family of morphisms of spectra that commute with the filtration maps. Most of the constructions in the category of filtered spaces will pass to constructions on the category of filtered spectra, $\ff \text{Spectra}$. In particular, we can restrict our attention to filtered CW-spectra, via an analogue of the CW approximation for spectra. 

\begin{lemma}
    Any filtered spectrum $X$ is weakly equivalent to a filtered CW-spectrum $\bar{X} \to X$, where the following homotopy commutes for all $r\leq s$
    \begin{equation}
        \begin{tikzcd}
            X(s)\ar[r,"\alpha(s)"] & \bar{X}(s)\\
            X(r)\ar[r,"\alpha(r)"]\ar[u,"i_{r,s}"] & \bar{X}(r)\ar[u,"i_{r,s}"]
        \end{tikzcd}
    \end{equation}
    \begin{proof}
        The proof is almost identical to the proof of Lemma \ref{CWspace} using the CW-appoximation theorem for spectra (see \cite{EKM} Theorem 1.5).
    \end{proof}
\end{lemma}


In order to pass to a persistence category by taking taking the homotopy category $\text{Ho}\ff \text{Spectra}^{\text{CW}}$, we need a filtered version of spectrification. In the category of filtered topological spaces we can define a filtered free infinite loop space functor $Q: \ff \text{Top}_* \to \ff \text{Top}_*$ given by 
\begin{equation}
    Q(X)(r):= \text{Colim} \Omega^k \S^k X(r)
\end{equation}

There are filtration maps $i_{r,s}:Q(X)(r) \to Q(X)(s)$ induced by the maps $i_{r,s}:X(r) \to X(s)$. The functor extends to a functor $Q: \ff \text{Spectra} \to \ff \text{Spectra}$ by 

\begin{equation*}
    Q(X)(r)_n=Q(X_n(r)).
\end{equation*}
We can then pass to a filtered stable homotopy category by defining hom-sets as the homotopy classes of maps
\begin{equation}
    \text{Hom}_{\text{Ho}\ff \text{Spectra}^\text{CW}}(X,Y)(r)=\text{Hom}_{\ff \text{Spectra}^{\text{CW}}}(Q(X),Q(Y))(r)/\sim
\end{equation}
Note that this is a persistence category with shift functors $\ss^a:\text{Ho}\ff \text{Spectra}^{\text{CW}}\to \text{Ho}\ff \text{Spectra}^{\text{CW}}$ given by $\ss^a(X)(r)=X(r-a)$.



\begin{lemma}
    The filtered stable homotopy category $\text{Ho}\ff \text{Spectra}^{\text{CW}}$ is a TPC. 
    \begin{proof}
        Exact triangles in $(\text{Ho}\ff \text{Spectra}^{\text{CW}})_0$ will be families of exact triangles 
        \begin{equation*}\{X(r) \to Y(r) \to Z(r) \to \S X(r)\}_{r\in \R}\end{equation*} 
        which commute with the filtration maps on $X,Y$ and $Z$. It follows from the usual stable homotopy category being triangulated that this is triangulated. The maps $\eta_r^X$ fit into exact triangles of the form 

        \begin{equation*}
            X \xrightarrow{\eta_r^X}\ss^{-r}X \to K \to \S X
        \end{equation*}
        with $K$-acyclic. Indeed, we have that 
        \begin{equation*}
            X(t) \xrightarrow{\eta_r^X(t)}\ss^{-r}X(t)
        \end{equation*}
        is given by the inclusion $X(t) \hookrightarrow X(t+r)$, thus has cone

        \begin{equation*}
            \text{Cone}(X(t) \hookrightarrow X(t+r))_n\simeq X_{n}(t+r)/X_n(t) 
        \end{equation*}
        Naturally, this object is $r$-acyclic as 
        \begin{equation*}
            \eta_{r}^{X_n(t+r)/X_n(t)}: X_n (t + r) / X_n (t) \to X_n (t + 2r) / X_n (t + r) \end{equation*} is null homotopic for all $r\in \R$ and $n\in\Z$.
    \end{proof}
\end{lemma}

One reason for working with $\text{Ho}\text{Spectra}$ and not with $\text{SW}$ is due to Brown's representation theorem; every generalised cohomology theorem $E^*$ can be represented by a spectrum $E$ with

\begin{equation*}
    E^n(-)\cong[-,E_n]
\end{equation*}

dually, every generalised homology theorem $E_*$ can be represented by a spectrum $E$ with
\begin{equation*}
    E_n(-)\cong\pi_n(E_n\Smash X).
\end{equation*}

It makes sense that a similar statement should hold for `persistence homology theories'. For example, consider the usual persistence (singular) homology $\text{H}_*(X;f)$ of some space $X$ with functional $f:X \to \R$. Let $K(\Q)$ be the Eilenberg-MacLane spectrum for the rationals, give this spectrum the zero filtration, i.e., $K(\Q)(r)=K(Q)$ for all $r\geq 0$ and is the trivial spectrum for $r<0$. 
Then \begin{align*}
    (K(Q)_n \bar{\Smash} X_f)(r)=&\bigcup_{s+t=r} K(\Q)_n(s) \Smash X_f(t)\\
    =& \bigcup_{t\leq r} K(\Q)_n \Smash X_f(t)\\
    =&K(\Q)_n \Smash X_f(r)
\end{align*}
Giving
\begin{equation}
    \text{H}_*^{\leq r}(X;\Q))=\pi_n \big( K(\Q)_n\Smash X_f(r)\big)= \pi_n\big((K(\Q)_n \bar{\Smash} X_f)(r)\big)=\pi_n^r \big( K(\Q)_n \bar{\Smash}X_f\big).
\end{equation}

Note that this is a specific example of what one could call a \textbf{generalised filtered homology theory}. Such an object should consist of the following:

\begin{enumerate}
    \item A functor $E^\leq_*:\ff \text{Top}^{\text{CW}}_* \to \text{Ab}_\Z^\pp$ from filtered CW complexes to $\Z$ graded persistence modules in Abelian groups. i.e., $\text{Ab}_\Z^\pp:= [(\R,\leq), \text{Ab}_\Z]$.
    \item Shift zero isomorphisms $s: E^\leq_n(-) \to E^\leq_{n+1}(\S(-))$.
\end{enumerate}
such that:
\begin{itemize}
\item $E^\leq_*$ restricts to maps $E^\leq_*(-):\text{Hom}_{\ff \text{Top}_*^{\text{CW}}}(X,Y)(r) \to \text{Hom}_{\text{Ab}_\Z^\pp}(E^\leq_*(X),E^\leq_*(Y))(r) $ such that $E^\leq_*\circ i_{r,s}=i_{r,s}\circ E^\leq_*$.
\item Isomorphisms $E^\leq_*(\ss^r(-)) \to \ss^{r}E^\leq_*(-)$.
    \item If $f\sim f'\in \text{Hom}_{\ff \text{Top}_*^{\text{CW}}}(X,Y)(r)$ are homotopic maps, then \begin{equation*}
        E^\leq_*(f)=E^\leq_*(f')\in \text{Hom}_{\text{Ab}_\Z^\pp}(E^\leq_*(X),E^\leq_*(Y))(r).
    \end{equation*}
    \item Let $i\in \text{Hom}_{\ff \text{Top}_*^\text{CW}}(A,X)(0)$ be levelwise an inclusion, then \begin{equation*}
        E^\leq_*(A) \xrightarrow{E^\leq_*(i)} E^\leq_*(X) \xrightarrow{E^\leq_*(j)}E^\leq_*( \text{Cone}(i))
    \end{equation*}
    is exact in $(\text{Ab}_\Z^\pp)_0$. 
    \item $E^\leq_*(\text{Cone}(\eta_r^X))$ is $r$-acylic.
\end{itemize}
It is easy to verify that persistence homology satisfies these axioms.
\begin{rmk}
This is a first attempt at what a generalised filtered homology theory should be. Notice that similar to the example of $H_*^\leq(X;\Q)$ if one takes any spectrum and gives it the zero filtration, then $E_n^\leq (-):=\pi_n^r(E\bar{\Smash}(-))$ defines a generalised filtered homology theory. In general though one could take any filtration on a spectrum and define such a theory. This follows from $S^1_0\bar{\Smash}E\bar{\Smash}X \simeq E \bar{\Smash}S^1_0 \bar{\Smash X}$, and shifting commuting with the filtered smash product:
\begin{equation}
    E^{\leq}_n(\S(-))=\pi_n^r(E \bar{\Smash} \S(-))\cong\pi_n^r\big(\S \big(E\bar{\Smash}(-)\big)\big)= \pi_{n+1}^r(E\bar{\Smash}(-))=E_{n+1}^{\leq}(-)
\end{equation}
and
\begin{equation}
    E^{\leq}_n(\ss^a(-))=\pi_n^r\big(E\bar{\Smash}(\ss^a(-))\big)=\pi_n^r\big( \ss^a \big( E \bar{\Smash}(-)\big)\big)=\pi_n^{r-a}\big((E\bar{\Smash}(-)\big)=\ss^aE^\leq_n(-).
\end{equation}


\end{rmk}

To conclude, we remark that this filtration construction (i.e., constructing $\ff \text{Top}_*$ and $\ff \text{Spectra}$ from $\text{Top}_*$ and $\text{Spectra}$) should be a part of a general construction on model categories. One would expect that if the model category is stable then the filtered homotopy category should return a TPC.
