Before proving this first give a few definitions/propositions, note that we can assume that all filtered spectra are filtered CW-$\Omega$-spectra.

\begin{prop}
Given two filtered spectra $(X,\ff_X)$ and $(Y,\ff_Y)$ the homotopy classes of morphisms between them of expansion $r$, form an abelian group, i.e., $[(X,\ff_X),(Y,\ff_Y)]^r \in Ab$ (or $[(X,\ff_X),(Y,\ff_Y)]^- \in \ff Ab$).

\begin{proof}
The usual group structure on homotopy classes of morphisms of spectra follows from the $\S \text{ and } \Omega$ being inverses of each other in the stable homotopy category, hence
\begin{equation*}[X,Y]\simeq [X, \Omega \S Y]\end{equation*}
and so we obtain a group structure given by
\begin{equation*}X \xrightarrow[]{\Delta} X \times X \xrightarrow[]{f\times g} \Omega \S Y \times \Omega \S Y \xrightarrow[]{\#}\Omega \S X\end{equation*}
the final map being concatenation of loops.

\begin{rmk}
Concatenation of loops in the filtered sense is a morphism of shift $\lfloor \Omega Y \rfloor$, consider 

\begin{equation*}(\Omega Y \times \Omega Y)^{\leq t} \xrightarrow{\#}(\Omega Y)^{\leq t+a}\end{equation*}
we see that $a=\lfloor \Omega Y \rfloor$ since the map is given by

\begin{equation*}(\Omega Y)^{\leq t-\lfloor \Omega Y \rfloor} \times (\Omega Y)^{\leq t-\lfloor \Omega Y \rfloor}\xrightarrow{\#} (\Omega Y)^{\leq t+a}\end{equation*}

\begin{equation*}\Omega( Y^{\leq t-\lfloor \Omega Y \rfloor+1}) \times \Omega( Y^{\leq t-\lfloor \Omega Y \rfloor+1})\xrightarrow{\#} \Omega (Y^{\leq t-\lfloor \Omega \rfloor +1})=(\Omega Y)^{\leq t- \lfloor\Omega Y \rfloor}\end{equation*}

where the second $\#$ is concatonation of loops in the $\text{Top}_*$.
\end{rmk}



In $\text{Ho} \ff \text{Spectra}$ (the stable filtered homotopy category) we have that $\S$ and $\Omega$ are inverses since 

\begin{equation*}(\Omega \S X)^{\leq r}=\Omega ((\S X)^{\leq r+1})= \Omega  \S (X^{\leq r+1-1})\cong \Omega\S(X(r))\cong X(r)  \end{equation*}


for all $r\in \R$. Hence 
\begin{equation*}[(X,\ff_X),(Y,\ff_Y)]^r \simeq [(X,\ff_X),\Omega\S (Y,\ff_Y)]^r\end{equation*}



Now let $f,g:(X,\ff_X) \to (Y,\ff_Y)$ be morphisms of shift $r$ and consider the composition (ommiting the filtration on morphisms for space)

\begin{equation*}\begin{tikzcd}
X^{\leq t}\arrow[rrrdd,dotted,"(f+g)^{\leq t}"]\arrow[r,"\Delta"] & (X \times X)^{\leq t+ \lfloor X \rfloor}\arrow[r,"f\times g"] & (Y \times Y)^{\leq t+\lfloor Y \rfloor +r }\arrow[r,equals] & (\Omega \S Y \times \Omega \S Y)^{\leq t+\lfloor Y \rfloor +r}\arrow[d,"\#"]\\
& & & (\Omega \S Y)^{\leq t +r}\arrow[d,equals]\\
& & & Y^{\leq t +r }\\
\end{tikzcd}\end{equation*}

Recalling that if $f,g$ have shift $r$ then $\lceil f \times g \rceil = r+(\lfloor Y \rfloor - \lfloor X \rfloor)$, and that concatention of the loops in $\Omega \S Y$ has shift $-\lfloor \Omega \S Y \rfloor = -\lfloor Y \rfloor$.

This operation 
\begin{equation*}[(X,\ff_X),(Y,\ff_Y)]^r  \times [(X,\ff_X),(Y,\ff_Y)]^r \xrightarrow{+} [(X,\ff_X),(Y,\ff_Y)]^r \end{equation*}

gives $[(X,\ff_X),(Y,\ff_Y)]^r $ the structure of an abelian group


\end{proof}
\end{prop}


\begin{rmk}
The zero object in $\text{Ho} \ff \text{Spectra}$ is given by $(\S^\infty *,0)$.
\end{rmk}


\subsubsection{Shift Functors}

\begin{defn}
Again we can define a natural functor for every $r\in \R$ denoted $\ss^r:\ff \text{Spectra} \to \ff \text{Spectra}$, given by
\begin{equation*}\mathcal{S}^r(X,\ff_X):= (\ss^r X,\ff_X - r)\end{equation*}
again where $\ss X=X$ and $\ff_X+r$ is the filtration given by
\begin{equation*}(\ss^r X)_n^{\leq s}=X_n^{\leq s-r}.\end{equation*}

\end{defn}
\begin{lemma}
$\text{Ho} \ff \text{Spectra}$ is a persistence category with shift functor $\ss$.
\begin{proof}
By construction.

\end{proof}
\end{lemma}

\begin{lemma}
The category $\text{Ho} \ff \text{Spectra}_0$, the subcategory of $\text{Ho} \ff \text{Spectra}$ who's morphisms consist of all morphisms with zero shift, is triangulated, with exact triangles isomorphic to triangles of the form
\begin{equation*}(X,\ff_X) \xrightarrow{\varphi} (Y,\ff_Y) \xrightarrow{\iota} \text{Cone}(\varphi) \xrightarrow{j} \ss^{-1}  \S(X,\ff_X)\end{equation*} 
\begin{proof}
 The data of the exact triangles are given by
\begin{equation*}\begin{tikzcd}X(r)\arrow[r,"\varphi^{\leq r}"]& Y(r)\arrow[r,"\iota^{\leq r}"]& \text{Cone}(\varphi^{\leq r})\arrow[r,"j^{\leq r}"]&  \ss^{-1}{\S} X(r)\\
X(s)\arrow[r,"\varphi^{\leq s}"]\arrow[u,"i_{s,r}",hook] & Y(s) \arrow[r,"\iota^{\leq s}"]\arrow[u,"i_{s,r}",hook]& \text{Cone}(\varphi^{\leq s})\arrow[r,"j^{\leq s}"]\arrow[u,"i_{s,r}",hook] & \ss^{-1}{\S}X(s)\arrow[u,"i_{s,r}",hook]\end{tikzcd}\end{equation*}
i.e., exact triangles in the usual stable homotopy category that commute with the inclusion maps $i_{s,r}$ for all $s<r$. The axioms for a triangulated category follow (almost) directly from the fact the stable homotopy category is triangulated. The main axiom to check is that if we have a diagram 
\begin{equation*}\begin{tikzcd}(X,\ff_X)\arrow[r,"\varphi"]\arrow[d,"f"] & (Y,\ff_Y)\arrow[r,"\iota"]\arrow[d,"g"] & \text{Cone}(\varphi)\arrow[r,"j"] & \ss^{-1}{\S} (X,\ff_X)\arrow[d,"\ss^{-1}{\S} f"]\\
(X',\ff_{X'}) \arrow[r,"\psi"]& (Y',\ff_{Y'}\arrow[r,"\iota'"]) & \text{Cone}(\psi)\arrow[r,"j'"] & \ss^{-1}{\S} (X',\ff_{X'})\end{tikzcd}\end{equation*} 
with the first square commuting then there exists a morphism $\nu$ making every square commute in
\begin{equation*}\begin{tikzcd}(X,\ff_X)\arrow[r,"\varphi"]\arrow[d,"f"] & (Y,\ff_Y)\arrow[r,"\iota"]\arrow[d,"g"] & \text{Cone}(\varphi)\arrow[r,"j"]\arrow[d,"\nu",dotted] & \ss^{-1}{\S}(X,\ff_X)\arrow[d,"\ss^{-1}{\S}f"]\\
(X',\ff_{X'}) \arrow[r,"\psi"]& (Y',\ff_{Y'}\arrow[r,"\iota'"]) & \text{Cone}(\psi)\arrow[r,"j'"] & \ss^{-1}{\S} (X',\ff_{X'})\end{tikzcd}\end{equation*}

By the triangulated structure of the stable homotopy category for every $r\in \R$ we can construct a morphism $\nu^{\leq r}$ making 
\begin{equation*}\begin{tikzcd}
X(r)\arrow[r,"\varphi^{\leq r}"]\arrow[d,"f(r)"]& Y(r)\arrow[r,"\iota^{\leq r}"]\arrow[d,"g^{\leq r}"]& \text{Cone}(\varphi^{\leq r})\arrow[r,"j^{\leq r}"]\arrow[d,"\nu^{\leq r}",dotted]&  \ss^{-1}{\S} X(r)\arrow[d,"\ss^{-1}{\S} f(r)"]\\
X'^{\leq r}\arrow[r,"\psi^{\leq r}"]& Y'^{\leq r}\arrow[r,"\iota^{\leq r}"]& \text{Cone}(\psi^{\leq r})\arrow[r,"j^{\leq r}"]&  \ss^{-1}{\S} X'^{\leq r}
\end{tikzcd}\end{equation*}
commute. This map can be formed since $Cone$ is a colimit ????
\end{proof}
\end{lemma}

\begin{prop}
The shift functors $\ss^r$ are compatible with the triangulated structure of the zero category $Ho\ff \text{Spectra}_0$.

\end{prop}


\begin{lemma}
For any $r\geq 0$ the map $(\eta_{r})^X:\ss^r (X,\ff_X) \to (X,\ff_X)$ embeds into an exact triangle 
\begin{equation*}\ss^r(X,\ff_X) \xrightarrow{(\eta_r)^X} (X,\ff_X) \to K \to \ss^{-1}{\S} \ss^r(X,\ff_X)\end{equation*}
with $K$ r-acyclic.

\begin{proof}
Sketch: Take $K= \text{Cone}((\eta_r)^X)$,

\begin{align*}
K^{\leq t}=&\text{Cone}((\ss^r X)^{\leq t} \xrightarrow{\eta_{r,o}} X^{\leq t-r}\xrightarrow{i_{-r,0}}X^{\leq t})\\
=&\text{Cone}(X^{\leq t-r}\xrightarrow{\cong} X^{\leq t-r}\xrightarrow[]{(i_{r,0})_*}X^{\leq t})\\
&\simeq X^{\leq t}/X^{\leq t-r}
\end{align*}

Being $r$-acyclic is equivalent to the map $\eta_r^K=0$ by Lemma 3.3.4 in \cite{OctPauJun}. We have that $\eta_r^K$ is the map
\begin{equation*}X^{\leq t}/X^{\leq t-r} \to X^{\leq r+ t}/X^{\leq t}\end{equation*}

given by inclusion, which is null-homotopic, and hence $K$ is $r$-acyclic.

\end{proof}
\end{lemma}

The above lemmas/propositions prove that $\text{Ho} \ff \text{Spectra}$ is a TPC.

