           {[n']}(X',k')\ar[r,"{[n']f'}"]\ar[d,"\cong"] & {[n']}(Y',l')\ar[r,"{[n']g'}"]\ar[d,"\cong"]  & {[n']}(Z',m')\ar[r,"{[n']h'}"] \ar[d,"\cong"] & {[n'+1]}(X',k')\ar[d,"\cong"] \\
           (\bar{X}',0)\ar[r,"\iota_0(\bar{f}')"] & (\bar{Y}',0)\ar[r,"\iota_0(i')"] & (\text{Cone}(\bar{f}'),0)\ar[r,"\iota_0(j')"] & {[1]}(\bar{X}',0)
       \end{tikzcd}
   \end{equation*}
hence we can produce a diagram 

\begin{equation*}
    \begin{tikzcd}
           (\bar{X},n')\ar[r,"{[n']\iota_0(\bar{f})}"] \ar[d,"u'"]& (\bar{Y},n')\ar[d,"v'"]\ar[r,"{[n']\iota_0(i)}"] & (\text{Cone}(\bar{f}),n')\ar[r,"{[n']\iota_0(j)}"] & {[1]}(\bar{X},n')\ar[d,"{[1]u'}"]\\
           (\bar{X}',n)\ar[r,"{[n]\iota_0(\bar{f}')}"] & (\bar{Y}',n)\ar[r,"{[n]\iota_0(i')}"] & (\text{Cone}(\bar{f}'),n)\ar[r,"{[n]\iota_0(j')}"] & {[1]}(\bar{X}',n)
    \end{tikzcd}
\end{equation*}
Hence we want to produce an morphism $w':(\text{Cone}(\bar{f}),0) \to (\text{Cone}(\bar{f}'),0)$, making this diagram commute. We may assume this is induced by the diagram

\begin{equation*}
    \begin{tikzcd}
        \S^{n'}\bar{X} \ar[r,""]& \S^{n'}\bar{Y} & \S^{n'}\text{Cone}(\S^{n'}\bar{f}) & \S^{n'+1}\bar{X}
    \end{tikzcd}
\end{equation*}

\end{itemize}






































\section{A smash product for Filtered Spectra}

In general defining a smash product, i.e., a tensor product, such as to form a symmetric monodial category of spectra, is difficult. One way to do so is via \textbf{$\Gamma$-Spaces}.

\begin{defn}
We denote by $\Gamma^{op}$, the category whose objects are given by finite sets 
\begin{equation*}\underbar{n}:=\{*,1,2,\hdots, n\},\end{equation*}
for all $n\in \N$ and noting that $\underbar{0}=*$. The morphisms are functions of finite sets that preserve $*$.
\end{defn}


\begin{defn}
A $\Gamma$-space is a functor 
\begin{equation*}A:\Gamma^{op} \to \text{Top}_*\end{equation*}
such that the \textbf{Segal maps}
\begin{equation*}A(\underbar{n}) \to A(\underbar{1}) \times A(\underbar{1}) \times \hdots A(\underbar{1})\end{equation*}
are weak equivalences. Note here that the Segal maps are induced by the unique morphisms $\underbar{1} \xrightarrow{\phi_k} \underbar{n}\in \Gamma$,defined by $1\mapsto k$.
We also require that 
\begin{equation*}A(\underbar{0})\simeq_{w.e}*\end{equation*}
i.e., the empty Segal map is a weak equivalence.
\end{defn}

\begin{defn}
There is a natural tensor product 
\begin{equation*}\Smash: \Gamma^{op}\times \Gamma^{op}\to \Gamma^{op}\end{equation*}
given by
\begin{equation*}\underbar{n}\Smash \underbar{m}:= \frac{\underbar{n} \times \underbar{m}}{\underbar{n}\vee \underbar{m}}\cong_{\in \Gamma^{op}} \underbar{n\cdot m}\end{equation*}
Note this tensor can be extended to a tensor on the category of finite sets. 

\end{defn}
\begin{rmk}
There exists a functor 
\begin{equation*}\delta:\Delta^{op} \to \Gamma^{op}\end{equation*}
defined on objects by
\begin{equation*}\delta([n])=\underbar{n}\end{equation*}


Hence given a $\Gamma$-space $A$, we obtain an underlying simplicial space given by $A \circ \delta$.
\end{rmk}
\begin{defn}
Given a $\Gamma$-space $A$, we write 
\begin{equation*}|A|:=|A \circ \delta|\end{equation*}
the geometric realisation of (the underlying simplicial space) of $A$.
\end{defn}

\begin{defn}
Let $A$ be a $\Gamma$-space, and $\underbar{n}\in \Gamma^{op}$, we can define a new $\Gamma$-space $A_{\underbar{n}}:\Gamma^{op} \to \text{Top}_*$ by 
\begin{equation*}A_{\underbar{n}}(\underbar{m}):=A(\underbar{m}\Smash \underbar{n})\end{equation*}
note that $A_{\underbar{n}}(\underbar{0})=A(\underbar{0}\Smash \underbar{n})=A(\underbar{0})$
\end{defn}


\begin{defn}
Now given a $\Gamma$-space $A$, we define it's \textbf{classifying space} or \textbf{delooping} by the $\Gamma$-space:

\begin{equation*}BA:\Gamma^{op}\to \text{Top}_*\end{equation*}
\begin{equation*}BA(\underbar{n}):=|A_{\underbar{n}}|=|\underbar{m}\mapsto A(\underbar{m}\Smash \underbar{n})|\end{equation*}


\end{defn}

\begin{rmk}
There is an isomorphism
\begin{equation*}BA(\underbar{1})= A_{\underbar{1}}\cong |A|\end{equation*}
\end{rmk}


Note that we can view $\underbar{1}$ as the zero-sphere $S^0$.

\begin{defn}
Let $A$ be a $\Gamma-$space, there is a natrual map 

\begin{equation*}\sigma^A:\S A(S^0)\to BA(S^{0}) \end{equation*}
i.e., a map
\begin{equation*}\sigma^A:\S A(S^0) \to |A|\end{equation*}

which is exactly the inclusion of the image of the $1$-skeleton of $A\circ \delta$. Therefore we obtain a spectrum $\Tilde{A}$, given by:


\begin{equation*}\Tilde{A}_n:=B^nA(S^0)\end{equation*}

with structure maps
\begin{equation*}\sigma_n=\sigma^{B^nA}:\S B^nA(S^0) \to B^{n+1}A(S^0)\end{equation*}
\end{defn}
\begin{rmk}
The adjoin structure maps
\begin{equation*}\sigma_n^t:B^nA(S^0) \to \Omega B^{n+1}A(S^{0})\end{equation*}
are weak-equivalences (for $n>0$).
\end{rmk}
\begin{defn}
The \textbf{smash product} of $\Gamma$-spaces is given by
\begin{equation*}A\Smash B(\underbar{n}):=colim_{\underbar{k}\Smash\underbar{l}=\underbar{n}}\big(A(\underbar{k})\Smash B(\underbar{l})\big)\end{equation*}
\end{defn}
The category of $\Gamma$-spaces has homotopy category equivalent to the stable homotopy category of spectra.






\begin{eg}
Write 
\begin{equation*}\mathbb{S} :\Gamma^{op}\to \text{Top}_*\end{equation*}
to denote the $\Gamma$-space given by 

\begin{equation*}\mathbb{S}(\underbar{n}):=\Gamma^{op}(\underbar{1},\underbar{n})=\bigvee^n_{i=1}S^0\end{equation*}

We then have
\begin{equation*}\mathbb{S}(\underbar{1})=S^0\end{equation*}
\begin{equation*}B\mathbb{S}(\underbar{1})=|\mathbb{S}|\end{equation*}
\end{eg}







\subsection{Filtered $\Gamma$-Spaces}
\begin{defn}
Let $A:\Gamma^{op}\to \ff \text{Top}_*$ be a functor such that
the \textbf{Segal maps}
\begin{equation*}A(\underbar{n}) \to A(\underbar{1}) \times A(\underbar{1}) \times \hdots A(\underbar{1})\end{equation*}
are $0$-weak equivalences and
\begin{equation*}A(\underbar{0})\simeq_{0} *\end{equation*}
i.e., the empty Segal map is a weak equivalence.

Restating:

\begin{equation*}A(\underbar{n})^{\leq r} \to A(S^0)^{\leq r-(n-1)\lfloor A(S^0) \rfloor}\times \hdots \times A(S^0)^{\leq r- (n-1)\lfloor A(S^0) \rfloor}\end{equation*}
is a weak equivalence for all $r\in \R$, $n>0$. And 
$A(\underbar{0})^{\leq r}$ is contractible for all $r$.
\end{defn}

\begin{rmk}
A filtered $\Gamma$-space admits a canonical filtration given by

\begin{equation*}A^{\leq r}(\underbar{n}):=(A(\underbar{n}))^{\leq r}\end{equation*}
\end{rmk}

Precomposing with $\delta$ as above we obtain an underlying filtered simplicial space,

\begin{equation*}A \circ \delta :\Delta^{op}\to \ff \text{Top}_*\end{equation*}




\begin{defn}
Given a filtered $\Gamma$-space, $A$, write 
\begin{equation*}|A|:=|A \circ \delta| \in \ff \text{Top}_*\end{equation*}
the filtered geometric realisation where
\begin{equation*}|A|^{\leq r}:=|A \circ \delta|^{\leq r}=|(A^{\leq r }\circ \delta)|\end{equation*}
\end{defn}

\begin{defn}
Given a filtered $\Gamma$-space, $A$, and $\underbar{n}\in \Gamma^{op}$, we obtain a new filtered $\Gamma$-space:

\begin{equation*}A_{\underbar{n}}:\Gamma^{op}\to \ff \text{Top}_*\end{equation*}
given by

\begin{equation*}(A_{\underbar{n}})^{\leq r}(\underbar{m}):=A^{\leq r}(\underbar{m}\Smash \underbar{n})\end{equation*}
\end{defn}

\begin{defn}
The \textbf{filtered delooping/ classifying space} of a filtered $\Gamma$-space is the new filtered $\Gamma$-space
\begin{equation*}BA:\Gamma^{op} \to \ff \text{Top}_* \end{equation*}
\begin{equation*}(BA)^{\leq r}(\underbar{n}):=|A^{\leq r}_{\underbar{n}}|=|A_{\underbar{n}}|^{\leq r}\end{equation*}
\end{defn}

\begin{eg}
\begin{equation*}B \mathbb{S} ^{\leq r}(S^0)=|\mathbb{S}_{S^0}^{\leq r}|=|\underbar{n}\mapsto \mathbb{S}(S^0 \Smash \underbar{n})|^{\leq r}=|\mathbb{S}|^{\leq r}\end{equation*}
\end{eg}



\begin{defn}
The spectrum associated to a filtered $\Gamma$-space $A$, is given by 

\begin{equation*}\Tilde{A}_n^{\leq r}=(B^nA)^{\leq r}(S^{0})\end{equation*}
with structure maps
\begin{equation*}\sigma_n^{\leq r}:\S (B^nA)^{\leq r}(S^0) \to (B^{n+1}A)^{\leq r-1}(S^0) \end{equation*}
\begin{equation*}\sigma_n^{\leq r}: \S \Tilde{A}_n^{\leq r} \to \Tilde{A}_{n+1}^{\leq r-1}\end{equation*}
given by the inclusion of the $1$-skeleton.
\end{defn}


We can then define a smash product of filtered $\Gamma$-spaces by 

\begin{equation*}(A \Smash B)^{\leq r}(\underbar{n}):=colim_{\underbar{l}\Smash \underbar{k}=\underbar{n}}A^{\leq r-\lfloor B \rfloor}(\underbar{l}) \Smash B^{\leq r- \lfloor A \rfloor}(\underbar{k})\end{equation*}


\begin{eg}[The filtered suspension spectrum]
Given a filtered space $X$, consider the filtered $\Gamma$-space,
\begin{equation*}\mathbb{S}\Smash X\end{equation*}
given by 
\begin{align*}
(\mathbb{S}\Smash X)^{\leq r}(\underbar{n})&=(\mathbb{S}(\underbar{n})\Smash X)^{\leq r}   \\
&=\mathbb{S}(\underbar{n})^{\leq r-\lfloor X \rfloor}\Smash X(r)\\
&=\begin{cases}(\bigvee_{i=1}^{\lfloor r -\lfloor X \rfloor \rfloor}S^0) \Smash X(r) & r-\lfloor X \rfloor <n\\
(\bigvee^{n}_{i=1} S^0) \Smash X(r) & r-\lfloor X \rfloor \geq n\end{cases}
\end{align*}

We then have 

\begin{equation*}(\mathbb{S}\Smash X)(\underbar{1})^{\leq r}=\begin{cases}S^0 \Smash X(r)=* & r<\lfloor X \rfloor\\
S^0 \Smash X(r)= X(r) & r\geq \lfloor X \rfloor
\end{cases}=X(r)\end{equation*}
\end{eg}
and that

\begin{align*}
B(\mathbb{S}\Smash X)(\underbar{1})^{\leq r}&= B(\mathbb{S}^{\leq r-\lfloor X \rfloor}\Smash X(r))(\underbar{1})\\
&=|(\mathbb{S}^{\leq r-\lfloor X \rfloor}\Smash X(r))_{\underbar{1}}|\\
&=|\underbar{n}\mapsto (\mathbb{S}^{\leq r - \lfloor X \rfloor}\Smash X(r))(\underbar{n})|\\
&=|\underbar{n}\mapsto \mathbb{S}^{\leq r-\lfloor X \rfloor}(\underbar{n})\Smash X(r)|\\
&=|\mathbb{S}^{\leq r-\lfloor X \rfloor}\Smash X(r)|
\end{align*}


We see that 
\begin{equation*}(\mathbb{S}^{\leq r-\lfloor X \rfloor}\Smash X(r) )\circ \delta ([1])=\begin{cases}* & r<1\\
S^0 \Smash X(r)=X(r) & r\geq 1\end{cases}\end{equation*}
hence looking at the first stage of the geometric realisation  of $|\mathbb{S}^{\leq r-\lfloor X \rfloor}\Smash X(r)|$ we see it is formed by attaching 
\begin{equation*}X^{\leq r-1}\times \Delta^1\end{equation*}
to $*$ via the face maps $\Delta^1(0)=*$ and $\Delta^1(1)=*$, i.e., 
\begin{equation*}X^{\leq r -1} \times I/(X^{\leq r-1}\times \{0,1\}\cup *\times I)\end{equation*}
the reduced suspension of $X^{\leq r-1}$. It follows (by repeating this process) that the spectrum associated to $\mathbb{S}\Smash X$ is the filtered suspension spectrum of $X$.





\begin{eg}[Filtered Eilenberg-MacLane spectra]
Let $G_0 \subset G_1 \subset ... \subset G_k=G$ be a filtration of $G$ by subgroups. This defines a cannonical filtered space $(G,\ff)$ given by
\begin{equation*}G^{\leq r}:=\begin{cases}G & r\geq k\\
G_{\lfloor r \rfloor} & 0\leq r < k\\
* & r< 0\\\end{cases}\end{equation*}
We define a filtered $\Gamma$-space $HG: \Gamma^{op}\to \ff \text{Top}_*$ by 

\begin{equation*}(HG)^{\leq r}(\underbar{n}):= G^{\leq r}\otimes \Z\langle \underbar{n}\rangle\end{equation*}

the associated filtered spectrum defines a filtered Eilenberg-MacLane spectrum, i.e., 

\begin{equation*}B^n(HG)(\underbar{1})^{\leq r}\cong K(G^{\leq r},n)\end{equation*}
See (~~).
A \textbf{$\Gamma$-ring} is a monoid in the categgory of $\Gamma$-spaces (with smash product) and so consists of a $\Gamma$-space $R$ and maps 
\begin{equation*}\mathbb{S}\xrightarrow[]{\eta} R\end{equation*}
\begin{equation*}R \Smash R \xrightarrow[]{p} R\end{equation*}
or equivelently maps
\begin{equation*}\bigvee^n_{i=1} S^0=\mathbb{S}(\underbar{n}) \xrightarrow{p_n} R(\underbar{n})\end{equation*}
\begin{equation*}R(\underbar{k})\Smash R(\underbar{l}) \xrightarrow[]{p_{k,l}}R\Smash R(\underbar{k}\Smash \underbar{l})\end{equation*}

satisfying the usual relations for a monoid object.






It is easy to check that if $G$ is a filtered ring (i.e., $G_i$ is a ring for all $i$) then $(HG)^{\leq r}$ is $\Gamma$-ring. Defining a \textbf{filtered $(s)$-$\Gamma$-ring} to be a monoidal object in $\ff \Gamma T$ the category of filtered $\Gamma$-spaces with tensor $\Smash$, we see that the filtered $\Gamma$-space $HG$ is a filtered $(\lfloor G \rfloor)-\Gamma$-ring via the cannonical maps

\begin{equation*}\begin{tikzcd}(HG(\underbar{k}) \Smash HG(\underbar{l}))^{\leq r}\arrow[r,equal]\arrow[ddrr,"p_{k,l}"] & HG(\underbar{k})^{\leq r- \lfloor G \rfloor} \Smash HG(\underbar{l})^{\leq r-\lfloor G \rfloor}\arrow[r,equal] & G^{\leq r- \lfloor G \rfloor} \otimes \Tilde{\Z}\langle \underbar{k}\rangle \Smash G^{\leq r - \lfloor G \rfloor} \otimes \Tilde{\Z}\langle \underbar{l}\rangle\arrow[d,"p_{k,l}"]\\
& &  G^{\leq r- \lfloor G \rfloor}\otimes \Tilde{\Z}\langle \underbar{k}\Smash \underbar{l}\rangle\arrow[d,equal]\\
& & HG(\underbar{k}\Smash \underbar{l})^{\leq r- \lfloor G \rfloor}
\end{tikzcd}\end{equation*}
induced by the ring structure of $G^{\leq r-\lfloor G \rfloor}$.

(WHere do unit maps go?)


\begin{rmk}
The spectrum associated to a filtered $\Gamma$-ring is a filtered ring-spectrum, i.e., a monoid in $\ff \text{Spectra}$.
\end{rmk}

