\section{The Filtration construction $\ff$ and TPCs}


Note the similarity in constructing $\ff \text{Top}_*$ and $\ff \text{Spectra}_*$, this construction is not unique to these categories in particular. We can extend construction to all categories, and the resulting `filtered' category will have different properties depending on the properties of the original category. 


\begin{defn}
Given a category $\cc$ with a zero object $0\in \cc$, we define a \textbf{filtered object} in $\cc$ to be a functor 

\begin{equation*}A:(\R,\leq) \to \cc \end{equation*}
such that 

\begin{itemize}
    \item $A(r)$ is a sub-object of $A(s)$ for all $r<s$.
    \item There exists a $r_0\in \R$ such that for all $r<r_0$ we have $A(r)=0 \in C$. We write $\lfloor A \rfloor$ for this such $r_0$.
    \item The collection $\{A(r)\}_{r\in \R}$, that is, the image of the functor $A$, forms an exhaustion of some object $A_\infty\in \cc$.
\end{itemize}
\begin{rmk}
Note that we actually require for every subobject $A(r)$ of $A(s)$ a choice of monomorphism $A(r) \hookrightarrow A(s)$, which we will denote $i^A_{r,s}$. 
We can require a stronger condition than $A(r)$ being simply a sub-object of $A(s)$ for all $r<s$, for example we required for filtered topological spaces that they are in fact inclusions of subspaces, i.e., we add the requirement that each $i^A_{r,s}$ is an inclusion of subsapces.
\end{rmk}
\begin{defn}
Given a filtered object $A: (\R,\leq) \to \cc$, we define it's \textbf{$s$-shift} to be the new filtered object
\begin{equation*}A^s:(\R,\leq) \to \cc\end{equation*}
such that 
\begin{equation*}A^s(r):= A(r-s)\end{equation*}
\end{defn}
A \textbf{morphsim of shift $s$} between two such filtered objects $A$ and $B$ is a natural transformation 

\begin{equation*}f: A \to B^s\end{equation*}
i.e., a collection of morphisms (in $\cc$) 
\begin{equation*}f(r): A(r) \to B^s(r)\end{equation*}
that commute with the choice of sub-object morphisms. Given an arbitrary morphism of filtered objects we write $\lceil f \rceil$ for it's shift.
\end{defn}
We can compose morphisms in the obvious way; say we have  $f:A \to B$ and $g: B \to C$ then $g \circ f(r): A(r) \to C^{\lceil f \circ g \rceil}(r)$ is given by

\begin{equation*}A(r) \xrightarrow{f(r)}B^{\lceil f \rceil}(r) \xrightarrow{g(r-\lceil f \rceil)}C^{\lceil g \rceil}(r- \lceil f \rceil)=C^{\lceil f \rceil + \lceil g \rceil}(r)\end{equation*}
We then define a category $\ff \cc$, whose objects are filtered objects of $\cc$ and whose morphisms are the collection of all morphisms of shift $s$ for all $s\in \R$. Note there is a natural collection of `shift functors' $\{\ss^a:\ff \cc \to \ff \cc\}_{a\in \R}$, given by
\begin{equation*}\ss^a (A):=A^{-a}\end{equation*}
we obtain isomorphisms
\begin{equation*}\eta^A_{a,b}:\ss^a \to \ss^b\end{equation*}
with $\lceil\eta^A_{a,b}\rceil=b-a$
given by the identity maps 
\begin{equation*}\eta^A_{a,b}(r)=A(r+a) \to A(r+a+(b-a))=A(r+b).\end{equation*}


There also exist maps
\begin{equation*}\iota_{r,s}:\text{Mor}^r(A,B) \to \text{Mor}^s(A,B)\end{equation*}
for all $r<s$ given by post-compostion with the morphisms $i^B_{r,s}$, where $\text{Mor}^r(A,B)=\{f\in \text{Hom}_{\ff \cc}(A,B): \lceil f \rceil = r\}$. We again denote by $\eta^A_a:  A\to \ss^{-a} A$

\begin{equation*}\eta_a^A=\iota_{-a,0}\circ \eta^A_{0,-a}\end{equation*}
for $a\geq 0$.
\begin{theorem}

Let $\cc$ be an additive category, then $\ff \cc$ forms a persistence category.

\begin{proof}
Firstly we have the product of two filtered objects $A,B$ is the new filtered object: 

\begin{equation*}(A \prod B): (\R,\leq) \to \cc\end{equation*}
\begin{equation*}(A \prod B)(r) := A^{-\lfloor B \rfloor}(r) \prod B^{-\lfloor A \rfloor}(r) \end{equation*}

We will show that the sets $\text{Mor}^s(A,B):=\{f: A \to B: f \text{ natural transformation }, \lceil f \rceil = s\}$ form an abelian group. 


Assume we have two morphisms $f,g \in \text{Mor}^s(A,B)$, we construct a new morphism $f+g \in \text{Mor}^s(A,B)$ as follows:

Firstly consider the morphism

\begin{equation*}A \xrightarrow{\Delta_A} (A \prod A)\end{equation*}
 of shift $\lceil \Delta_A \rceil = \lfloor A \rfloor$, given by 
\begin{equation*}\Delta_A(r)(a)=(a,a)\in A(r) \prod A(r)\end{equation*}
and then consider the morphism
\begin{equation*}(A \prod A) \xrightarrow{f \prod g}( B \prod B)\end{equation*}
given by

\begin{equation*}(A \prod A)(r) \xrightarrow{(f \prod g)(r)}( B \prod B)^{\lceil f \prod g \rceil}(r)\end{equation*}
noting that
\begin{align*}
(B \prod B)^k(r)=&(B \prod B)(r-k)\\
=&B^{-\lfloor B \rfloor}(r-k) \prod B^{-\lfloor B \rfloor}(r-k)\\
=& B^{-\lfloor B \rfloor+k}(r)\prod B^{-\lfloor B \rfloor +k}(r)\\
\end{equation*}
\begin{equation*}A^{-\lfloor A \rfloor}(r) \prod A^{-\lfloor A \rfloor}(r) \xrightarrow{(f \prod g) (r)}B^{-\lfloor B \rfloor + \lceil f \prod g \rceil}(r)\prod B^{-\lfloor B \rfloor + \lceil f \prod g \rceil}(r)    
\end{align*}

\begin{equation*}(a_1,a_2) \mapsto (f(r)(a_1),g(r) (a_2))\end{equation*}

in particular $\lceil f \prod g \rceil= s+(\lfloor B \rfloor - \lfloor A \rfloor)$. 

We remark that since $\cc$ is an additive category there exists a codiagonal map 
\begin{equation*}\nabla_X: X \prod X \to X\end{equation*}
 for all $X\in \cc$ that satisfies $\nabla_X \circ \Delta_X \cong id_X$, we can therefore form a map

\begin{equation*}\nabla_B: (B \prod B) \to B\end{equation*}

where 
\begin{equation*}\nabla_B(r): B^{-\lfloor B \rfloor}(r) \prod B^{-\lfloor B \rfloor}(r) \to B^{  \lceil \nabla_B \rceil}\end{equation*}
is given by $\nabla_B(r):=\nabla_{B(r)}$. We have that $\lceil \nabla_B \rceil = -\lfloor B \rfloor$

Finally we define $f+g$ by composition

\begin{equation*}A \xrightarrow{\Delta_A(r)} (A \prod A)^{\lceil \Delta_A \rceil} \xrightarrow{f \prod g(r+\lceil \Delta_A \rceil)}(B \prod B)^{\lceil \Delta_A \rceil + \lceil f \prod g \rceil} \xrightarrow{\nabla_B(r+\lceil \Delta_A \rceil + \lceil f \prod g \rceil)} B^{\lceil \Delta_A \rceil + \lceil f \prod g \rceil + \lceil \nabla_{B^{}}\rceil}\end{equation*}

and find that 
\begin{align*}
\lceil f + g \rceil&=\lceil \Delta_A \rceil + \lceil f \prod g \rceil + \lceil \nabla_B \rceil \\
&= \lfloor A \rfloor + s + (\lfloor B \rfloor - \lfloor A \rfloor) - \lfloor B \rfloor\\
&= s
\end{align*}

It is then easy to check that the map 
\begin{equation*}+:\text{Mor}^s(A,B) \times \text{Mor}^s(A,B) \to \text{Mor}^s(A,B)\end{equation*}
defines an abelian operation with identitiy $0$ given by the trivial map 
\begin{equation*}0: A \to B^s\end{equation*}
\begin{equation*}0(r)(a) =0 \in B^s(r).\end{equation*}
Given $f \in \text{Mor}^s(A,B)$ it's inverse is given by $f^{-1}$ where
\begin{equation*}f^{-1}(r) = (f(r))^{-1}\in \text{Hom}(A(r), B^s(r))\end{equation*}

One can check this is well defined. To do so consider the diagram in $\cc$

\begin{equation*}\begin{tikzcd}
A \arrow[r,"f"]& B \\
 & B^s(r)\arrow[u,"i^{B^s}_r",hook]
\end{tikzcd}\end{equation*}
where, with abuse of notation, $A:=\text{colim}_t\{A(t)\}$, $B:=\text{colim}_t\{B(t)\}$ and $f:=\text{colim}_{t}\{f(t)\}$, where colimits are taken over the sub-object morphisms.

One can see that the pullback of the above diagram is given by

\begin{equation*}\begin{tikzcd}A \arrow[r,"f"]& B \\
A(r)\arrow[u,"i^A_r",hook]\arrow[r,swap,"f(r)=(i_r^{B^s})^*f"] & B^s(r)\arrow[u,"i^{B^s}_r",hook]\end{tikzcd}\end{equation*}

and also that all squares below are pullback squares that commute 
\begin{equation*}\begin{tikzcd}A \arrow[r,"f"]& B \\
A(r)\arrow[u,"i^A_r",hook]\arrow[r,swap,"f(r)"] & B^s(r)\arrow[u,"i^{B^s}_r",hook]\\
A(t)\arrow[u,"i^A_{t,r}",hook]\arrow[r,"f(t)"] & B^s(t)\arrow[u,hook,"i_{t,r}^{B^s}"]\end{tikzcd}\end{equation*}

Now since $\cc$ is additive we have an diagram induced by $f$:

\begin{equation*}\begin{tikzcd}
A \arrow[r,"f^{-1}"]& B \\
 & B^s(r)\arrow[u,"i^{B^s}_r",hook]
\end{tikzcd}\end{equation*}

hence pulling this diagram back (twice) we obtain a commutative diagram

\begin{equation*}\begin{tikzcd}A \arrow[r,"f^{-1}"]& B \\
A(r)\arrow[u,"i^A_r",hook]\arrow[r,swap,"f^{-1}(r)"] & B^s(r)\arrow[u,"i^{B^s}_r",hook]\\
A(t)\arrow[u,"i^A_{t,r}",hook]\arrow[r,"f^{-1}(t)"] & B^s(t)\arrow[u,hook,"i_{t,r}^{B^s}"]\end{tikzcd}\end{equation*}

Lastly, we note that there exist module morphisms
\begin{equation*}\iota_{r,s}:\text{Mor}^r(A,B) \to \text{Mor}^s(A,B)\end{equation*}
induced by the sub-object morphisms, i.e
\begin{equation*}\iota_{r,s}(f)=i^B_{r,s}\circ f\end{equation*}
\end{proof}




\end{theorem}

\begin{theorem}

Given a triangulated category $\cc$, such that exact triangles are of the form

\begin{equation*}A \xrightarrow{f} B \xrightarrow{} \text{Cone}(f) \xrightarrow{}T A\end{equation*}

moreover assume that $\text{Cone}(f)\cong B/A$, then it's filtered category $\ff \cc$ is a Triangulated persistence category. 

\end{theorem}
\begin{rmk}
We can assume $cc$ to be a the homotopy category of some category with weak equivalences, i.e., a derived category.
\end{rmk}
\begin{proof}
We have seen that if $\cc$ is additive then $\ff \cc$ is a persistence category. We therefore need to check the following:

\begin{enumerate}
    \item The zero level category $\ff \cc_0$ is triangulated with some translation functor $\S$.
    \item The restriction of $\ss^a$ to $End(\ff \cc_0)$ is a triangulated functor.
    \item For any $a>0$ and $A\in \ff \cc$ the morphism $\eta^A_a:\ss^a \to A$ embedds into an exact triangle 
    \begin{equation*}\ss^a A \xrightarrow[]{\eta^A_a}A \to K \to \S \ss^a A\end{equation*}
    with $K$ $r$-acyclic.


\end{enumerate}
We prove these in order:

\begin{enumerate}
    \item First we construct a functor $\S$, assume that $T$ is the translation functor for the triangulated category $\cc$. We define $\S$ as follows

    \begin{equation*}\S A:(\R, <) \to \cc\end{equation*}
    \begin{equation*}(\S A)(r):= T(A(r-\alpha))\end{equation*}
    where $\alpha\in \R$ is some constant we will call the \textbf{weight of $\S$}. Given $f:A \to B$ we set $\S f:\S A \to \S B$ by

    \begin{equation*}\S A(r) \xrightarrow{\S f(r)} \S B^{\lceil f \rceil}(r)\end{equation*}
    \begin{equation*}T(A(r-\alpha)) \xrightarrow{T(f(r-\alpha))}T(B^s(r-\alpha))\end{equation*}
 i.e., $\S f (r):= T(f(r-\alpha))$, importantly $\lceil Tf \rceil = \lceil f \rceil$. 

 It is obvious that $\S: \text{Mor}^s(A,B) \to \text{Mor}^s(\S A, \S B)$ and so in particular $\S : \text{Mor}^0(A,B) \to \text{Mor}^0(A,B)$.

 \begin{rmk}
 The weight of $\S$ in the construction of $\ff \text{Top}_*$ and $\ff \text{Spectra}_*$ was equal to $1$. 
 \end{rmk}

 We now show $\ff \cc_0$ is triangulated. This follows almost directly from the fact $\ff \cc$ is a persistence category and that $\cc$ is triangulated. We set exact triangles in $\ff \cc_0$ to be triangles isomorphic to those of the form 

 \begin{equation*}A \to B \to C \to \S \ss^{-\alpha}A\end{equation*}
 with 
 \begin{equation*}A(r) \to B(r) \to C(r) \to T A(r)\end{equation*}
 exact triangles in $\cc$ for all $r\in \R$. Note by our translation functor is given by composition $\S \ss^{-\alpha}$. One can then easily check that with this class of exact triangles  $\ff \cc$ is triangulated, since the properties of a triangulated category will hold level-wise. The one difficulty is checking that the $4$-th axiom holds, but under assumption that triangles in $\cc$ are cofiber sequences this holds true by taking $\text{Cone}(f)(s)=\text{Cone}(f(s))$



 \item By definition the functor $\ss^a$ maps the exact triangle:
 \begin{equation*}A \xrightarrow{u} B \xrightarrow{v} C \xrightarrow{w} \S \ss^{-\alpha}A\end{equation*}
 to 
\begin{equation*}\ss^a A \xrightarrow{\ss^a u} \ss^a B \xrightarrow{\ss^a v} \ss^a C \xrightarrow{\ss^a w} \ss^a \S \ss^{-\alpha}A\end{equation*}
which evaluated at `level' $r$, is exactly 
\begin{equation*}A(r-a) \xrightarrow{u(r-a)}B(r-a) \xrightarrow{v(r-a)}C(r-a) \xrightarrow{w(r-a)}\S A(r-a+\alpha)\end{equation*}
and is equal to
\begin{equation*}A(r-a) \xrightarrow{u(r-a)}B(r-a) \xrightarrow{v(r-a)}C(r-a) \xrightarrow{w(r-a)} T\big(A(r-a)\big)\end{equation*}
which is triangulated in $\cc$ for all $a,r\in \R$.
Hence we have the triangle 
\begin{equation*}\ss^a A \xrightarrow{\ss^a u} \ss^a B \xrightarrow{\ss^a v} \ss^a C \xrightarrow{\ss^a w} \ss^a \S \ss^{-\alpha}A\end{equation*}
is exact in $\ff \cc_0$.
\item Finally, let $K:=\text{Cone}(\eta_a^A)$, clearly $\eta_a^A$ embeds into the exact triangle

  \begin{equation*}\ss^a A \xrightarrow[]{\eta^A_a}A \to K \to \S \ss^{-\alpha} \ss^a A\end{equation*}

  so we just need to show $K$ is $a$-acyclic, i.e., we need show $\eta_a^{\text{Cone}(\eta_a^A)}$ is the zero map. It is sufficient to show that for all $r$
  \begin{equation*}\eta_a^{\text{Cone}(\eta_a^A)}(r)=0\in \text{Mor}^0\big(\text{Cone}(\eta_a^A), \ss^{-a}\text{Cone}(\eta_a^A)\big)\end{equation*}

 we have that
 \begin{align*}
 \text{Cone}(\eta_a^A)(r):=&\text{Cone}(\eta_a^A(r))\\  
 =&\text{Cone}( \iota_{-a,0}\circ \eta_{a,0}^A(r))\\
 =&\text{Cone}(\ss^a A(r) \xrightarrow{\cong}A(r-a) \xrightarrow{ \iota_{-a,0}}A(r))\\
 &=A(r)/A(r-a)
 \end{align*}
 since $\cc$ is homotopical.
 We therefore have that $\eta_a^{\text{Cone}(\eta_a^A)}(r)$ a map
 \begin{equation*}A(r)/A(r-a) \xrightarrow{\eta_a^{\text{Cone}(\eta_a^A)}(r)}A(r+a)/A(r)\end{equation*}
 which must be the zero map.
\end{enumerate}
\end{proof}
\subsection{Monoidal Objects in Tensor Persistence Categories}
Given a symmetric monoidal category $\cc$ with tensor product $\otimes$, taking its filtered category $\ff \cc$ we have a natural tensor product $\otimes $ in $\ff \cc$, given by 
\begin{equation*}(A \otimes B)^{\leq r}= A^{\leq r- \lfloor B \rfloor}\otimes B^{\leq r - \lfloor A \rfloor}\end{equation*}
We say $A$ is a monoidal object in $\cc$ if there exist maps $C \otimes C \xrightarrow[ ]{\mu} C$ and $1 \xrightarrow[]{\eta} C$, such that the following commute:

\begin{enumerate}
    \item \begin{equation*}\begin{tikzcd}1 \otimes A\arrow[r,"\eta \otimes id"]\arrow[dr,swap,"\cong"]& A \otimes A \arrow[d,"\mu"]& A \otimes 1 \arrow[l,swap,"id \otimes \eta"]\arrow[dl,"\cong"]\\
    & A & \end{tikzcd}\end{equation*}
    \item
    \begin{equation*}\begin{tikzcd} (A \otimes A) \otimes A\arrow[d,"\mu \otimes id"] \arrow[rr,"\alpha"]& & A \otimes (A \otimes A)\arrow[d,"id \otimes \mu"] \\
    A \otimes A \arrow[dr,"\mu"]& & A\otimes A\arrow[dl,swap, "\mu"]\\
    & A &\end{tikzcd}\end{equation*}
\end{enumerate}
where $ \alpha$ is the \textit{associator} and the isomoprhims in 1 are defined by the left and right \textit{unitors}.

We therefore define a filtered monoidal object in $\ff \cc$ to be an object $A \in \ff \cc$ along with maps $A \otimes A \xrightarrow{\mu} A$ and $1 \xrightarrow{\eta} A$ of shift $\lceil \mu \rceil= -\lfloor A \rfloor$ and $\lceil \eta \rceil = \lfloor A \rfloor$

such that

 \begin{equation*}\begin{tikzcd} (A \otimes A)^{\leq r- \lfloor A \rfloor} \otimes A^{\leq r - 2\lfloor A \rfloor}\arrow[d,"\mu \otimes id"] \arrow[rr,"\alpha"]& & A^{\leq r-2 \lfloor A \rfloor} \otimes (A \otimes A)^{\leq r - \lfloor A \rfloor}\arrow[d,"id \otimes \mu"] \\
    (A \otimes A)^{\leq r - \lfloor A \rfloor} \arrow[dr,"\mu"]& & (A\otimes A)^{\leq r - \lfloor A \rfloor}\arrow[dl,swap, "\mu"]\\
    & A^{\leq r- 2\lfloor A \rfloor} &\end{tikzcd}\end{equation*}

\begin{equation*}\begin{tikzcd}(1 \otimes A)^{\leq r}\arrow[r,"\eta \otimes id"]\arrow[dr,swap,"\cong"]& (A \otimes A)^{\leq r + \lfloor A \rfloor} \arrow[d,"\mu"]& (A \otimes 1)^{\leq r} \arrow[l,swap,"id \otimes \eta"]\arrow[dl,"\cong"]\\
    & A^{\leq r} & \end{tikzcd}\end{equation*}



