The organization of this paper is as follows. In Section \ref{Sec:2}, we will briefly recall some basic definitions of embedded ideal circle patterns and the Gromov-Hausdorff topology on graphs. In Section \ref{Sec:3}, we investigate the limit structures of embedded ICPs and establish several Ring Lemmas. After that, with the help of the Ring lemmas, we prove the existence theorem of embedded ICPs and obtain a He-Schramm type estimate for discrete extremal length in Section \ref{Sec:4}. As a consequence, we prove the discrete uniformization theorem \ref{uniformization}. Finally, in Section \ref{Sec:5}, we prove the rigidity of ICPs with the help of maximum principles and a Liouville's theorem for discrete harmonic functions.  


	\section{Preliminary}\label{Sec:2}
	\subsection{Gromov-Hausdorff convergence on graphs}
Let \( \mathcal{D} = (V, E, F) \) be a cellular decomposition of a simply connected planar domain \( \Omega \), which is called a \textbf{disk cellular decomposition} for short, where \( V \), \( E \), and \( F \) denote the sets of vertices, edges, and faces of \( \mathcal{D} \), respectively. Throughout this paper, we assume that any two distinct faces of \( \mathcal{D} \) share at most one edge, and each face has at least three edges.

For each vertex \( v \in V \) (resp. face \( f \in F \)), we denote by \( \deg(v) \) (resp. \( \deg(f) \)) the number of edges incident to \( v \) (resp. to \( f \)), which we refer to as the \emph{vertex degree} (resp. \emph{face degree}).

	We use $G = (V, E)$ to denote a graph, which always refers to the $1$-skeleton of a cellular decomposition $\mathcal{D}$ in this paper. We denote by $\overrightarrow{E}$ the set of directed edges, where for each undirected edge $\{v, w\} \in E$, both $(v, w)$ and $(w, v)$ are elements of $\overrightarrow{E}$. 
	The \emph{combinatorial distance} between two vertices $v$ and $w$ in the graph $G$ is defined as
	\[
	\mathrm{d}_G(v, w) := \inf\{n \in \mathbb{N} : v = v_0 \sim v_1 \sim \cdots \sim v_n = w\}.
	\]
	For any $N \in \mathbb{R}_{\geq 0}$ and $v \in V$, we define the \emph{combinatorial ball} and \emph{sphere} of radius $N$ centered at $v$ by
	\[
	B_N(v) := \{w \in V : \mathrm{d}_G(v, w) \leq N\}, \quad S_N(v) := \{w \in V : \mathrm{d}_G(v, w) = N\}.
	\]	

	We now introduce the concept of \emph{pointed Gromov--Hausdorff convergence} on rooted graphs, which can be found in the work \cite{MR4829680}. Let $\mathcal{G}^r$ denote the set of all rooted simple graphs $(G, v)$, where $G$ is a graph and $v$ is a vertex of $G$. 

	Let $G_i = (V_i, E_i)$ be two graphs with vertices $v_i \in V_i$ for $i = 1, 2$. A bijection $\phi: V_1 \rightarrow V_2$ is called a \emph{rooted graph isomorphism}, denoted by
	\[
	(G_1, v_1) \stackrel{\phi}{\simeq} (G_2, v_2),
	\]
	if the following conditions hold:
	\begin{enumerate}
		\item $v \sim w \iff \phi(v) \sim \phi(w)$ for all $v, w \in V_1$;
		\item $\phi(v_1) = v_2$.
	\end{enumerate}

	If $(G_1, v_1) \stackrel{\phi}{\simeq} (G_2, v_2)$, then for any edge $e = \{u, v\} \in E_1$, we denote the corresponding edge in $G_2$ by $\phi(e) := \{\phi(u), \phi(v)\} \in E_2$.

	Let $W$ be a subset of the vertex set $V$ of a graph $G$. We denote by $I_G(W) = (W, E_W)$ the subgraph of $G$ \emph{induced} by $W$, where
	\[
	\{w_1, w_2\} \in E_W \iff \{w_1, w_2\} \in E.
	\]

\begin{defn}[Pointed Gromov–Hausdorff convergence]\label{ghconvergence}
	Let $\{(G_i, v_i)\}_{i \in \mathbb{N}}$ be a sequence of rooted graphs. We say that $(G_i, v_i)$ converges in the pointed Gromov–Hausdorff sense to a rooted graph $(G_\infty, v_\infty)$, denoted by
	\[
	(G_i, v_i) \stackrel{\mathrm{pGH}}{\longrightarrow} (G_\infty, v_\infty),
	\]
	if for any $n > 0$, there exists a sufficiently large $N \in \mathbb{N}$ such that for all $i \geq N$, there exists a rooted graph isomorphism $\phi_{i,n}$ satisfying
	\[
	(I_{G_i}(B_n(v_i)), v_i) \stackrel{\phi_{i,n}}{\simeq} (I_{G_\infty}(B_n(v_\infty)), v_\infty).
	\]
\end{defn}

\begin{defn}
	We say that a graph $\mathcal{D} = (V, E, F)$ has \emph{bounded geometry} if there exists a constant $B > 0$ such that
	\[
	\deg(v) \leq B, \quad \forall v \in V.
	\]
\end{defn}

We denote by $\mathcal{BG}(B)$ the set of all graphs with bounded geometry whose vertex degree is bounded by $B$, and by $\mathcal{BG}^r(B)$ the set of all rooted graphs $(G, v)$ such that $G \in \mathcal{BG}(B)$ and $v$ is a vertex of $G$. The following result, which is a simplified version of \cite[Theorem 2.5]{MR4829680}, will be useful for proving the Ring Lemma in Section~\ref{Sec:3}.

\begin{lem}\label{compactness1}
	The space $\mathcal{BG}^r(B)$, equipped with the pointed Gromov–Hausdorff topology, is sequentially compact. That is, for any sequence $\{(G_i, v_i)\}_{i=1}^\infty \subseteq \mathcal{BG}^r(B)$, there exists a subsequence (still denoted by $\{(G_i, v_i)\}_{i=1}^\infty$) and a rooted graph $(G_\infty, v_\infty) \in \mathcal{BG}^r(B)$ such that
	\[
	(G_i, v_i) \stackrel{\mathrm{pGH}}{\longrightarrow} (G_\infty, v_\infty).
	\]
\end{lem}
This is the discrete analog of Gromov's compactness theorem.

	\subsection{Ideal circle patterns and ideal polyhedra}\label{Ideal_circle_patterns_planes}
