\begin{defn}[Ideal Circle Pattern]\label{ICP}
	A \textbf{circle pattern} \( \mathcal{P} \) in the plane is a collection of circles \( \{\Pac(v)\}_{v \in V} \) in \( \mathbb{R}^2 \). A circle pattern \( \mathcal{P} \) is called an \emph{ideal circle pattern} (ICP for short) of a cellular decomposition \( \mathcal{D} = (V,E,F) \) if the following conditions hold:
	\begin{enumerate}[(1)]
		\item \(  \Pac(u) \cap \Pac(v) \neq \emptyset \) whenever \( u \sim v \).
		\item \( \bigcap\limits _{v < f} \Pac(v) = \{v_f\} \) for each face \( f \in F \), where \( v_f \) can be regarded as a dual vertex corresponding to the face \( f \) in the dual graph of \( \mathcal{D} \).
	\end{enumerate}
	We denote by \( D(v) \) the closed disk bounded by \( \Pac(v) \).
\end{defn}


For each edge \( e = \{u,v\} \), we denote by \( \Theta(e) = \Theta(u,v) \) the intersection angle of circles \(  \Pac(u) \) and \( \Pac(v) \). It is easy to see that for an ideal circle pattern defined as above, the intersection angles satisfy the condition $(C1)$.
%\angle equality
From the condition $(C1)$, we immediately obtain the following proposition:

\begin{prop}\label{face_degree}
	Let \( \mathcal{P} \) be an ideal circle pattern of a cellular decomposition \( \mathcal{D} = (V, E, F) \) with intersection angles \( \Theta(e) \in (0, \pi - \epsilon] \) for some \( \epsilon > 0 \). Then each face in $F$ is bounded by at most \( \frac{2\pi}{\epsilon} \) edges.
\end{prop}


	\begin{prop}\label{compactness2}
		Supposing that $\{\mathcal{D}_i=(V_i,E_i,F_i)\}_{i\in \mathbb{N}}$ is a sequence of locally finite cellular decompositions that admit ICPs $\{\Pac_i\}_{\in\mathbb{N}}$ with intersection angle $\Theta_i\in [0,\pi-\epsilon]^{E_i}$ for each $i$. Let $G_i$ be the $1-$skeleton of $\mathcal{D}_i$ and $v_i\in V_i$. Then $\{(G_i,v_i)\}_{i\in\mathbb{N}}$ has a convergent subsequence in the pointed Gromov-Hausdorff topology. 

		Moreover, if $G_i\in \mathcal{BG}^r(B)$ for some constant $B$, then the limit of those rooted graphs is a $1$-skeleton of a locally finite cellular decomposition.
	\end{prop}
	\begin{proof}
		By Proposition \ref{face_degree}, for every $i$, we have $\deg(f)\le \frac{2\pi}{\epsilon},\forall f\in F_i$. Therefore, the degree of dual graph $G^*_i$, which is the $1-$skeleton of the Poincar\'e dual of  $\mathcal{D}_i,$ is bounded by $\frac{2\pi}{\epsilon}$. Since the pointed Gromov-Hausdorff convergence of the dual graphs is equivalent to that of the original graphs, by Lemma \ref{compactness1}, we see that $\{(G_i,v_i)\}_{i\in\mathbb{N}}$ has a convergent subsequence, which converges to $(G_\infty,v_\infty)$. Moreover, if $G_i\in \mathcal{BG}(B),$ then $G_\infty\in \mathcal{BG}(B)$. Therefore, we finish the proof.
	\end{proof}

	We now introduce a geometric method for constructing ideal circle patterns. Let $r\in\mathbb{R}_+^V$ be radii of circles, which is called the \textbf{circle packing metric} in the literature.
	For each cell \( f \) in the cellular decomposition \( \mathcal{D} \),  we add an auxiliary vertex $v_f$ in the interior of the face as its dual point, labeled as a small triangle in Figure \ref{fig01}. We denote by $V_F$ the set of those dual vertices. We define the incidence graph of $G$; see e.g. \cite{coxeter1950self}.


	\begin{defn}
		An \textit{incidence graph} $I(G)$ is a bipartite graph with the bipartition $\{V,V_F\}$. For $v\in V$ and $v_f\in V_F$, $v$ and $v_f$ are adjacent in $I(G)$ if and only if $v$ is on the boundary of the face $f$.
	\end{defn}
	The notion of incidence graph is used to demonstrate the relationship between vertices and faces. Let $e=\{v,w\}\in E$. Assume that $f_1,f_2\in F$ are faces whose boundaries contain $e$. By $Q_e$ we denote the quadrilateral $vv_{f_1}wv_{f_2}$ in the incidence graph $I(G)$. 
