	Obviously, any edge in the original graph $G$ uniquely corresponds to a quadrilateral in the incident graph $I(G)$, as shown in the Figure \ref{fig01}. Then we can construct a Euclidean quadrilateral $\tilde{Q}_e$ with 
	\begin{align*}
		\angle vv_{f_1}w=\angle vv_{f_2}w=\pi-\Theta(e),~
		|vv_{f_1}|=|vv_{f_2}|=r(v),~ |wv_{f_1}|=|wv_{f_2}|=r(w),
	\end{align*}
	as in Figure \ref{quadrilateral}.

	We denote by $\alpha_{(e,v)}=\alpha_{v}^w\in (0,2\pi)$ the angle $\angle v_{f_1}vv_{f_2}$ in $\Tilde{Q}_e$, as shown in Figure \ref{quadrilateral}, given by 
	\begin{align}\label{anglefunction}
		\alpha_v^w(r(v),r(w),\Theta(e))=2\arccos\frac{r(v)+r(w)\cos\Theta(e)}{\sqrt{r(v)^2+r(w)^2+2r(v)r(w)\cos\Theta(e)}},~\forall(r(u),r(v))\in\mathbb{R}^2_+.
	\end{align}
	Since the function above only depends on the ratio $q_{vw}:=\frac{r(v)}{r(w)}$ and the angle $\Theta(e)$, we can write it as $\alpha_v^w(q_{vw},\Theta(e)).$
	Gluing all the Euclidean quadrilaterals along the edges in $I(G)$, we obtain a piece-wise flat metric $g=g(r,\Theta)$ on $\Sigma$ (for the gluing procedure, see \cite[Chapter 3]{burago2022course}). It is clear that $g$ is a flat metric outside $V\cup V_F.$ $V$ and $V_F$ are possible cone points in $\Sigma.$ In this paper, we always assume $(C1)$ holds for each pair $(\mathcal{D},\Theta)$ so that $V_F$ does not contain conical points.

    For each vertex \( v \in V \), the \emph{cone angle} \( \alpha_v \) is defined by  
    \[
    \alpha_v = \sum_{e : v < e} \alpha_{(e, v)} = \sum_{w:w \sim v} \alpha_v^w,
    \]  
    and the \emph{vertex curvature} (also called the \emph{discrete Gauss curvature}) at \( v \) is given by  
    \[
    K_v = 2\pi - \alpha_v.
    \]

	\begin{defn}\label{def-embed-ICP}
		Given a disk cellular decomposition $\mathcal{D}$ and intersection angles $\Theta\in (0,\pi)^E$ satisfying $(C1)$, we say that the circle packing metric $r$ supports an \textbf{embedded planar ideal circle pattern} (embedded ICP for short) if and only if the following conditions hold:
		\begin{enumerate}[I)]
			\item $\alpha_v=2\pi,~\forall v\in \mathrm{Int}(V),$ where $\alpha_v$ is the cone angle defined before.
			\item There exists an isometric embedding $\eta:(\Omega,g(\Theta,r))\rightarrow(\mathbb{R}^2,\mathrm{d}s^2),$ where $\mathrm{d}s^2$ is the standard Euclidean metric.
		\end{enumerate}
