	\section{Limit structures of ICPs}\label{Sec:3}
	In this section, we study the limit structures of ICPs.  As a direct application, we will establish two Ring lemmas for embedded ICPs with the help of the properties of the limit structures.
	\subsection{The limits of embedded ICPs}
	\begin{defn}
		Let $\{D_i=(V_i,E_i,F_i)\}_{i\in \mathbb{N}}$ be a sequence of locally finite cellular decompositions, whose $1$-skeleton is denoted by $G_i.$ Let $D_\infty=(V_\infty,E_\infty,F_\infty)$ be another locally finite cellular decomposition with the $1-$skeleton $G_\infty.$
		Let $\mathcal{P}_i$ be a sequence of ICPs of $D_i$ respectively, with intersection angles $\Theta_i\in (0,\pi)^{E_i}$ and radii $r_i\in \mathbb(0,\infty)^{V_i}.$ 
		We say a quadruple $(\mathcal{D}_\infty,v_\infty,\Theta_\infty,q_\infty)$ with $\Theta_\infty\in [0,\pi]^{E_\infty}$ and $q_\infty\in [0,+\infty]^{\overrightarrow{E_\infty}}$ an \textbf{ICP limit} of $\{(\mathcal{D}_i,v_i,\Theta_i,r_i)\}_{i\in \mathbb{N}}$, if the following statements hold:
		\begin{enumerate}
			\item $(G_i,v_i)\stackrel{pGH}{\longrightarrow}(G_\infty,v_\infty)$.
			\item Let $\phi_{i,n}$ be the graph isomorphism as defined in Definition \ref{ghconvergence}. Then for each $n\in \mathbb{N}$, for sufficiently large $i$ one has
			\[
			r_i(\phi^{-1}_{i,n}(v))/r_i(\phi^{-1}_{i,n}(w))\rightarrow q_\infty(v,w), ~\forall w\in B_n(v_\infty).
			\]
			\item For each $n\in \mathbb{N}$, for sufficiently large $i$, one has
			\[
			\Theta_i(\phi^{-1}_{i,n}(e))\rightarrow \Theta_\infty(e)\in (0,\pi),~\forall e\subseteq B_n(v_\infty).
			\]
		\end{enumerate}
	\end{defn}
	From the definition, it is easy to see that for an edge $\{v,w\}\in E$, if $q(v,w)\in (0,\infty)$, then $q(v,w)=q(w,v)^{-1};$ if $q(v,w)=0$, then $q(w,v)=\infty$.
	Now we recall the function $\alpha_v^w(r(v),r(w),\Theta(e))$ in \eqref{anglefunction}. For an edge $e=(v,w)$, we can extend it to the following form.
	$$\hat{\alpha}_{(e,v)}=\hat{\alpha}_v^w(q_{vw},\Theta(v,w))=\left\{\begin{aligned}
		&2\Theta(v,w),&q_{vw}=0,\\&\alpha_v^w(q_{vw},\Theta(v,w)),~&q_{vw}\in(0,\infty),\\
		&0,&q_{vw}=\infty.
	\end{aligned}
	\right.$$

	\begin{prop}\label{property}
		Let $(\mathcal{D}_\infty,v_\infty,\Theta_\infty,q_\infty)$ be an ICP limit of $\{(\mathcal{D}_i,v_i,\Theta_i,r_i)\}_{i\in \mathbb{N}}$, then the following statements hold:
		\begin{enumerate}[(A)]
			\item  For each $n\in\mathbb{N}$, for sufficiently large $i$, we have $$ \alpha_{(\phi^{-1}_{i,n}(e),\phi^{-1}_{i,n}(v))}\rightarrow\hat{\alpha}(q_\infty(v,w),\Theta_\infty(v,w)),\forall  e\subseteq B_n(v_\infty).$$
			\item $\sum\limits _{w:w\sim v}\hat{\alpha}(q_\infty(v,w),\Theta_\infty(v,w))=2\pi,~\forall v\in \mathrm{Int}(V_\infty).$
			\item If the closed curve $\gamma=(e_1,e_2,...,e_n)$ is a boundary of a face, then 
			\[
			\sum_{j=1}^n(\pi-\Theta_\infty(e_i))=2 \pi.
			\]

		\end{enumerate}
	\end{prop}
	\begin{proof}
		This proposition can be obtained easily from the definition of ICPs.
	\end{proof}
	Now we introduce an operation on graphs.
	\begin{defn}[Reduce graphs by faces]
		Let \( G_0 = (V_0, E_0) \) be a subgraph of the $1$-skeleton of a disk cellular decomposition \( \mathcal{D} = (V, E, F) \) such that \( G_0 \) does not contain all boundary edges of any two faces that share a common vertex in \( \mathcal{D} \). We denote by $F_0$ the set of faces in $F$ whose boundary edges are all contained $E_0.$ For each face $f\in F_0,$ we introduce a new vertex $v_f.$ Then let $V_1=V_0\backslash(\cup_{f\in F_0}V(f))$ and $V_2=\{v_f:f\in F_0\}.$ We say a graph $G'=(V',E')$ is the \textbf{reduced graph} of $G_0$ by faces if the following statements hold (as shown in Figure \ref{fig:reduce}):
		\begin{enumerate}
			\item $V'=V_1\cup V_2.$
			\item Every two vertices $v_{f_1},v_{f_2}\in V_2$ are connected in $G'$ if there exist $v_1\in V(f_1)$ and $v_2\in V(f_2)$ such that $v_1\sim v_2$ in $G_0$.
			\item Every two vertices in $V_1$ are connected in $G'$ if and only if they are connected in $G_0$.
			\item Every two vertices \( v_1 \in V_1 \) and \( v_2 = v_f \in V_2 \), we have \( v_1 \sim v_2 \) in \( G' \) if and only if \( v_1 \sim v \) for some \( v \in V(f) \) in \( G_0 \).
		\end{enumerate}
	\end{defn}
	\begin{figure}
		\centering
		\includegraphics[width=0.7\linewidth]{reduced.png}
		\caption{A subgraph $G_0$ of a cellular decomposition and its reduced graph.}
		\label{fig:reduce}
	\end{figure}
	Now we consider the following Lemma, which is crucial in proving the Ring lemma.
	\begin{lem}\label{limit lemma}
		Let $\{D_i=(V_i,E_i,F_i)\}_{i\in \mathbb{N}}$ be a sequence of locally finite cellular decompositions, whose $1$-skeleton is denoted by $G_i.$ Let $\mathcal{P}_i$ be the embedded ICP of $\mathcal{D}_i$ with intersection angle $\Theta_i\in [\epsilon,\pi-\epsilon]^{E_i}$ and radius $r_i\in (0,\infty)^{V_i}$.
		Suppose that $(\mathcal{D}_\infty,v_\infty,\Theta_\infty,q_\infty)$ is an ICP limit of $\{(\mathcal{D}_i,v_i,\Theta_i,r_i)\}_{i\in \mathbb{N}}$, and that the condition $(C2)$ in Theorem \ref{riv} holds for $(\mathcal{\mathcal{D}}_\infty,\Theta_\infty).$ For $v\in V,$ if $B_{\frac{6\pi}{\epsilon}}(v)\cap\partial V_\infty=\emptyset,$ then $q_\infty(v,w)<+\infty,~\forall w\sim v.$
	\end{lem}
	\begin{proof}
		Without loss of generality, we assume $v=v_\infty, B_{\frac{6\pi}{\epsilon}}(v_\infty)\cap\partial V_\infty=\emptyset.$ Since $\mathcal{P}_i$ is an embedded ICP for each $i,$ by scaling and translation, we can assume that 
		$\mathcal{P}_i(\phi_i^{-1}(v_\infty))$ is the unit disk in $\mathbb{R}^2.$
		By subtracting a subsequence, we may assume that for each vertex $v\in V_\infty$, the limit $r_\infty(v):=\lim_{i\rightarrow\infty}r_i(\phi_i^{-1}(v))$ exists in $[0,\infty].$
		We now prove this lemma by contradiction. 

		Suppose that $q_\infty(v,w)=+\infty,$ for some $w\sim v_\infty.$ Then the limit $r_\infty(w)=0$. Let $W$ be the set
		\[
		\{v\in V_\infty:r_\infty(v)=0\}.
		\]
		We denote by $W_0$ the face connected component of $W$ containing $w$. Then $v_\infty\in \tilde{\partial}W_0$. We denote by $W_+$ the connected component of $\tilde{\partial}W_0$ containing $v_\infty$.  By $(B)$ of Proposition \ref{property}, we see that for each vertex $v\in V_\infty,$ there exist at least two vertices $v',v''\sim v$ such that $q_\infty(v,v')$ and $q_\infty(v,v'')<+\infty.$ Otherwise, the summation $\sum_{w:w\sim v}\hat{\alpha}_v^w(q_\infty(v,w),\Theta(v,w))\le2\pi-2\epsilon.$ Therefore, the induced subgraph $I_{G_\infty}(W_+)$ either contains a closed curve or contains an infinite path. We claim that $I_{G_\infty}(W_+)$ contains no infinite path without self-intersection.

		We prove the claim by contradiction. Assuming that $\gamma=(e_1,e_2,...,e_n,...)$ is an infinite path in $I_{G_\infty}(W_+)$ without self-intersection. Since $W_+$ is the boundary of $W_0,$ for each $j$, there exists a face $f_j\in F_\infty$ and a vertex $w_j\in W_0$ such that $w_j<f_j$ and $e_j<f_j$. For simplicity, we write $\phi_i$ for $\phi_{i,n}$, assuming that the vertices considered in the proof is contained in a sufficiently large ball $B_n(v_\infty)$. We denote by $v_{f_j}^i$ the dual vertex of $\phi_i^{-1}(f_j)$ at the quadrilateral $\tilde{Q}_{\phi_i^{-1}(e_j)}$. Since the radii of circles in $W_0$ converge to $0$ and $W_0$ is face connected, for fixed $i$ and $N$ we have
		\[
		\lim_{i\rightarrow\infty}\mathrm{diam}(\{v_{f_1}^i,\cdots v_{f_N}^i\})\le \lim_{i\rightarrow\infty}\sum_{j=1}^Nr_i(\mathcal{P}_i(\phi_i^{-1}(w_j)))=0.
		\]
		Here the diameter is the Euclidean diameter of the vertex set of the embedded ICP in $\mathbb{R}^2$, as shown in Figure \ref{fig:accumulation} , where the vertices $v_{f_j}^i$ are colored red. Since the interiors of those embedded quadrilaterals do not intersect with each other, it is easy to see that 
        $$\lim_{i\rightarrow+\infty}\sum_{j=1}^N(\pi-\Theta_i(e_j))\le2\pi.$$ The fact that $N$ can be arbitrarily large contradicts the assumption that $\Theta(e_i)\le \pi-\epsilon.$ Thus the claim is proved.
		\begin{figure}
			\centering
			\includegraphics[width=0.6\linewidth]{accumulation.png}
			\caption{Half of the quadrilaterals $\{\tilde{Q}_{(\phi^{-1}_i(e_1))},\cdots,\tilde{Q}_{(\phi^{-1}_i(e_N))}\}$ in the embedded ICP $\Pac_i$.}
			\label{fig:accumulation}
		\end{figure}

		By the discussion above, we see that $I_{G_\infty}(W_+)$ must contain a closed curve. Moreover, we have $W_+\subseteq B_{\frac{2\pi}{\epsilon}}(v_\infty).$ Now we prove that $I_{G_\infty}(W_+)$ must contain a closed curve which is not a boundary of a face. If $I_{G_\infty}(W_+)$ does not contain a boundary of any face in $\mathcal{D}_\infty$, then the proof is completed. Therefore, we assume that $V(f)\subset W_+$ for a face $f$.

		We claim that $\tilde{\partial}V(f)\cap W_+$ must contain at least two vertices. 
		To prove this claim, we consider the equation obtained from Proposition \ref{property} as follows.
		\begin{align}\label{sum1}
			\sum_{v\in V(f)}\hat{\alpha}_v=\sum_{v\in V(f)}\sum_{w:w\sim v}\hat{\alpha}_v^w=2\deg(f)\pi.
		\end{align}
		We further write the summation as
		\small\begin{align}
			\sum_{v\in V(f)}\sum_{w:w\sim v}\hat{\alpha}_v^w&=\sum_{v\in V(f)}\sum_{e\in E(f):v<e}\hat{\alpha}_{(e,v)}
			+\sum_{v\in V(f)}\sum_{e\notin E(f):v<e}\hat{\alpha}_{(e,v)}\nonumber,\\
			\nonumber&=\sum_{e:e<f}2\Theta_\infty(e)+\sum_{v\in V(f)}\sum_{e\notin E(f):v<e}\hat{\alpha}_{(e,v)}\nonumber,
			\\&=2(\deg(f)-2)\pi+\sum_{v\in V(f)}\sum_{e\notin E(f):v<e}\hat{\alpha}_{(e,v)},\label{sum2}
		\end{align}
		where the last equation comes from $C.$ of Proposition \ref{property}. By equations \eqref{sum1} and \eqref{sum2}, we have
		\[
		\sum_{v\in V(f)}\sum_{e\notin E(f):v<e}\hat{\alpha}_{(e,v)}=4\pi.
		\]
		Since $\hat{\alpha}(\infty,\cdot)=0,$ we prove the claim.

		By the above discussion, we know that $W_+\backslash V(f)\neq\emptyset.$ If $I_{G_\infty}(W_+)$ contains the edges of the boundaries of two faces that share a common vertex, then the proof is completed. Therefore, we only need to consider the situation where the preceding case does not occur. Let $G'=(V',E')$ be the reduced graph of $I_{G_\infty}(W_+)$ by face. Then by the claim above, we see that each $v\in V'$ has at least two neighbors. Therefore, the graph $G'$ has a closed curve. This means that $I_{G_\infty}(W_+)$ has a closed curve which is not the boundary of a face. 

		In summary, $I_{G_\infty}(W_+)$ must contain a curve $\gamma$ that is not a boundary of a face. Since for each vertex $v$ in $W_0$, $\Pac_i(v)$ will degenerate to a point. The circles $\{\Pac(v)\}_{v\in \gamma}$ with radii $r_\infty(v)$ form an ``ideal circle pattern'' that may contain circles with infinitely large radii.
        It follows that $\sum_{e\in \gamma}\Theta_\infty(e)=2\pi.$ However, this contradicts the assumption of $\Theta_\infty$. Therefore, we finish the proof.

	\end{proof}


	\subsection{Ring lemmas for ICPs}\label{Sec:4}
    The Ring Lemma is crucial for the existence of infinite circle packings. Such a result was first established for tangential circle packings by Rodin and Sullivan~\cite{Rodin_Sullivan}. We say that a circle packing \( \mathcal{P} = \{\Pac(v)\}_{v \in V} \) is \emph{univalent} if and only if the following condition holds:
    \[
     \Pac(u) \cap \Pac(v) \neq \emptyset \iff u \sim v.
    \]

	\begin{lem}[\cite{Rodin_Sullivan} Ring lemma]
		Let $\Pac$ be a univalent circle packing of a triangulation $\mathcal{T}$. Set $v\in V$ and $w\in N(v)$. If $|N(v)|= k$ for some $k\ge 3$, then there exists a positive constant $\mathcal{R}(k)$ that only depends on $k$ such that $$\frac{r(w)}{r(v)}>\mathcal{R}(k).$$  Moreover, $$\mathcal{R}(k+1)<\mathcal{R}(k)\leq 1.$$
	\end{lem}

	Subsequently, He \cite[Lemma 7.1]{HE} extended the Ring lemma for circle patterns with the intersection angle $\Theta\in[0,\frac{\pi}{2}]^E$. 


	In the proof of He, the limit structure of circle packings is considered, which is used to make a contradiction. In the spirit of He, we prove the Ring lemma for ideal circle patterns.
	\begin{lem}[Ring lemma for ICPs]\label{ring1}
		Let $\Pac$ be an embedded ICP of a finite disk cellular decomposition $\mathcal{D}=(V,E,F)$ with the intersection angle $\Theta\in[0,\pi-\epsilon]^E$ satisfying conditions $(C1)$ and $(C2)$ in Theorem \ref{riv}. If $v\in V$ is a vertex in $V$ such that $B_{\frac{6\pi}{\epsilon}}(v)\cap\partial V=\emptyset$, then there exists a constant $C=C(v,\Theta,\mathcal{D})>0$ such that 
		\[
		\frac{r(w)}{r(v)}\ge C,~\forall w\sim v.
		\]
	\end{lem}
	\begin{proof}
		We prove this lemma by contradiction. If the statement does not hold, then there exists a sequence of embedded ICPs $\{\mathcal{P}_i\}_{i\in\mathbb{N}}$ such that $\frac{r_i(w)}{r_i(v)}\rightarrow0.$ Let $\mathcal{D}_i\equiv\mathcal{D}$ and $\Theta_i\equiv\Theta$, by subtracting a subsequence, we can obtain an ICP limit $(D_\infty,v_\infty,\Theta_\infty,q_\infty)$ with 
		$D_\infty=\mathcal{D}, v_\infty=v,\Theta_\infty=\Theta$ and $q_\infty(v,w)=\infty.$ Since the condition $(C2)$ holds for $(\mathcal{D},\Theta),$ by Lemma \ref{limit lemma} we finish the proof.
	\end{proof}

	Now we assume that $(C2')$ holds for some constant $\epsilon_0$, then we can obtain a stronger Ring lemma, which is an analog of the earliest Ring lemma for tangential circle packings.

	\begin{lem}[Uniform Ring lemma for ICPs]\label{ring2}
		Let $\Pac$ be an embedded ICP of a finite disk cellular decomposition $\mathcal{D}=(V,E,F)$ with vertex degree bounded by $N$. Assume that the corresponding intersection angle $\Theta\in(0,\pi-\epsilon]^E$ satisfies conditions $(C1)$ and $(C2')$ for some constant $\epsilon_0$. If $v\in V$ is a vertex in $V$ such that $B_{\frac{6\pi}{\epsilon}}(v)\cap\partial V=\emptyset$, then there exists a constant $C=C(\epsilon,\epsilon_0,N)>0$ such that 
		\[
		\frac{r(w)}{r(v)}\ge C,~\forall w\sim v.
		\]
	\end{lem}
	\begin{proof}
		This follows from the Proposition \ref{compactness2} and Lemma \ref{limit lemma}.
	\end{proof}

By $B(0,r)$ we denote the ball centered at the origin with the radius $r$.
    With the help of the uniform ring lemma, we have the following lemma.
    \begin{lem}\label{appl_ring}
        Let $\Pac$ be an embedded ICP of a finite disk cellular decomposition $\mathcal{D}=(V,E,F)$ with vertex degree bounded by $N$. Assume that $\Pac(v_0)$ is centered at the origin for some $v_0\in V$. We denote by $V(r)$ the set of vertices, centers of circles of which are contained in the ball $B(0,r)$. If $r\ge r(\Pac(v_0))$,
        then there exists a constant $\delta_0$ such that 
        $V(r)$ and $\tilde{\partial}V(\delta_0r)$ are not connected by any edge in $E$.
    \end{lem}
    \begin{proof}
    Let $\delta_0=1+3C(\epsilon,\epsilon_0,N).$
        We prove this lemma by contradiction. If $w\in\tilde\partial V(\delta_0 r)$ and $w\sim v$ for some $v\in V(r)$. By the assumption, we see that $r(\Pac(v))\le 2r(\Pac(v_0))+r\le3r$. Therefore, by the uniform Ring Lemma \ref{ring2}, we have $$r(\Pac(w))\le 3C(\epsilon,\epsilon_0,N)r.$$ Therefore, the center of $\Pac(w)$ is contained in the ball $B(0,(1+3C(\epsilon,\epsilon_0,N))r)$, which contradicts our assumption.
    \end{proof}
	\section{The existence of infinite ICPs}
	%\eta的符号要改
	In this section, we will establish the existence of embedded ideal circle patterns on the plane $\mathbb{R}^2$ and prove Theorem \ref{infinite_existence} and Theorem \ref{uniformization}. Let 
	\begin{proof}[Proof of theorem \ref{infinite_existence}]
		Let $G$ be the $1-$skeleton of $\mathcal{D}=(V,E,F)$.
		Let $\{\mathcal{D}_i=(V_i,E_i,F_i)\}_{i\in\mathbb{N}}$ be an exhausting sequence of sub-complexes of the cellular decomposition $\mathcal{D}$, which are finite disk cellular decompositions, i.e.
		\[
		\mathcal{D}_i\subset\mathcal{D}_{i+1},\cup_{i\in \mathbb{N}}{\mathcal{D}_i}=\mathcal{D}.
		\]
		By Theorem \ref{finite_existence}, there exists an embedded ICP $\Pac_i$ for each $\mathcal{D}_i$. Fix a vertex $v\in \cap_i\mathcal{D}_i$, by scalings and translations, we can assume that $\Pac_i(v)$ is embedded into $\mathbb{R}^2$ as the unit disk. For each vertex $w\in V_i$, by the Ring lemma \ref{ring1}, it is easy to see that $0<a(w)<r_i(w)<b(w)<\infty$ for sufficiently large $i$, where $a(w)$ and $b(w)$ are some constants that only depend on $\mathcal{D}$, $\Theta$ and $\mathrm{d}_G(v,w)$. Then we see that the centers of $\{\mathcal{P}_i(w)\}_{i\in \mathbb{N}}$ are also contained in a compact subset of $\mathbb{R}^2$ for sufficiently large $i$. Therefore, by the standard diagonal argument, we can find an embedded infinite ICP as the limit of the subsequence of $\{\Pac_i\}_{i\in\mathbb{N}}$.
	\end{proof}
	\subsection{Vertex extremal length}
	For resolving the type problem of infinite ICPs, we need to  introduce the concept of \textbf{vertex extremal length}, which was introduced and studied by Cannon \cite{MR1301392}.
    Let $G=(V,E)$ be an infinite connected graph. We call a non-negative function $m\in [0,+\infty)^V$ a vertex metric. The \textbf{area} of $m$ is given by
	\[
	\mathrm{area}(m)=\sum_{v\in V}m_v^2.
	\]
	Suppose $\gamma=(v_0,v_1,...,v_n,...)$ is a finite or infinite path. We denote by $|\gamma|$ the number of vertices in $\gamma$ (counting repeated vertices, e.g., for a path $\gamma=(v=v_1,v_2,...,v_n=v)$, we have $|\gamma|=n$ in this case). The length of the curve $\gamma$ in the metric $m$ is given by 
	\[
	\int_\gamma\mathrm{d}m=\sum_{i=1}^{|\gamma|}m(v_i).
	\]
	\begin{defn}
		Let $\Gamma$ be a collection of paths. We call a vertex metric $m$ $\Gamma-$admissible if
		\[
		\int_{\gamma}\mathrm{d}m\ge 1, ~\forall \gamma\in \Gamma.
		\]
		The \textbf{vertex module} of $\Gamma$ is given by 
		\[
		\mathrm{MOD}(\Gamma)=\inf\{\area(m):m: V\rightarrow[0,\infty)~\text{is} ~\Gamma-\text{admissible} \}.
		\]
		The vertex extremal length (VEL for short) of $\Gamma$ is defined to be 
		\[
		\mathrm{VEL}(\Gamma)={\mathrm{MOD}(\Gamma)}^{-1}.
		\]
	\end{defn}
	Let $V_1,V_2\subset V$ be two disjoint vertex sets, we denote by $\Gamma(V_1,V_2)$ ($\Gamma^*(V_1,V_2)$ resp.) the paths connecting (the closed curves separating resp.) $V_1$ and $V_2$. By $\Gamma(V_1,\infty)$ and $\Gamma^*(V_1,\infty)$ we denote the sets of paths given by 
	\begin{align*}
		&\Gamma(V_1,\infty)=\{\gamma:\gamma~\text{starts from}~V_1~\text{and can not be contained in any finite subset of}~V\},\\
		&\Gamma(V_1,\infty)^*=\{\gamma:\gamma \cap \gamma'\neq \emptyset,~\forall \gamma'\in \Gamma(V_1,\infty)\}.
	\end{align*}
	Furthermore, allowing $V_2=\infty$, we write VEL$(V_1,V_2)$ and VEL$(V_1,V_2)^*$  for VEL$(\Gamma(V_1,V_2))$ and VEL$(\Gamma(V_1,V_2)^*)$ respectively.
	\begin{defn}
		We call an infinite graph $G$ a VEL-parabolic graph if there exists a finite subset $V_0\subset V$ such that VEL$(V_0,\infty)=\infty.$ Otherwise, we call $G$ a VEL-hyperbolic graph.
	\end{defn}
	The following lemmas for vertex extremal lengths, which are similar to that of the extremal length in the continuous case, are listed as below.

	\begin{lem}\label{vel_sum}
		Let $V_1, V_2, ..., V_{2m}$ be mutually disjoint, nonempty subsets of vertices such that for $i_1 < i_2 < i_3, V_{i_2}$ 
		separates $V_{i_1}$ from $V_{i_3}$. We allow $V_{2m} = \infty$. Then we have
		\[
		\mathrm{VEL}(V_1,V_{2m})\ge \sum_{k=1}^m \mathrm{VEL(V_{2k-1},V_{2k})}.
		\]
	\end{lem}
	\begin{lem}
		Let $V_1$ and $V_2$ be two disjoint nonempty vertex sets. We allow $V_{2} = \infty$. Then
		\[
		\mathrm{VEL}(V_1,V_2)^*=\mathrm{VEL}(V_1,V_2)^{-1}.
		\]
	\end{lem}
	\begin{lem}\label{vellimt}
		Let $\{\mathcal{D}_i=(V_i,E_i,F_i)\}_{i\in\mathbb{N}}$ be an exhausting sequence of sub-complexes of the cellular decomposition $\mathcal{D}$. Then for a finite vertex set $W\subset V$, we have 
		\[
		\lim_{i\rightarrow\infty}\vel(W,\partial V_i)=\vel(W,\infty).
		\]
	\end{lem}
	\subsection{Geometric behaviors of embedded ICPs}
	For the rest of the paper, we denote by ICP$(\mathcal{D,}\epsilon,\epsilon_0)$ the set of ICPs of the disk cellular decomposition $\mathcal{D}=(V,E,F)$ satisfying $(C2')$ for some constant $\epsilon_0$ with the intersection angle $\Theta\in(0,\pi-\epsilon]^E$. 

	Now we introduce several geometric lemmas for embedded ICPs, which can be used to estimate the vertex extremal length of the corresponding cellular decompositions.

	For an embedded ICP $\Pac$ of $\mathcal{D}=(V,E,F)$, for a vertex $v\in V$, we denote by $\mathcal{M}(v)$ the union $\cup_{e\in E:v<e}\tilde{Q}_{(v,e)}$, which is called the \textbf{maple} of $v$, as shown in Figure \ref{fig:maple}. For a disk $D(v)$ and a positive constant $\lambda$, we denote by $\lambda D (v)$ the disk that shares the same center as $D(v)$ and has the radius $\lambda r(v)$. Moreover, we denote by $c(v)$ the center of $\Pac(v)$.
    	\begin{figure}[H]
		\centering
		\includegraphics[width=4in]{figure_002.png}
		\caption{A maple $\mathcal{M}(v)$.}
		\label{fig:maple}
	\end{figure}
	\begin{prop}\label{maple}
		Let $\Pac\in \mathrm{ICP}(D,\epsilon,\epsilon_0)$ be an embedded ICP, then for each vertex $v\in V$, $\sin\epsilon \Pac(v)\subsetneq\mathcal{M}(v)$.
	\end{prop}
	\begin{proof}
		This is deduced from the fact that $\Theta\in(0,\pi-\epsilon]^E$.
	\end{proof}


	We denote by $C(r)$ the circle centered at the origin of $\mathbb{R}^2$ with the radius $r$. We have the following lemma, which estimates the vertex extremal length via the geometry of embedded ICP.
	\begin{lem}\label{teichumller1}
		Let $\mathcal{D}$ be an infinite disk cellular decomposition with vertex degree bounded by $N$. Let $\mathcal{P}\in \mathrm{ICP}(\mathcal{D},\epsilon,\epsilon_0)$.
		Assuming that $V_1\subseteq V$ is a finite nonempty vertex set such that $\cup_{v\in V_1}\mathcal{M}(v)\subset B(0,r_1)$ for some $r_1$. Suppose that $C(r_2)\cap\carrier(\Pac)\neq\emptyset$ and $r_2\ge 2r_1$. Let $W=\{v\in V: c(v)\in B(0,r_2)\}$ and $V_2=\tilde{\partial}W$. Then 
		\[
		\vel(V_1,V_2)\ge \frac{\sin^4\epsilon(r_2-r_1)^2}{2(\sin\epsilon+4C(\epsilon,\epsilon_0,N)+4)^2r_2^2}\ge\frac{\sin^4\epsilon}{8(\sin\epsilon+4C(\epsilon,\epsilon_0,N)+4)^2}.
		\]
	\end{lem}
	\begin{proof}
		Since $V_1\subset W$, $V_1$ and $V_2$ are two disjoint vertex sets. We define a vertex metric $m$ as follows.
		\[m(v)=
		\left\{\begin{array}{cc}
			\frac{2r(v)}{r_2-r_1}, & v\in W\cup V_2,\\
			0, & v\notin W\cup V_2.
		\end{array}\right.
		\]
		It is clear that $m$ is $\Gamma(V_1,V_2)-$admissible. Since $\vel(V_1,V_2)=\mathrm{MOD}(V_1,V_2)^{-1},$ by the definition of the vertex module, we only need to estimate the summation $\sum_{v\in W\cup V_2}r(v)^2$.

		First of all, we observe that for each vertex $w\in V_2$, $B(0,r_1)\backslash \sin\epsilon D(w)\neq\emptyset$. Otherwise, by the assumption, $\cup_{v\in V_1}\mathcal{M}(v)\subset \sin\epsilon D(w)\subsetneq\mathcal{M}(w)$, which contradicts the embedding condition. Therefore, we have 
		\[
		r(w)\le \frac{(2r_1+r_2)}{\sin\epsilon}\le\frac{2r_2}{\sin\epsilon},~\forall w\in V_2.
		\]
		By the uniform Ring lemma \ref{ring2}, we see that $r(v)\le \frac{2C(\epsilon,\epsilon_0,N)r_2}{\sin\epsilon},~\forall v\in V_2.$

		Therefore, we see that 
		$
		D(v)\subset B(0,(1+\frac{4(1+C(\epsilon,\epsilon_0,N))}{\sin\epsilon})r_2).
		$
		It is easy to see that every point on the plane is contained in at most two different maples.
		Then we have 
		\begin{align}
			\sum_{v\in W\cup V_2} \sin^2\epsilon r^2(v)&= \frac{\mathrm{Area}(\sin\epsilon D(v))}{\pi}  \nonumber
			\\&\le \frac{2}{\pi}\mathrm{Area}(B(0,(1+\frac{4(1+C(\epsilon,\epsilon_0,N))}
			{\sin\epsilon})r_2))\nonumber\\&
			\le \frac{2(\sin\epsilon+4C(\epsilon,\epsilon_0,N)+4)^2r_2^2}{\sin^2\epsilon}.
		\end{align}
		Therefore, we have
		\[
		\mathrm{area}(m)\le \frac{2(\sin\epsilon+4C(\epsilon,\epsilon_0,N)+4)^2r_2^2}{\sin^4\epsilon(r_2-r_1)^2}.
		\]
		This proves the estimate of $\vel(V_1,V_2)$.
	\end{proof}
	Next, we introduce a lemma from the converse direction, which depicts the geometric property of an embedded ICP by its vertex extremal length. We denote by $V(\rho)$ the set of vertices that have non-empty intersection with the circle $B(0,\rho)$. Moreover, we denote by $D(\gamma)$ the set $\cup_{v\text{~is a vertex in}~ \gamma}D(v)$ for each curve $\gamma$.
	\begin{lem}\label{teichmuller2}
		Let $\mathcal{D}$ be an infinite disk cellular decomposition with vertex degree bounded by $N$. Let $\mathcal{P}\in \mathrm{ICP}(\mathcal{D},\epsilon,\epsilon_0)$. Let $V_0=\{v_0\}$, $V_1$, and $V_2$ be mutually disjoint, finite, connected subsets of vertices, and let $V_4=\infty$. Assume that for any $ 0 < i_1 < i_2 < i_3 < i_4$, the set $V_{i_2}$ separates $V_{i_1}$
		from $V_{i_3}$. We assume that $v_0$ is located at the origin. 
		If \begin{align}\label{vel_condition}
			\vel(V_1,V_2)>\frac{18(\sin\epsilon+4C(\epsilon,\epsilon_0,N)+4)^2}{\sin^4\epsilon},\end{align} 
		then there exists a constant $\rho>0$, such that $V(r)$ separates $V_1$ and $V_2$ for any $r\in[\rho,2\rho]$.
	\end{lem}
	\begin{proof}
		Let $$\rho=\sup\{\mathrm{dist}(0,c(v)):v\in V_1\}.$$ We now prove that $\rho$ is the desired constant. 

		We prove this by the contradiction. Without loss of generality, we assume that $\rho=1$. If this lemma fails, then there exists a constant $\rho_0\in [1,2]$ such that $V(\rho_0)$ does not separate $V_1$ and $V_2$. 
		By the definition of $\rho$, it is clear that $c(v)\subseteq B(0,1),~\forall v\in V_1$.
		Therefore, $D(\gamma)\cap B(0,\rho_0)\ne\emptyset,~\forall\gamma\in \Gamma(V_1,V_2).$ Since $V(\rho_0)$ does not separate $V_1$ and $V_2$. There exists $\gamma_0\in\Gamma(V_1,V_2)$ such that $\gamma\cap V(\rho_0)=\emptyset.$ 
		Therefore, $\mathcal{P}(v)$ is contained in the interior $D(0,\rho_0)$ for each $v\in \gamma_0$. Let $W$ be the set of vertices whose centers are contained in $B(0,3)$. We define a vertex metric
		\[m(v)=
		\left\{\begin{array}{cc}
			2r(v) & v\in W\cup \tilde{\partial}W,\\
			0, & v\notin W\cup \tilde{\partial}W.
		\end{array}\right.
		\]
		For each closed curve $\gamma^*\in \Gamma^*(V_1,V_2),$ there exists a vertex $v\in \gamma_0\cap\gamma^*$, whose circle is contained in the disk $B(0,\rho_0).$ Therefore, either  $D(\gamma^*)$ is contained in the interior of $B(0,3)$ or it links $D(\rho_1)$ with $\partial B(0,3)$. In any case, it is easy to see that $\int_{\gamma^*} \dis m\ge 1$. Therefore, $m$ is $\Gamma^*(V_1,V_2)$-admissible. By a similar argument as in the proof of Lemma \ref{teichumller1}, we see that
		\[
		\vel(\Gamma(V_1,V_2))=\mathrm{MOD}(\Gamma^*(V_1,V_2))\le  \frac{18(\sin\epsilon+4C(\epsilon,\epsilon_0,N)+4)^2}{\sin^4\epsilon}.
		\]
		This contradicts to the assumption \ref{vel_condition}.
	\end{proof}



	\subsection{Proof of the uniformization theorem}
	Now, we prove the uniformization theorem. We divide it into two parts.

	\begin{thm}\label{uniformization1}
		Let $\mathcal{D}$ be an infinite disk cellular decomposition with vertex degree bounded by $N$. Let $\Theta\in[0,\pi-\epsilon]$, where condition (C2') is satisfied for some constant $\epsilon_0$. Then the following statements are equivalent:
		\begin{enumerate}
			\item $(\mathcal{D,}\Theta)$ is ICP-parabolic. 
			\item The infinite disk cellular decomposition $\mathcal{D}$ is VEL-parabolic.
		\end{enumerate}
	\end{thm}
	\begin{proof}
		We first assume that $(\mathcal{D,}\Theta)$ is ICP-parabolic. Then by the definition of locally finite, we can easily see that $\carrier(\Pac)=\mathbb{R}^2$. Let $V_1=\{v_1\}$ for some vertex $v_1\in V$.  Now we define the vertex set $V_i$ by induction. When $i$ is odd, and $V_i$ is defined. Let $r_i$ be a number large enough such that 
		$\cup_{v\in V_i}\mathcal{M}(v_i)\subseteq B(0,r_i)$ is contained in the interior of $B(0,r_i)$. Let $r_{i+1}=2r_i$. We denote by $W_{i+1}=\{v\in V:c(v)\in B(0,r_{i+1})\}$. We define $V_{i+1}:=\tilde{\partial}W_i$. When $i>0$ is even, we choose a vertex set $V_{i+1}$ which separates $V_i$ and $\infty$. 
		Then by the Lemma \ref{teichumller1}, we see that 
		\[
		\vel(V_{2i-1},V_{2i})\ge\frac{\sin^4\epsilon}{8(\sin\epsilon+4C(\epsilon,\epsilon_0,N)+4)^2},~\forall i\in\mathbb{N}_+.
		\]
		By the lemma \ref{vel_sum}, we see that $\mathcal{D}$ is VEL-parabolic.

		Secondly, we prove the converse direction. 
		By the theorem \ref{infinite_existence} existence, there exists an ICP of $\mathcal{D}$ in the plane. 
		Assume that $\mathcal{D}$ is VEL-parabolic. Let $v_1$ be a vertex in $V$. We can choose a sequence of mutually disjoint, nonempty vertex sets $\{V_i\}_{i\in\mathbb{N_+}}$ with $V_1=\{v_1\}$ such that for $i_1 < i_2 < i_3, V_{i_2}$ 
		separates $V_{i_1}$ from $V_{i_3}$ with 
		\[
		\vel(V_{2i-1},V_{2i})>\frac{18(\sin\epsilon+4C(\epsilon,\epsilon_0,N)+4)^2r_2^2}{\sin^4\epsilon}.
		\]
		Therefore, there exists a sequence of $\rho_i$, such that $V(r)$ separates $V_{2i-1}$ and $V_{2i}$, $\forall r\in [\rho_i,2\rho_i]$. It is easy to see that $\rho_{i+1}\ge2\rho_i$. Thus $\rho_i\rightarrow+\infty$. Therefore, any compact set in $\mathbb{R}^2$ only intersects with finitely many circles in $\Pac$. Therefore, we finish the proof.
	\end{proof}

	Before proving the equivalence of ICP-hyperbolic and VEL-hyperbolic, we need to introduce the following lemma, which is proved by He \cite{HE} for the triangulations.
	\begin{lem}\label{hehyp}
		Let $\mathcal{D}$ be an infinite disk cellular decomposition with bounded face degree. Then the following statements are equivalent.
		\begin{enumerate}
			\item The cellular decomposition $\mathcal{D}$ is VEL-hyperbolic.
			\item For any connected subsets of vertices $V_k$ in such that $V_{\infty}=\cup_{k=1}^\infty V_k$ is infinite, we have $\lim_{k\rightarrow\infty} \vel (V_k,\infty) = 0$.
		\end{enumerate}
	\end{lem}
	This lemma will be proved in the Appendix \ref{appendix}. Now we prove the equivalence of VEL-hyperbolic and ICP-hyperbolic.
	\begin{thm}\label{uniformization2}
		Let $\mathcal{D}$ be an infinite disk cellular decomposition with vertex degree bounded by $N$. Let $\Theta\in[0,\pi-\epsilon]$, where condition (C2') is satisfied for some constant $\epsilon_0$. Then the following statements are equivalent:
		\begin{enumerate}
			\item $(\mathcal{D},\Theta)$ is ICP-hyperbolic. 
			\item The infinite disk cellular decomposition $\mathcal{D}$ is VEL-hyperbolic.
		\end{enumerate}
	\end{thm}
	\begin{proof}
		By Theorem \ref{uniformization2}, it is easy to see that if $(\mathcal{D},\Theta)$ is ICP-hyperbolic then $\mathcal{D}$ is VEL-hyperbolic. Therefore, we only need to prove ``2.$\Rightarrow$1.''.

		Let $\{\mathcal{D}_i=(V_i,E_i,F_i)\}_{i\in\mathbb{N}}$ be an exhausting sequence of sub-complexes of the cellular decomposition $\mathcal{D}$, which are finite disk cellular decompositions, i.e.
		\[
		\mathcal{D}_i\subset\mathcal{D}_{i+1},\cup_{i\in \mathbb{N}}{\mathcal{D}_i}=\mathcal{D}.
		\]
		By Theorem \ref{finite_existence}, there exists an embedded ICP $\Pac_i$ for each $\mathcal{D}_i$, with boundary circles inner tangent to the unit disk. For a given $v_0\in V$, without loss of generality, we assume that $v_0\in V_i,~\forall i\in V$. By mobi\"us transformations, we can locate the circle $\Pac_i(v_0)$ at the center of the unit disk for each $i$. By a maximum principle \ref{MaximumPrincipleHyper}, which will be introduced in Section \ref{Sec:5}, we can prove that $r_i(v_0)\ge r_j(v_0),$ whenever $i<j$. Let $\Pac^*_i=\frac{1}{r_i(v_0)}\Pac_i$ be the ICP obtained by scaling $\Pac_i$. Then $\Pac^*_i(v)$ is inner tangent to the circle $C(\frac{1}{r_i(v_0)})$ for each $i$ and $v\in \partial V_i$. We denote by $R_i:=\frac{1}{r_i(v)}$. Since $R_i$ is non-decreasing, it has a limit $R_\infty$. By Lemma \ref{teichumller1}, we see that $R_\infty<+\infty$. Therefore, by the Ring Lemma \ref{ring2}, we obtain an embedded ICP $\mathcal{P}_\infty$ that is contained in $B(0,R_\infty)$. Therefore, we only need to prove the locally finite property.

		Assume that $\Pac_\infty$ is not locally finite in $B(0,R_\infty)$. Then there exists a vertex $x\in \mathrm{Int}(B(0,R_\infty))$, such that $x\in \partial\carrier(\Pac_\infty)$. Since $\partial\carrier(\mathcal{P}_\infty)$ is a closed set, without loss of generality, we can assume that $x$ is a point in $\partial\carrier(\mathcal{P}_\infty)$ closest to the origin $o$. Let 
		Since $\Pac_\infty$ is contained in $B(0,R_\infty)$, by Proposition \ref{maple}, 
		\begin{align*}
			\# \{v\in V:r_\infty(v)\ge \delta\}<+\infty,~\forall \delta>0.
		\end{align*}
		Then there exists a connected infinite vertex set $W=\{v_i\}_{i\in\mathbb{N}_+}$ such that $\lim_{n\rightarrow\infty}c(v_n)=x$, and $W_i=\{v_1,\cdots,v_i\}$ is connected for each $i$. Then $W=\cup_{i=1}^\infty W_i$. Actually, one can draw a straight line connecting the origin and $x$ without intersecting $\partial\carrier(\mathcal{P}_\infty)$. Then let $V_1$ be the set of vertices whose maples intersect with the line segment.  Let $R^*=\mathrm{dist}(0,x)$. Then there exist constants $R'$ and $R''$ such that $R^*<R'<R''<R_\infty$ and $\mathcal{M}(v)\subset B(0,R'),~\forall v\in W$. Now we fix a number $N$, let $k$ be large enough, we can guarantee that   $\mathcal{M}^k(v)\subset B(0,\frac{R'+R''}{2}),~\forall v\in W_n,~n\ge N$. Here, the $M^k(v)$ is the maple of $v$ in the embedded ICP $\mathcal{P}_i$. Let $W'_k$ be the set of vertices whose maples are contained in $ B(0,\frac{R'+R''}{2})$, with a similar argument as in Lemma \ref{teichumller1},  for each sufficiently large $k$ we have
		\[
		\vel(W_n,\partial V_k)\ge \vel(W_k',\partial V_k)\ge C\frac{(R''-R')^2}{(R''+R')^2},
		\]
		for some constant $C$. Therefore, by Lemma \ref{vellimt}, $\vel(W_n,\infty)> C\frac{(R''-R')^2}{(R''+R')^2}$ for each $n$, which contradicts Lemma \ref{hehyp}.
	\end{proof}
	\section{The rigidity of ICPs}\label{Sec:5}
	\subsection{Networks and harmonic function}

	To prove the rigidity of infinite ideal circle patterns (ICPs), we require some tools from the theory of infinite networks. In this subsection, we provide a brief overview of the relevant background (see \cite{anandam2011harmonic, HE} for more details).

	Given an undirected infinite graph $G=(V, E)$, where $V$ and $E$ are the vertex and edge sets of $G$ respectively, we write $v \sim w$ if $v$ and $w$ are connected by an edge in $E$. For a function $f: V \rightarrow \mathbb{R}$, the discrete Laplacian operator $\Delta_\omega$ is given by
	$$
	\Delta_\omega f_v=\sum_{w:w \sim v} \omega_{vw}\left(f_w-f_v\right),
	$$
	where $\omega_{vw}$ is the weight on the edge $E$. For a edge $e=\{v,w\}\in E$, we also write $\omega_{vw}$ as $\omega_{e}$ without ambiguity.

	\begin{defn}
		A function $f: V\rightarrow \mathbb{R}$ is called \textbf{harmonic (subharmonic resp.)} if $\Delta_\omega f_v=0$ ($\Delta_\omega f_v\ge0$ resp.), for each $v\in V$.
	\end{defn}
The following maximum principle is basic for harmonic and subharmonic functions on finite graphs.
\begin{lem}(\cite[Proposition 1.4.1]{anandam2011harmonic})\label{maxharmonic}
    Let $G=(V,E)$ be a finite connected graph. If $f$ a subharmonic function on $\mathrm{int}(V)$, that attains its maximum at a vertex in $\mathrm{int}(V)$, then s is constant.
\end{lem}

	The following Liouville's theorem is crucial for our proof of the rigidity theorem.
	\begin{lem}(\cite[Lemma 5.4]{HE}\label{harmonic_current})
	Let $G=(V,E)$ be a $\vel$-parabolic	infinite graph.
        If there is a uniform constant $C>0$, such that 
		$$
		\sum_{w:w \sim v}\omega_{vw} \leq C,
		$$
	then all bounded harmonic functions on $G$ are constant.
	\end{lem}
	\subsection{Variational principles and maximum principles for ICPs}
        The rigidity result introduced in this section follows from the pioneering work of He \cite{HE}. See also refer readers to \cite{MR4389487,MR4792293} for some recent studies of the rigidity of infinite triangulations with the discrete conformal structure.

    We first introduce the variational principles for ICPs. We denote by $\triangle(vwv_f)$ the triangle formed by two centers $v,w$ and one point $v_f$, which is an intersection point of the circles $\Pac(v), \Pac(w)$. Let $\alpha_{v}^w, \alpha_{w}^v$ be the corresponding inner angles at the centers, as we defined in Preliminary \ref{Ideal_circle_patterns_planes}, $l_{vw}$ be the length of $\overline{vw}$, $d_{vw}$ be the length of the altitude to the side $\overline{vw}$ of $\triangle(v w v_f)$, and $\tilde{Q}_{vw}$ be the quadrilateral formed by two centers $v,w$ and two face points $v_{f_1},v_{f_2}$. 
    For simplicity, let $r_v=r(v)$ be the radius of the circle $\Pac(v)$.
    Set $u_v = \ln r_v$ ($u_v= \ln \tanh \frac{r_v}{2}$ resp.) in Euclidean (hyperbolic resp.) background geometry, which are usually called the \textbf{discrete conformal factors} in the literature, see e.g. \cite{gu2008computational}. Then the following variational principle holds, see \cite[Lemma 2.2]{ge2021combinatorial}. 

	\begin{lem}(Variational principle)\label{vari}
		Let $\Theta(v,w) \in (0, \pi)$ be a fixed intersection angle. In hyperbolic background geometry, we have
		\[
		\frac{\partial \alpha_{v}^w}{\partial u_v} = -\frac{2\cosh l_{vw} \sinh d_{vw}}{\sinh l_{vw}} < 0, \quad \frac{\partial \alpha_{v}^w}{\partial u_w} = \frac{\partial \alpha_{w}^v}{\partial u_v} = \frac{2\sinh d_{vw}}{\sinh l_{vw}} > 0,
		\]
        and
        \[
         \quad \frac{\partial \operatorname{Area}(\tilde{Q}_{vw})}{\partial u_v}=-\frac{\partial(\alpha_v^w+\alpha_w^v)}{u_v}> 0.
        \]
		In Euclidean background geometry, we have
		\[
		\frac{\partial \alpha_{v}^w}{\partial u_v}  = -\frac{2d_{vw}}{l_{vw}} < 0, \quad \frac{\partial \alpha_{v}^w}{\partial u_w} = \frac{\partial \alpha_{w}^v}{\partial u_v}  = \frac{2d_{vw}}{l_{vw}} > 0.
		\]
	\end{lem}
Moreover, in hyperbolic geometry, the following proposition holds.
    \begin{prop}(\cite[Lemma 2.3]{ge2021combinatorial}\label{hyperconstr}
	In hyperbolic geometry, for any $\epsilon > 0$, there exists a positive number $L(\epsilon)$ such that $ \alpha_v^w < \epsilon$ whenever $r_v > L(\epsilon)$.
    \end{prop}

	Moreover, we have the following lemma for estimating the partial derivatives.
	\begin{lem}(\cite[Lemma 2.4]
{ge2025characterizationinfiniteidealpolyhedra})\label{partialthetabound}
		In both hyperbolic and Euclidean background geometries, let $\Theta(v,w) \in [\epsilon, \pi-\epsilon]$ be fixed. Then
		\[
		0 < \frac{\partial \alpha_v^w}{\partial u_w} \leq C \alpha_v^w,
		\]
		where $C$ only depends on $\epsilon$.
	\end{lem}

	Now, we extend the concept of the discrete conformal factor to generalized circles including horocycles and hypercycles as shown in Figure \ref{fig:generalized circles}.
	\begin{figure}[H]
		\centering
		\includegraphics[width=0.3\textwidth]{circle_horocycle_and_hypercycle.png}
		\caption{Circle, horocycle and hypercycle.}
		\label{fig:generalized circles}
	\end{figure}

Here, a hypercycle refers to a curve consisting of points that are at a constant distance from a geodesic line. We call the geodesic line the ``center'' of the corresponding hypercycle, as indicated by the dashed line in Figure \ref{fig:generalized circles}. The ``radius'' of a hypercycle in this paper refers to the distance from the center to the hypercycle. Then we define the discrete conformal factor $u_v$ of a hypercycle with radius $r_v$ by 
	\[
	u_v=\mathrm{arccot}(\sinh(r_v))= \int^{+ \infty}_{r_v}\frac{1}{\cosh{ x}}\mathrm{d}x.
	\]\

    With the above definitions, consider an ICP \(\mathcal{P}\) in \(\mathbb{R}^2\). If all circles in \(\mathcal{P}\) have nonempty intersection with the unit disk, then they can be regarded as generalized circles in the hyperbolic plane \(\mathbb{H}^2\). We call this kind of ICPs as \textbf{generalized hyperbolic ICPs}.

	Besides, we define the discrete conformal factor of a horocycle as $0$. Then we have the following extended variational principle, which originates from a generalized maximum principle in the work of He \cite[2.3]{HE}. 

\begin{figure}[htbp]
		\centering
		\includegraphics[width=1.0\textwidth]{quadrilateral_perpendicular_circle.png}
		\caption{Configurations of two intersecting generalized hyperbolic circles with the intersection angle $\Theta(v,w)=\Theta_{vw}$.}
		\label{fig:generalized quadrilateral}
	\end{figure}


\begin{lem}[Generalized variational principle]\label{vari2}
    Let $\Pac(w)$ be a circle in the hyperbolic plane $\mathbb{H}^2$. Assume that $\mathcal{P}(v)$ is a generalized circle whose generalized discrete conformal factor is $u_v\in(-\infty,\frac{\pi}{2})$. Then the following holds. Then the inner angle $\alpha_w^v=\alpha^v_w(u_v,u_w)$ is a continuous function of $u_v$ and $u_w$ with $u_w\in(-\infty,0)$. Moreover, we have 
    \[
    \pp{\alpha_w^v}{u_v}>0.
    \]
\end{lem}
\begin{proof}
    With direct calculation, we see that 
    \[ 
    \cot{\frac{\alpha_w^v}{2}}=\frac{1}{\sin\Theta(v,w)}(\mathrm{coth}r_v\sinh r_w+\cos(\Theta(v,w))\cosh r_w),
    \]
    when $\mathcal{P}(v)$ is a hyperbolic circle, and 
    \[
    \cot{\frac{\alpha_w^v}{2}}=\frac{1}{\sin\Theta(v,w)}(\mathrm{tanh}r_v\sinh r_w+\cos(\Theta(v,w))\cosh r_w).
    \]
     when $\mathcal{P}(v)$ is a hypercycle. It is easy to check that $\alpha_w^v$ is a continuous function of $u_v$ and $u_w$. Moreover,
     \[
     \pp{\alpha_w^v}{u_v}=\frac{\sin^2{\alpha^v_w}\sinh{r_w}}{\sin\Theta(v,w)\cosh{r_v}}>0.
     \]

     Therefore, we finish the proof.
\end{proof}
	\subsection{The rigidity of embedded ICPs in the hyperbolic case}
	In order to prove the rigidity of embedded ICPs in the hyperbolic case,  we  establish the following maximum principle for generalized hyperbolic ICPs such that $u_v< 0,~\forall v\in \mathrm{Int}(V)$.  
	\begin{lem}\label{MaximumPrincipleHyper}(Maximum principle for generalized hyperbolic ICPs)
	Let $\mathcal{D}=(V,E,F)$ be a finite disk cellular decomposition, and $\Theta\in (0,\pi)^E$ be the given intersection angle. Assuming that $\Pac$ and $\Pac^*$ are two generalized ICPs of $(\mathcal{D},\Theta)$ with $u(\Pac(v)),u(\Pac^*(v))\le 0,~\forall v\in \mathrm{int}(V)$. 
 If $u(\Pac(v))\ge u(\Pac^*(v))$ and $u(\Pac^*(v))\le 0$,~$\forall v\in \partial V$. Then we have 
            \[
            u(\Pac(v))\ge u(\Pac^*(v)),~\forall v\in V
            \]

	\end{lem}
	\begin{proof}
	    For simplicity, we write $u_v=u(\Pac(v))$ and $u^*_v=u(\Pac^*(v))$ for each vertex $v$. Let \[\tilde{u}_v=
		\left\{\begin{array}{cc}
			u_v, & v\in \mathrm{int}(V),\\
			\min\{0,u_v\}, & v\in \partial V.
		\end{array}\right.
		\]
        By the definition of ICPs and the variational principle \ref{vari2} we have 
        \[
        \sum_{w:w\sim v}\alpha_v^w(\tilde{u}_v,\tilde{u}_w)\le2\pi,~\forall v\in \mathrm{int}
(V)\]
        and
        \[\sum_{w:w\sim v}\alpha_v^w(u_v^*,u_w^*)=2\pi,~\forall v\in \mathrm{int}
(V).        \]
Then by the Newton-Leibniz formula, for each $v\in \mathrm{int}(V)$ we have 
\begin{align*}
    0&<\sum_{w:v\sim w}\int_0^1\pp{\alpha_v^w((1-t)\tilde{u}_v+tu_v^*,(1-t)\tilde{u}_w+tu_w^*)}{u_w}\mathrm{d}t\cdot(u_w^*-\tilde{u}_w)
    \\&+\sum_{w:v\sim w}\int_0^1\pp{\alpha_v^w((1-t)\tilde{u}_v+tu_v^*,(1-t)\tilde{u}_w+tu_w^*)}{u_v}\mathrm{d}t\cdot({u}_v^*-\tilde{u}_v).
\end{align*}


Then by the variational principles \ref{vari} and \ref{vari2}, we have
\[
\Delta_\omega(u^*_v-\tilde{u}_v)\ge h(u_v^*-\tilde{u}_v),~\forall v\in \mathrm{int}(V),
\]
where $\omega$ is a weight such that $$\omega_{vw}=\int_0^1\pp{\alpha_v^w((1-t)\tilde{u}_v+tu_v^*,(1-t)\tilde{u}_w+tu_w^*)}{u_w}\mathrm{d}t>0,$$ and 
$h$ is a positive function. It is easy to check that the function $\max\{u_v^*-\tilde{u}_v,0\}$ is a subharmonic function, i.e.
\[
\Delta_{\omega}\max\{u_v^*-\tilde{u}_v,0\}\ge 0,~\forall v\in \mathrm{int}(V).
\]
Therefore, by the maximum principle of subharmonic functions \ref{maxharmonic}, we have
\[
\max_{v\in \mathrm{int(V)}}\{u^*_v-u_v\}=\max_{v\in \mathrm{int(V)}}\{u^*_v-\tilde{u}_v\}=0
\]
Therefore, we finish the proof.
	\end{proof}
\begin{rem}
    Actually, if we only assume that  $u(\Pac(v))\ge u(\Pac^*(v))$,~$\forall v\in \tilde\partial V$, the maximum principle also holds.
\end{rem}

	\begin{thm}
		Let $\mathcal{D} = (V, E, F)$ be a finite cellular decomposition of a disk, and let $\Theta: E \rightarrow [0, \pi)$ be a function defined on $E$ that satisfies $(C1)$. Let $\Pac$ and $\Pac^*$ be disk patterns in $U$ realizing $(\mathcal{D}, \Theta)$. Assume that both $\Pac$ and $\Pac^*$ are locally finite in $U$. Then there exists a hyperbolic isometry $f: U \rightarrow U$ such that $\Pac^* = f(\Pac)$.
	\end{thm}

	\begin{proof}
		Let $P$ and $P^*$ be as given. Choose an arbitrary vertex $v_0$ of $G$. Since they are ICPs contained in the unit disk, we view those two patterns as ICPs in the hyperbolic plane $\mathbb{H}^2$. We denote by $r_{\mathrm{hyp}}(\cdot)$ the hyperbolic radius of the corredponding circle.
        We will show that 
		\[
		r_{\text{hyp}}\left(\Pac(v_0)\right) = r_{\text{hyp}}\left(\Pac^*(v_0)\right),
		\]
		which implies the theorem. 

        Without loss of generality, we assume that $\Pac(v_0)$ and $\Pac^*(v_0)$ are circles centered at the origin.
		Assume, for contradiction, that $r_{\text{hyp}}\left(\Pac(v_0)\right) < r_{\text{hyp}}\left(\Pac^*(v_0)\right)$. Then there exists a constant $\delta > 1$ that is sufficiently close to $1$, such that 
		\[
		r_{\text{hyp}}\left(\delta \Pac(v_0)\right) < r_{\text{hyp}}\left(\Pac^*(v_0)\right).
		\]

		Suppose that $\Pac_\delta$ is an ICP obtained from $\mathcal{P}$ via the affine transformation $g(x)=\delta x$.
        Since $\mathcal{P}$ is locally finite in $U$, there are only finite circles in $\Pac_\delta$ that intersect $U$.
        Let $V_1\subset V$ be the set of vertices defined as 
        \[
        V_1=\{v\in V:\Pac_\delta(v)\subset U\}.
        \]
        It is easy to see that $\mathcal{P}_\delta(v)\cap \tilde\partial U\neq \emptyset$ for all $v\in \partial V_1$.
        Let $G$ be the $1-$skeleton of $\mathcal{D}$.
        Now we consider the induced subgraph $G_1:=I_G(V_1\cup\tilde{\partial}V_1)$.
        Let $\Pac_1 \subset \Pac_\delta$  and $\Pac_1^* \subset \Pac^*$ be the ICPs of $G_0$ in $\Pac_\delta$ and $\Pac^*$ respectively.

		Since for each vertex $v\in \tilde{\partial}V_1$, the disk $\Pac_1(v)$ intersects the boundary of $U$, $\Pac$ can be viewed as a horocycle or hypercycle, which means that $u(P_1(v))\ge 0$.
        Therefore, we have
		\[
		r_{\text{hyp}}\left(P_1(v)\right) > r_{\text{hyp}}\left(\Pac^*(v)\right).
		\]

		Applying Lemma~\ref{MaximumPrincipleHyper}, we conclude that
		\[
		r_{\text{hyp}}(P_\delta(v_0))=r_{\text{hyp}}\left(P_1(v_0)\right) \geq r_{\text{hyp}}(P_1^*(v_0))=r_{\text{hyp}}(P^*(v_0)),
		\]
		which contradicts the fact that $r_{\text{hyp}}(P_\delta(v_0))< r_{\text{hyp}}(P^*(v_0))$. Therefore, the assumption must be false, and we conclude that 
		\[
		r_{\text{hyp}}\left(P(v_0)\right) = r_{\text{hyp}}\left(P^*(v_0)\right).
		\]

		Since $v_0$ was arbitrary, the result follows by the rigidity of hyperbolic isometries.
	\end{proof}



	\subsection{The rigidity of embedded ICPs in the parabolic case}
	Denote the 1-skeleton of $\mathcal{D}$ by $G$.
	We establish the following maximum principle for generalized hyperbolic circle packings:

	\begin{lem}\label{maximum_principle_euc}(Maximum Principle in Euclidean plane)
		Let $\mathcal{D}=(V,E,F)$  be a finite cellular decomposition of a disk and $\Theta \in(0, \pi)^E$ satisfies $(C1)$.  Assume $\mathcal{P}= \{\Pac(v)\}_{v\in V}$ and $\mathcal{P^*}= \{\Pac^*(v)\}_{v\in V}$ are two finite ideal disk patterns realizing $(\mathcal{D}, \Theta)$. Then the maximum (or minimum) of $r^*_v/ r_v$ is attained at a boundary vertex.
	\end{lem}
	\begin{proof}
		To see this, we only need to prove that the difference of the discrete conformal factors $u_v-u^*_v=\ln r_v-\ln r^*_v$ attains its minimum and maximum at the boundary $\partial V$. Indeed, with a similar argument as in Lemma \ref{MaximumPrincipleHyper} we see that 
        $\Delta_\omega( u_v-u^*_v)=0$, where
        \[\omega_{vw}=\int_0^1\pp{\alpha_v^w((1-t)u_v+tu_v^*,(1-t)u_w+tu_w^*)}{u_w}\mathrm{d}t>0.\]
        Therefore, by the maximum principle of discrete harmonic functions, we finish the proof.
	\end{proof}
	Let $\mathcal{D}=(V,E,F)$  be an infinite cellular decomposition embedded on a plane and $\Theta \in(0, \pi)^E$ satisfies $(C1)$.  Assume $\mathcal{P}= \{\Pac(v)\}_{v\in V}$ be an infinite ideal disk pattern realizing $(\mathcal{D}, \Theta)$.  Let $D(v)$ be the corresponding closed disk of $\Pac(v)$ and $c_v$ be the center of the circle $\Pac(v)$. For a circle $C$, we denote by $V_C(\mathcal{P})$ the set of vertices $v \in V$ for which $\Pac(v) \cap C \neq \emptyset$. And we denote $\mathcal{P}(V_C) = \cup_{v \in V_C} D(v)$.

%%	Here we give a discrete version of modulus of annuli.


	For any circle \( C \subset \mathbb{C} \), we define its \textbf{normalized radius} (or distortion) by
	\[
	\tau(C) = \frac{r(C)}{\mathrm{dist}(0, C)},
	\]
	where \( r(C) \) denotes the radius of the circle \( C \), and \( \mathrm{dist}(0, C) \) is the Euclidean distance from the origin to \( C \).

	Given an infinite circle pattern \( \mathcal{P} = \{ \Pac(v) \}_{v \in V} \), we define its \textbf{distortion coefficient} by
	\[
	\tau(\mathcal{P}) = \limsup_{i \rightarrow +\infty} \tau(\Pac({v_i})),
	\]
	where \( \{v_i\}_{i \in \mathbb{N}} \) is an arbitrary enumeration of the vertex set \( V \). It is clear that \( \tau(\mathcal{P}) \) is independent of the choice of enumeration, and moreover, it is invariant under Euclidean similarities \( f: \mathbb{C} \to \mathbb{C} \), that is,
	\[
	\tau(f(\mathcal{P})) = \tau(\mathcal{P}).
	\]

	The quantity \( \tau(\mathcal{P}) \) measures how uniformly the radii of the circles are controlled relative to their Euclidean distance from the origin.


	\begin{lem}\label{rigidity_bound_tau_finite}
		Let $\mathcal{P}$ and $\mathcal{P}^*$ be as in Lemma~\ref{uniform_bound_infinite}. If $\tau(\mathcal{P}) < +\infty$, then there exists a uniform constant $C \geq 1$ such that
		\[
		\frac{1}{C} \leq \frac{r^*_{v}}{r_{v}} \leq C, \quad \forall v \in V.
		\]
	\end{lem}

	\begin{proof}
		Without loss of generality, we assume $\mathcal{P}^*({v_0})= \mathcal{P}({v_0})$ and the center $c_{v_0}$ of $\Pac(v_0)$ lies at the origin.

		Let $v_1$ be an arbitrary vertex different from $v_0$, and let $V_0 \subset V$ be a finite set of vertices containing both $v_0$ and $v_1$. Since $\tau(\mathcal{P}) < +\infty$, we can choose $\delta > 3+\delta_0$, where $\delta_0$ is the constant in Lemma \ref{appl_ring}, such that
		\begin{equation} \label{taufiniteP}
			\tau(\Pac(v)) = \frac{r_v}{\mathrm{dist}(0, \Pac(v))} \leq \frac{\delta}{3}, \quad \forall v \in V \setminus V_0.
		\end{equation}

		Let $\tilde{r} > 0$ be such that $\mathcal{P}(V_0) = \bigcup_{v \in V_0} \Pac(v) \subset D(0, \tilde{r})$. Then for any $r > \tilde{r}$, there is no disk $\Pac(v)$ in $\mathcal{P}$ intersecting both $C(0, r)$ and $C(0, \delta r)$. Otherwise, if $\Pac(v)$ intersects  both $C(0, r)$ and $C(0, \delta r)$, then $v \in V \setminus V_0$. However, if $v \in V \setminus V_0$, we have $\mathrm{dist}(0, \Pac(v)) \leq r$ and $\delta r \leq \mathrm{dist}(0, \Pac(v)) + 2r_v$. By \eqref{taufiniteP}, we have $\delta \le 3$ which contradicts $\delta > 3$. Hence, for any $r > \tilde{r}$,
		\begin{equation} \label{taufiniteP1}
			V_{C(0, r)}(\mathcal{P}) \cap V_{C(0, \delta r)}(\mathcal{P}) = \emptyset.
		\end{equation}

		Let $\tilde{r}_n := \delta^n \tilde{r}$, $W_n := \{w\in V:c(w)\in B(0, \tilde{r}_n)\}$ and $V_n=\tilde{\partial}W_n$ , for $n \geq 1$. From \eqref{taufiniteP1} and Lemma \ref{appl_ring}, the sets $\{V_n\}_{n \in \mathbb{N}}$ are mutually disjoint and satisfy the property that $V_{n_2}$ separates $V_{n_1}$ from $V_{n_3}$ for $0 \leq n_1 < n_2 < n_3$.

		By \eqref{vel_sum} and Lemma~\ref{teichumller1}, we have
		\begin{align*}
			\mathrm{VEL}(V_2, V_{2k-1}) &\geq \sum_{n=1}^{k-1} \mathrm{VEL}(V_{2n}, V_{2n+1}) \\
			&\geq \frac{(k-1)\sin^4 \epsilon}{8(\sin \epsilon + 4C(\epsilon, \epsilon_0, N) + 4)^2}.
		\end{align*}

		Let $k$ be an integer larger than
		\[
		\frac{144(\sin \epsilon + 4C(\epsilon, \epsilon_0, N) + 4)^4}{\sin^8 \epsilon} + 2.
		\]
		Then,
		\[
		\mathrm{VEL}(V_2, V_{2k-1}) \geq \frac{18(\sin \epsilon + 4C(\epsilon, \epsilon_0, N) + 4)^2}{\sin^4 \epsilon}.
		\]

		From Lemma~\ref{teichmuller2}, there exists $\hat{r} > 0$ such that for any $\rho \in [\hat{r}, 2\hat{r}]$, the vertex set $V_{C(0, \rho)}(\mathcal{P}^*)$ separates $V_2$ from $V_{2k-1}$, and hence separates $V_1$ from $V_{2k}$. Moreover, since $V_1\cap V_2=\emptyset$ and $V_{2k-1}\cap V_{2k}=\emptyset$, we have
		\begin{align}
			P^*(V_1) &\subset \mathbb{D}(0, \hat{r}), \label{taufiniteP3} \\
			P^*(V_{2k}) &\subset \mathbb{C} \setminus D(0, 2\hat{r}). \label{taufiniteP4}
		\end{align}

		Let $G_1$ be the subgraph of $G$ consisting of vertices $V_{D(0, \tilde{r}_1)}(\mathcal{P})$, and let $G_2$ be the subgraph of $G$ consisting of $V_{D(0, 2\hat{r})}(\mathcal{P}^*)$. By Lemma~\ref{MaximumPrincipleHyper}, for each $v \in V_{D(0, \tilde{r}_1)}(\mathcal{P})$,
		\begin{equation} \label{taufiniteP5}
			r_{\mathrm{hyp}}\left(\frac{1}{2\hat{r}} \Pac^*(v)\right) \leq r_{\mathrm{hyp}}\left(\frac{1}{\tilde{r}_1} \Pac(v)\right),
		\end{equation}
		and for $v \in V_{D(0, 2\hat{r})}(\mathcal{P}^*)$,
		\begin{equation} \label{taufiniteP6}
			r_{\mathrm{hyp}}\left(\frac{1}{2\hat{r}} \Pac^*(v)\right) \geq r_{\mathrm{hyp}}\left(\frac{1}{\tilde{r}_{2k}} \Pac(v)\right).
		\end{equation}

		Since the disks involved in \eqref{taufiniteP5} and \eqref{taufiniteP6} are all contained in $(1/2)\mathbb{D}(0,1)$, the hyperbolic and Euclidean radii are uniformly comparable. Thus, there exists a universal constant $\tilde{C} > 0$ such that for $v = v_0, v_1$,
		\begin{align}
			\frac{1}{2\hat{r}} r^*_{v} &\leq \tilde{C} \cdot \frac{1}{\tilde{r}_1} r_{v}, \label{taufiniteP7} \\
			\tilde{C} \cdot \frac{1}{2\hat{r}} r^*_{v} &\geq \frac{1}{\tilde{r}_{2k}} r_{v}. \label{taufiniteP8}
		\end{align}

		Combining \eqref{taufiniteP7} and \eqref{taufiniteP8}, and using $\mathcal P^*(v_0) = \mathcal P(v_0)$ and $\tilde{r}_n = \delta^n \tilde{r}$, we obtain
		\[
		\frac{1}{\tilde{C}^2 \delta^{2k-1}} \leq \frac{r^*_{v_1}}{r_{v_1}} \leq \tilde{C}^2 \delta^{2k-1}.
		\]

		Letting $C := \tilde{C}^2 \delta^{2k-1}$ completes the proof, as this constant does not depend on the choice of $v_1$.
	\end{proof}

	Given an infinite circle pattern \( \mathcal{P} = \{ \Pac(v) \}_{v \in V} \), we define $W\subset V$ be the set consisting of vertex $v$ such that $\tau(\Pac(v)) \geq 1$. 

	\begin{lem}\label{tau_P_bound}
		Let $\mathcal{P}$ and $\mathcal{P}^*$ be as in Lemma~\ref{uniform_bound_infinite}. If $\tau(\mathcal{P}) = +\infty$, then
		$$\limsup_{i \rightarrow +\infty}\tau(\Pac^*(v_i))>0,$$
		where \( \{v_i\}_{i \in \mathbb{N}} \) is an arbitrary enumeration of the vertex set \( W \).
	\end{lem}
	\begin{proof}
		Without loss of generality, we assume that $\Pac^*(v_0)= \Pac(v_0)$ and the center $c_{v_0}$ of $\Pac(v_0)$ lies at the origin.

		We prove this lemma by contradiction. If $\limsup_{i \rightarrow +\infty}\tau(\Pac^*(v_i))=0$, then for any $0<\epsilon < 1/2$, there is a finite vertex set $V_0\subset V$ such that $v_0\in V_0$ and 
		\begin{equation} \label{tauinfinite_P}
			\tau(\Pac(v)) = \frac{r_v}{\mathrm{dist}(0, \Pac(v))} < \epsilon \quad \forall v \in W \setminus V_0.
		\end{equation}



		Let $W^{\prime}=W-V_0$, and let $\tilde{G}$ be the subgraph of $G$ obtained by removing the vertices in $W^{\prime}$ as well as the edges with an end in $W^{\prime}$.
		Let $\tilde{r} > 0$ be such that $D(V_0) = \bigcup_{v \in V_0} D(v) \subset D(0, \tilde{r})$. Let $\tilde{r}_n := 4^n \tilde{r}$, $W_n := \{w\in V:c(w)\in B(0,\tilde{r}_n)\}$, and $V_n=\tilde{\partial} W_n$ for $n \geq 1$. From \eqref{tauinfinite_P}, we know for $n_i\neq n_j$, we have 
		\begin{equation} \label{tauinfinite_P1}
			V_{n_i} \cap V_{n_j} \subset W^{\prime}=W-V_0
		\end{equation}
		and for any $0 \leq n_1<n_2<n_3$, $V_{n_2}$ separates $V_{n_1}$ from $V_{n_3}$ in $G$. Let $\operatorname{VEL}_{\tilde{G}}\left(V_{n_i}, V_{n_j}\right)$ denote the vertex extremal length between $V_{n_i} \cap\left(V-W^{\prime}\right)$ and $V_{n_j} \cap\left(V-W^{\prime}\right)$ in the subgraph $\tilde{G}$.

		By \eqref{vel_sum} and Lemma~\ref{teichumller1}, we have
		\begin{align*}
			\mathrm{VEL}_{\tilde{G}}(V_2, V_{2k-1}) &\geq \sum_{n=1}^{k-1} \mathrm{VEL}_{\tilde{G}}(V_{2n}, V_{2n+1}) \\
			&\geq \frac{(k-1)\sin^4 \epsilon}{8(\sin \epsilon + 4C(\epsilon, \epsilon_0, N) + 4)^2}.
		\end{align*}

		Let $k$ be an integer larger than
		\[
		\frac{288(\sin \epsilon + 4C(\epsilon, \epsilon_0, N) + 4)^4}{\sin^8 \epsilon} + 2.
		\]
		Then,
		\begin{equation}\label{tauinfinite_P2}
			\mathrm{VEL}_{\tilde{G}}(V_2, V_{2k-1}) \geq \frac{36(\sin \epsilon + 4C(\epsilon, \epsilon_0, N) + 4)^2}{\sin^4 \epsilon}.
		\end{equation}


		\emph{Step I: we prove that  there exists a  $\hat{r} > 0$ such that for any $\rho \in [\hat{r}, 2\hat{r}]$, the vertex set $V_{C(0, \rho)}(\mathcal{P}^*)$ separates $V_2$ from $V_{2k-1}$ in $G$.}

		Let $U_{2,2 k-1}$ be the set of vertices in $G$ which is separated from $V_0$ by $V_2$, and separated from $\infty$ by $V_{2 k-1}$. In fact, let $A(0,a, b)= \{z\in \mathbb C: a\leq |z|\leq b \}$, then 
		\begin{equation}\label{tauinfinite_P3}
			U_{2,2 k-1}= \{v\in V : D(v) \cap A(0, \tilde r_2, \tilde r_{2k-1})\}.
		\end{equation}
		Let $W^{\prime \prime}=U_{2,2 k-1} \cap W$. Then, clearly the cardinality of $W^{\prime \prime}$ is bounded by a universal constant $\tilde C_1$.

		Now, we use the method similar in proving Lemma \ref{teichmuller2}.

		Let
		\begin{equation}\label{tauinfinite_P4}
			\tilde r^* = \min \{r: D(0, r) \cap D(v) \neq \emptyset, \forall v \in V_2 \}.
		\end{equation}

		Let $\gamma^* \in \Gamma^*(V_2, V_{2k-1})$.  Thus, by the minimality of $\tilde r$, we have 
		\begin{equation}\label{tauinfinite_P5}
			\mathrm{diam} (\mathcal P^*(\gamma^*))\geq \tilde r^*.
		\end{equation}

		By contradiction, we assume there is a $\rho \in [\tilde r^*, 2\tilde r^*]$ such that $V_{C(0, \rho)}(\mathcal{P}^*)$ does not  separate $V_2$ from $V_{2k-1}$ in $G$. Thus, there is a $\gamma_0 \in \Gamma(V_2, V_{2k-1})$ such that
		\begin{equation}
			\gamma_0 \cap V_{C(0, \rho)}(\mathcal{P}^*) = \emptyset.
		\end{equation}
		By the definition of $V_{C(0, \rho)}(\mathcal{P}^*)$, we have
		\begin{equation}
			D(v)^* \cap C(0, \rho)   = \emptyset, \quad \forall v \in \gamma_0.
		\end{equation}
		Hence 
		\begin{equation}\label{tauinfinite_P6}
			\mathcal{P}^*(\gamma_0) \cap C(0, \rho)     = \emptyset.
		\end{equation}
		Since $\gamma_0 \in \Gamma(V_2, V_{2k-1})$, we know $\gamma_0$ contains a vertex in $V_2$. By the definition of $	\tilde r^*$ and $\mathcal{P}^*(\gamma_0)$, we know
		\begin{equation}\label{tauinfinite_P7}
			\mathcal{P}^*(\gamma_0) \cap C(0, \tilde r^* )   \neq  \emptyset.
		\end{equation}
		Combining \eqref{tauinfinite_P6} and \eqref{tauinfinite_P7}, with $\tilde r^* \leq \rho$ we know 
		\begin{equation}
			\mathcal{P}^*(\gamma_0) \subset \mathbb D(0, \rho).
		\end{equation}
		Hence, since $\gamma^* \in \Gamma^*(V_2, V_{2k-1})$ and $\gamma_0 \in \Gamma (V_2, V_{2k-1})$, we have
		\begin{equation}\label{tauinfinite_P8}
			\mathcal{P}^*(\gamma^*) \cap D(0, \rho) \supset	\mathcal{P}^*(\gamma^*) \cap 	\mathcal{P}^*(\gamma_0) \supset \mathcal{P}^*(\gamma^* \cap \gamma_0) \neq \emptyset.
		\end{equation}

		Define $m(v)={ \mathrm{diam} (D(v)^* \cap D(0, 3\tilde r^*))}/{\tilde r^*}$, which is a vertex metric in the cellular decomposition $\mathcal{D}$. 
		If $\gamma^*$ is connected, \eqref{tauinfinite_P8} implies two cases:
		\begin{itemize}
			\item (1) If $\mathcal{P}^*(\gamma^*) \subset D(0, 3\tilde r^*)$, from \eqref{tauinfinite_P5}, we have $$\int_{\gamma^*} d m=\sum_{v \in \gamma^*} \mathrm{diam} (D(v)^* \cap D(0, 3\tilde r^*)) /{\tilde r^*}=\sum_{v \in \gamma^*} \mathrm{diam} (D(v)^*) /{\tilde r^*} \geq \mathrm{diam} (\mathcal P^*(\gamma^*))  /{\tilde r^*} \geq 1$$.

			\item (2) If $\mathcal{P}^*(\gamma^*)$ is not completely contained $D(0, 3\tilde r^*)$, from \eqref{tauinfinite_P8}, we have $\mathcal{P}^*(\gamma^*)$ joining $D(0, \rho)$ and $D(0, 3\tilde r^*))$. Then we have
			$$\int_{\gamma^*} d m=\sum_{v \in \gamma^*} \mathrm{diam} (D(v)^* \cap D(0, 3\tilde r^*)) /{\tilde r^*}=(3\tilde r^*- \rho) /{\tilde r^*} \geq 1$$.
		\end{itemize}
		Since every $\gamma^*\in \Gamma^*(V_2, V_{2k-1})$ contains a connected sub-curve in $\Gamma^*(V_2, V_{2k-1})$, it follows that $m$ is $\Gamma^*(V_2, V_{2k-1})$-admissible.

		From \eqref{tauinfinite_P}, for any $v\in W^{\prime} \supset W^{\prime \prime}$, we have
		$$
		m (v)\leq 6\epsilon.
		$$
		Since the cardinality of $W^{\prime \prime}$ is at most $\tilde C_1$, we see that
		$$
		\sum_{v \in W^{\prime \prime}} m(v) \leq 6 C_1 \varepsilon
		$$
		Now let $\beta^* \in \Gamma_{\tilde{G}}^*\left(V_2 \cap\left(V-W^{\prime}\right), V_{2 k-1} \cap\left(V-W^{\prime}\right)\right)$. Then, the union $\gamma^*=\beta^* \cup W^{\prime \prime}$ is a vertex curve in $\Gamma_G^*\left(V_2, V_{2 k-1}\right)$. 
		$$
		\sum_{v \in \beta^*} m(v) =  \sum_{v \in \gamma^*} m(v) -\sum_{v \in W^{\prime \prime}} m(v)  \geq 1-6 C_1 \varepsilon
		$$


		We choose $\varepsilon>0$ so small that $1-6 C_1 \varepsilon \geq 1 / \sqrt{2}$. Then $\sqrt{2} \eta$ is $\Gamma_{\tilde{G}}^*\left(V_2 \cap(V-\right.$ $\left.\left.W^{\prime}\right), V_{2 k-1} \cap\left(V-W^{\prime}\right)\right)$-admissible. Thus, 
		$$
		\begin{aligned}
			\operatorname{VEL}_{\tilde{G}}\left(V_2, V_{2 k-1}\right) & =\operatorname{MOD}\left(\Gamma_{\tilde{G}}^*\left(V_2 \cap\left(V-W^{\prime}\right), V_{2 k-1} \cap\left(V-W^{\prime}\right)\right)\right) \\
			& \leq \operatorname{area}(\sqrt{2} m)
		\end{aligned}
		$$

		By a similar argument as in the proof of Lemma \ref{teichumller1}, we see that
		$$
		\mathrm{area}(\sqrt{2} m)\le \frac{36(\sin\epsilon+4C(\epsilon,\epsilon_0,N)+4)^2 }{\sin^4\epsilon}.
		$$
		This contradicts \eqref{tauinfinite_P2}.





		\emph{Step II: we finish the proof.}


		We have proved there exists a $\hat{r} > 0$ such that for any $\rho \in [\hat{r}, 2\hat{r}]$, the vertex set $V_{C(0, \rho)}(\mathcal{P}^*)$ separates $V_2$ from $V_{2k-1}$ in $G$. Then we have 
		\begin{equation}
			V_2 \cap V_{2 k-1} \subset V_{C(0, \hat{r})}(\mathcal{P}^*)\cap V_{C(0,2  \hat{r})}(\mathcal{P}^*).
		\end{equation}
		From  \eqref{tauinfinite_P} and \eqref{tauinfinite_P1}, we have
		\begin{equation}
			V_2 \cap V_{2 k-1} \subset  V_{C(0, \hat{r})}(\mathcal{P}^*)\cap V_{C(0,2  \hat{r})}(\mathcal{P}^*) \cap (W-V_0) = \emptyset,
		\end{equation}
		which implies
		$$
		V_{C(0, 4^2\tilde{r})}(\mathcal{P})\cap V_{C(0, 4^{2k-1}\tilde{r})}(\mathcal{P}) =\emptyset.
		$$
		Since $\tilde{r}$ is arbitrarily large, this contradicts $\tau(\mathcal{P}) = +\infty$.
	\end{proof}

	\begin{lem}\label{rigidity_bound_tau_infinite}
		Let $\mathcal{P}$ and $\mathcal{P}^*$ be as in Lemma~\ref{uniform_bound_infinite}. If $\tau(\mathcal{P}) = +\infty$, then there exists a uniform constant $C \geq 1$ such that
		\[
		\frac{1}{C} \leq \frac{r^*_{v}}{r_{v}} \leq C, \quad \forall v \in V.
		\]
	\end{lem}

	\begin{proof}
		Without loss of generality, we assume $\Pac^*(v_0)= \Pac(v_0)$ and the center $c_{v_0}$ of $\Pac(v_0)$ lies at the origin.

		As shown in Lemma~\ref{tau_P_bound}, let $\tau^* := \limsup_{i \to +\infty} \tau(\Pac^*(v_i))$. Fix $\delta \in (0, 1/3)$ such that $\delta < \tau^*$. Then there exists a sequence $\{u_k\}$ of mutually distinct vertices such that $\tau\left(\Pac(u_k)\right) \geq 1$ and $\tau\left(\Pac^*(u_k)\right) \geq 3\delta$. Since both $\mathcal P$ and $\mathcal P^*$ are locally finite in $\mathbb{C}$, we have
		\[
		\mathrm{dist}\left(0, \Pac(u_k)\right) \to \infty \quad \text{and} \quad \mathrm{dist}\left(0, \Pac^*(u_k)\right) \to \infty.
		\]

		Let $\rho_0 > 0$ be such that
		\[
		D_{v_0} \cup D_{v_1} \cup D^*_{v_0} \cup D^*_{v_1} \subseteq D(0, \rho_0).
		\]
		Choose one $\tilde{u}$ from the sequence $\{u_k\}$ such that
		\[
		d := \mathrm{dist}(0,  \Pac (\tilde{u})) \geq \frac{100 \rho_0}{\delta^2}, \quad
		d^* := \mathrm{dist}(0, \Pac^* (\tilde{u})) \geq \frac{100 \rho_0}{\delta^2}.
		\]

		Let $F$ be a Möbius transformation with $F(0) = 0$ and \( F(\hat{\mathbb{C}} \setminus D(\tilde{u})) = \mathbb{D}(0,1) \), and similarly let $F^*$ be a Möbius transformation with $F^*(0) = 0$ and \( F^*(\hat{\mathbb{C}} \setminus D^*(\tilde{u})) = \mathbb{D}(0,1) \).

		Observe that the hyperbolic distance between $F(\infty)$ and $0$ is greater than the hyperbolic distance between $0$ and
		\[
		\frac{r_{\tilde{u}}}{d + \rho_0 +r_{\tilde{u}}}.
		\]
		It follows that
		\[
		|F(\infty)| = \frac{r_{\tilde{u}}}{d + r_{\tilde{u}}} = \frac{\tau(\Pac (\tilde{u}))}{1 + \tau(\Pac (\tilde{u}))} > \frac{1}{3} > \delta.
		\]
		Similarly,
		\[
		|F^*(\infty)| = \frac{\tau(\Pac^* (\tilde{u}))}{1 + \tau(\Pac^* (\tilde{u}))} \geq \frac{3\delta}{1.01 + 3\delta} > \delta.
		\]

		Moreover, from \( \rho_0 \leq \frac{\delta^2 d}{100} \) and \( \rho_0 \leq \frac{\delta^2 d^*}{100} \), we deduce that the images
		\[
		F(D(0,\rho_0)), \quad F^*(D(0, \rho_0)), \quad F(\Pac(v_0)), \quad F(\Pac (v_1)), \quad F^*(\Pac^*(v_0)), \quad F^*(\Pac^* (v_1))
		\]
		are all contained in the disk \( (\delta/2) \cdot U \), where $U$ denotes the unit disk.

		Since \( \mathrm{dist}(0, \Pac (\tilde{u})) \geq 100 \rho_0 \), the absolute derivative \( |dF/dz| \) of $F$ within \( D(0, \rho_0) \) varies by at most a factor of 2. Hence, the ratio
		\[
		\frac{r(F(\Pac (v_1)))}{r(F(\Pac(v_0))} \quad  \text{ or }\quad \frac{r(\Pac (v_1))}{r(\Pac(v_0))}\in [1/4, 4].
		\]
		Similarly, we have
		\[
		\frac{r(F^*(\Pac^* (v_1)))}{r(F^*(\Pac^*(v_0)))} \quad \text{   or   }  \quad\frac{r(\Pac^* (v_1))}{r(\Pac^*(v_0)))} \in [1/4, 4].
		\]

		Since $\Pac^*(v_0)= \Pac(v_0)$, in order to compare \( r(\Pac^* (v_1)) / r(\Pac (v_1)) \), it suffices to compare
		\[
		\frac{r(F(\Pac (v_1)))}{r(F(\Pac(v_0)))} \quad \text{and} \quad \frac{r(F^*(\Pac^* (v_1)))}{r(F^*(\Pac^*(v_0)))}.
		\]

		Now consider the comparison of the pattern \( (1/\delta) F(\mathcal P) \) with \( F^*(\mathcal P^*) \). Since \( |F(\infty)| > \delta \) and \( F(\mathcal P) \) is locally finite in \( \hat{\mathbb{C}} \setminus \{F(\infty)\} \), only finitely many disks intersect the unit disk $U$. Then, using Lemma~\ref{MaximumPrincipleHyper}, we get, for \( j = 0, 1 \),
		\[
		r_{\mathrm{hyp}}\left((1/\delta) F(\Pac (v_j))\right) \geq r_{\mathrm{hyp}}\left(F^*(\Pac^* (v_j))\right).
		\]
		Conversely, comparing \( F(\mathcal P) \) with \( (1/\delta) F^*(\mathcal P^*) \), and noting that \( |F^*(\infty)| > \delta \), we obtain
		\[
		r_{\mathrm{hyp}}\left(F(\Pac (v_j))\right) \leq r_{\mathrm{hyp}}\left((1/\delta) F^*(\Pac^* (v_j))\right).
		\]
		The lemma then follows, since all involved disks are contained in \( (1/2) U \).
	\end{proof}



	\begin{lem}\label{uniform_bound_infinite}
		Let $\mathcal{D}=(V,E,F)$  be an infinite cellular decomposition embedding on a plane and $\Theta \in(0, \pi)^E$ satisfies $(C1)$.  Assume $\mathcal{P}= \{\Pac(v)\}_{v\in V}$ and $\mathcal{P^*}= \{\Pac^* (v)\}_{v\in V}$ be two infinite ideal disk patterns realizing $(\mathcal{D}, \Theta)$. There is an uniform constant $C \geq 1$ such that
		\[
		\frac{1}{C} \leq \frac{r^*_{v}}{r_{v}} \leq C, \quad \forall v \in V.
		\]
	\end{lem}
	\begin{proof}
		Combining Lemmas~\ref{rigidity_bound_tau_finite} and~\ref{rigidity_bound_tau_infinite}, we obtain the desired result.
	\end{proof}





	\begin{lem}
		Let $\mathcal{D}=(V,E,F)$  be an infinite cellular decomposition embedding on a plane and $\Theta \in [\epsilon,\pi-\epsilon]^E$ satisfies $(C1)$.  Assume $\mathcal{P}= \{\Pac(v)\}_{v\in V}$ and $\mathcal{P^*}= \{\Pac^* (v)\}_{v\in V}$ be two infinite ideal disk patterns realizing $(\mathcal{D}, \Theta)$. Assume that $P$ is locally finite in the plane. Then there is a Euclidean similarity $f: \mathbb{C} \rightarrow \mathbb{C}$ such that $\mathcal P^*=f(\mathcal P)$.
	\end{lem}
	\begin{proof}

		Denote $\mathcal{P}(0)=\mathcal{P}$ and $\mathcal{P}(1)=\mathcal{P^*}$. For $v \in V$, denote $r_v(0)$ and $r_v(1)$ be  the radius of $\Pac(v)$ and $\Pac^* (v)$, respectively. 

		Now, we construct a $r(t)$ connect $r(0)$ and $r(t)$. Let $u_v (t)= \ln r_v(t)$. Firstly, we construct $\tilde u_v (t)= u_v (0) + (u_v(1)- u_v(0))t$. Lemma \ref{uniform_bound_infinite} tells us that $|u_v(1)- u_v(0)|\leq \ln C$, $\forall v \in V$. Hence, we have 
		\begin{equation}\label{harmonic_proof_1}
			|\tilde u_v (t+h)- \tilde u_v (t)| \leq |u_v(1)- u_v(0)||h| \leq \ln C \cdot |h|, \quad \forall v \in V.
		\end{equation}

		Consider an exhaustive sequence of finite, simple, connected cellular decompositions
		$$
		\left\{\mathcal{D}^{[n]}=\left(V^{[n]}, E^{[n]}, F^{[n]}\right)\right\}_{n=1}^{\infty}
		$$
		satisfying
		$$
		\mathcal{D}^{[n]} \subset \mathcal{D}^{[n+1]}, \quad \text { and } \quad \bigcup_{n=1}^{\infty} \mathcal{D}^{[n]}=\mathcal{D}
		$$
		The sequence must exist, since we have assumed the connectedness of $\mathcal{D}$, which means $d\left(v, w\right)<+\infty$ for all $v, w \in V$. Denote $\partial V^{[n]}$ be all boundary vertices in $\mathcal{D}^{[n]}$, $\mathrm{int} (V)^{[n]}$ be all interior vertices in $\mathcal{D}^{[n]}$. For any $t \in [0,1]$, from Lemma \ref{prescribed_boundary_radius_prob}, we know there is a unique $\mathcal{P}^{[n]}(t)$ realizing $(\mathcal{D}^{[n]}, \Theta)$ and its radius $r^{[n]}_v(t)= \tilde r_v(t)$ for any boundary vertex $v \in \partial V^{[n]}$. Particularly, ideal circle pattern $\mathcal{P}^{[n]}(0)$ (resp. $\mathcal{P}^{[n]}(1)$) is exactly the $\mathcal{P}(0)$ (resp. $\mathcal{P}(1)$) restricted on $\mathcal{D}^{[n]}$. 

		By Lemma \ref{maximum_principle_euc}, we know $u_v^{[n]}(t+h)- u_v^{[n]}(t)$ attains its maximum and minimum at the vertex in $ \partial V^{[n]}$. Hence, by \eqref{harmonic_proof_1}, we have
		\begin{equation}\label{harmonic_proof_2}
			|u_v^{[n]}(t+h)- u_v^{[n]}(t)| \leq \ln C\cdot |h|, \quad \forall v \in V^{[n]}.
		\end{equation}
		Since $t \in [0,1]$, we have 
		$$|u_v^{[n]}(t)- u_v^{[n]}(0)| \leq  \ln C$$
		Thus, for any $t \in (0, 1)$, there is a sub-sequence $\{u^{[n_k]}(t)\}_{k}$ of $\{u^{[n]}(t)\}$ that converges as $k \rightarrow + \infty$. Let $u(t)$ be the limit of $\{u^{[n_k]}(t)\}$.  From \eqref{harmonic_proof_2}, we have
		\begin{equation}\label{harmonic_proof_3}
			|u_v(t+h)- u_v(t)| \leq \ln C\cdot |h|, \quad \forall v \in V.
		\end{equation}
		Therefore, $u_v(t)$ is absolutely continuous, and for a.e. $t$, we have
		\begin{equation}
			\bigg|\dfrac{d u_v(t)}{dt}\bigg|\leq \ln C, \quad \forall v \in V.
		\end{equation}
		It is obvious that the ICP $\mathcal{P}(t)$ consisting of circles $\Pac(t)(v)$ with radius $e^{u_v(t)}$ is an ICP realizing  $(\mathcal{D}, \Theta)$. Therefore, 
		$$
		K_v(t) =0, \quad \forall v \in V.
		$$
		So, 
		\begin{equation}\label{harmonic_proof_4}
			\begin{aligned}
				0 &= \dfrac{d K_v(u(t))}{dt}= \dfrac{\partial K_v}{\partial u_v} \dfrac{d u_v(t)}{dt}+ \sum_{w:w\sim v} \dfrac{\partial K_v}{\partial u_w}\dfrac{d u_w(t)}{dt}\\
				&=  \sum_{w:w\sim v} \dfrac{\partial K_v}{\partial u_w}\left(\dfrac{d u_w(t)}{dt}- \dfrac{d u_v(t)}{dt}\right)  +  \left(\sum_{w:w\sim v} \dfrac{\partial K_v}{\partial u_w}+\dfrac{\partial K_v}{\partial u_v}\right) \dfrac{d u_v(t)}{dt}\\
			\end{aligned}
		\end{equation}
		From Lemma \ref{vari}, we know 
		$$
		\sum_{w:w\sim v} \dfrac{\partial K_v}{\partial u_w}+\dfrac{\partial K_v}{\partial u_v}=0.
		$$
		Let $f_v(t)= {d u_v(t)}/{dt}$, by \eqref{harmonic_proof_4}, 
		$$
		\Delta_\omega f_v= \sum_{w:w \sim v} \omega_{vw}\left(f_w-f_v\right)=0
		$$
		where
		$$
		\omega_{vw} = -\dfrac{\partial K_v}{\partial u_w}.
		$$
		From Lemma \ref{vari}, we know $\omega_{vw}=\omega_{wv}>0$. Therefore, $f$ is  a harmonic function for weighted graph $(\mathcal{D}, \omega)$.

		From Lemma \ref{partialthetabound}, we know
		\begin{equation}\label{harmonic_proof_5}
			\sum_{w:w\sim v} \omega_{vw} =-\sum_{w:w\sim v} \dfrac{\partial K_v}{\partial u_w}=\sum_{w:w\sim v} \dfrac{\partial \alpha_v^w}{\partial u_w}\leq \sum_{w:w\sim v} C_0 \alpha_v^w= 2\pi C_0.
		\end{equation}

		From Theorem \ref{uniformization1}, we know $\mathcal{D}$ is VEL-parabolic. Since $f$ is  a harmonic function for weighted graph $(\mathcal{D}, \omega)$, by Lemma \ref{harmonic_current} and \eqref{harmonic_proof_5}, we know $f_v(t)= c(t)$, $\forall v \in V$. It follows that
		$$
		u_v(1)-u_v(0)= \int_0^1 c(t) dt.
		$$
		Since $ \int_0^1 c(t) dt$ is a constant, we know $r_v(1)/r_v(0)= e^{ \int_0^1 c(t) dt}$ is constant, for any $v \in V$. This implies that $P^*$ and $P$ are images of each other by Euclidean similarities.
	\end{proof}

	\section{Appendix}\label{appendix}
	\subsection{Existence of finite embedded ICPs}
	For the completeness of our paper, we will establish the existence of embedded ICPs of finite disk cellular decompositions. In particular, we will prove Theorem \ref{finite_existence}, which asserts the existence of an embedded ICP $\mathcal{P}$ on $\mathcal{D}$ such that each boundary circle is a horocycle. This result serves as an analogue of the classical existence theorem for circle packings in the plane; see, for example, \cite[Chapter 6]{Stephenson_intro}. Moreover, we will prove the existence and uniqueness of an ICP $\mathcal{P}$ on $\mathcal{D}$ whose boundary circles realize prescribed radii.

	\begin{lem}\label{bobenko_springborn_type_lemma}
		In both hyperbolic and Euclidean background geometry, let $\mathcal{D}=(V,E,F)$  be a finite cellular decomposition embedding on a plane and $\Theta \in(0, \pi)^E$ satisfies $(C1)$. If we prescribe a radius $\hat r_i>0$ for any boundary vertex $i \in \partial V$.
		Then, discrete Gauss curvature $K$ is an injective function for $u$, which take values in $\mathbb{R}^{| \mathrm{int}\, (V)|}$.  Moreover, all $\left(K_1, K_2, \ldots, K_{|\mathrm{int}\, V|}\right)$ satisfying
		\begin{equation}\label{k_value1}
			K_i< 2 \pi
		\end{equation}
		and 
		\begin{equation}\label{k_value2}
			\sum_{v_i \in A} K_i>2 \pi|A|-2 \sum_{e \in E(A)} \Theta(e) 
		\end{equation}
		is attainable, where $A$ is an arbitrary non-empty subset of $\mathrm{int}\, V$.
	\end{lem}

	\begin{proof}
		The proof is similar to the method of Bobenko--Springborn \cite{MR2022715}.  
		Let $Z \subset \mathbb{R}^{| \mathrm{int}\, V|}$ be the set of points that satisfy the inequalities \eqref{k_value1} and \eqref{k_value2}. Since these inequalities are linear, $Z$ is convex.

		Let \( u_i = \ln r_i \) and take values in $\mathbb{R}^{| \mathrm{int}\, V|}$. The discrete Gauss curvature $K$ is a continuous function for $u$. We will divide the proof into parts.

		\emph{Step I: $K$ is an injective function.}



    	From Lemma~\ref{vari}, for any \( i, j \in \mathrm{int}\, V \), we have
        \[
        \dfrac{\partial K_i}{\partial u_j} = \dfrac{\partial K_j}{\partial u_i} < 0,
        \]
        \[
        \dfrac{\partial K_i}{\partial u_i} = -\sum_{j:j \sim i} \dfrac{\partial \alpha_i^j}{\partial u_i} > 0,
        \]
        and
        \[
        \left| \dfrac{\partial K_i}{\partial u_i} \right| - \sum_{j \neq i} \left| \dfrac{\partial K_i}{\partial u_j} \right| = \sum_{j=1}^{|V|} \dfrac{\partial K_i}{\partial u_j} \geq 0,
        \]
        where in the Euclidean background geometry, the inequality is strict if the vertex \( i \) is adjacent to a boundary vertex in \( \partial V \), and equality holds otherwise. In contrast, in the hyperbolic background geometry, the inequality is always strict.


		Linear algebra tells us that the matrix $\left(\dfrac{\partial K_i}{\partial u_j}\right)$ is positive definite, which implies that $K$ is an injective function.

		\emph{Step II: $K (u) \in Z$, for any $u \in \mathbb{R}^{| \mathrm{int}\, V|}$ .}

		We only need to prove that, for any $u \in \mathbb{R}^{| \mathrm{int}\, V|}$, $K (u) $ satisfies the inequalities \eqref{k_value1} and \eqref{k_value2}. The inequality \eqref{k_value1} is natural from the definition of discrete Gauss curvature. As for inequality \eqref{k_value2}, since for any arbitrary non-empty subset $A$ of $\mathrm{int}\, V$, there exists at least one  $e=[i, j] \in E(A)$, whose $ \Theta(e)$ attributes an angle of a vertex not in $A$. So, we have
		$$
		\sum_{v_i \in A} \alpha_i(u)< 2 \sum_{e \in E(A)} \Theta(e),
		$$
		which is equivalent to inequality \eqref{k_value2}.

		\emph{Step III: $K$ is an inverse proper function.}

		We only need to prove that, as $u$ approaches the boundary of $\mathbb{R}^{| \mathrm{int}\, (V)|}$, one of the inequalities \eqref{k_value1} and \eqref{k_value2} becomes an equality. There are two cases:
		\begin{itemize}
			\item[(i)] There exists a vertex $i\in  \mathrm{int}\, V$ such that $u_i \rightarrow + \infty$. By calculus, we know $\alpha_i^j \rightarrow 0$. Hence $K_i  \rightarrow 2\pi$.
			\item[(ii)] There exists a non-empty set $A \subset \mathrm{int}\, V$ such that $u_i\rightarrow - \infty$ for all $i \in A$. By calculus, we know $\alpha_j^i \rightarrow 0$, which implies $ \Theta(e)$ attributes zero angle of a vertex not in $A$. So, we have
			$$
			\sum_{v_i \in A} \alpha_i(u) \rightarrow \sum_{e \in E(A)} \Theta(e),
			$$
			which means inequality \eqref{k_value2} becomes equality.
		\end{itemize}

		\emph{Step IV: we finish the proof.}

		From Brouwer invariance of domain Theorem,  we know that $K$ is a bijective function from $ \mathbb{R}^{| \mathrm{int}\, V|}$ to $Z$. 
	\end{proof}

	Given $A \subset  \mathrm{int}\, V$, for convenience, we use the following notations:
	\begin{itemize}
		\item $F(A)=\{f \mid \partial f \cap A \neq \emptyset\}$
		\item $E(A)=\{e \mid \partial e \cap A \neq \emptyset\}$
		\item $\operatorname{Tk}(A)=\{(e, f) \mid e \in E(A), f \in F(A), e \subset \partial f\}$
		\item $\operatorname{Lk}(A)=\{(e, f) \mid e \notin E(A), f \in F(A), e \subset \partial f\}$
        \item  We denote by $S(A)$ the CW-complex whose $2$-simplexes consists of all faces in $F(A)$. 
	\end{itemize}

	\begin{lem}\label{prescribed_boundary_radius_prob}
		In both hyperbolic and Euclidean background geometry, let $\mathcal{D}=(V,E,F)$  be a finite planar cellular decomposition, and $\Theta \in(0, \pi)^E$ satisfies $(C_1)$ and $(C_2)$. If we prescribe a radius $\hat r_i>0$ for any boundary vertex $i \in \partial V$, then there is a unique $\mathcal{P}= \{C_i\}_{i\in V}$ realizing $(\mathcal{D}, \Theta)$ and its radius $r_i = \hat r_i$ for any boundary vertex $i \in \partial V$.
	\end{lem}
	\begin{proof}
		By Lemma \ref{bobenko_springborn_type_lemma}, we only need to check $\left(0, 0, \ldots, 0\right)$ satisfies the inequalities \eqref{k_value1} and \eqref{k_value2}.  The inequality \eqref{k_value1} is natural from the definition of discrete Gauss curvature. As for inequality \eqref{k_value2}, from  $(C1)$, we have
		$$
		2 \pi+\sum_{e_i \in \partial f}\left(\Theta\left(e_i\right)-\pi\right)=0, \quad \forall f \in F.
		$$
		Hence, for  any non-empty $A \subset \mathrm{int}\, V$,
		\begin{equation}\label{finiteICP_proof_1}
			\begin{aligned}
				0 & =\sum_{f \in F(A)}\left[2 \pi+\sum_{e_i \in \partial f}\left(\Theta\left(e_i\right)-\pi\right)\right] \\
				& =2 \pi|F(A)|+\sum_{f \in F(A)} \sum_{e_i \in \partial f}\left(\Theta\left(e_i\right)-\pi\right) \\
				& =2 \pi|F(A)|+\sum_{(e, f) \in \operatorname{Tk}(A)}(\Theta(e)-\pi)+\sum_{(e, f) \in \operatorname{Lk}(A)}(\Theta(e)-\pi) .
			\end{aligned}
		\end{equation}
        Without loss of generality, we assume that $S(A)$ is connected, since the quantities $|A|$ and $\sum_{e \in E(A)} \Theta(e)$ are additive with respect to connected components.
		For an edge $e$ in $\operatorname{Tk}(A)$, e must connect with two faces in $F(A)$, we have
		\begin{equation}\label{finiteICP_proof_2}
			\sum_{(e, f) \in \operatorname{Tk}(A)}(\Theta(e)-\pi)=2 \sum_{E(A)} \Theta(e)-2 \pi\left|E(A)\right|.
		\end{equation}
		Combing \eqref{finiteICP_proof_1} and \eqref{finiteICP_proof_2}, it follows
		\begin{equation}\label{finiteICP_proof_3}
			\begin{aligned}
				& 2 \pi|A| -2 \sum_{e \in E(A)} \Theta(e)\\
				=& 2 \pi|A| -2 \pi\left|E(A)\right|-\sum_{(e, f) \in \operatorname{Tk}(A)}(\Theta(e)-\pi)\\
				= & 2 \pi|A| -2 \pi\left|E(A)\right| +2 \pi|F(A)|+\sum_{(e, f) \in \operatorname{Lk}(A)}(\Theta(e)-\pi)    \\
				= & 2\pi \chi (S(A)) +\sum_{(e, f) \in \operatorname{Lk}(A)}(\Theta(e)-\pi),  \\
			\end{aligned}
		\end{equation}
		where $\chi (S(A))$ is the Euler characteristic number of $S(A)$. If $\chi (S(A))>0$, $S(A)$ is homeomorphic to a disk. Therefore, $\chi (S(A))=1$. Together with $(C2)$, from \eqref{finiteICP_proof_3}, we have
		$$
		2 \pi|A| -2 \sum_{e \in E(A)} \Theta(e)< 0,
		$$
		which is exactly the inequality \eqref{k_value2} when $\left(K_1, K_2, \ldots, K_{|\mathrm{int}\, V|}\right)= \left(0, 0, \ldots, 0\right)$.
	\end{proof}



  By employing Lemma \ref{MaximumPrincipleHyper} and Lemma \ref{prescribed_boundary_radius_prob}, we can give a proof of Theorem \ref{finite_existence}. 

