	\subsection{Vertex extremal lengths on cellular decompositions and triangulations}
	In this part, we will prove Lemma \ref{hehyp}. Actually, when $\mathcal{D}$ is an infinite triangulation, this lemma was already proved by He, see \cite[Lemma 7.3]{HE}. Therefore, we actually need to prove the following lemma.
	\begin{lem}
		Let $\mathcal{D}=(V,E,F)$ be an infinite disk cellular decomposition whose vertex degree and face degree are bounded by $N$. By adding an auxiliary point (or dual point) $v_f$ in each face $f\in F$ and connecting $v_f$ with all vertices on $f$, we obtain a triangulation $\mathcal{T}=(V',E',F')$ which is the subdivision of $\mathcal{D}$. Let $\vel_{\mathcal{T}}$ and $\vel_{\mathcal{D}}$ be the vertex extremal length defined  in $\mathcal{T}$ and $\mathcal{D}$, respectively. Then there exists a uniform constant $C=C(N)$ such that for any two disjoint non-empty vertex sets $W_1$ and $W_2$ of $\mathcal{D}$, we have
		\[
		C^{-1}\vel_{\mathcal{D}}(W_1,W_2)\le\vel_{\mathcal{T}}(W_1,W_2)\le C\vel_{\mathcal{D}}(W_1,W_2)
		\]
	\end{lem}
	\begin{proof}
		Let $m$ be a $\Gamma(W_1,W_2)$-admissible vertex metric in $\mathcal{D}$. We define a new vertex metric $\tilde{m}$ on $V'$ as follows.
		\[\tilde{m}(v)=
		\left\{\begin{array}{cc}
			m(v), & v\in V,\\
			\sum_{v<f}m(v), & v=v_f\in V'\backslash V.
		\end{array}\right.
		\]
		It is easy to see that $\tilde{m}$ is also $\Gamma(W_1,W_2)$-admissible in $\mathcal{T}$.
		Moreover, \[\area(\tilde{m})=\area(m)+\sum_{f\in F}(\sum_{v<f}m(v))^2\le\area(m)+N\sum_{f\in F}\sum_{v<f}m(v)^2\le (N^2+1)\area(m).\]
		Therefore, we have 
		\[
		\vel_{\mathcal{D}}(W_1,W_2)\le(N^2+1)\vel_{\mathcal{T}}(W_1,W_2).
		\]
		We then assume that $m$ is a $\Gamma(W_1,W_2)$-admissible vertex metric in $\mathcal{T}$. We define a vertex metric $\tilde{m}=m|_{V}$. Since $m$ is $\Gamma(W_1,W_2)$-admissible in $\mathcal{T}$, $\tilde{m}$ is also $\Gamma(W_1,W_2)$-admissible in $\mathcal{T}$. Therefore, we have
		\[
		\vel_{\mathcal{D}}(W_1,W_2)\ge\vel_{\mathcal{T}}(W_1,W_2).
		\]

	\end{proof}



