\begin{theorem}
Let $p,q,\gamma>0$
Let  $g\in H(U^n), g(z)=\sum\limits_{k\in Z^n_{+}}c_kz^k$. Then
 \[1) If\  g\in (M_T)(T^{p, q}_\gamma, Y)\ then \ \sup\limits_{r\in I^n}M_\infty(D^\beta g, r)\prod\limits_{j=1}^{n}(1-r_j)^{\tau_j+\beta+1-\frac{\gamma}{n}-\frac{1}{p}}<\infty,\]\[ \beta>\max\limits_{j}\left(\frac{1}{p}+\frac{\gamma}{n}-\tau_j-1\right), \tau_j>0;\; j=1,\dots,n\]
 \[2) If\  g\in (M_T)(T^{p, \infty}_\gamma, Y)\ then\ \sup\limits_{r\in I^n}M_\infty(D^\beta g, r)\prod\limits_{j=1}^{n}(1-r_j)^{\tau_j+\beta+1-\frac{\gamma}{n}-\frac{1}{p}}<\infty, \]\[ \beta>\max\limits_{j}\left(\frac{1}{p}+\frac{\gamma}{n}-\tau_j-1\right), \tau_j >0;\; j=1,\dots,n\]
 \[3) If\  g\in (M_T)(T^{\infty, q}_\gamma, Y)\ then\ \sup\limits_{r\in I^n}M_\infty(D^\beta g, r)\prod\limits_{j=1}^{n}(1-r_j)^{\tau_j+\beta+1-\frac{\gamma}{n}-\frac{1}{p}}<\infty,\]\[ \beta>\max\limits_{j}\left(\frac{1}{p}+\frac{\gamma}{n}-\tau_j-1\right), \tau_j>0, \; j=1,\dots,n.\] 
with $p=\infty$.
\end{theorem}
