\section{Generalized inverse of quaternion matrices with prescribed range and/or null space}\label{sec3}
In this section, we study the generalized inverses of quaternion matrices with prescribed right and/or left range and/or null spaces. Although such results are well established for real and complex matrices \cite{BenGrev2003, WangWeiQiao2018}, their extension to quaternion matrices is less developed. We define these generalized inverses, establish their existence conditions, and derive their explicit representations.

The following definition formalizes the outer inverses with the prescribed subspace constraints.
\begin{definition}\label{def3.2}
Let $A \in \Q^{m \times n}$, $S_1 \in \Q^{n \times p}$, $T_1 \in \Q^{q \times m}$, $S_2 \in \Q^{l \times m}$, and $T_2 \in \Q^{n \times t}$. An outer inverse of matrix $A$ with specific range and/or null space constraints is a solution of the matrix equation $XAX = X$. Additionally, $X$ must satisfy one of the following conditions:
\begin{itemize}
      \item[(a)] If $\mathcal{R}_r(X) = \mathcal{R}_r(S_1)$, then $X$ is denoted as $A^{(2)}_{r, (S_1, *)}$.
      \item[(b)]  If $\mathcal{N}_r(X) = \mathcal{N}_r(T_1)$, then $X$ is denoted by $A^{(2)}_{r, (*, T_1)}$.
      \item[(c)] If $\mathcal{R}_r(X) = \mathcal{R}_r(S_1)$ and $\mathcal{N}_r(X) = \mathcal{N}_r(T_1)$, then $X$ is denoted as $A^{(2)}_{r, (S_1, T_1)}$.
      \item[(d)]  If $\mathcal{R}_l(X) = \mathcal{R}_l(S_2)$, then $X$ is denoted by $A^{(2)}_{l, (S_2, *)}$.
      \item[(e)] If $\mathcal{N}_l(X) = \mathcal{N}_l(T_2)$, then $X$ is denoted as $A^{(2)}_{l, (*, T_2)}$.
	\item[(f)] If $\mathcal{R}_l(X) = \mathcal{R}_l(S_2)$ and $\mathcal{N}_l(X) = \mathcal{N}_l(T_2)$, then $X$ is denoted as $A^{(2)}_{l, (S_2, T_2)}$.
	\item[(g)] If $X$ satisfies both the right and left range and null space conditions, that is, $\mathcal{R}_r(X) = \mathcal{R}_r(S_1)$, $\mathcal{N}_r(X) = \mathcal{N}_r(T_1)$, $\mathcal{R}_l(X) = \mathcal{R}_l(S_2)$, and $\mathcal{N}_l(X) = \mathcal{N}_l(T_2)$, then $X$ is denoted as $A^{(2)}_{(S_1, T_1), (S_2, T_2)}$.
\end{itemize}
\end{definition}
Next, we define the $\{1,2\}$-inverse that satisfies specific subspace conditions.
\begin{definition}\label{def3.3}
Let $A \in \Q^{m \times n}$, $S_1 \in \Q^{n \times p}$, $T_1 \in \Q^{q \times m}$, $S_2 \in \Q^{l \times m}$, and $T_2 \in \Q^{n \times t}$. A $\left\{1,2\right\}$-inverse of matrix $A$ with specific range and null space constraints is a solution to the matrix equations $AXA=A$ and $XAX = X$. Additionally, $X$ must satisfy one of the following conditions:
\begin{itemize}
    \item[(a)]  If $\mathcal{R}_r(X) = \mathcal{R}_r(S_1)$ and $\mathcal{N}_r(X) = \mathcal{N}_r(T_1)$, then $X$ is denoted as $A^{(1,2)}_{r, (S_1, T_1)}$.
    \item[(b)] If $\mathcal{R}_l(X) = \mathcal{R}_l(S_2)$ and $\mathcal{N}_l(X) = \mathcal{N}_l(T_2)$, then $X$ is denoted as $A^{(1,2)}_{l, (S_2, T_2)}$.
    \item[(c)] If $X$ satisfies both right and left range and null space conditions, that is, $\mathcal{R}_r(X) = \mathcal{R}_r(S_1)$, $\mathcal{N}_r(X) = \mathcal{N}_r(T_1)$, $\mathcal{R}_l(X) = \mathcal{R}_l(S_2)$, and $\mathcal{N}_l(X) = \mathcal{N}_l(T_2)$, then $X$ is denoted as $A^{(1,2)}_{(S_1, T_1), (S_2, T_2)}$.
 \end{itemize}
 \end{definition}
Let $A\left\{1\right\}$, $A\{2\}_{r, (S_1, *)}$, $A\{2\}_{r, (*, T_1)}$, $A\{2\}_{l, (S_2, *)}$, and $A\{2\}_{l, (*, T_2)}$ be the set of all generalized inverses $A^{(1)}$, $A^{(2)}_{r, (S_1, *)}$, $A^{(2)}_{r, (*, T_1)}$, $A^{(2)}_{l, (S_2, *)}$, and $A^{(2)}_{l, (*, T_2)}$, respectively.

We now present the necessary conditions for the existence of generalized inverse of a matrix with prescribed right range and/or null space, along with the corresponding expression for this inverse.
\begin{theorem}\label{thm3.4}
	Let $A \in \Q_r^{m \times n}$, $S_1 \in \Q^{n \times p}$, $T_1 \in \Q^{q \times m}$, and $X=S_1\left(T_1AS_1\right)^{(1)}T_1$, where $\left(T_1AS_1\right)^{(1)}$ is a fixed but arbitrary element of $\left(T_1AS_1\right)\left\{1\right\}$. Then
	\begin{enumerate}
            \item[$(a)$] $X \in A\{1\}$ if and only if $\rank(T_1AS_1)=r$.
		\item[$(b)$] $X \in A\{2\}_{r, (S_1, *)}$ if and only if $\rank\left(T_1AS_1\right)=\rank\left(S_1\right)$.
		\item[$(c)$] $X \in A\{2\}_{r, (*, T_1)}$ if and only if $\rank\left(T_1AS_1\right)=\rank\left(T_1\right)$.
		\item[$(d)$] $X = A^{(2)}_{r,(S_1, T_1)}$ if and only if $\rank\left(T_1AS_1\right)=\rank\left(S_1\right)=\rank\left(T_1\right)$.
		\item[$(e)$] $X = A^{(1,2)}_{r,(S_1, T_1)}$ if and only if $\rank\left(T_1AS_1\right)=\rank\left(S_1\right)=\rank\left(T_1\right)=r$.
	\end{enumerate}
\end{theorem}
\begin{proof}
\begin{enumerate}
\item[$(a)$]Assume that $\rank\left(T_1AS_1\right) = r$. From Lemma \ref{lem2.12}, we obtain
		 \begin{equation*}
			r=\rank\left(T_1AS_1\right) \leq \rank\left(AS_1\right) \leq \rank\left(A\right)=r.
		\end{equation*}
	This implies that $\rank\left(AS_1\right)=\rank\left(A\right)$. Additionally, from Definition \ref{def2.2}, we obtain $\mathcal{R}_r\left(AS_1\right) \subseteq \mathcal{R}_r\left(A\right).$
    Since both subspaces have the same dimensions, it follows that 
    $\mathcal{R}_r\left(AS_1\right) = \mathcal{R}_r\left(A\right).$ Hence, $\mathcal{R}_r\left(A\right) \subseteq \mathcal{R}_r\left(AS_1\right)$. Thus, there exists a matrix $Y \in \Q^{p \times n}$ such that $A=AS_1Y.$
 Now consider the expression
	\begin{equation*}
		AXA=A\left(S_1\left(T_1AS_1\right)^{(1)}T_1\right)A =A\left(S_1\left(T_1AS_1\right)^{(1)}T_1\right)AS_1Y.
	\end{equation*}
    Rewriting, we get
    \begin{equation}\label{pf1.1}
        AXA= AS_1\left(T_1AS_1\right)^{(1)}\left(T_1AS_1\right)Y.
    \end{equation}
We have $\rank\left(T_1AS_1\right)=\rank\left(AS_1\right)=r$ and by Definition \ref{def2.2}, we have $\mathcal{N}_r\left(AS_1\right) \subseteq \mathcal{N}_r\left(T_1AS_1\right)$. Consequently, 
$\mathcal{N}_r\left(T_1AS_1\right) = \mathcal{N}_r\left(AS_1\right)$.
Thus, $\mathcal{N}_r\left(T_1AS_1\right) \subseteq \mathcal{N}_r\left(AS_1\right)$  implies the existence of a matrix $Z \in \Q^{m \times q}$ such that 
$
AS_1=ZT_1AS_1.
$
Using this, we can write
\begin{equation*}
AS_1=ZT_1AS_1=Z\left(T_1AS_1\right)\left(T_1AS_1\right)^{(1)}\left(T_1AS_1\right)=AS_1\left(T_1AS_1\right)^{(1)}\left(T_1AS_1\right).
\end{equation*}
Substituting this into equation \eqref{pf1.1}, we obtain
\begin{equation*}
	AXA=AS_1\left(T_1AS_1\right)^{(1)}\left(T_1AS_1\right)Y = AS_1Y=A.
\end{equation*}
Thus, $X \in A\{1\}$.

Conversely, assume $X \in A\{1\}$. We have
\begin{equation*}
A=AXA=AX\left(AXA\right)=A\left(S_1\left(T_1AS_1\right)^{(1)}T_1\right)A\left(S_1\left(T_1AS_1\right)^{(1)}T_1\right)A.
\end{equation*}
Using Lemma \ref{lem2.12}, it follows that
\begin{equation*}
	\rank(A) \leq \rank\left(T_1AS_1\left(T_1AS_1\right)^{(1)}T_1A\right) \leq \rank\left(T_1AS_1\right).
\end{equation*}
Additionally, we have
\begin{equation*}
\rank\left(T_1AS_1\right) \leq \rank\left(AS_1\right) \leq \rank\left(A\right).
\end{equation*}
By combining these inequalities, we conclude that 
$\rank\left(T_1AS_1\right)=\rank(A)=r$. \\
 %%%%%%%%%%%%%%
\item[$(b)$] Assume $\rank\left(T_1AS_1\right)=\rank\left(S_1
\right)$. This implies that $\dim\left(\mathcal{R}_r\left(T_1AS_1\right)\right)=\dim\left(\mathcal{R}_r\left(S_1\right)\right)$, and hence $\dim\left(\mathcal{N}_r\left(T_1AS_1\right)\right)=\dim\left(\mathcal{N}_r\left(S_1\right)\right)$. Since $\mathcal{N}_r\left(S_1\right) \subseteq \mathcal{N}_r\left(T_1AS_1\right)$, we conclude that $\mathcal{N}_r\left(S_1\right) = \mathcal{N}_r\left(T_1AS_1\right)$. Consequently, $\mathcal{N}_r\left(T_1AS_1\right) \subseteq \mathcal{N}_r\left(S_1\right)$, which implies that there exists a matrix $Z \in \Q^{n \times q}$ such that $S_1=ZT_1AS_1$. Thus,
\begin{equation}\label{pr1.2}
	S_1=ZT_1AS_1\left(T_1AS_1\right)^{(1)}T_1AS_1 = S_1\left(T_1AS_1\right)^{(1)} T_1AS_1.
\end{equation}
From this, we derive
\begin{equation*}
XAX=S_1\left(T_1AS_1\right)^{(1)}T_1AS_1\left(T_1AS_1\right)^{(1)}T_1 = S_1\left(T_1AS_1\right)^{(1)}T_1=X.
\end{equation*}
Hence, $X \in A\{2\}$. 

Since $X=S_1\left(T_1AS_1\right)^{(1)}T_1$, and applying Definition \ref{def2.2}, we have
\begin{equation*}
\mathcal{R}_r(X)=\mathcal{R}_r\left(S_1\left(T_1AS_1\right)^{(1)}T_1\right) \subseteq \mathcal{R}_r\left(S_1\right).
\end{equation*}
From \eqref{pr1.2}, it follows that
\begin{equation*}
	S_1=S_1\left(T_1AS_1\right)^{(1)}T_1AS_1 = XAS_1.
\end{equation*}
By Definition \ref{def2.2}, we get
\begin{equation*}
	\mathcal{R}_r(S_1) = \mathcal{R}_r\left(XAS_1\right) \subseteq \mathcal{R}_r(X).
\end{equation*}
Combining both results, we conclude $\mathcal{R}_r(X)=\mathcal{R}_r\left(S_1\right)$.

Conversely, assume $X \in A\{2\}$ and $\mathcal{R}_r(X)=\mathcal{R}_r\left(S_1\right)$. Then
\begin{equation*}
X=XAX=S_1\left(T_1AS_1\right)^{(1)}T_1AS_1\left(T_1AS_1\right)^{(1)}T_1.
\end{equation*}
By Lemma \ref{lem2.12}, we get
\begin{equation}\label{pr1.3}
	\rank\left(X\right) \leq \rank\left(T_1AS_1\left(T_1AS_1\right)^{(1)}T_1\right) \leq \rank\left(T_1AS_1\right) \leq \rank\left(S_1\right).
\end{equation}
Since $\mathcal{R}_r(X)=\mathcal{R}_r\left(S_1\right)$, we have $\dim\left(\mathcal{R}_r(X)\right)=\dim\left(\mathcal{R}_r(S_1)\right)$, implying $\rank\left(X\right)=\rank\left(S_1\right) $. Combining this with the previous inequality gives 
\begin{equation*}
		\rank\left(X\right) \leq  \rank\left(T_1AS_1\right) \leq \rank\left(S_1\right) =\rank\left(X\right).
\end{equation*}
Therefore, $\rank\left(T_1AS_1\right)=\rank\left(S_1\right)$. \\
%%%%%%%%%%%%%%%%%%%%
\item[$(c)$] Assume that $\rank(T_1AS_1) = \rank(T_1)$. According to Definition \ref{def2.2}, we have 
$\mathcal{R}_r(T_1AS_1) \subseteq \mathcal{R}_r(T_1)$. 
As both subspaces have the same dimensions, it follows that
$\mathcal{R}_r(T_1AS_1) = \mathcal{R}_r(T_1)$. 
Thus, $\mathcal{R}_r(T_1) \subseteq \mathcal{R}_r(T_1AS_1)$, implying the existence of a matrix $Z \in \mathbb{Q}^{p \times m}$ such that
$T_1 = T_1AS_1Z$. 
Consequently, we obtain
\begin{equation}\label{pr1.4}
    T_1 = (T_1AS_1)(T_1AS_1)^{(1)}T_1AS_1Z = T_1AS_1(T_1AS_1)^{(1)}T_1.
\end{equation}
Utilizing this result, we deduce
\begin{equation*}
    XAX = S_1 (T_1AS_1)^{(1)} T_1AS_1 (T_1AS_1)^{(1)} T_1 
    = S_1 (T_1AS_1)^{(1)} T_1 = X.
\end{equation*}
Hence, $X \in A\{2\}$. 

Because $X = S_1(T_1AS_1)^{(1)}T_1$, it follows that $\mathcal{N}_r(T_1) \subseteq \mathcal{N}_r(X)$. From \eqref{pr1.4}, we obtain
\begin{equation*}
    T_1 = T_1AS_1 (T_1AS_1)^{(1)} T_1 = T_1AX.
\end{equation*}
Thus, $\mathcal{N}_r(X) \subseteq \mathcal{N}_r(T_1)$. Combining both results, we conclude that
$\mathcal{N}_r(X) = \mathcal{N}_r(T_1)$. 

Conversely, assume that $X \in A\{2\}$ and $\mathcal{N}_r(X) = \mathcal{N}_r(T_1)$. Then,
\begin{equation*}
    X = XAX = S_1(T_1AS_1)^{(1)} T_1AS_1 (T_1AS_1)^{(1)} T_1.
\end{equation*}
Using Lemma \ref{lem2.12}, we obtain
\begin{equation}\label{pr1.5}
    \rank(X) \leq \rank(T_1AS_1(T_1AS_1)^{(1)}T_1) \leq \rank(T_1AS_1) \leq \rank(T_1).
\end{equation}
Since $\mathcal{N}_r(X) = \mathcal{N}_r(T_1)$, we have
$\dim(\mathcal{N}_r(X)) = \dim(\mathcal{N}_r(T_1))$. 
Applying Lemma \ref{lem2.8}, we conclude that
$\rank(X) = \rank(T_1)$.
Substituting this into \eqref{pr1.5}, we obtain
\begin{equation*}
    \rank(X) \leq \rank(T_1AS_1) \leq \rank(T_1) = \rank(X).
\end{equation*}
Thus, we conclude that $\rank(T_1AS_1) = \rank(T_1)$. \\
%%%%%%%%%%%%%%%%%%%%%%%
\item[$(d)$] The result directly follows from parts $(b)$ and $(c)$. \\
%%%%%%%%%%%%%%%%%%%%%%%%%
\item[$(e)$] The result directly follows from parts $(a)$ and $(d)$. 
\end{enumerate}
\end{proof}
Next, we present the conditions required for the existence of a generalized inverse of a matrix with a prescribed left range and/or null space. In addition, we provide the corresponding expression for this inverse.
\begin{theorem}\label{thm3.5}
	Let $A \in \Q_r^{m \times n}$, $S_2 \in \Q^{l \times m}$, $T_2 \in \Q^{n \times t}$, and $X=T_2\left(S_2AT_2\right)^{(1)}S_2$, where $\left(S_2AT_2\right)^{(1)}$ is a fixed but arbitrary element of $\left(S_2AT_2\right)\left\{1\right\}$. Then
	\begin{enumerate}
            \item[$(a)$] $X \in A\{1\}$ if and only if $\rank(S_2AT_2)=r$.
		\item[$(b)$] $X \in A\{2\}_{l, (S_2, *)}$ if and only if $\rank\left(S_2AT_2\right)=\rank\left(S_2\right)$.
		\item[$(c)$] $X \in A\{2\}_{l, (*, T_2)}$if and only if $\rank\left(S_2AT_2\right)=\rank\left(T_2\right)$.
		\item[$(d)$] $X = A^{(2)}_{l,(S_2, T_2)}$ if and only if $\rank\left(S_2AT_2\right)=\rank\left(S_2\right)=\rank\left(T_2\right)$.
		\item[$(e)$] $X = A^{(1,2)}_{l,(S_2, T_2)}$ if and only if $\rank\left(S_2AT_2\right)=\rank\left(S_2\right)=\rank\left(T_2\right)=r$.
	\end{enumerate}
\end{theorem}
\begin{proof}
		\begin{enumerate}
        \item[$(a)$]
    Assume that $\rank\left(S_2AT_2\right) = r$. Using Lemma \ref{lem2.12}, we obtain
		\begin{equation*}
			r=\rank\left(S_2AT_2\right) \leq \rank\left(S_2A\right) \leq \rank\left(A\right)=r.
		\end{equation*}
	Thus, $\rank\left(S_2A\right)=\rank\left(A\right)$. Additionally, from Definition \ref{def2.2}, we have 
    $ \mathcal{R}_l\left(S_2A\right) \subseteq \mathcal{R}_l\left(A\right)$.
    Because both subspaces have the same dimensions, it follows that 
    $ \mathcal{R}_l\left(S_2A\right) = \mathcal{R}_l\left(A\right)$.
    Hence, $\mathcal{R}_l\left(A\right) \subseteq \mathcal{R}_l\left(S_2A\right)$, implying the existence of a matrix $Y \in \Q^{m \times l}$ such that 
    \[
    A=YS_2A.
    \]
    Now, consider the expression
		\begin{equation*}
			AXA=A\left(T_2\left(S_2AT_2\right)^{(1)}S_2\right)A =YS_2A\left(T_2\left(S_2AT_2\right)^{(1)}S_2\right)A.
		\end{equation*}
        Rewriting, we get
        \begin{equation}\label{pf2.1}
            AXA =Y\left(S_2AT_2\right)\left(S_2AT_2\right)^{(1)}S_2A.
        \end{equation}
		We have $\rank\left(S_2AT_2\right)=\rank\left(S_2A\right)$ and by Definition \ref{def2.2}, we have $\mathcal{N}_l\left(S_2A\right) \subseteq \mathcal{N}_l\left(S_2AT_2\right)$. Consequently, 
        $ \mathcal{N}_l\left(S_2AT_2\right) = \mathcal{N}_l\left(S_2A\right)$.
        Thus, $\mathcal{N}_l\left(S_2AT_2\right) \subseteq \mathcal{N}_l\left(S_2A\right)$, implying the existnece of a matrix $Z \in \Q^{t \times n}$ such that 
        \[
        S_2A=S_2AT_2Z.
        \]
		Using this result,
		\begin{equation*}
S_2A=S_2AT_2Z=\left(S_2AT_2\right)\left(S_2AT_2\right)^{(1)}\left(S_2AT_2\right)Z=\left(S_2AT_2\right)\left(S_2AT_2\right)^{(1)}S_2A.
		\end{equation*}
		Substituting this into equation \eqref{pf2.1}, we obtain
		\begin{equation*}
			AXA=Y\left(S_2AT_2\right)\left(S_2AT_2\right)^{(1)}S_2A= YS_2A=A.
		\end{equation*}
		Thus, $X \in A\{1\}$.

		Conversely, assume $X \in A\{1\}$. We have
		\begin{equation*}
A=AXA=AX\left(AXA\right)=A\left(T_2\left(S_2AT_2\right)^{(1)}S_2\right)A\left(T_2\left(S_2AT_2\right)^{(1)}S_2\right)A.
		\end{equation*}
		Using Lemma \ref{lem2.12}, it follows that
		\begin{equation*}
			\rank(A) \leq \rank\left(S_2AT_2\left(S_2AT_2\right)^{(1)}S_2A\right) \leq \rank\left(S_2AT_2\right).
		\end{equation*}
		Additionally, we have
		\begin{equation*}
			\rank\left(S_2AT_2\right) \leq \rank\left(S_2A\right) \leq \rank\left(A\right).
		\end{equation*}
		By combining these inequalities, we conclude that 
        $\rank\left(S_2AT_2\right)=\rank(A)=r$. \\
          %%%%%%%%%%%%%
	\item[$(b)$] Assume that $\rank\left(S_2AT_2\right)=\rank\left(S_2\right)$. This implies that $\dim\left(\mathcal{R}_l\left(S_2AT_2\right)\right)=\dim\left(\mathcal{R}_l\left(S_2\right)\right)$, and hence $\dim\left(\mathcal{N}_l\left(S_2AT_2\right)\right)=\dim\left(\mathcal{N}_l\left(S_2\right)\right)$. Because $\mathcal{N}_l\left(S_2\right) \subseteq \mathcal{N}_l\left(S_2AT_2\right)$, we can conclude that $\mathcal{N}_l\left(S_2\right) = \mathcal{N}_l\left(S_2AT_2\right)$. Consequently, $\mathcal{N}_l\left(S_2AT_2\right) \subseteq \mathcal{N}_l\left(S_2\right)$, which implies the existence of a matrix $Z \in \Q^{t \times m}$ such that $S_2=S_2AT_2Z$. Thus,
		\begin{equation}\label{pr2.2}
			S_2=S_2AT_2\left(S_2AT_2\right)^{(1)}S_2AT_2Z = S_2AT_2\left(S_2AT_2\right)^{(1)} S_2.
		\end{equation}
		From this, we derive
		\begin{equation*}
XAX=T_2\left(S_2AT_2\right)^{(1)}S_2AT_2\left(S_2AT_2\right)^{(1)}S_2 = T_2\left(S_2AT_2\right)^{(1)}S_2=X.
		\end{equation*}
		Hence, $X \in A\{2\}$. 

        Since $X=T_2\left(S_2AT_2\right)^{(1)}S_2$, and applying Definition \ref{def2.2}, we obtain
		\begin{equation*}
\mathcal{R}_l(X)=\mathcal{R}_l\left(T_2\left(S_2AT_2\right)^{(1)}S_2\right) \subseteq \mathcal{R}_l\left(S_2\right).
		\end{equation*}
		From \eqref{pr2.2}, it follows that
		\begin{equation*}
			S_2=S_2AT_2\left(S_2AT_2\right)^{(1)}S_2 = S_2AX.
		\end{equation*}
		By Definition \ref{def2.2}, we get
		\begin{equation*}
			\mathcal{R}_l(S_2) = \mathcal{R}_l\left(S_2AX\right) \subseteq \mathcal{R}_l(X).
		\end{equation*}
		Combining these results, we can conclude that $\mathcal{R}_l(X)=\mathcal{R}_l\left(S_2\right)$. 

		Conversely, assume $X \in A\{2\}$ and $\mathcal{R}_l(X)=\mathcal{R}_l\left(S_2\right)$. Then,
		\begin{equation*}
X=XAX=T_2\left(S_2AT_2\right)^{(1)}S_2AT_2\left(S_2AT_2\right)^{(1)}S_2.       \end{equation*}
		By Lemma \ref{lem2.12}, we get
		\begin{equation}\label{pr2.3}
			\rank\left(X\right) \leq \rank\left(S_2AT_2\left(S_2AT_2\right)^{(1)}S_2\right) \leq \rank\left(S_2AT_2\right) \leq \rank\left(S_2\right).
		\end{equation}
		Since $\mathcal{R}_l(X)=\mathcal{R}_l\left(S_2\right)$, we have $\dim\left(\mathcal{R}_l(X)\right)=\dim\left(\mathcal{R}_l(S_2)\right)$, which implies $\rank\left(X\right)=\rank\left(S_2\right) $. Combining this with \eqref{pr2.3}, we obtain
		\begin{equation*}
			\rank\left(X\right) \leq  \rank\left(S_2AT_2\right) \leq \rank\left(S_2\right) =\rank\left(X\right).
		\end{equation*}
Thus, we conclude that $\rank\left(S_2AT_2\right)=\rank\left(S_2\right)$.   \\
        %%%%%%%%%%%%%%%%%
		\item[$(c)$] Assume that $\rank\left(S_2AT_2\right)=\rank\left(T_2\right)$. By Definition \ref{def2.2}, we have $\mathcal{R}_l\left(S_2AT_2\right) \subseteq \mathcal{R}_l(T_2)$. As both subspaces have the same dimensions, it follows that $\mathcal{R}_l\left(S_2AT_2\right) = \mathcal{R}_l(T_2)$. Thus, $\mathcal{R}_l\left(T_2\right) \subseteq \mathcal{R}_l(S_2AT_2)$,  implying the existence of a matrix $Z \in \Q^{n \times l}$ such that $T_2=ZS_2AT_2$. Using this result, we obtain
		\begin{equation}\label{pr2.4}
T_2=Z\left(S_2AT_2\right)\left(S_2AT_2\right)^{(1)}S_2AT_2=T_2\left(S_2AT_2\right)^{(1)}S_2AT_2.
		\end{equation}
		Utilizing this, we derive
		\begin{equation*}
XAX=T_2\left(S_2AT_2\right)^{(1)}S_2AT_2\left(S_2AT_2\right)^{(1)}S_2 = T_2\left(S_2AT_2\right)^{(1)}S_2=X.
		\end{equation*}
		Hence, $X \in A\{2\}$.

		Since $X=T_2\left(S_2AT_2\right)^{(1)}S_2$, it follows that $\mathcal{N}_l(T_2) \subseteq \mathcal{N}_l(X)$. From \eqref{pr2.4}, we also have
		\begin{equation*}
			T_2=T_2\left(S_2AT_2\right)^{(1)}S_2AT_2 = XAT_2.
		\end{equation*}
		Thus, $\mathcal{N}_l(X) \subseteq \mathcal{N}_l\left(T_2\right)$. Combining these results, we conclude that $\mathcal{N}_l(X) = \mathcal{N}_l\left(T_2\right)$.

		Conversely, assume $X \in A\{2\}$ and $\mathcal{N}_l(X)=\mathcal{N}_l\left(T_2\right)$. Then,
		\begin{equation*}
X=XAX=T_2\left(S_2AT_2\right)^{(1)}S_2AT_2\left(S_2AT_2\right)^{(1)}S_2.
		\end{equation*}
		Using Lemma \ref{lem2.12}, we obtain
		\begin{equation}\label{pr2.5}
			\rank(X) \leq \rank\left(S_2AT_2\left(S_2AT_2\right)^{(1)}S_2\right) \leq \rank\left(S_2AT_2\right) \leq \rank(T_2).
		\end{equation}
		Since $\mathcal{N}_l(X)=\mathcal{N}_l\left(T_2\right)$, we have $\dim\left(\mathcal{N}_l(X)\right)=\dim\left(\mathcal{N}_l\left(T_2\right)\right)$. Applying Lemma \ref{lem2.8}, we conclude that $\rank(X)=\rank\left(T_2\right)$. Substituting this into \eqref{pr2.5}, we obtain
		\begin{equation*}
			\rank(X) \leq \rank\left(S_2AT_2\right) \leq \rank\left(T_2\right)=\rank(X).
		\end{equation*}
		Thus, we conclude that $\rank\left(S_2AT_2\right)=\rank(T_2)$. \\
