		\item[$(d)$] The result directly follows from parts $(b)$ and $(c)$. \\
        %%%%%%%%%%%%%%%
		\item[$(e)$] The result directly follows from parts $(a)$ and $(d)$.
        \end{enumerate}
\end{proof}
We now present the conditions required for the existence of a generalized inverse of a matrix with prescribed right and left range and null space. We also provide a corresponding expression for this inverse.
\begin{theorem}\label{thm3.6}
	Let $A \in \Q_r^{m \times n}$, $S \in \Q^{n \times m}$, $T \in \Q^{n \times m}$, and $X=S\left(TAS\right)^{(1)}T$, where $\left(TAS\right)^{(1)}$ is a fixed but arbitrary element of $\left(TAS\right)\left\{1\right\}$. Then
	\begin{enumerate}
	    \item[$(a)$] $X=A^{(2)}_{(S, T), (T, S)}$ if and only if $\rank\left(TAS\right)=\rank\left(S\right)=\rank\left(T\right)$.
		\item[$(b)$] $X=A^{(1,2)}_{(S, T), (T, S)}$ if and only if $\rank\left(TAS\right)=\rank\left(S\right)=\rank\left(T\right)=r$.
	\end{enumerate}
\end{theorem}
\begin{proof}
	The proof for both parts follows directly from Theorems \ref{thm3.4} and \ref{thm3.5}.
\end{proof}
The following theorems establish an explicit formula for the Moore–Penrose inverse, Drazin inverse, and group inverse of a quaternion matrix in terms of its outer inverse under predefined subspace conditions.
\begin{theorem}\label{thm3.7}
	Let $A \in \Q^{m \times n}$. Then, the Moore-Penrose inverse $A^{\dagger}$ is given by
	\begin{equation}\label{pi}
		A^{\dagger} = A^{(2)}_{l,\left(A^*, A^*\right)}=A^{(2)}_{r,\left(A^*, A^*\right)}=A^*\left(A^*AA^*\right)^{(1)}A^*,
	\end{equation}
where $\left(A^*AA^*\right)^{(1)} \in \left(A^*AA^*\right)\{1\}$. 
\end{theorem}
\begin{proof}
We prove the result for $A^{\dagger} = A^{(2)}_{l, (A^*, A^*)}$. The proof for $A^{\dagger} = A^{(2)}_{r, (A^*, A^*)}$ follows similarly.

    Evidently, $A^{\dagger} = A^{(2)}$. Thus, it remains to show that
    \begin{equation*}
        \mathcal{R}_l(A^{\dagger}) = \mathcal{R}_l(A^*) ~ \text{and} ~ \mathcal{N}_l(A^{\dagger}) = \mathcal{N}_l(A^*).
    \end{equation*}
 Using the properties of the Moore-Penrose inverse, we have
    \begin{equation*}
        A^{\dagger} = A^{\dagger} A A^{\dagger} = A^{\dagger} (A A^{\dagger})^*  = A^{\dagger} (A^{\dagger})^* A^*,
    \end{equation*}
    and
    \begin{equation*}
        A^* = (A A^{\dagger} A)^* = A^* (A^{\dagger})^* A^* = A^* (A A^{\dagger})^* = A^* A A^{\dagger}.
    \end{equation*}
Using the above identities and Definition \ref{def2.2}, we get 
    \begin{equation*}
        \mathcal{R}_l(A^{\dagger}) \subseteq \mathcal{R}_l(A^*) ~ \text{and} ~ \mathcal{R}_l(A^*) \subseteq \mathcal{R}_l(A^{\dagger}).
    \end{equation*}
    Consequently,
   $\mathcal{R}_l(A^{\dagger}) = \mathcal{R}_l(A^*)$.

Next, we show that the left null spaces are also equal. Let $u \in \mathcal{N}_l(A^*)$, such that $u A^* = 0$. Then
    \begin{equation*}
        u A^* (A^{\dagger})^* = 0 \implies u (A^{\dagger} A)^* = 0 \implies u A^{\dagger} A = 0 \implies u A^{\dagger} A A^{\dagger} = 0 \implies u A^{\dagger} = 0.
    \end{equation*}
    Thus, $u \in \mathcal{N}_l(A^{\dagger})$, and hence,
  $\mathcal{N}_l(A^*) \subseteq \mathcal{N}_l(A^{\dagger})$.
Conversely, let $v \in \mathcal{N}_l(A^{\dagger})$, so that $v A^{\dagger} = 0$. Then
    \begin{equation*}
        v A^{\dagger} A = 0 \implies v (A^{\dagger} A)^* = 0 \implies v A^* (A^{\dagger})^* A^* = 0 \implies v (A A^{\dagger} A)^* = 0 \implies v A^* = 0.
    \end{equation*}
    Thus, $v \in \mathcal{N}_l(A^*)$, hence, $\mathcal{N}_l(A^{\dagger}) \subseteq \mathcal{N}_l(A^*)$. Consequently,
   $\mathcal{N}_l(A^{\dagger}) = \mathcal{N}_l(A^*)$.
Therefore, $A^{\dagger} = A^{(2)}_{l, (A^*, A^*)}$. This completes the proof.
