\begin{theorem}\label{thm3.7d}
    Let $A \in \mathbb{Q}^{m \times m}$ with $\text{Ind}(A) = k$. Then, the Drazin inverse of $A$ is given by  
    \[
    A^{D} = A^{(2)}_{l,\left(A^k, A^k\right)} = A^{(2)}_{r,\left(A^k, A^k\right)}.
    \]
\end{theorem}
\begin{proof}
    We aim to prove that  
  $A^D = A^{(2)}_{l,\left(A^k, A^k\right)}$. 
    Because $A^D$ is an outer inverse, it suffices to establish that  
    \[
    \mathcal{R}_l(A^D) = \mathcal{R}_l(A^k), ~ \mathcal{N}_l(A^D) = \mathcal{N}_l(A^k).
    \]
 From the defining properties of the Drazin inverse, we have 
    \begin{equation}\label{eqdra1}
        A^D = A^D A A^D, ~ AA^D = A^D A, ~ A^{k+1} A^D = A^k.
    \end{equation}
    Using these identities, it follows that
    \begin{equation}\label{eqdra2}
        A^k = A^D A^{k+1}, ~ A^D = A^k (A^D)^{k+1}, ~ A^D = (A^D)^{k+1} A^k.
    \end{equation}
    We now verify the range and null space conditions.

     From Definition~\ref{def2.2} and using \eqref{eqdra1} and \eqref{eqdra2}, we obtain
 $\mathcal{R}_l(A^D) = \mathcal{R}_l(A^k)$.
    Let $x \in \mathcal{N}_l(A^D)$, that is, $x A^D = 0$. Post-multiplying by $A^{k+1}$ yields  
    \[
    x A^D A^{k+1} = 0.
    \]
    Using \eqref{eqdra2}, this simplifies to $x A^k = 0$,  implying that $x \in \mathcal{N}_l(A^k)$. Hence,  
  $\mathcal{N}_l(A^D) \subseteq \mathcal{N}_l(A^k)$.
  Conversely, let $y \in \mathcal{N}_l(A^k)$, that is, $y A^k = 0$. Post-multiplying by $(A^D)^{k+1}$ yields  
    \[
    y A^k (A^D)^{k+1} = 0.
    \]
    Again using \eqref{eqdra2}, we obtain $y A^D = 0$, implying $y \in \mathcal{N}_l(A^D)$. Thus,  
  $\mathcal{N}_l(A^k) \subseteq \mathcal{N}_l(A^D)$.
    This establishes $\mathcal{N}_l(A^D) = \mathcal{N}_l(A^k)$.

    The proof of $A^D = A^{(2)}_{r,\left(A^k, A^k\right)}$ follows analogously. Hence, the result is proved.
\end{proof}
\begin{corollary}\label{cord}
    If $\text{Ind}(A) = 1$, then the group inverse of $A \in \Q^{m \times m}$ is given by  
    \[
    A^{\#} = A^{(2)}_{l,\left(A, A\right)} = A^{(2)}_{r,\left(A, A\right)}.
    \]
\end{corollary}
\begin{proof}
   The proof follows immediately by setting $k = 1$ in Theorem \ref{thm3.7d}.
\end{proof}
The following theorems establish the key results regarding the range and null space of a quaternion matrix based on its full rank decomposition.
\begin{theorem}\label{thm3.8}
    Let $A \in \Q_r^{m \times n}$, and suppose $A = F_1 G_1$ is an arbitrary full rank decomposition of $A$. Then,
    \begin{equation*}
        \mathcal{R}_r(A) = \mathcal{R}_r(F_1), ~ \mathcal{N}_r(A) = \mathcal{N}_r(G_1).
    \end{equation*}
   \end{theorem}
\begin{proof}
Let $\text{col}_i(A)$ and $\text{col}_i(F_1)$ denote the $i^{\text{th}}$ column of matrix $A$ and matrix $F_1$, respectively. Consider $G_1=(g_{ij})_{r \times n}$. We have
    \begin{equation*}
        \begin{bmatrix}
            \text{col}_1(A) & \text{col}_2(A) & \cdots & \text{col}_n(A)
        \end{bmatrix} = \begin{bmatrix}
            \text{col}_1(F_1) & \text{col}_2(F_1) & \cdots & \text{col}_r(F_1)
        \end{bmatrix}
        \begin{bmatrix}
            g_{11} & g_{12} & \cdots & g_{1n} \\
            g_{21} & g_{22} & \cdots & g_{2n} \\
            \vdots & \vdots &        & \vdots\\
            g_{r1} & g_{r2} & \cdots & g_{rn}
        \end{bmatrix}.
    \end{equation*}
 Therefore,
    \begin{equation*}
        \text{col}_i(A) = \text{col}_1(F_1) g_{1i} + \text{col}_2(F_1) g_{2i} + \cdots + \text{col}_r(F_1) g_{ri}, ~ \text{for } i=1,2,\ldots,n.
    \end{equation*}
    Thus,
    \begin{equation*}
        \text{col}_i(A) \in \mathcal{R}_r(F_1), ~ \text{for } i=1,2,\ldots,n.
    \end{equation*}
    Consequently,
  $\mathcal{R}_r(A) \subseteq \mathcal{R}_r(F_1)$.
    Since $r = \rank(A) = \dim(\mathcal{R}_r(A)) = \dim(\mathcal{R}_r(F_1))$, it follows that
   $\mathcal{R}_r(A) = \mathcal{R}_r(F_1)$.

    Next, we investigate the relationship between the null spaces. Let $x \in \mathcal{N}_r(G_1)$, implying that $G_1 x = 0$. Consequently, $F_1 G_1 x = 0$, implying 
that $A x = 0$.
    Thus, $x \in \mathcal{N}_r(A)$, leading to
   $\mathcal{N}_r(G_1) \subseteq \mathcal{N}_r(A)$.
    Furthermore, we have
    \begin{align*}
        \dim(\mathcal{N}_r(G_1)) &= n - \dim(\mathcal{R}_r(G_1)) = n - \rank(G_1) = n - r, \\
        \dim(\mathcal{N}_r(A)) &= n - \dim(\mathcal{R}_r(A)) = n - \rank(A) = n - r.
    \end{align*}
    Since $\dim(\mathcal{N}_r(G_1)) = \dim(\mathcal{N}_r(A))$, we conclude that
   $\mathcal{N}_r(A) = \mathcal{N}_r(G_1)$.
    This completes the proof.
\end{proof}
\begin{theorem}\label{thm3.9}
Let $A \in \Q_r^{m \times n}$, and suppose $A = G_2 F_2$ is an arbitrary full rank decomposition of $A$. Then,
    \begin{equation*}
        \mathcal{R}_l(A)=\mathcal{R}_l(F_2), ~ \mathcal{N}_l(A) = \mathcal{N}_l(G_2).
    \end{equation*}
\end{theorem}
\begin{proof}
  Let $\text{row}_i(A)$ and $\text{row}_i(F_2)$ denote the $i^{\text{th}}$ row of matrix $A$ and matrix $F_2$, respectively. Consider $G_2=(g_{ij})_{m \times r}$. We have
\begin{equation*}
    \begin{bmatrix}
        \text{row}_1(A) \\ \text{row}_2(A) \\ \vdots \\ \text{row}_m(A)
    \end{bmatrix} = \begin{bmatrix}
        g_{11} & g_{12} & \cdots & g_{1r} \\
        g_{21} & g_{22} & \cdots & g_{2r} \\
        \vdots & \vdots &        & \vdots\\
        g_{m1} & g_{m2} & \cdots & g_{mr}
    \end{bmatrix}\begin{bmatrix}
        \text{row}_1(F_2) \\ \text{row}_2(F_2) \\ \vdots \\ \text{row}_r(F_2)
    \end{bmatrix}.
\end{equation*}
Therefore,
\begin{equation*}
    \text{row}_i(A) =  g_{i1} \text{row}_1(F_2) + g_{i2} \text{row}_2(F_2) + \cdots + g_{ir} \text{row}_r(F_2), ~ \text{for } i=1,2,\ldots,m.
\end{equation*}
Thus,
\begin{equation*}
    \text{row}_i(A) \in \mathcal{R}_l(F_2), ~ \text{for }  i=1,2,\ldots,m.
\end{equation*}
Consequently,
$\mathcal{R}_l(A) \subseteq \mathcal{R}_l(F_2)$.
Since $r = \rank(A) = \dim(\mathcal{R}_l(A)) = \dim(\mathcal{R}_l(F_2))$, it follows that
$\mathcal{R}_l(A) = \mathcal{R}_l(F_2)$.

Next, we investigate the relationship between the null spaces. Let $x \in \mathcal{N}_l(G_2)$, implying that $x G_2 = 0$. Consequently,
$x G_2 F_2 = 0$, implying 
that $x A = 0$.
Thus, $x \in \mathcal{N}_l(A)$, leading to
$\mathcal{N}_l(G_2) \subseteq \mathcal{N}_l(A)$.
Furthermore, we have
\begin{align*}
    \dim(\mathcal{N}_l(G_2)) &= m - \dim(\mathcal{R}_l(G_2)) = m - \rank(G_2) = m - r, \\
    \dim(\mathcal{N}_l(A)) &= m - \dim(\mathcal{R}_l(A)) = m - \rank(A) = m - r.
\end{align*}
As $\dim(\mathcal{N}_l(G_2)) = \dim(\mathcal{N}_l(A))$, we conclude that
$\mathcal{N}_l(A) = \mathcal{N}_l(G_2)$.
This completes the proof.  
\end{proof}
The following theorem establishes the explicit representation of $A^{(2)}_{r,\left(W_1, W_1\right)}$, based on the full rank factorization of $W_1$.
\begin{theorem}\label{thm3.10}
Let $A \in \Q_r^{m \times n}$ and $W_1 \in \Q^{n \times m}$ be a matrix such that $\dim(\mathcal{R}_r(W_1)) = s \leq r$ and $\dim(\mathcal{N}_r(W_1)) = m-s$. Assume $W_1 = S_1 T_1$ is a full rank factorization of $W_1$, and define
\[
    X = S_1 (T_1 A S_1)^{-1} T_1.
\]
If $A$ has a $\{2\}$-inverse $A^{(2)}_{r,(W_1,W_1)}$, then the following statements hold:
\begin{enumerate}
    \item[$(a)$] $T_1 A S_1$ is an invertible matrix.
    \item[$(b)$] $A^{(2)}_{r,(W_1,W_1)} = X = A^{(2)}_{r,(S_1,T_1)}$.
\end{enumerate}
\end{theorem}
\begin{proof}
\item[$(a)$]
According to Theorem \ref{thm3.8}, we have the following relations:
\begin{equation}\label{3.10.1}
    \mathcal{R}_r(W_1)=\mathcal{R}_r(S_1), ~ \mathcal{N}_r(W_1)=\mathcal{N}_r(T_1).
\end{equation}
Now, observe that $\mathcal{R}_r(AS_1) = A \mathcal{R}_r(S_1) = A \mathcal{R}_r(W_1)$.
Using \cite[Theorem $3.1$]{SongWangchang2011}, we get 
\begin{equation}\label{3.10.2}
A \mathcal{R}_r(W_1) \oplus \mathcal{N}_r(W_1) = \Q^{m \times 1}.
\end{equation}
Utilizing this, we can compute the dimension
\begin{eqnarray*}
    \dim(\mathcal{R}_r(AS_1)) &=& \dim(A \mathcal{R}_r(W_1)) \\
                            &=& m- \dim(\mathcal{N}_r(W_1)) \\
                            &=& m -(m-s) = s.
\end{eqnarray*}
Therefore, $\rank(AS_1) = s.$ By a similar argument, we also obtain
$\rank(AW_1) = s.$ This implies that
\[ AW_1 = AS_1 T_1 \]
is a full rank factorization of $AW_1$.

Next, suppose $y \in \mathbb{Q}^{s \times 1}$ satisfies $(T_1 AS_1) y = 0$. This implies that $AS_1 y \in \mathcal{N}_r(T_1)$.
Using equation \eqref{3.10.1}, we obtain $AS_1 y \in \mathcal{N}_r(W_1).$
 In addition, because $AS_1 y \in \mathcal{R}_r(AS_1) = A \mathcal{R}_r(W_1)$, we have
\begin{equation*}
    AS_1y \in A \mathcal{R}_r(W_1) \cap \mathcal{N}_r(W_1).
\end{equation*}
Using equation \eqref{3.10.2}, it follows that
$AS_1 y = 0$, which implies $y \in \mathcal{N}_r(AS_1)$.
Now, observe that
\[
    \dim(\mathcal{N}_r(AS_1)) = s - \dim(\mathcal{R}_r(AS_1)) = s - \rank(AS_1) = 0,
\]
Therefore, we conclude that $y = 0.$
Hence, for any $y \in \mathbb{Q}^{s \times 1}$,
$(T_1 AS_1) y = 0$ implies $y = 0$.
Therefore,
$\dim(\mathcal{N}_r(T_1 AS_1)) = 0$,
and consequently,
\[
    \rank(T_1 AS_1) = \dim(\mathcal{R}_r(T_1 AS_1)) = s - \dim(\mathcal{N}_r(T_1 AS_1)) = s,
\]
implying that $T_1 AS_1$ is a nonsingular matrix; hence, it is invertible. \\
%%%%%%%%%%%%%%%%%
\item[$(b)$]
We verify that $X$ satisfies the defining equation for a $\{2\}$-inverse
\[
    XAX = S_1 (T_1 AS_1)^{-1} T_1 A S_1 (T_1 AS_1)^{-1} T_1 = S_1 (T_1 AS_1)^{-1} T_1 = X,
\]
thus, $X \in A\{2\}.$

Applying Definition \ref{def2.2}, we obtain the following results
\begin{equation}\label{3.10.3}
    \mathcal{R}_r(X) = \mathcal{R}_r \left( S_1 (T_1 AS_1)^{-1} T_1 \right) \subseteq \mathcal{R}_r(S_1),
\end{equation}
and
\begin{equation}\label{3.10.4}
    \mathcal{N}_r(T_1) \subseteq \mathcal{N}_r \left( S_1 (T_1 AS_1)^{-1} T_1 \right) = \mathcal{N}_r(X).
\end{equation}
We will now prove that $\mathcal{R}_r(S_1) \subseteq \mathcal{R}_r(X)$ and $\mathcal{N}_r(X) \subseteq \mathcal{N}_r(T_1)$. We observe the relation
\[
    S_1 = S_1 (T_1 AS_1)^{-1} T_1 A S_1 = X A S_1,
\]
which implies that
\begin{equation}\label{3.10.5}
    \mathcal{R}_r(S_1) = \mathcal{R}_r(X A S_1) \subseteq \mathcal{R}_r(X).
\end{equation}
Next, let $u \in \mathcal{N}_r(X)$. This implies that $X u = 0,$
 leading to
$S_1 (T_1 AS_1)^{-1} T_1 u = 0$.
Because $S_1$ is a full column rank matrix, it has a left inverse. Pre-multiplying both sides by the left inverse of $S_1$, we get
$(T_1 AS_1)^{-1} T_1 u = 0$.
Again, by pre-multiplying both sides by $T_1 AS_1$, we obtain $T_1u=0$ which shows that $u \in \mathcal{N}_r(T_1)$. Therefore,
\begin{equation}\label{3.10.6}
  \mathcal{N}_r(X) \subseteq \mathcal{N}_r(T_1).
\end{equation}
Combining equations \eqref{3.10.3}, \eqref{3.10.4}, \eqref{3.10.5}, and \eqref{3.10.6}, we conclude that
\[
  \mathcal{N}_r(X) = \mathcal{N}_r(T_1), ~ \mathcal{R}_r(X) = \mathcal{R}_r(S_1).
\]
Therefore, $A^{(2)}_{r,(S_1,T_1)} = X = A^{(2)}_{r,(W_1,W_1)}.$ This completes the proof.
\end{proof}
The following theorem establishes the explicit representation of $A^{(2)}_{l,\left(W_2, W_2\right)}$, based on the full rank factorization of $W_2$.
\begin{theorem}\label{thm3.11}
Let $A \in \Q_r^{m \times n}$ and $W_2 \in \Q^{n \times m}$ be a matrix such that $\dim(\mathcal{R}_l(W_2)) = t \leq r$ and $\dim(\mathcal{N}_l(W_2)) = n-t$. Assume $W_2 = T_2 S_2$ is a full rank factorization of $W_2$, and define
\[
    X = T_2 (S_2 A T_2)^{-1} S_2.
\]
If $A$ has a $\{2\}$-inverse $A^{(2)}_{l,(W_2,W_2)}$, then the following statements hold:
\begin{enumerate}
    \item[$(a)$] $S_2 A T_2$ is an invertible matrix.
    \item[$(b)$] $A^{(2)}_{l,(W_2,W_2)} = X = A^{(2)}_{l,(S_2,T_2)}$.
\end{enumerate}
\end{theorem}
\begin{proof}
    \item[$(a)$]
According to Theorem \ref{thm3.9}, we have the following relations:
\begin{equation}\label{3.11.1}
    \mathcal{R}_l(W_2)=\mathcal{R}_l(S_2), ~ \mathcal{N}_l(W_2)=\mathcal{N}_l(T_2).
\end{equation}
Now, observe that $\mathcal{R}_l(S_2 A) = \mathcal{R}_l(S_2) A = \mathcal{R}_l(W_2) A$.
Using \cite[Theorem $3.1$]{SongWangchang2011}, we get 
\begin{equation}\label{3.11.2}
 \mathcal{R}_l(W_2) A \oplus \mathcal{N}_l(W_2) = \Q^{1 \times n}.
\end{equation}
Utilizing this, we can compute the dimension
\begin{eqnarray*}
    \dim(\mathcal{R}_l(S_2 A)) &=& \dim(\mathcal{R}_l(W_2) A) \\
                            &=& n- \dim(\mathcal{N}_l(W_2)) \\
                            &=& n -(n-t) = t.
\end{eqnarray*}
Therefore, $\rank(S_2 A) = t.$ By a similar argument, we also obtain
$\rank(W_2 A) = t.$ This implies that
\[ W_2 A = T_2 S_2 A \]
is the full rank factorization for $ W_2A$.

Next, suppose $y \in \mathbb{Q}^{1 \times t}$ satisfies $y (S_2 A T_2) = 0$. This implies that $y S_2 A \in \mathcal{N}_l(T_2)$. 
Using equation \eqref{3.11.1}, we obtain $y S_2 A \in \mathcal{N}_l(W_2).$
 In addition, because $y S_2 A \in \mathcal{R}_l(S_2 A) = \mathcal{R}_l(W_2) A$, we have
\begin{equation*}
    y S_2 A \in \mathcal{R}_l(W_2) A \cap \mathcal{N}_l(W_2).
\end{equation*}
Using equation \eqref{3.11.2}, it follows that
$y S_2 A = 0$, which implies $y \in \mathcal{N}_l(S_2 A)$.
Now, observe that
\[
    \dim(\mathcal{N}_l(S_2 A)) = t - \dim(\mathcal{R}_l(S_2 A)) = t - \rank(S_2 A) = 0,
\]
we conclude that $y = 0.$
Hence, for any $y \in \mathbb{Q}^{1 \times t}$, the equation
$y(S_2 A T_2)  = 0$ implies $y = 0$.
Therefore,
$\dim(\mathcal{N}_l(S_2 A T_2)) = 0$,
and consequently,
\[
    \rank(S_2 A T_2) = \dim(\mathcal{R}_l(S_2 A T_2)) = t - \dim(\mathcal{N}_l(S_2 A T_2)) = t,
\]
implying that $S_2 A T_2$ is a nonsingular matrix; hence, it is invertible. \\
\item[$(b)$]
We verify that $X$ satisfies the defining equation for a $\{2\}$-inverse
\[
    XAX = T_2 (S_2 A T_2)^{-1} S_2 A T_2 (S_2 A T_2)^{-1} S_2 = T_2 (S_2 A T_2)^{-1} S_2 = X,
\]
thus, $X \in A\{2\}.$

Applying Definition \ref{def2.2}, we obtain the following results
\begin{equation}\label{3.11.3}
    \mathcal{R}_l(X) = \mathcal{R}_l \left( T_2 (S_2 A T_2)^{-1} S_2 \right) \subseteq \mathcal{R}_l(S_2),
\end{equation}
and
\begin{equation}\label{3.11.4}
    \mathcal{N}_l(T_2) \subseteq \mathcal{N}_l \left( T_2 (S_2 A T_2)^{-1} S_2 \right) = \mathcal{N}_l(X).
\end{equation}
We will now prove that $\mathcal{R}_l(S_2) \subseteq \mathcal{R}_l(X)$ and $\mathcal{N}_l(X) \subseteq \mathcal{N}_l(T_2)$. We observe the relation
\[
    S_2 = (S_2 A T_2) (S_2 A T_2)^{-1} S_2  = S_2 A X,
\]
which implies that
\begin{equation}\label{3.11.5}
    \mathcal{R}_l(S_2) = \mathcal{R}_l(S_2 A X) \subseteq \mathcal{R}_l(X).
\end{equation}
Next, let $v \in \mathcal{N}_l(X)$. This implies $v X = 0,$
which leads to
$v T_2 (S_2 A T_2)^{-1} S_2 = 0$.
Since $S_2$ is a full row rank matrix, it has a right inverse. Post-multiplying both sides by the right inverse of $S_2$, we get
$v T_2 (S_2 A T_2)^{-1} = 0.$ Again post-multiplying both sides by $S_2 A T_2$, we obtain $v T_2 =0$ which shows that $v \in \mathcal{N}_l(T_2)$. Therefore,
\begin{equation}\label{3.11.6}
  \mathcal{N}_l(X) \subseteq \mathcal{N}_l(T_2).
\end{equation}
Combining equations \eqref{3.11.3}, \eqref{3.11.4}, \eqref{3.11.5}, and \eqref{3.11.6}, we conclude that
\[
  \mathcal{N}_l(X) = \mathcal{N}_l(T_2), ~ \mathcal{R}_l(X
  )= \mathcal{R}_l(S_2).
\]
Therefore, $A^{(2)}_{l,(S_2,T_2)} = X = A^{(2)}_{l,(W_2,W_2)}$. This completes the proof.
\end{proof}

\section{Computational algorithms and numerical examples}\label{sec4}
In this section, we present algorithms to compute the generalized inverse of a quaternion matrix with specified right and/or left range and/or null space constraints. To demonstrate their effectiveness, we provide numerical examples. All computations are performed on a system equipped with an Intel Core $i9$-$12900K$ processor running at $3200$ MHz, with $32$ GB of RAM, using MATLAB $R2024b$.

\subsection{Algorithms}
This subsection is dedicated to designing computational algorithms for computing generalized inverses with predefined subspace constraints, based on the theoretical results established in the previous section. Theorem \ref{thm3.4} provides a powerful unified framework for computing generalized inverses, including the Moore-Penrose inverse, the group inverse, the Drazin inverse, and other constrained generalized inverses with prescribed range and null space properties. Specifically, for the given matrices 
$A \in Q^{m \times n}_r,~S_1 \in \Q^{n \times p},~T_1 \in \Q^{q \times m},
$ the matrix 
$
X = S_1 \left(T_1 A S_1\right)^{(1)} T_1
$
yields different generalized inverses depending on the rank relations among \( T_1 A S_1 \), \( S_1 \), and \( T_1 \). To efficiently compute \( X \), we propose the following algorithms:
\begin{itemize}
    \item \textbf{Algorithm~\ref{alg1}}: Based on direct computation in QTFM. 
    \item \textbf{Algorithm~\ref{alg2}}: Based on the complex representation of quaternion matrices. 
\end{itemize}

\begin{algorithm} [H]
	\caption{Computation of $X=S_1\left(T_1AS_1\right)^{(1)}T_1$ by using direct computation in QTFM}\label{alg1}
{\small{
	\textbf{Input:} $A \in \Q_r^{m \times n}$, $S_1 \in \Q^{n \times p}$, and $T_1  \in  \Q^{q \times m}$. \\
	\textbf{Output:} $X=X_1+X_2\j \in \Q^{n \times m}$.
	\begin{enumerate}
		\item Compute $W=T_1AS_1 \in \Q^{q \times p}$.
		\item Compute the SVD of $W$ using QTFM. That is $W=U \Sigma V^*$, where $U \in \Q^{q \times q}$, $V \in \Q^{p \times p}$, and $\Sigma=\begin{bmatrix}
			\Sigma_s & 0\\
			0 & 0
		\end{bmatrix} \in \R^{q \times p}$.  Here, $U$ and $V$ are unitary quaternion matrices, and $\Sigma_{s}=\diag(\sigma_1,\ldots,\sigma_{s}) \in \R^{s \times s}$ contains the nonzero singular values of $W$. Here, $s=\rank(W)$.
        \item Define arbitrary matrices $K \in \Q^{s \times (q-s)}$, $L \in \Q^{(p-s) \times s}$, and $M \in \Q^{(p-s) \times (q-s)}$.
		\item Calculate $W^{(1)}$ as follows:
		\[
		W^{(1)} = V\begin{bmatrix}
			\Sigma_s^{-1} & K \\
			L & M
		\end{bmatrix}U^*.
		\] 
		\item Compute $X=S_1W^{(1)}T_1$. 
	\end{enumerate}
	}}
\end{algorithm}


	\begin{algorithm} [H]
\small{
    \caption{Computation of $X=S_1\left(T_1AS_1\right)^{(1)}T_1$ using the complex representation of quaternions}\label{alg2}
	\vspace{0.2cm}
	\textbf{Input:} $A=A_1+A_2\j \in \Q_r^{m \times n}$, $S_1=S_{11}+S_{12}\j \in \Q^{n \times p}$, and $T_1=T_{11}+T_{12}\j  \in  \Q^{q \times m}$. \\
	\textbf{Output:} $X=X_1+X_2\j \in \Q^{n \times m}$.
	\begin{enumerate}
   \item \textbf{Compute} $\mathbf{W=W_1+W_2\j=T_1AS_1}$ \textbf{as follows:} \begin{itemize}
        \item Compute $\left(T_1\right)_r^C$, $A^C$, and $S_1^C$.
        \item Compute $W^C_r$ as: $W^C_r=(T_1)^C_rA^CS_1^C.$
        \item Extract the components of $W$: $
		W_1 = W^C_r(:,1:p), ~ W_2 = W^C_r(:,p+1:end).$
        \end{itemize}
		 \item \textbf{Compute} $\mathbf{\left(W^{(1)}\right)^C}$ \textbf{as follows:}
         \begin{itemize}
         \item Compute the SVD of $W$ using the complex structure-preserving algorithm \cite[Algorithm $3$]{ZhangJiaJiaWang2024}. That is, compute  $W=U \Sigma V^*$, where $U \in \Q^{q \times q}$, $\Sigma=\begin{bmatrix}
			\Sigma_s & 0\\
			0 & 0
		\end{bmatrix} \in \R^{q \times p}$, and $V \in \Q^{p \times p}$. Here, $U$ and $V$ are unitary quaternion matrices, and $\Sigma_{s}=\diag(\sigma_1,\ldots,\sigma_{s}) \in \R^{s \times s}$ contains the nonzero singular values of $W$. Here, $s=\rank(W)$.         %In the complex structure-preserving algorithm, the inputs are the matrices $W_1$ and $W_2$, and the outputs are the matrices $U$, $\Sigma$, and $V$.
        \item Define arbitrary matrices $K \in \Q^{s \times (q-s)}$, $L \in \Q^{(p-s) \times s}$, and $M \in \Q^{(p-s) \times (q-s)}$. 
        \item Define $Y=\begin{bmatrix}
			\Sigma_{s}^{-1} & K \\
			L & M
		\end{bmatrix}.$ \\
        \item Compute $V^C$, $Y^C$, and $\left(U^*\right)^C$.
         \item Compute ${\left(W^{(1)}\right)}^C$ as follows:
        $\left(W^{(1)}\right)^C = V^C Y^C (U^*)^C.$
\end{itemize}
         \item \textbf{Compute} $\mathbf{X^C_r}$.
         \begin{itemize}
		\item Compute $(S_1)^C_r$ and $(T_1)^C$.
		\item Compute $X^C_r=\left(S_1\right)^C_r\left(W^{(1)}\right)^C (T_1)^C.$
        \end{itemize}
		\item \textbf{Extract the components of} $\mathbf{X}$:
		$X_1 = X^C_r(:,1:m)$ and $X_2 = X^C_r(:,m+1:end)$.
	\end{enumerate}
    }
\end{algorithm}
The versatility of Algorithms~\ref{alg1} and~\ref{alg2} lies in their ability to compute different generalized inverses with the prescribed right range and/or null space, depending on the rank conditions specified in Theorem~\ref{thm3.4}. 

\begin{remark}
The computation of \( X \) in Theorems~\ref{thm3.5} and~\ref{thm3.6} follows a methodology similar to that in Theorem~\ref{thm3.4}. Specifically:
\begin{itemize}
    \item In Theorem~\ref{thm3.5}, \( X \) represents a generalized inverse with a prescribed left range and/or null space.
    \item In Theorem~\ref{thm3.6}, \( X \) represents a generalized inverse with both-sided prescribed range and null space.
\end{itemize}
\end{remark}
Since Algorithms~\ref{alg1} and~\ref{alg2} are formulated to compute \( X \), they can be easily adapted for Theorems~\ref{thm3.5} and~\ref{thm3.6}. Therefore, we do not present separate algorithms for computing the generalized inverse \( X \) described in Theorems~\ref{thm3.5} and~\ref{thm3.6}. We develop the following two algorithms for computing the generalized inverse \( A^{(2)}_{r,(W_1, W_1)} \) using the full rank factorization technique described in Theorem~\ref{thm3.10}. 
\begin{itemize}
    \item \textbf{Algorithm~\ref{alg3}}: Utilizes direct computation in QTFM.
    \item \textbf{Algorithm~\ref{alg4}}: Employs the complex representation of quaternion matrices.
\end{itemize}
These algorithms are based on the full rank factorization of \( W_1 = S_1 T_1 \) and involve computing  $X = S_1 (T_1 A S_1)^{-1} T_1.$
According to Theorem~\ref{thm3.10}, this computation yields the generalized inverse \( A^{(2)}_{r,(W_1, W_1)} \) if and only if \( T_1 A S_1 \) is invertible.
\begin{algorithm} [H]
	\caption{Computation of $A^{(2)}_{r,\left(W_1, W_1\right)}$ by full rank factorization technique using direct computation in QTFM}\label{alg3}
	{\small{
	\textbf{Input:} $A \in \Q_r^{m \times n}$ and $W_1 \in \Q^{n \times m}$ such that $\dim\left(\mathcal{R}_r\left(W_1\right)\right) =s \leq r$ and $\dim\left(\mathcal{N}_r\left(W_1\right)\right) =m-s$. \\
	\textbf{Output:} $X=X_1+X_2\j=A^{(2)}_{r,\left(W_1, W_1\right)} \in \Q^{n \times m}$.
	\begin{enumerate}
		\item Compute the full rank factorization of $W_1$ by using direct computation in QTFM \cite[Algorithm $1$]{WangZhangVasilJiang2022} in order to find matrices $S_1 \in \Q^{n \times s}$ and $T_1 \in \Q^{s \times m}$ such that $W_1=S_1 T_1.$
        % In \cite[Algorithm $1$]{WangZhangVasilJiang2022}, the input is $W_1$ and the outputs are the matrices $S_1$ and $T_1$.
    \item If $\rank(T_1AS_1)=s$, then compute $X$ as: $ X=S_1(T_1AS_1)^{-1}T_1.$
       \end{enumerate}
}}
\end{algorithm}

\begin{algorithm} [H]
	\caption{Computation of $A^{(2)}_{r,\left(W_1, W_1\right)}$ by full rank factorization technique using complex representation of quaternions}\label{alg4}
	{\small{
	\textbf{Input:} $A=A_1+A_2\j \in \Q_r^{m \times n}$ and $W_1=W_{11}+W_{12}\j \in \Q^{n \times m}$, where $W_1$ is a matrix such that $\dim\left(\mathcal{R}_r\left(W_1\right)\right) =s \leq r$ and $\dim\left(\mathcal{N}_r\left(W_1\right)\right) =m-s$. \\
	\textbf{Output:} $X=X_1+X_2\j=A^{(2)}_{r,\left(W_1, W_1\right)} \in \Q^{n \times m}$.
	\begin{enumerate}
		\item Compute the full rank factorization of $W_1=W_{11}+W_{12}\j$ using complex structure-preserving algorithm \cite[Algorithm $2$]{WangZhangVasilJiang2022} in order to find matrices $S_1=S_{11}+S_{12}\j \in \Q^{n \times s}$ and $T_1=T_{11}+T_{12}\j \in \Q^{s \times m}$ such that 
        $W_1=S_1 T_1$.
        %In \cite[Algorithm $2$]{WangZhangVasilJiang2022}, the inputs are $W_{11}$ and $W_{12}$, and the outputs are the matrices $S_{11}$, $S_{12}$, $T_{11}$, and $T_{12}$.
        \item Compute $T_1^C$, $A^C$, and $S_1^C$.
        \item Define $R=T_1AS_1$. Compute $R^C$ as:
                $ R^C = T_1^CA^CS_1^C.$

        \item Compute $(S_1)^C_r$.
        \item If $R^C$ is invertible, then compute $X^C_r$ as:
	       $X^C_r=(S_1)^C_r \left(R^C\right)^{-1}T_1^C.$

        \item Extract the components of $X$ as:
       $X_1 = X^C_r(:,1:m), ~ X_2=X^C_r(:, m+1:end).$
		\end{enumerate}
        }}
	%\vspace{-0.2cm}
\end{algorithm}
\begin{remark}\label{rem4.2}
The procedure for computing \( A^{(2)}_{l,(W_2, W_2)} \), as described in Theorem~\ref{thm3.11}, is fundamentally the same as that used to compute \( A^{(2)}_{r,(W_1, W_1)} \). Therefore, Algorithms~\ref{alg3} and~\ref{alg4} can  easily be adapted to compute \( A^{(2)}_{l,(W_2, W_2)} \). To avoid redundancy, we did not provide separate algorithms for computing \( A^{(2)}_{l,(W_2, W_2)} \).
\end{remark}

