\section{Numerical implementation details}
\label{sect:numerics}
\subsection{Stochastic simulation algorithm for synthetic data}

\cref{alg:particleSim} describes the generation procedure for synthetic data used in the inference setups of \cref{fig:inferencefig,fig:random_areas}. Importantly, we simulate trajectories of the particle process, and do inference using the point process theory from \cref{thm:main}. The simulation procedure is exact except for a small $\Delta_t$-controlled approximation error in computing whether a Brownian path has exited the domain \cite{smith2019spatial}. In all simulations, we take $\Delta_t=10^{-5}$, several orders of magnitude smaller than any other timescale. 

\begin{algorithm}
\caption{Stochastic simulation to generate particle positions for synthetic data.}\label{alg:particleSim}
\begin{algorithmic}[1]
\Procedure{SimulateParticles}{$k_\text{birth}, k_\text{death}, D, z, L, T, \Delta_t$}
\State $N\text{births} \sim \operatorname{Poisson}(\ksource T)$
\For{$n=1,\ldots,N{\text{births}}$}
\State $T\text{birth}_n \sim \operatorname{unif}(0,T)$
\State $\tau\text{decay}_n \sim \operatorname{exp}(1/\kswitch)$
\State $T\text{decay}_n \gets T\text{birth}_n+\tau\text{decay}_n$
\If{$T\text{decay}_n>T$}\Comment{only simulate if particle is possibly alive $T$}
\State $x\gets z$, \, $t_n\gets T\text{birth}_n$  \Comment{birth particle at source location} 
\State $\text{survived}_n\gets 1$
\While{$t_n \leq T$}
\State $x\gets x+  \sqrt{2D\Delta_t} \cdot \texttt{randn}$ \Comment{Brownian step}
\State $t_n\gets t_n+\Delta_t$
\If{$x<0$\text{ or }$x>L$}   \Comment{if exits domain}
\State  $\text{survived}_n\gets 0$ \textbf{break} \Comment{instantly absorbed, stop simulating}  \EndIf
\EndWhile
\If{$\text{survived}_n$} \Comment{if alive at observation $T$}
\State \textbf{append} $x$ \Comment{store final position}
\EndIf
\EndIf
\EndFor
\State \textbf{return} $x_1,\ldots,x_N$
\EndProcedure
\end{algorithmic}
\end{algorithm}

\subsection{Metropolis-in-Gibbs sampling for Bayesian inference}

See \cref{subsect:inference} for an explanation of prior choices for $\lambda, \mu$. The choice of prior for $\lambda$ provides a (marginal) conjugate posterior that can be computed analytically, so a Gibbs-in-Metropolis MCMC approach is used and described in \cref{alg:MCMCalg}. 


\begin{algorithm}
\caption{MCMC Gibbs-in-Metropolis sampling of posterior distribution.}\label{alg:MCMCalg}
\begin{algorithmic}[1]
\Procedure{PosteriorSampMCMC}{$X,\sigma,\alpha_\lambda,\beta_\lambda, \mu_\mathrm{max}$}
\State \textbf{init} $\lambda_0\sim\operatorname{Gamma}(\alpha_\lambda,\beta_\lambda)$, $\mu_0\sim \operatorname{unif}(0,\mu_\mathrm{max})$
\For{$s=1\ldots,S$}
\LComment{MH step for $\mu$ first}
\State $\mu_* \gets \mu + \sigma \cdot \texttt{randn}$
\While{$\mu_*<0$ \text { or } $\mu_*>\mu_\text{max}$}
 $\mu_* \gets \mu + \sigma \cdot \texttt{randn}$ \Comment{only accept proposals for $\mu$ in range of prior}
\EndWhile
\State $\pi_* \gets \ell( \lambda_{s-1},\mu_*,X)$, $\pi_{s-1} \gets \ell(\lambda_{s-1},\mu_{s-1}, X)$   \Comment{proposal \& current log-likelihood}

\State $p \gets \min\{\exp(\pi_*-\pi_{s-1}),1\}$
\If{$\texttt{rand}<p$} 
$\mu_s \gets \mu_*$ \Comment{accept proposal}
\Else \, 
$\mu_s \gets \mu_{s-1}$   \Comment{keep current}
\EndIf
\LComment{Gibbs sample $\lambda$ using Gamma conjugacy}
\State  $\alpha,\beta$ $\gets$ using prior $\alpha_\lambda,\beta_\lambda$, data $X$, and $\mu_s$ in \eqref{eq:gamma_conj_update}  \Comment{Gibbs step uses current value of $\mu$}
\State $\lambda_s \sim \operatorname{Gamma}(\alpha,\beta)$ 
\EndFor
\State \textbf{return} $\lambda_0,\ldots,\lambda_S,\quad \mu_0,\ldots,\mu_S$
\EndProcedure
\end{algorithmic}
\end{algorithm}

\begin{figure}[htb]
    \centering
    \includegraphics[width=0.6\textwidth]{images/rhat.ai}
    \caption{Rubin-Gelman $\hat{R}$-1 demonstrating convergence of MCMC (on the setup in Fig \ref{fig:inferencefig} with $M=10$) for two chains. Convergence is considered good when $\hat{R}-1<10^{-1}$,  achieved in approximately $10^3$ MCMC steps. }
    \label{fig:rhat}
\end{figure}


As is standard practice \cite{gelman1995bayesian}, we do sequence of warm-up phases to target the range of acceptance probabilities between $0.3$ and $0.5$, starting with $\sigma=1$ and rounds of 500 steps. After each warm-up round, if the acceptance frequency is below the target range, $\sigma \to \sigma/2$, and if above $\sigma \to 2\sigma$. Once in the range, the ending values of $\lambda,\mu$ are used as initial values and the full algorithm is run with this step size $\sigma$ for much greater number of steps. The values from the chains for this burn-in phase are discarded.  

To choose the number of MCMC steps, we investigate the Gelman-Rubin diagnostic $\hat{R}$ \cite{gelman1995bayesian} for the presumed worst-case scenario of $M=10$ snapshots in the setup of \cref{fig:inferencefig}. For $M=10$, we initialize multiple chains and compute $\hat{R}$ as a function of the number of MCMC steps, shown in \cref{fig:rhat}. Convergence is considered satisfactory for $\hat{R}<1.1$ \cite{gelman1995bayesian}, which is achieved around $10^3$ MCMC steps. We take $10^5$ MCMC steps for all setups in the main text and do not monitor convergence further.  


