\subsection{Parameters Estimation}
We estimate the parameters of CMGND models using the ECM algorithm proposed by \cite{mgnd2025}, introducing new update equations for the constrained parameters as given in Eqs. (\ref{NRmu}), (\ref{NRsigma}) and (\ref{NRnu}). The updates of the unconstrained model can be found in \cite{mgnd2025,Wen2020,Bazi2006}.

From Eq. \ref{MGND} the log-likelihood function is given by 
\begin{equation}
\log L(\theta)=\sum_{n=1}^N\log{\Biggr[\sum_{k=1}^K\pi_kf_k(x_n|\mu_k, \sigma_k, \nu_k)\Biggr]}.
\label{loglikelihood}
\end{equation}


The \textbf{E-step} involves computing the following equation

\begin{equation}
Q(\theta,\theta^{(m-1)})=\sum_{n=1}^N\log{\Biggr[\sum_{k=1}^Kz_{nk}^{(m-1)}\pi_k^{(m-1)}f_k(x_n|\mu_k^{(m-1)}, \sigma_k^{(m-1)}, \nu_k^{(m-1)})\Biggr]},
\label{E-step}
\end{equation}

where 
\begin{equation*}
z_{nk}^{(m-1)}=\frac{\pi_k^{(m-1)}f_k(x_n|\mu_k^{(m-1)}, \sigma_k^{(m-1)}, \nu_k^{(m-1)})}{\sum_{k=1}^K\pi_k^{(m-1)}f_k(x_n|\mu_k^{(m-1)}, \sigma_k^{(m-1)}, \nu_k^{(m-1)})}.
\end{equation*}
The term $z_{nk}^{(m-1)}$ represents the current estimate of the posterior probability or responsibility \citep{Bishop2006} at the $(m-1)$-th iteration, that is, the probability that the observation $n$ belongs to the group $k$ given the parameters of the current component $\theta^{(m-1)}$.  

The parameter estimation in the $m$-th iteration is obtained by maximising $Q(\theta,\theta^{(m-1)})$ with respect to $\theta$, thus increasing the expectation of the complete likelihood of the data. In what follows,  we provide the updating equations for the parameters of the CMGND models.

\paragraph{Mixture weights} 
Set $\frac{\partial Q(\theta,\theta^{(m-1)})}{\partial\pi_k}=0$, then
\begin{equation}\label{Mweights}
\pi_k^{(m)}=\frac{\sum_{n=1}^Nz_{kn}^{(m-1)}}{\sum_{k=1}^K\sum_{n=1}^Nz_{kn}^{(m-1)}}.
\end{equation}

\paragraph{Location parameter}

To obtain the iteration equation for the constrained location parameter at any partition $r \in 1,2,...R$, where $\mu_k=\mu_r$ for all $k \in C_r$, we impose that the first derivative of the Q-function with respect to $\mu_r$ is set to zero, {\it i.e.}
\begin{equation*}
\begin{split}
\frac{\partial Q(\theta,\theta^{(m-1)})}{\partial \mu_r}&=\sum_{k \in C_r}\Biggr[\frac{\nu_k^{(m-1)}}{\bigr(\sigma_k^{(m-1)}\bigr)^{\nu^{(m-1)}_k}}\Biggr(\sum_{x_n\geq\mu_r^{(m-1)}}^Nz_{kn}^{(m-1)}(x_n-\mu_r^{(m-1)})^{\nu_k^{(m-1)}-1}\\
&-\sum_{x_n<\mu_r^{(m-1)}}^Nz_{kn}^{(m-1)}(\mu_r^{(m-1)}-x_n)^{\nu^{(m-1)}_k-1}\Biggr)\Biggr]=0.
\end{split}
\end{equation*}
Since the above equation is non-linear, the iterative Newton-Raphson method is applied as follows:
\begin{equation}\label{NRmu}
\mu_r^{(m)}=\mu_r^{(m-1)}-\frac{g\bigr(\mu_r^{(m-1)}\bigr)}{g'\bigr(\mu_r^{(m-1)}\bigr)},
\end{equation}
where
\begin{equation*}
\begin{split}
&g\bigr(\mu_r^{(m-1)}\bigr)=\sum_{k \in C_r}\Biggr[\frac{\nu^{(m-1)}_k}{\bigr(\sigma_k^{(m-1)}\bigr)^{\nu^{(m-1)}_k}}\Biggr(\sum_{x_n\geq \mu_r^{(m-1)}}^Nz_{kn}^{(m-1)}(x_n-\mu_r^{(m-1)})^{\nu^{(m-1)}_k-1}\\
&\hspace{2cm}-\sum_{x_n< \mu_r^{(m-1)}}^Nz_{kn}^{(m-1)}(\mu_r^{(m-1)}-x_n)^{\nu^{(m-1)}_k-1}\Biggr)\Biggr],\\
&g'\bigr(\mu_r^{(m-1)}\bigr)=\sum_{k \in C_r}\Biggr[-\frac{\nu^{(m-1)}_k}{\bigr(\sigma_k^{(m-1)}\bigr)^{\nu^{(m-1)}_k}}\Biggr(\sum_{x_n\geq\mu_r^{(m-1)}}^Nz_{kn}^{(m-1)}(x_n-\mu_r^{(m-1)})^{\nu^{(m-1)}_k-2}\\
&\hspace{2cm}\times(\nu^{(m-1)}_k-1)+\sum_{x_n<\mu_r^{(m-1)}}^Nz_{kn}^{(m-1)}(\mu_r^{(m-1)}-x_n)^{\nu^{(m-1)}_k-2}(\nu^{(m-1)}_k-1)\Biggr)\Biggr].\\
\end{split}
\end{equation*}
