\paragraph{Scale parameter}
To obtain the iteration equation for the constrained scale parameter at any partition $r \in 1,2,...R$, where $\sigma_k=\sigma_r$ for all $k \in C_r$, we impose that the first derivative of the Q-function with respect to $\sigma_r$ is set to zero, {\it i.e.}
\begin{equation*}\label{sigmafpartial0}
\begin{split}
\frac{\partial Q(\theta,\theta^{(m-1)})}{\partial \sigma_r}&=\sum_{k \in C_r}\Biggr[\sum_{n=1}^Nz_{kn}^{(m-1)}\biggr(-\frac{1}{\sigma_r^{(m-1)}}\biggr)+\frac{\nu_k^{(m-1)}}{(\sigma_r^{(m-1)})^{\nu_k^{(m-1)}+1}}\sum_{n=1}^Nz_{kn}^{(m-1)}\bigr|x_n-\mu_k^{(m)}\bigr|^{\nu_k^{(m-1)}}\Biggr]=0.
\end{split}
\end{equation*}
The iterative Newton-Raphson method is applied as follows:
\begin{equation}\label{NRsigma}
\sigma_r^{(m)}=\sigma_r^{(m-1)}-\frac{g\bigr(\sigma_r^{(m-1)}\bigr)}{g'\bigr(\sigma_r^{(m-1)}\bigr)} ,
\end{equation}
where
\begin{equation*}
\begin{split}
&g\bigr(\sigma_r^{(m-1)}\bigr)=\sum_{k \in C_r}\Biggr[\sum_{n=1}^Nz_{kn}^{(m-1)}\biggr(-\frac{1}{\sigma_r^{(m-1)}}\biggr)+\frac{\nu^{(m-1)}_k}{\bigr(\sigma_r^{(m-1)}\bigr)^{\nu^{(m-1)}_k+1}}\sum_{n=1}^Nz_{kn}^{(m-1)}\bigr|x_n-\mu_k^{(m)}\bigr|^{\nu_k^{(m-1)}}\Biggr],\\
&g'\bigr(\sigma_r^{(m-1)}\bigr)=\sum_{k \in Cr}\Biggr[\sum_{n=1}^Nz_{kn}^{(m-1)}\frac{1}{\bigr(\sigma_r^{(m-1)}\bigr)^2}+\nu_k^{(m-1)}\bigr(-\nu_k^{(m-1)}-1\bigr)\\
&\hspace{2.5cm}\times\bigr(\sigma_r^{(m-1)}\bigr)^{-\nu_k^{(m-1)}-2}\sum_{n=1}^Nz_{kn}^{(m-1)}\bigr|x_n-\mu_k^{(m)}\bigr|^{\nu_k^{(m-1)}}\Biggr].
\end{split}
\end{equation*}

\paragraph{Shape parameter}
To obtain the iteration equation for the constrained shape parameter at any partition $r \in 1,2,...R$, where $\nu_k=\nu_r$ for all $k \in C_r$, we impose that the first derivative of the Q-function with respect to $\nu_r$ is set to zero, {\it i.e.}
\begin{equation*}
\begin{split}
\frac{\partial Q(\theta,\theta^{(m-1)})}{\partial \nu_r}&=\sum_{k \in C_r}\Biggr[\sum_{n=1}^Nz_{kn}^{(m-1)}\frac{1}{\nu_r^{(m-1)}}\Biggr(\frac{1}{\nu_r^{(m-1)}}\Psi\Biggr(\frac{1}{\nu_r^{(m-1)}}\Biggr)+1\Biggr)\\
&-\sum_{n=1}^Nz_{kn}^{(m-1)}\Biggr|\frac{x_n-\mu_k^{(m)}}{\sigma_k^{(m)}}\Biggr|^{\nu_r^{(m-1)}} \log \Biggr|\frac{x_n-\mu_k^{(m)}}{\sigma_k^{(m)}}\Biggr|\Biggr]=0.
\end{split}
\end{equation*}
Since the above equation is a non-linear equation, the iterative Newton-Raphson method is applied as follows:
\begin{equation}\label{NRnu}
\nu_r^{(m)}=\nu_r^{(m-1)}-\alpha\bigr(\nu_r^{(m-1)}\bigr)\frac{g\bigr(\nu_r^{(m-1)}\bigr)}{g'\bigr(\nu_r^{(m-1)}\bigr)},
\end{equation}
where: 
\begin{equation*}\label{nuf}
\begin{split}
&\alpha\bigr(\nu_r^{(m-1)}\bigr)=e^{-\nu_r^{(m-1)}},\\
&g\bigr(\nu_r^{(m-1)}\bigr)=\sum_{k \in C_r}\Biggr[\sum_{n=1}^Nz_{kn}^{(m-1)}\frac{1}{\nu_r^{(m-1)}}\Biggr(\frac{1}{\nu_r^{(m-1)}}\Psi\Biggr(\frac{1}{\nu_r^{(m-1)}}\Biggr)+1\Biggr)\\
&\hspace{2cm}-\sum_{n=1}^Nz_{kn}^{(m-1)}\Biggr|\frac{x_n-\mu^{(m)}_k}{\sigma^{(m)}_k}\Biggr|^{\nu_r^{(m-1)}} \log \Biggr|\frac{x_n-\mu^{(m)}_k}{\sigma^{(m)}_k}\Biggr|\Biggr],\\
&g'\bigr(\nu_r^{(m-1)}\bigr)=\sum_{k \in C_r}\Biggr[\sum_{n=1}^Nz_{kn}^{(m-1)}-\frac{1}{\bigr(\nu_r^{(m-1)}\bigr)^{2}}\Biggr(1+\frac{2}{\nu_r^{(m-1)}}\Psi\Biggr(\frac{1}{\nu_r^{(m-1)}}\Biggr)\\
&\hspace{2cm}+\frac{1}{\bigr(\nu_r^{(m-1)}\bigr)^{2}}\Psi'\Biggr(\frac{1}{\nu_r^{(m-1)}}\Biggr)\Biggr)-\sum_{n=1}^Nz_{kn}^{(m-1)}\Biggr|\frac{x_n-\mu^{(m)}_k}{\sigma^{(m)}_k}\Biggr|^{\nu_r^{(m-1)}}\Biggr(\log \Biggr|\frac{x_n-\mu^{(m)}_k}{\sigma^{(m)}_k}\Biggr|\Biggr)^2\Biggr].
\end{split}
\end{equation*}
The term $\alpha\bigr(\nu_r^{(m-1)}\bigr)=e^{-\nu_r^{(m-1)}}$ represents the adaptive step size function proposed by \cite{DuttiloR2024}, while a \textit{plain} updating equation can be recovered by setting $\alpha\bigr(\nu_r^{(m-1)}\bigr)=1$. The digamma $\Psi\bigr(1/\nu_r^{(m-1)}\bigr)$ and trigamma $\Psi'\bigr(1/\nu_r^{(m-1)}\bigr)$ functions are defined as follows
\begin{equation*}
\Psi\bigr(1/\nu_r^{(m-1)}\bigr)=\frac{\partial\Gamma\bigr(1/\nu_r^{(m-1)}\bigr)}{\partial\bigr(1/\nu_r^{(m-1)}\bigr)}\log\Gamma\bigr(1/\nu_r^{(m-1)}\bigr),\hspace{0.2cm} \Psi'\bigr(1/\nu_r^{(m-1)}\bigr)=\frac{\partial^2\Gamma\bigr(1/\nu_r^{(m-1)}\bigr)}{\partial\bigr(1/\nu_r^{(m-1)}\bigr)^2}\log\Gamma\bigr(1/\nu_r^{(m-1)}\bigr).
\end{equation*}

\section{Simulation study}\label{SM}
In the simulation, two important aspects are investigated: the performance of the parameter estimation in the presence of constraints and the choice among different constrained models. Two different sample sizes ($N=400, 1000$) and three levels of overlap between the mixture components (low, medium, and high) are considered.  
Data were simulated from the MGND and CMGND models with $K=3$ components and weights $\pi_1=0.4$, $\pi_2=0.3$ and $\pi_3=0.3$. We consider constraints that involve equality between two of the three components for the scale (UCU), the shape (UUC) and both the scale and shape (UCC) parameters.
