    % Define nodes for a right triangle
    \node (A) at (0,0) {$y_{\alpha}$};
    \node (B) at (2.5,2.5) {$M_{\alpha}(0)$};
    \node (C) at (5,0) {$u_0 $};

    % Draw arrows for the mappings
    \draw[->, thick] (A) -- node[left] {Inverting \eqref{eq:ODE_moments}} (B);
    \draw[->, thick] (B) -- node[right] {Solving \eqref{pb:opt_moments}} (C);
    \draw[->] (A) to node[below] {Solving \eqref{pb:OC}} (C);

 \node[left=3mm] at (A) { $M_{\alpha}(T)\, \approx  $};
    \node[right=3mm] at (C) {$\approx \, u_0^{*}$};
\end{tikzpicture}      
  \end{center} 


\subsection{Main results}  Our main contributions to the theoretical analysis of problem \eqref{pb:OC} are summarized as follows:
\begin{enumerate}\setlength{\itemsep}{5pt} 
    \item \textbf{(Existence of atomic solutions)} In Theorem \ref{thm:existence} we first establish the existence of an atomic solution to \eqref{pb:OC}  of the form 
        \begin{equation}\label{intro_eq:extreme_point}
        u^k_0 = \sum_{i=1}^{\binom{k + d}{d}} m_i \delta_{x_i}.
    \end{equation}
by leveraging results from representer theorems. 



The number of masses in the sparse atomic reconstruction is exactly the same as the number of moments under consideration.

This existence result holds for any observed data \( \mathbf{y} = (y_{\alpha})_{\|\alpha\|_1\leq k} \).

    \item \textbf{(Error estimate)} Next, in Theorem \ref{thm:rate}, assuming that \( u_0^* \) is compactly supported within \( \Omega = [-R, R]^d \), we establish an error estimate that quantifies the difference between the recovered solution \( u_0^k \) and the true initial distribution \( u_0^* \). This difference, measured by the Kantorovich distance (see Definition \ref{def:kant}), is given by:
    \begin{equation}\label{intro_eq:conv}
        \| u_0^{k}- u_0^{*}\|_{\textnormal{Kant}} \leq C_1 \left(\frac{  \|u_0^*\|_{\textnormal{TV}}}{k} +  k^{k/2}\,e^{C_2\,k} \, \max\left\{ T^{\lfloor k/2\rfloor} \, , \,1 \right\} \,\|\epsilon\|_{\infty}\right),
    \end{equation}
    where \( C_1 \) and \(C_2\) are constants depending only on $d$ and $R$.  The variable \( \epsilon = (\epsilon_{\alpha})_{\|\alpha\|_1\leq k} \) represents the observation error of the moments of \( u(\cdot, T) \). 



The right-hand side of \eqref{intro_eq:conv} decomposes into two distinct components:

\begin{itemize}
    \item[(a)] The first term, representing the approximation error in our moment reconstruction, is independent of both the terminal time $T$ and observation error $\epsilon$. It decays with the order $1/k$,  as the moment order $k \to \infty$.   

        \item[(b)] The second term reveals a crucial analogy but also an important difference: the maximal moment order $k$ plays a role similar  to the frequency cutoff in Fourier analysis \eqref{eq:fourier}. But, for fixed $k$, this term exhibits only \emph{polynomial growth} in $T$, in stark contrast to the \emph{exponential growth} seen in \eqref{eq:fourier}. This improved stability stems directly from the favorable properties of the moment system \eqref{eq:moments_grow}.
\end{itemize}


\medskip

Based on points (a)-(b), the optimal moment order \( k^* \) is determined by balancing the two competing terms in the reconstruction error estimate. As detailed in Remark~\ref{rem:moment_opt}, if the observation errors satisfy
\[
\delta_1 \leq \|\epsilon\|_{\infty} \leq \delta_2,
\quad \text{for all } k \geq 0,
\]
with \( 0 < \delta_1 \leq \delta_2 < 1/(2e) \), then the unique solution \( k^* \) to the balancing condition satisfies the asymptotic bounds
\begin{equation}
    \frac{c_1\,\ln(1/\delta_2)}{\ln T + \ln\ln(1/\delta_2)}
\;\leq\; k^* \;\leq\;
\frac{c_2\,\ln(1/\delta_1)}{\ln T + \ln\ln(1/\delta_1)},
\end{equation}
where \( c_1 \), \( c_2 \) are constants independent of \( \delta_1, \delta_2 \), and \( T \). This framework captures two relevant regimes:
\begin{itemize}
    \item If the observation becomes more accurate (i.e., \( \delta_2 \to 0 \)) while \( T \) is fixed, then the optimal order \( k^* \to \infty \), and the recovery error tends to zero.
    \item Conversely, if the final time \( T \) increases and the lower bound \( \delta_1 \) also grows with \( T \) (as is common in practice due to error accumulation), then \( k^* \) decreases and the reconstruction error increases.
\end{itemize}




For complete technical details and extended discussion of \eqref{intro_eq:conv}, including precise convergence rates, see the full formulation in \eqref{eq:conv} and the analysis in Remarks~\ref{rem:conv} and \ref{rem:moment_opt}.
\end{enumerate}

\medskip
\textit{Techniques used in the proof.}
The proof of our main results combines techniques from several areas, including the representer theorem, optimal transportation, and polynomial approximation.


We apply the representer theorem from \cite{fisher1975spline} to show that the extreme points of the solution set of \eqref{pb:OC} are sums of Dirac measures. 
Optimization problems over measures, together with their associated representer theorems, play a fundamental role in classical inverse problems; see \cite{unser2017splines} and references therein. The core idea behind representer theorems is that the extreme points of the feasible set, defined by linearly independent test functions, take the form of finite sums of Dirac measures. In practice, when the test functions are monomials, this recovers the classical result known as Tchakaloff’s Theorem \cite{bayer2006tchakaloff}.

Notably, problem \eqref{pb:OC} also bears strong resemblance to mean-field relaxation problems arising in the training of neural networks \cite{chizat2018global,mei2018mean,liu2025representation}. The use of representer theorems in such machine learning settings has recently drawn increasing attention; see, for example, \cite{bach2017breaking,unser2019representer,liu2025representation}.


To quantify the distance between the solution of \eqref{pb:OC} and the true initial distribution \( u_0^* \), we use the Kantorovich distance, as introduced in \cite{hanin1999kantorovich,piccoli2016properties}, which is also referred to as the flat metric in the literature. This metric generalizes the Wasserstein distance \cite[Sec.~6]{villani2009} from probability measures to signed measures. We discuss the connection between the Kantorovich and Wasserstein distances in Section~\ref{sec_wasserstein}. A key feature of the Kantorovich distance is that it is defined via duality with respect to test functions that are \(1\)-Lipschitz continuous, i.e.,
there exists $v^*$, with $\|v^*\|_{\mathcal{C}(\Omega)}\leq 1$ and Lip$(v^*)\leq 1$, such that 
    \begin{equation*}
         \| u_0^{k}- u_0^*\|_{\textnormal{Kant}} = \int_{\Omega} v^*\, d (u_0^{k}- u_0^*).  
    \end{equation*}
The test function \( v^* \) can be approximated by a degree-\( k \) polynomial \( p^k \) with an explicit convergence rate of \( 1/k \), as guaranteed by Jackson's Theorem \cite{newman1964jackson}. This allows us to decompose the integral into the sum of two terms:
\begin{enumerate}
    \item First term: \( \int_{\Omega} (v^* - p^k) \, d(u_0^k - u_0^*) \). Since the integrand is uniformly bounded by \( C/k \), it suffices to estimate the total variation of \( u_0^k - u_0^* \), which is controlled via Lemma~\ref{prop:a priori bound}.

    \item Second term: \( \int_{\Omega} p^k \, d(u_0^k - u_0^*) \). Since \( p^k \) is a polynomial of degree \( k \), its integral against \( u_0^k - u_0^* \) depends on two components: the coefficients of \( p^k \) and the difference between the moments of \( u_0^k \) and \( u_0^* \) up to order \( k \). The moment differences are controlled by the backward stability of the moment system; see \eqref{eq:moments_grow}. The coefficients of \( p^k \) are in turn governed by its \( L^\infty \)-norm in $\Omega$, via Bernstein's inequality; see Lemma~\ref{lem:poly_coef}.
\end{enumerate}




\subsection{Numerical implementation}
According to the error estimate \eqref{intro_eq:conv}, the success of our moment method relies on two main factors: (1) the robust observation of moments, and (2) the accurate resolution of the moment problem \eqref{pb:OC}. However, each factor poses its own numerical challenge:
\begin{enumerate}
  \item The moment \( M_{\alpha}(T) \) is not directly accessible through observations. In practice, we can only measure the values of \( u(x,T) \) at a finite set of sensor locations.
  \item Although \eqref{pb:OC} is a convex optimization problem, it is posed in the infinite-dimensional Banach space \(\mathcal{M}(\Omega)\), making the direct application of standard optimization algorithms infeasible.
\end{enumerate}
We address these two challenges in the following paragraphs.


\medskip
  \textit{Observation of moments.} 
For the numerical computation of \( M_{\alpha}(T) \), we adopt quadrature methods. In practice, the values of \( u(\cdot,T) \) are observed through sensors. The position of these sensors can be interpreted as quadrature points for estimating the moments.

We then approximate \( M_{\alpha}(T) \) by a weighted sum of these observed values, that is,
\[
M_{\alpha}(T) \approx y_{\alpha} = \sum_{j=1}^n w_j z_j^{\alpha} u(z_j,T),
\]
where \( n \) is the number of sensors, and \( (z_j,w_j) \) denote the sensor positions and corresponding weights. In Section \ref{sec:quadrature}, we discuss two quadrature methods particularly suited to the approximation of heat moments: (1) uniform quadrature and (2) Gauss--Hermite quadrature. In the uniform case, the sensor positions are independent of \( T \), whereas in the Gauss--Hermite case, they grow proportionally to \( \sqrt{T} \). 

For a fixed number of sensors, the Gauss--Hermite method achieves better quadrature performance. This superiority becomes more pronounced as \( T \) increases, as illustrated in Figure~\ref{fig:quadrature}.



\medskip
  \textit{First Discretize, then Optimize.} To solve \eqref{pb:OC} numerically, we adopt a discretize--then--optimize strategy. Specifically, we discretize the domain $\Omega$ by selecting $N$ points:
\[
\Omega \xrightarrow{\text{discretize}} \Omega_h = \{x_1,\ldots, x_N\}.
\]
Then, in \eqref{pb:OC} we replace $\mathcal{M}(\Omega)$ with $\mathcal{M}(\Omega_h)$, which yields a convex optimization problem in $\mathbb{R}^N$:
\begin{equation}\label{intro_pb:OC_dis}\tag{P$^{\text{dis}}_{\Omega,k}$}
    \inf_{\mathbf{m}\in \mathbb{R}^N} \|\mathbf{m}\|_{\ell^1} 
    \quad
    \text{subject to}
    \quad
    B\, \mathbf{m} \;=\; e^{-T A}\, \mathbf{y},
\end{equation}
where $B$ is a (rectangular) Vandermonde matrix with entries
\begin{equation*}
    b_{\alpha,i} =x_i^{\alpha}, \quad \text{for }\|\alpha\|_1\leq k, \quad i=1,\ldots, N.
\end{equation*}

Under mild assumptions on the mesh $\Omega_h$,  in Lemma \ref{lem:exist} we prove
 the existence of solutions of \eqref{intro_pb:OC_dis}.  We can then apply the \textit{Simplex method} \cite[Sec.~3]{bertsimas1997introduction} to solve \eqref{intro_pb:OC_dis}, which returns a solution of the form \eqref{intro_eq:extreme_point} in a finite number of iterations, see Proposition \ref{prop:simplex}. 

 Numerical experiments in Section~\ref{sec_num} demonstrate that the solutions of \eqref{intro_pb:OC_dis}, obtained using our numerical schemes, converge rapidly to the initial source as \( k \) increases. Moreover, the moment method exhibits strong numerical stability even for moderately large values of \( T \), such as \( T \in [1, 100] \), significantly outperforming classical algorithms in this regard, as we discuss in more detail below.  

Finally, we mention the limitations of moment methods in high-dimensional settings: (1) fixing the maximal moment--order $k$, the theoretical error grows exponentially with the dimension \(d\), as shown in~\eqref{eq:conv}, and (2) the discretization of \(\Omega\) suffers from the curse of dimensionality.




\subsection{Related work}
\textit{Tikhonov regularization methods}.
As previously mentioned, Tikhonov regularization is a classical approach to mitigate the ill-posedness of the initial source identification problem. In \cite{biccari2023two}, the authors introduce a combined penalty involving the \( L^1 \) and \( L^2 \) norms of \( u_0 \) in the formulation of \eqref{pb:OC_pde}. However, this penalization prevents the solution from being a sum of Dirac measures as in \eqref{eq:Dirac}. To address this limitation, they propose a two-stage method: first, solve the penalized optimization problem; then, detect the local maxima of the solution; and finally, determine the amplitudes of these maxima by solving a finite-dimensional convex problem. Although numerically efficient for small terminal times (e.g., \( T = 0.01 \) in \cite{biccari2023two}), this approach lacks reliable theoretical guarantees of convergence and is instable for large $T$.

In contrast, \cite{casas2019using} replaces the \( L^p \) penalty with a TV norm penalty \( \|u_0\|_{\text{TV}} \) for \eqref{pb:OC_pde}. The authors analyze the structure of the solution using first-order optimality conditions \cite[Thm.~3.1 and Thm.~4.4]{casas2019using}. When the minimizers of the adjoint solution are finite, this method recovers a sum of Dirac measures as in \eqref{eq:Dirac}. In our work, such sparsity arises naturally through the representer theorem and the finite observations of moments. The regularization formulations in \cite{casas2019using} are highly sensitive to the choice of penalty coefficients, and no efficient numerical algorithms are designed to solve these problems.

A further limitation of these Tikhonov-based methods on \eqref{pb:OC_pde} is their reliance on full knowledge of the terminal solution \( u(\cdot, T) \), which is unrealistic in practical scenarios where only discrete observations of \( u(x,T) \) at sensor locations are available. Our method addresses this by computing moments through quadrature of these pointwise values. The issue of limited observations is also noted in \cite{li2014heat}, where the authors adapt the formulation of \eqref{pb:OC_pde} using value residuals at sensor locations and impose an $L^1$ penalty. They prove convergence with respect to observation error (see \cite[Thm.~2.2]{li2014heat}), but the result holds only in one spatial dimension, assumes the true initial distribution \( u_0^* \) is a single Dirac measure, and does not explicitly characterize the dependence of the convergence rate on the terminal time \( T \). Our main result, Theorem~\ref{thm:rate}, improves on these limitations by providing an explicit error bound that scales polynomially with \( T \). In contrast to the fixed small terminal times used in \cite{biccari2023two} and \cite{li2014heat} (both with \( T = 0.01 \)), our method remains stable for terminal times up to \( T = 100 \) in two dimensions, offering robust performance across a much broader range of scenarios.

\medskip
\textit{Algorithms for the discretized problem.}
The optimization problem \eqref{intro_pb:OC_dis} is convex, and a variety of algorithms can be used to solve it. These include Bregman iteration \cite{osher2005iterative} and its variants \cite{goldstein2009split}, the Alternating Direction Method of Multipliers (ADMM) \cite{glowinski1975approximation}, and primal-dual methods \cite{chambolle2011first}. Following \cite{chen2001atomic}, we rewrite \eqref{intro_pb:OC_dis} as a linear programming problem.
Consequently, a natural and robust approach is to solve the discretized problem \eqref{intro_pb:OC_dis} using the simplex method. Importantly, the simplex method yields solutions located at extreme points of the feasible set (see \cite[Thm.~3.3]{bertsimas1997introduction}), which leads to sparse solutions with fewer support points in the recovered initial distribution.



\subsection{Organization and notations}
In Section~\ref{sec_main}, we establish the existence of solutions to the optimization problem \eqref{pb:OC} and analyze their convergence to the true initial condition 
\( u_0^* \) 
  under appropriate assumptions. Building on these theoretical foundations, Section~\ref{sec_dis} develops numerical methods for both moment observation and efficient solution of \eqref{pb:OC}. The effectiveness of our moment-based approach for initial source identification is then demonstrated through numerical experiments in Section~\ref{sec_num}. Finally, Section~\ref{sec_proof} collects the technical lemmas required for proving our main results.

\medskip
\textit{Notations}.
We begin by fixing notation:
\begin{itemize}
    \item For $x \in \mathbb{R}^n$, $\|x\|_p$ denotes the standard $\ell^p$-norm
    \item $\lfloor a \rfloor$ represents the floor function for $a \in \mathbb{R}$
    \item $\binom{n}{m}$ is the binomial coefficient for $n,m \in \mathbb{N}$
\end{itemize}

Let $\Omega \subset \mathbb{R}^d$ be compact. We consider:
\begin{itemize}
    \item $\mathcal{C}(\Omega)$: The Banach space of continuous functions on $\Omega$ equipped with the supremum norm $\|\cdot\|_{\mathcal{C}(\Omega)}$
    \item $\mathcal{M}(\Omega)$: Its dual space, identified with Radon measures on $\Omega$ having finite total variation.\end{itemize}

\begin{defn}[Kantorovich Norm \cite{hanin1999kantorovich,piccoli2016properties}]\label{def:kant}
    For $u_0 \in \mathcal{M}(\Omega)$, the Kantorovich norm is
    \begin{equation}\label{eq:kant_norm}
        \|u_0\|_{\mathrm{Kant}} \coloneqq \max_{\substack{v \in \mathcal{C}(\Omega) \\ \|v\|_{\mathcal{C}(\Omega)} \leq 1 \\ \mathrm{Lip}(v) \leq 1}} \, \int_{\Omega} v \, du_0 ,
    \end{equation}
    where $\mathrm{Lip}(v)$ denotes the Lipschitz constant of $v$. The maximum is indeed attained \cite[Eq.\,(4.2)]{hanin1999kantorovich}.
\end{defn}
In this article, we use the Kantorovich norm to quantify the difference between measures. This choice is motivated by the fact that the recovered initial distribution and the true one may have different total masses, in which case the classical Wasserstein distance is not well-defined. When the total mass is preserved, these two norms are equivalent, leading to  an error estimate in the Wasserstein distance, as detailed in Section~\ref{sec_wasserstein}.




\section{Main results}\label{sec_main}
The main results of this article are presented in Section~\ref{sec_theorems}. In Section~\ref{sec_moments}, we analyze the dynamics of moments for solutions to the heat equation; these results serve as preliminary tools for the proof of the main error estimates in Section~\ref{sec_proof_main}. Finally, in Section~\ref{sec_wasserstein}, we discuss the error estimates in the Wasserstein sense.

\subsection{Main results}\label{sec_theorems}
We first show the existence of the solutions of problem \eqref{pb:OC}. 

\begin{thm}[Existence]\label{thm:existence}
Assume that \( \Omega \) is compact and has a non-empty interior. Then, for any \( k \in \mathbb{Z}_+ \), any $T>0$  and any vector \( \mathbf{y} = (y_{\alpha})_{\|\alpha\|_1 \leq k} \in \mathbb{R}^{\binom{k + d}{d}} \), the following statements hold:
\begin{enumerate}
    \item The solution set of \eqref{pb:OC} is non-empty, convex, and compact in the weak-\(*\) topology;
    \item The extreme points of the solution set of \eqref{pb:OC} are of the form:
    \begin{equation}\label{eq:extreme_point}
        u^k_0 = \sum_{i=1}^{\binom{k + d}{d}} m_i \delta_{x_i},
    \end{equation}
    where \( m_i \in \mathbb{R} \), \( x_i \in \Omega \), and \( \delta_{x_i} \) are Dirac measures.
\end{enumerate}
\end{thm}
\begin{proof}
Since \(\Omega\) has nonempty interior, the monomials \(\{x^{\alpha}\}_{\|\alpha\|_1\leq 1}\) are linearly independent in \(\mathcal{C}(\Omega)\). Therefore, the conclusions of Theorem \ref{thm:existence} follow from the Representer Theorem  in \cite{fisher1975spline} (see also Theorem \ref{thm:representation}).
\end{proof}



Next, we bound the error between the solution of \eqref{pb:OC} and the true initial distribution \(u_0^*\) in terms of the moment order \(k\) and the measurement error.  To quantify this discrepancy, we use the Kantorovich norm (see Definition~\ref{def:kant}).




\begin{thm}[Error estimate]\label{thm:rate}
Assume $u_0^*$ is a compactly supported Radon measure in $\R^d$ with a finite total variation and that \((u, u_0^*)\) satisfies the heat equation \eqref{eq:heat}.
Let $R>0$ be such that 
\[\operatorname{supp}(u_0^*) \subseteq [-R,R]^d =\colon \Omega.
\]
Fix any \( k \in \mathbb{Z}_+^* \) and let
\[
\mathbf{y} = (y_{\alpha})_{\|\alpha\|_1 \leq k} \in \mathbb{R}^d
\]
denote the vector of observed moments of $u(\cdot,T)$. The observation error is given by
\[
\epsilon = (\epsilon_{\alpha})_{\|\alpha\|_1 \leq k}, \quad \text{with} \quad \epsilon_{\alpha} = y_{\alpha} - \int_{\mathbb{R}^d} x^{\alpha}\, u(x,T) \, dx.
\]
Let \( u_0^k \) be any solution of \eqref{pb:OC}. Then, we have
\begin{equation}\label{eq:conv}
\|u_0^k - u_0^*\|_{\textnormal{Kant}} \leq \frac{C_d\, R\, \|u_0^*\|_{\textnormal{TV}}}{k} + C_{d,R} (k)\; \max\{ T^{\lfloor k/2\rfloor},1\} \,\|\epsilon\|_{\infty},
\end{equation}
where \(C_d\) is a constant, depending only on \(d\), and
\begin{equation}\label{grosseconstante}
C_{d,R} (k) =  \left( \sqrt{\frac{k}{\pi}} + \frac{C_d \, R}{ \sqrt{\pi\, k}}\right) \,  \, \exp\Bigg( k\left(1+ 2d/R +  \ln \sqrt{k} \right)\Bigg) .
\end{equation}
\end{thm}


\begin{proof}
    The proof is presented in Section \ref{sec_proof_main}.
\end{proof}



\begin{rem}[Error estimate analysis]\label{rem:conv}
 The right-hand side of the estimate \eqref{eq:conv} consists of two terms:
\begin{equation*}
    \frac{C_d\, R\, \|u_0^*\|_{\textnormal{TV}}}{k}   \quad \text{and} \quad   C_{d,R} (k)\; \max\{ T^{\lfloor k/2\rfloor},1\} \,\|\epsilon\|_{\infty}.
\end{equation*} 
Let us analyze each term:
\begin{enumerate}
    \item The first term is independent of the terminal time \( T \) and the observation error \( \epsilon \). It decays to zero at a rate of \( 1/k \). Therefore, we represent it as
    \begin{equation*}
        \frac{C_0}{k},
    \end{equation*}
    where \( C_0 \) is a constant independent of \( k \), \( T \), and \( \epsilon \).

For the second term, recalling the definition of \( C_{d,R}(k) \) from \eqref{grosseconstante}, we obtain the following leading-order expression:
    \begin{equation*}
        C_1\,(T\,k)^{k/2} e^{C_2 k} \|\epsilon\|_{\infty},
    \end{equation*}
    where \( C_1 \) and \( C_2 \) are constants independent of \( k \), \( T \), and \( \epsilon \). 
\begin{itemize}
    \item Fixing \( k \), we observe that the prefactor of \( \|\epsilon\|_{\infty} \) grows polynomially with \( T \), which marks a significant improvement over the classical ill-posedness in time illustrated in \eqref{eq:fourier}, where the error increases exponentially with time. 
    \item The moment order \( k \) plays a role analogous to the frequency amplitude in the Fourier analysis of the inverse problem for \eqref{eq:heat}. For large \( k \), achieving a small reconstruction error at final time requires increasingly accurate moment observations\ -\ that is, a smaller observation error \( \epsilon \). This reflects the inherent ill-posedness of the backward heat equation in the high-frequency regime.
\end{itemize}
\end{enumerate}
\end{rem}



\begin{rem}[Optimal choice of the moment order $k$]\label{rem:moment_opt}
Let the final time be~$T>2$, and assume that the observation errors for all moments (until infinity) satisfy
\begin{equation}\label{eq:constraint}
   \delta_1 \;\le\; \max_{\alpha\in\mathbb{Z}_+^d}|\epsilon_\alpha|
   \;\le\;\delta_2,
   \quad \text{for some } 0<\delta_1\le\delta_2<1/(2e).
\end{equation}
As noted in Remark~\ref{rem:conv}, the first term in the convergence estimate \eqref{eq:conv} decays in~$k$, whereas the second grows.  Hence the optimal moment order~$k^*$ is determined by balancing
\[
   \frac{C_0}{k}
   \;=\;
   C_1\,(T\,k)^{k/2}\,e^{C_2k}\,\|\epsilon\|_{\infty},
\]
a transcendental equation in~$k$.  Under the constraint \eqref{eq:constraint}, its unique solution satisfies the following bounds:
\begin{equation}\label{eq:optimal_k}
   \frac{c_1\,\ln(1/\delta_2)}%
        {\ln T \;+\;\ln\ln(1/\delta_2)}
   \;\le\; k^*
   \;\le\;
   \frac{c_2\,\ln(1/\delta_1)}%
        {\ln T \;+\;\ln\ln(1/\delta_1)},
\end{equation}
where $c_1,c_2>0$ are constants independent of~$\delta_i$ and~$T$.  Substituting this $k^*$ back into \eqref{eq:conv} yields
\begin{equation}\label{eq:optimal_value}
   \bigl\|u_0^{k^*}-u_0^*\bigr\|_{\mathrm{Kant}}
   \;\le\;
   \frac{c_3\bigl(\ln T + \ln\ln(1/\delta_2)\bigr)}%
        {\ln(1/\delta_2)},
\end{equation}
for some constant $c_3$ also independent of~$\delta_i$ and~$T$.  From these estimates, we observe:
\begin{itemize}
  \item For fixed $T$, as the maximal error bound $\delta_2\to0$, the optimal order $k^*\to\infty$ and the reconstruction error vanishes.
  \item If $T$ increases so that the minimal error bound $\delta_1$ typically grows, then $k^*$ decreases and the reconstruction error increases, in agreement with the numerical results in Figure~\ref{fig:recover-1d} (A).
\end{itemize}
\end{rem}



\subsection{The dynamic system of moments}\label{sec_moments}
This subsection is dedicated to a rigorous description of the ODE satisfied by the moments of the solution to the heat equation. This ODE plays an essential role in the proof of Theorem~\ref{thm:rate}.

Throughout this subsection, we fix $\Omega$ as a compact subset of $\mathbb{R}^d$. For any initial data \( u_0 \in \mathcal{M}(\Omega) \), the associated solution $u$ of the heat equation is given explicitly by:
\begin{equation}
    \label{eq:heat_u_0}
    u(x,t) = \bigl(G(\cdot,t) * u_0\bigr)(x), 
\quad \text{for } (x,t) \in \mathbb{R}^d \times \mathbb{R}_+,
\end{equation}
where \(G(x,t)\) denotes the heat kernel:
\begin{equation}\label{eq:kernel}
    G(x,t) 
    = \frac{1}{(4\pi t)^{d/2}} 
      \exp \Bigl(-\tfrac{\|x\|^2}{4t}\Bigr),
    \quad (x,t) \in \mathbb{R}^d \times \mathbb{R}_+.
\end{equation}
For any $\alpha\in \mathbb{Z}_+^d $ and $t\geq 0$, define
    \begin{equation*}
        M_{\alpha}(t) \coloneqq \begin{cases}
            \int_{\R^d}   x^{\alpha} \, u(x,t) \, dx ,\quad  &\textnormal{if } t>0, \\[0.6em]
            \int_{\R^d}   x^{\alpha} \, du_0(x),\quad  &\textnormal{if } t=0.
        \end{cases} 
    \end{equation*}
The following holds:

\begin{lem}[The ODE system of moments]\label{lem:ODE}
     Fix any \( k \in \mathbb{Z}_+ \) and let \( M(t)  = ( M_\alpha(t) )_{\|\alpha\|_1 \leq k} \),  $t\geq 0$. Then, we have
   \begin{equation}\label{eq:ODE}
    \begin{cases}
        \frac{d M(t)}{d t}  &=  A \, M(t), \quad \textnormal{for }t>0, \\[0.6em]
        M(0) &= \lim_{t\to 0^+} M(t),
    \end{cases} 
    \end{equation}
  with $A$ as in \eqref{eq:ODE_moments}.

\end{lem}

\begin{proof} We proceed in several steps.

\textbf{Step 1}   For any \( t > 0 \), by the heat equation, we have
\[
\frac{d M_{\alpha}(t)}{dt} = \int_{\mathbb{R}^d} x^{\alpha} \partial_t u (x,t) \,dx = \int_{\mathbb{R}^d} x^{\alpha} \Delta u (x,t) \,dx.
\]
Since \( u(\cdot, t) \in \mathcal{S}(\mathbb{R}^d) \), applying integration by parts twice, we obtain
\[
\int_{\mathbb{R}^d} x^{\alpha} \Delta u (x,t) \,dx = \sum_{i=1}^d \alpha_i (\alpha_i-1) \int_{\mathbb{R}^d} x^{\alpha - 2 e_i} u(x,t) \,dx,
\]
where \( x^{\alpha - 2e_i} \) is set to be zero if \( \alpha_i \leq 1 \) for any \( i \). Therefore, equation \eqref{eq:ODE} holds for \( t > 0 \).

\medskip
\noindent\textbf{Step 2} (The limit $t\to 0^+$). 
 For any $t>0$, we have
\begin{equation*}
   M_{\alpha}(t) = \int_{\mathbb{R}^d} z^{\alpha}\, u(z,t)\, dz
    \;=\;
    \int_{\mathbb{R}^d} z^{\alpha}\, (G(\cdot,t) * u_0)(z) \,d z  \;=\;
    \int_{\mathbb{R}^d} \int_{\Omega} z^{\alpha}\, G(x-z,t) \,du_0(x)\,dz .
\end{equation*}
Note that there exists a constant $C_{\alpha}>0$ such that
    \begin{equation}\label{eq:claim}
         \int_{\R^d} |z|^{\alpha} G(x-z, t) \, d z  \leq  C_{\alpha} (|x|^{\alpha} +t^{\|\alpha\|_1/2}), \quad \text{for }(x,t)\in \R^d\times (0, +\infty).
    \end{equation}
Indeed, using \eqref{eq:claim} and Fubini's theorem, we can interchange the order of integration in \( M_{\alpha}(t) \), yielding
\[
M_{\alpha}(t) = \int_{\Omega} \int_{\mathbb{R}^d} z^{\alpha} G(x-z, t) \,dz\,du_0(x).
\]
The inner integral can be computed explicitly:
\[
\int_{\mathbb{R}^d} z^\alpha\,G(x-z,t)\,dz =
\sum_{\substack{\beta\le\alpha \\ \beta_i\,\text{even for all } i}} \binom{\alpha}{\beta}\,x^{\alpha-\beta}\,(-1)^{\|\beta\|_1} (2t)^{\|\beta\|_1/2} \prod_{i=1}^d (\beta_i-1)!!.
\]
Taking the limit as \(t\to 0^+\), we obtain
\[
\lim_{t\to 0^+} \int_{\mathbb{R}^d} z^{\alpha} G(x-z, t) \,dz = x^{\alpha}, \quad \text{for all } x \in \mathbb{R}^d.
\]
By inequality \eqref{eq:claim}, the absolute value of the integrand is uniformly integrable with respect to \( u_0 \) for $t\ge 0$ bounded, since \( u_0 \) has compact support. Therefore, by Lebesgue's Dominated Convergence Theorem, we conclude that
\[ 
\lim_{t\to 0^+} M_{\alpha}(t) = M_{\alpha}(0).
\]

\medskip
\noindent\textbf{Step 3} (Proof of \eqref{eq:claim}). Let us rewrite the convolution in \eqref{eq:claim} as
\[
\int_{\mathbb{R}^d} |z|^{\alpha} G(x - z, t) \, dz = \int_{\mathbb{R}^d} |x - z|^{\alpha} G(z, t) \, dz.
\]
   Decompose the right-hand-side by the following inequality:
    \begin{equation*}
        |x-z|^{\alpha} \leq 2^{\|\alpha\|_1} (|x|^{\alpha} + |z|^{\alpha}).
    \end{equation*}
   Since the total mass of \( G(\cdot, t) \) is 1, it remains to estimate the second integral involving \( |z|^{\alpha} \). By a direct computation, splitting the integral along each coordinate direction, we obtain
    \begin{equation*}
        \int_{\R^d} |z|^{\alpha} G(z,t)\, dz = \prod_{i=1}^d \frac{1}{\sqrt{4\pi t}} \int_{\R} |z_i|^{\alpha_i} \, \exp \left(-\frac{z_i^2}{4t}\right)\, dz_i  = \prod_{i=1}^d \frac{(4t)^{\frac{\alpha_i}{2}}}{\sqrt{\pi}} \Gamma \left(\frac{\alpha_i+1}{2}\right),
    \end{equation*}
    where $\Gamma$ is the Gamma function. This yields the term involving $t^{\|\alpha\|_1/2}$ in \eqref{eq:claim}. 
\end{proof}



\begin{lem}[Growth rate]\label{lem:growth}
    The matrix \(A\) defined by \eqref{eq:ODE_moments} is \( (\lfloor k/2 \rfloor +1) \)-nilpotent, i.e.,
    \begin{equation}\label{eq:A0}
        A^{\lfloor k/2 \rfloor +1} = 0.
    \end{equation}
    As a consequence, the solution $M(\cdot)$ of \eqref{eq:ODE} satisfies the following:
\begin{equation}\label{eq:grownwall}
    \| M(0) \|_{\infty} \leq  
       \| M(t) \|_{\infty} \, \sum_{j=0}^{\lfloor k/2 \rfloor} \frac{k^j(k-1)^j}{j\, ! } t^j, \quad \text{for any } t\geq 0.
\end{equation}
\end{lem}

\begin{proof}
Let $\mathcal{P}_k(\mathbb{R}^d)$ be
the space of polynomials in \(d\) variables of total degree at most \(k\). For any monomial \(x^\alpha\) with \(\alpha=(\alpha_1,\dots,\alpha_d)\), we have 
\[
\Delta x^\alpha = \sum_{i\in I_{\alpha}} \alpha_i(\alpha_i-1)x^{\alpha-2e_i}, \quad \text{where }I_{\alpha} = \left\{i\in\{1,\ldots, d\} \,\mid\, \alpha_i\geq 2 \right\}.
\]
Thus, if we define a linear operator
\[
L : \mathcal{P}_k(\mathbb{R}^d) \to \mathcal{P}_k(\mathbb{R}^d), \quad L\, p = \Delta\, p,
\]
its matrix representation in the basis \(\{x^\alpha\}_{\|\alpha\|_1\le k}\) is exactly
\[
A_{\alpha,\alpha'} =
\begin{cases}
\alpha_i(\alpha_i-1), & \text{if } \alpha'=\alpha-2e_i,\\[0.6em]
0, & \text{otherwise.}
\end{cases}
\]
Note that applying \(\Delta\) reduces the total degree of a polynomial by 2. 
Thus, after applying the Laplacian \(\lfloor k/2 \rfloor +1 \) times, we obtain
\[
\Delta^{\lfloor k/2 \rfloor +1} \, p  = 0, \quad \text{for any } p\in \mathcal{P}_k(\mathbb{R}^d).
\]
Since \(A\) is the matrix representation of \(\Delta\), \eqref{eq:A0} follows

\medskip
Next,  from \eqref{eq:ODE} we deduce that
\[
M(0) = e^{-tA}\, M(t),\quad \text{for any } t\ge 0.
\]
Hence,
\[
\|M(0)\|_{\infty} \le \|M(t)\|_{\infty}\, \|e^{-tA}\|_{\infty}.
\]
Since \(A\) is \(\bigl(\lfloor k/2 \rfloor + 1\bigr)\)-nilpotent, we have
\[
e^{-tA} = \sum_{j=0}^{\lfloor k/2 \rfloor} \frac{(-A)^j}{j!}\, t^j,\quad \text{for any } t\ge 0.
\]
Moreover, by definition,
\[
\|-A\|_{\infty} = \max_{\|\alpha\|_1\le k} \sum_{\alpha'} |A_{\alpha,\alpha'}| = \max_{\|\alpha\|_1\le k} \sum_{i=1}^d \bigl(\alpha_i(\alpha_i-1)\bigr)_+ = k(k-1).
\]
Combining these estimates, we obtain the desired inequality \eqref{eq:grownwall}.
\end{proof}

\begin{lem}[A priori bound]\label{prop:a priori bound}
  Let $ \Omega = [-R,R]^d$ for some $R>0$.
   For any \( k \in \mathbb{Z}_+ \) and any vector \( \mathbf{y}= (y_{\alpha})_{\|\alpha\|_1 \leq k} \), let $u_0^k$ be a solution of \eqref{pb:OC}. Then, we have
    \begin{equation*}
    \|u_0^k\|_{\textnormal{TV}} \leq \| \mathbf{y} \|_{\infty}  \,    \sqrt{\frac{k}{\pi}} \, \exp\Bigg( k\left(1+ 2d/R +  \ln \sqrt{k} \right)\Bigg) 
\max \left\{ T^{\lfloor k/2 \rfloor}, \, 1 \right\}.
\end{equation*}
\end{lem}

\begin{proof}
   Let \(u^k_0\) be a solution of \eqref{pb:OC}, and let \(u\) be its corresponding heat flow. By Lemma \ref{lem:ODE}, the moments of \(u\) satisfy the ODE system \eqref{eq:ODE}, and their growth rates are controlled by \eqref{eq:grownwall}. Since the moments at time \(T\) are given by \(\{y_\alpha\}_{\|\alpha\|_1\leq k}\), it follows from \eqref{eq:grownwall} that
\[
\left|\int_{\mathbb{R}^d} x^\alpha \, d u^k_0(x)\right|
\;\le\;
\|\mathbf{y}\|_{\infty} \sum_{j=0}^{\lfloor k/2 \rfloor} \frac{k^j(k-1)^j}{j\, ! } T^j, \quad \text{for any }  \|\alpha\|_1 \le k.
\]
By Lemma \ref{lem:Stirling}, we have
\begin{equation*}
   \sum_{j=0}^{\lfloor k/2 \rfloor} \frac{k^j(k-1)^j}{j\, ! } T^j \leq   \sqrt{\frac{k}{\pi}} \, \exp\left( k + \frac{k}{2} \ln k \right)
\max \left\{ T^{\lfloor k/2 \rfloor}, \, 1 \right\}.
\end{equation*}
Finally, the conclusion follows from Lemma \ref{lem:moment_exist} and \eqref{eq:total_variation}, given that \(u^k_0\) solves \eqref{pb:OC}.
\end{proof}

    \begin{rem}
    The argument combines two key ingredients:
\begin{enumerate}
    \item  \emph{Backward moment propagation}: We first employ the quantitative estimates for the evolution of moments backward in time.
    \item \emph{Optimality condition exploitation}: Crucially, we use that $u_0^k$ satisfies the variational condition \eqref{pb:OC}.
\end{enumerate}
The interplay between (i) the analytic moment estimates and (ii) the variational structure of the optimization problem yields the desired error bounds.     \end{rem}




\subsection{Proof of Theorem \ref{thm:rate}}\label{sec_proof_main}
By the definition of the Kantorovich norm, there exists $v^*$, with $\|v^*\|_{\mathcal{C}(\Omega)}\leq 1$ and Lip$(v^*)\leq 1$, such that 
    \begin{equation}\label{eq:diff}
         \| u_0^{k}- u_0^*\|_{\textnormal{Kant}} = \int_{\Omega} v^*\, d (u_0^{k}- u_0^*).  
    \end{equation}
We now estimate the right hand side expression in several steps.

\medskip
\noindent\textbf{Step 1} (Decomposition of the r.h.s. of \eqref{eq:diff}). By Corollary \ref{cor:approx_poly}, there exists a polynomial $p_k$  of degree $k$ such that
    \begin{equation}\label{eq:p_k}
        \|v^* - p_k\|_{\mathcal{C}(\Omega)} \leq \frac{C_d \, R}{2 k},
 \end{equation}
where \( C_d \) is a constant depending only on the dimension \( d \). 

Let us write
\begin{equation}\label{eq:decomp}
    \int_{\Omega} v^*\, d (u_0^{k}- u_0^*) = \underbrace{\int_{\Omega} (v^* - p_k)\, d (u_0^{k}- u_0^*)}_{\gamma_1} + \underbrace{\int_{\Omega}  p_k\, d (u_0^{k}- u_0^*)}_{\gamma_2}.
\end{equation}
In the following two steps, we estimate upper bounds of $\gamma_1$ and $\gamma_2$, respectively.

\medskip
\noindent\textbf{Step 2} (Estimate on $\gamma_1$). Recalling the definition of the observation error $\epsilon$, by Lemma \ref{prop:a priori bound}, there exists $\tilde{u}_0 \in \mathcal{M}(\Omega)$, such that
\begin{align}
   & \int_{\Omega} x^{\alpha}\, d\tilde{u}_0(x) = \left(e^{-TA}\, \epsilon \right)_{\alpha}, \quad \text{for } \|\alpha\|_1 \leq k; \label{eq:tu} \\[0.6em]
    & \|\tilde{u}_0\|_{\text{TV}} \leq  \| \epsilon \|_{\infty}\, \underbrace{\sqrt{\frac{k}{\pi}} \, \exp\Bigg( k\left(1+ 2d/R +  \ln \sqrt{k} \right)\Bigg)}_{=\colon \tilde{C}_{d,r}(k)} 
\max \left\{ T^{\lfloor k/2 \rfloor}, \, 1 \right\}. \label{eq:C_d,k,r}
\end{align}
Since $u_0^*$ is the true initial distribution, we deduce from \eqref{eq:tu} that 
\begin{equation*}
    \int_{\Omega} x^{\alpha}\, d(\tilde{u}_0+u^*_0)(x) = \left(e^{-TA}\, \mathbf{y} \right)_{\alpha} \quad \text{for } \|\alpha\|_1 \leq k.
\end{equation*}
Since $u_0^k$ is a solution of \eqref{pb:OC}, we have
\begin{equation*}
    \|u_0^k\|_{\text{TV}} \leq \|\tilde{u}_0 + u_0^*\|_{\text{TV}}.
\end{equation*}
By the triangle inequality, 
\begin{equation*}
 \|u_0^k - u_0^*\|_{\text{TV}} \leq  \|u_0^*\|_{\text{TV}} + \|u_0^k\|_{\text{TV}} \leq  \|u_0^*\|_{\text{TV}} +
     \| \tilde{u}_0 + u_0^* \|_{\text{TV}}    
     \leq 2\|u_0^*\|_{\text{TV}} + \| \tilde{u}_0  \|_{\text{TV}}.
\end{equation*}
Combining with \eqref{eq:p_k} and the a priori bound of $\|\tilde{u}_0\|_{\text{TV}}$ in \eqref{eq:C_d,k,r}, it follows that
\begin{equation}\label{eq:gamma_1}
    \gamma_1\leq  \frac{ C_d \, R \, \|u_0^*\|_{\textnormal{TV}}}{k} + \frac{C_d\,R}{2k} \,  \tilde{C}_{d,R}(k)\, \max \left\{ T^{\lfloor k/2 \rfloor}, \, 1 \right\} \,\|\epsilon\|_{\infty}.
\end{equation}

\noindent\textbf{Step 3} (Estimate on $\gamma_2$). By \eqref{eq:p_k}, we have  
\begin{equation*}
    \|p_k\|_{\mathcal{C}(\Omega)} \leq 1 + \frac{C_d \, R}{2 k}.
\end{equation*}
Then, according to Lemma \ref{lem:poly_coef}, 
\begin{equation}\label{eq:c_alpha}
    \sum_{\|\alpha\|_1 \leq k} |c_\alpha| \leq e^{\frac{2dk}{R}} \left( 1 + \frac{C_d \, R}{2 k}\right),
\end{equation}
where \( c_\alpha \) are the coefficients of \( p_k \). Letting \(u_0^k - u_0^*\) be the initial distribution of the heat equation, then the solution at time $T$ has moments $\epsilon_{\alpha}$ by the linearity of the heat equation. Therefore, we deduce from Lemmas \ref{lem:growth} and \ref{lem:Stirling} that
\begin{equation}\label{eq:x^alpha}
    \left| \int_{\R^d} x^{\alpha} \, d (u_0^k - u_0^* )  \right |\leq  \sqrt{\frac{k}{\pi}} \, \exp\left( k + \frac{k}{2} \ln k \right)
\max \left\{ T^{\lfloor k/2 \rfloor}, \, 1 \right\} \, \| \epsilon \|_{\infty}, \quad \text{for }\|\alpha\|_1\leq k.
\end{equation}
Recalling the definition of $\gamma_2$ from \eqref{eq:decomp}, we have
\begin{equation}\label{eq:gamma_2_poly}
    \gamma_2 = \sum_{\|\alpha\|_1\leq k} c_{\alpha}  \int_{\R^d} x^{\alpha} \, d (u_0^k - u_0^* ) .
\end{equation}
Recalling the definition of $C_{d,r}(k)$ from \eqref{grosseconstante} and combining \eqref{eq:c_alpha}-\eqref{eq:gamma_2_poly}, we obtain
\begin{equation}
    \label{eq:gamma_2}
        \gamma_2  \leq   \left( 1 + \frac{C_d \, R}{2 k}\right)\, \tilde{C}_{d,R}(k)\, \max \left\{ T^{\lfloor k/2 \rfloor}, \, 1 \right\}\, \| \epsilon \|_{\infty}.
\end{equation}
The final estimate \eqref{eq:conv} follows from \eqref{eq:diff}, \eqref{eq:decomp}, \eqref{eq:gamma_1}, and \eqref{eq:gamma_2}.

\subsection{Error estimate in Wasserstein distance}\label{sec_wasserstein}

The Kantorovich norm (see Definition~\ref{def:kant}) is introduced to quantify the distance between two signed measures that may have different total masses. In the case where the total mass is the same, the Wasserstein distance is a well-known metric for measuring the discrepancy between distributions. Indeed, in this case, we can also estimate the Wasserstein distance between the recovered distribution $u_0^k$ and the true one $u^*_0$, see \eqref{eq:conv2}.

Let $\Omega$ be a compact set. Let \( u_1 \) and \( u_2 \) be two signed measures in \( \mathcal{M}(\Omega) \) with the same total mass, i.e., \( u_1(\Omega) = u_2(\Omega) \). The Wasserstein-1 distance (also referred to as the Kantorovich-Rubinstein distance or the Earth Mover's Distance in the literature) is defined as 
\begin{equation}\label{eq:W1}
    W_1(u_1,u_2) \coloneqq \max_{\substack{v \in \mathcal{C}(\Omega) \\ \mathrm{Lip}(v) \leq 1}} \int_{\Omega} v \, d(u_1-u_2).
\end{equation}  
Compared to the Kantorovich distance defined in~\eqref{eq:kant_norm}, the \(W_1\) distance removes the upper bound of 1 on the maximum norm of the test function \(v\). As a result, the \(W_1\) distance is not applicable when \(u_1(\Omega) \neq u_2(\Omega)\). Indeed,  adding a constant \(c\) to \(v\) does not change its Lipschitz constant, but introduces an additional nonzero term \(\int_{\Omega} c \, d(u_1 - u_2)\) in the integral. By choosing \(c\) with arbitrarily large magnitude, one can make the right-hand side of~\eqref{eq:W1} diverge to infinity.

Restricting \( u_1 \) and \( u_2 \) to the space of probability measures recovers the classical definition of the Wasserstein-1 distance in \cite[Sec.~6]{villani2009}. 



In the case of equal total mass, the Wasserstein-1 distance is equivalent to the Kantorovich norm, as shown in~\cite[Eq.\ (1.20)]{hanin1999kantorovich}: If \( u_1(\Omega) = u_2(\Omega) \), then  
\begin{equation}
    \| u_1 - u_2 \|_{\text{Kant}} \leq W_1(u_1,u_2) \leq \max\left\{1\,,\, D_{\Omega}/2\right\} \, \| u_1 - u_2 \|_{\text{Kant}},
\end{equation}  
where \( D_{\Omega} \) denotes the diameter of \( \Omega \).  

Therefore, in the context of Theorem \ref{thm:rate}, if we suppose that there is no error in the total mass observation, i.e., \( \epsilon_0 = 0 \), then,
\begin{equation}\label{eq:conv2}
    W_1(u_0^k, u_0^*) \leq \max\{1\,,\, \sqrt{d} R\} \|u_0^k-u_0^*\|_{\text{Kant}},
\end{equation}
and $ \|u_0^k-u_0^*\|_{\text{Kant}}$ is bounded by \eqref{eq:conv}.


We note that if the total mass of the initial distribution is known a priori (for example, if \( u_0^* \) is known to be a probability measure), then it can be preserved throughout the entire numerical resolution process. First, since the heat equation conserves total mass, we can directly set \( y_0 \) to the known value, without needing to estimate it via quadrature methods. Next, the semigroup \( e^{-tA} \), associated with the reverse moment dynamics, is a polynomial operator. As a result, computing \( e^{-tA} y \) introduces no numerical error, as it simply involves evaluating a polynomial in \( tA \) applied to \( y \); see Section~\ref{sec_discretzation} for the explicit formula. Finally, the moment constraints in the primal problem are given as equalities, ensuring that the total mass is exactly preserved in the final solution.


\section{Observation, discretization, and algorithms}\label{sec_dis}
This section is devoted to the numerical implementation of our moment-based method. Section~\ref{sec:quadrature} introduces two quadrature techniques for observing the moments of \( u(\cdot, T) \), while Section~\ref{sec_discretzation} describes the discretization procedure and the optimization algorithm used to solve \eqref{pb:OC}.


\subsection{Observation of moments}\label{sec:quadrature} 
The numerical calculation of the moments
\begin{equation*}
   M_{\alpha}(T) = \int_{\R^d} x^{\alpha} u(x,T) \,dx.
\end{equation*}
 is based on the observations of \( u(x, T) \) at specific sensor locations. Therefore, quadrature methods are used to approximate the integral. In the following paragraphs, two quadrature methods are presented.



\subsubsection{Uniform Quadrature}
The first and most direct way to compute \( M^{\alpha}(T) \) is via uniform quadrature, that is, by approximating the integral with a Riemann sum on a uniform grid. Specifically, we choose a large \( L>0 \) to bound the domain and discretize \([-L,L]^d\) uniformly using \( n^d \) points (with \( n \) points along each edge). The grid points are denoted by \( x_{\beta} \) for \(\beta\in \mathbb{Z}^{*\,d}_{+}\) with \( \|\beta\|_{\infty} \le n \). The resulting approximation is given by:
\begin{equation}\label{eq:uniform}
    M_{\alpha}(T) \approx \left(\frac{2L}{n}\right)^d \sum_{\|\beta\|_{\infty} \le n} x_{\beta}^{\alpha}\, u(x_{\beta}, T).
\end{equation}
In this method, the sensors are fixed at points \( x_{\beta} \) and hence their positions are independent of \( T \). However, when \( T \) is large, the solution \( u(\cdot, T) \) becomes widely spread, meaning that the concentration within the hypercube \([-L,L]^d\) decreases. 

For example, if the initial distribution is \( \delta_0 \), then by the Gaussian tail estimate,  \( (1 - \epsilon) \) of the mass of \( u(\cdot, T) \) is concentrated in the box \( [-L_{\epsilon, T}, L_{\epsilon, T}]^d \), where \( L_{\epsilon, T} \) is of order \( \sqrt{T \ln(d/\epsilon)} \). 
As a result, the discretization parameter \( n \) must be sufficiently large to accurately capture the solution. In conclusion, the uniform approach is straightforward to implement and works for small terminal times \( T \), but for larger \( T \), we instead propose the Gauss--Hermite method described below.




\subsubsection{Gauss--Hermite quadrature} 
To derive the quadrature formula of this method, we first apply a change of variable to the moment integral by scaling \( x \) by a factor \(\sigma\) (to be determined later):
\begin{equation}\label{eq:Gauss-1}
    \int_{\R^d} x^{\alpha} u(x,T) \,dx = \sigma^{\|\alpha\|_1+d} \int_{\R^d} z^{\alpha} u(\sigma z,T) \,dz.
\end{equation}
Next, we rewrite the integral on the right-hand side of \eqref{eq:Gauss-1} as
\begin{equation}\label{eq:Gauss-2}
    \int_{\R^d} z^{\alpha} u(\sigma z,T) \,dz = \int_{\R^d} \underbrace{\Bigl( z^{\alpha} u(\sigma z,T) e^{\|z\|^2} \Bigr)}_{=\colon g_{\sigma}(z)}\, e^{-\|z\|^2} \,dz.
\end{equation}
By applying the Gauss--Hermite quadrature in dimension \(d\), we obtain that
\begin{equation}\label{eq:Gauss-3}
    \int_{\R^d} g_{\sigma}(z) \, e^{-\|z\|^2} \,dz \approx \sum_{i_1=1}^n\cdots\sum_{i_d=1}^n \Biggl(\prod_{j=1}^d \omega_{i_j}\Biggr) \, g_{\sigma}(z_{i_1}, \ldots, z_{i_d}),
\end{equation}
where $n\geq 1$ is the degree of quadrature, \((\omega_i)_{i=1}^n\) and \((z_i)_{i=1}^n\) denote the weights and nodes corresponding to the \(n\)-th Hermite polynomial (see \cite[Sec.~18.3]{olver2010nist}).

For the quadrature to succeed, it is essential that \(g_{\sigma}(z_{i_1}, \ldots, z_{i_d})\) remains within moderate bounds. Otherwise, numerical overflow may occur, especially since \(g_{\sigma}\) contains the exponential factor \(e^{\|z\|^2}\). However, the rapid spatial decay of the heat solution \(u(\cdot,T)\) compensates for this exponential growth if a reasonable scaling factor \(\sigma\) is chosen.
Indeed, note that \(u(\sigma z, T)\) behaves like \(e^{-\|\sigma z\|^2/(4T)}\) (according to the formula for the heat kernel \(G\)). Hence, we choose
\begin{equation}\label{eq:Gauss-4}
    \sigma = 2\sqrt{T}.
\end{equation}
Therefore, by \eqref{eq:Gauss-1}--\eqref{eq:Gauss-4} we obtain the following complete approximation for \(M_{\alpha}(T)\):
\begin{equation}\label{eq:Gauss}
    M_{\alpha}(T) \approx (2\sqrt{T})^{\|\alpha\|_1+d} \sum_{i_1=1}^n \cdots \sum_{i_d=1}^n \Biggl( \prod_{j=1}^d \omega_{i_j} \, z_{i_j}^{\alpha_j} \Biggr) \,\exp\!\left(\sum_{j=1}^d z_{i_j}^2\right)\,  u\Bigl( 2\sqrt{T}(z_{i_1}, \ldots, z_{i_d}), T\Bigr) .
\end{equation}
Compared to \eqref{eq:uniform}, the Gauss--Hermite quadrature features sensor positions that depend on \( T \). Indeed, the positions 
\[
2\sqrt{T}(z_{i_1},\ldots, z_{i_d})
\]
grow at a rate proportional to \(\sqrt{T}\). Despite the inconvenience associated with moving sensors, our numerical simulations indicate that the Gauss--Hermite quadrature \eqref{eq:Gauss} yields superior results to the uniform quadrature \eqref{eq:uniform} with the same number of sensors, see Figure \ref{fig:quadrature} for a comparison.




\subsection{Discretize-then-optimize}\label{sec_discretzation}
Since \eqref{pb:OC} is an optimization problem defined on an infinite-dimensional space, we adopt a discretize-then-optimize approach to solve it.
\subsubsection{Discretization} We first discretize the domain $\Omega$ by selecting a set of $N$ points,
\[
\Omega \xrightarrow{\text{discretize}} \Omega_h = \{x_1,\ldots, x_N\}.
\]
In this discrete setting, any initial condition \( u_0 \in \mathcal{M}(\Omega_h) \) can be expressed as a finite sum of Dirac measures:
\[
u_0 = \sum_{i=1}^N m_i\, \delta_{x_i}.
\]
Thus, the discretized version of \eqref{pb:OC} reduces to a finite-dimensional optimization problem in \(\mathbb{R}^N\), with the optimization variables given by the vector of weights \(\mathbf{m} = (m_i)_{i=1}^N\):
\begin{equation}\label{pb:OC_dis}\tag{P$^{\text{dis}}_{\Omega,k}$}
    \inf_{\mathbf{m}\in \mathbb{R}^N} \|\mathbf{m}\|_{\ell^1} 
    \quad
    \text{subject to}
    \quad
    B\, \mathbf{m} \;=\; e^{-T A}\, \mathbf{y},
\end{equation}
where $\mathbf{y} = (y_{\alpha})_{\|\alpha\|_1\leq k}$ denotes the observations of moments at time $T$, and
\begin{itemize}
    \item $A$ is defined in \eqref{eq:ODE_moments}. By Lemma~\ref{lem:growth}, $A$ is \( (\lfloor k/2 \rfloor +1) \)-nilpotent, so that
    \[
    e^{-T A} = \sum_{j=0}^{\lfloor k/2 \rfloor} \frac{(-A)^j}{j!}\, T^j ;
    \]
    \item $B$ is a $\binom{k + d}{d} \times N$ matrix with entries
    \[
    b_{\alpha, i} = x_i^{\alpha},\quad \text{for } \|\alpha\|_1 \leq k,\quad i=1,\ldots, N.
    \]
\end{itemize}

The non-emptiness of the admissible set for the discretized problem \eqref{pb:OC_dis} is nontrivial. This is because the monomials $\{x^{\alpha}\}_{\|\alpha\|_1\leq k}$ are not, in general, linearly independent in $\mathcal{C}(\Omega_h)$. To guarantee the feasibility of \eqref{pb:OC_dis}, we introduce the notion of a \textit{unisolvent set}.
 A set of points \( \{z_{i} \in \mathbb{R}^d\}_{i=1,\ldots, \binom{k + d}{d} }\) is said to be a unisolvent set of degree \( k \) if and only if the only polynomial \( p \) of degree at most \( k \) that satisfies  
\[
p(z_{i}) = 0 \quad \text{for all } i\leq \binom{k + d}{d} 
\]
is the zero polynomial, i.e., \( p \equiv 0 \). 
Here, we give two examples of unisolvent sets:
\begin{enumerate}
    \item If $d=1$, then \( \{z_{i} \in \mathbb{R}\}_{i =1,\ldots, k+1} \) is a unisolvent set of degree \( k \) if and only if $z_{i}\neq z_{j}$ for any $i\neq j$.
    \item If \(d = 2\), then the family of Padua points \cite{caliari2005bivariate,bos2007bivariate} up to degree \(k\) forms a unisolvent set of degree \(k\). Suppose \(k\) is even, then the family of Padua points up to degree \(k\) is the collection of $z_{i,j} = (z^1_i,z^2_j) \in\R^2$ for $0\leq i\leq k$ and $0\leq j\leq k/2$ with
\begin{equation*}
z^1_i = \cos\Bigl(\tfrac{i\,\pi}{k}\Bigr),
\quad
z^2_j =
\begin{cases}
\displaystyle \cos\Bigl(\tfrac{2j \,\pi}{\,k+1 \,}\Bigr), 
& \text{if \(i\) is odd},\\[1em]
\displaystyle \cos\Bigl(\tfrac{(2j+1)\,\pi}{\,k+1 \,}\Bigr), 
& \text{if \(i\) is even}.
\end{cases}
\end{equation*}

\end{enumerate}


\begin{lem}\label{lem:exist}
   Suppose that \(N \ge \binom{k + d}{d}\) and that \(\Omega_h\) contains \(\binom{k + d}{d}\) points forming a unisolvent set of degree \(k\). Then  problem \eqref{pb:OC_dis} admits solutions for any $\mathbf{y} \in \R^{\binom{k+d}{d}}$.
\end{lem}

\begin{proof}
    The matrix \( B \) is a high-dimensional (rectangular) Vandermonde matrix. It has full row rank if it contains a square, invertible Vandermonde submatrix. According to \cite[Thm.\@ 4.1]{olver2006multivariate}, this condition is equivalent to the existence of \(\binom{k + d}{d}\) points in \(\Omega_h\) that form a unisolvent set of degree \(k\). In this case, the admissible set is non-empty and convex. The existence of a solution then follows from standard arguments based on the convexity and coercivity of problem~\eqref{pb:OC_dis}.
\end{proof}

\subsubsection{Optimization}\label{sec_optimization}
Following the general idea in \cite{chen2001atomic}, we transform \eqref{pb:OC_dis} into an equivalent linear programming and employ the simplex method to solve it. 
The equivalent linear programming for \eqref{pb:OC_dis} is given by
\begin{equation}\label{pb:OC_dis_eq}
    \inf_{\mathbf{m_+}\in \mathbb{R}_+^N, \, \mathbf{m_-}\in \mathbb{R}_+^N} 
    \langle \mathbf{1}, \mathbf{m_+} + \mathbf{m_-} \rangle 
    \quad
    \text{subject to}
    \quad
    B \bigl(\mathbf{m_+} - \mathbf{m_-}\bigr) = e^{-T A}\, \mathbf{y} ,
\end{equation}
where \(\mathbf{1}\) is the \(N\)-dimensional vector of all ones.

\begin{prop}\label{prop:simplex}
      Under the setting of Lemma \ref{lem:exist}, problem \eqref{pb:OC_dis_eq} has solutions. Let \((\mathbf{m_+} , \mathbf{m_-})\) be the solution of \eqref{pb:OC_dis_eq} obtained from the simplex method. Then \( \mathbf{m} = \mathbf{m_+} - \mathbf{m_-} \) is a solution of \eqref{pb:OC_dis} and $\|\mathbf{m}\|_{\ell^0} \leq \binom{k + d}{d}$.
\end{prop}
\begin{proof}
    The proof is the same as the proof of Theorem 4.7 in \cite{liu2025representation}.
\end{proof}



