\section{Technical lemmas and proofs}\label{sec_proof}

\subsection{A Representer Theorem}
We first recall a representer theorem from \cite[Thm.\@ 1]{fisher1975spline}, which plays the essential role in the proof of Theorem \ref{thm:existence}.
\begin{thm}[Fisher-Jerome 75]\label{thm:representation}
Let $\Omega$ be a compact set in $\R^d$. Let $N\in \mathbb{Z}_+$ and $l_i \colon \Omega \to \mathbb{R}$ be  continuous functions for $i=1,\ldots,N$. Consider the following optimization problem:
\begin{equation}\label{pb:total_variation}
    \inf_{\mu\in \mathcal{M}(\Omega)} \|\mu\|_{\textnormal{TV}}, \qquad \text{s.t. } \int_{\Omega} l_i(\theta) d\mu(\theta) \in I_i, \quad \text{for }i=1,\ldots,N,
\end{equation}
where $I_i$ is a compact interval or a singleton in $\R$ for $i=1,\ldots,N$.
Assume that the feasible set of problem \eqref{pb:total_variation} is non-empty. Then, its solution set is non-empty, convex, and compact in the weak-$*$ sense. Moreover, the extreme points of the solution set of \eqref{pb:total_variation} are of the form: 
   \begin{equation*}
       \mu^* = \sum_{i=1}^N \omega_i\delta_{x_i},
   \end{equation*}
   where $\omega_i\in \R$ and $x_i\in \Omega$ for $i=1,\ldots, N$.
\end{thm}


\begin{lem}\label{lem:moment_exist}
Fix any \(k \ge 0\). Let $\Omega$ be a compact subset of $\R^d$ such that $[-r,r]^d\subseteq \Omega$ for some $r>0$. Consider the moment problem
\begin{equation}\label{pb:moment_standard}
    \inf_{\mu\in \mathcal{M}(\Omega)} \|\mu\|_{\textnormal{TV}}, \qquad \textnormal{subject to } \int_{\Omega} x^{\alpha}\, d\mu(x) = z_{\alpha}, \quad \textnormal{for all } \|\alpha\|_1 \le k,
\end{equation}
where \(\mathbf{z} = (z_\alpha)_{\|\alpha\|_1 \le k} \in \mathbb{R}^{\binom{k+d}{d}}\) is an arbitrary vector. Let \(\mu^*\) be any solution of problem \eqref{pb:moment_standard}. Then, the total variation of \(\mu^*\) satisfies the following a priori estimate:
\begin{equation}\label{eq:total_variation}
    \|\mu^*\|_{\textnormal{TV}} \le e^{\frac{2dk}{r}}\, \|\mathbf{z}\|_{\infty}.
\end{equation}
\end{lem}

\begin{proof}
Since $\Omega$ contains a nonempty interior, the collection of monomials 
\(
\{x^{\alpha} \colon \Omega \to \mathbb{R}\}_{\|\alpha\|_1 \le k}
\)
is linearly independent. Hence, the existence of a solution $\mu^*$ follows from Theorem~\ref{thm:representation}.

The dual problem of \eqref{pb:moment_standard} is given by (see \cite[Sec.~2.3]{duval2015exact})
\begin{equation}\label{pb:dual}
   \sup_{c_{\alpha}} \; \sum_{\|\alpha\|_1 \le k} z_{\alpha}\,c_{\alpha} \quad \text{subject to} \quad \sup_{x\in \Omega}\left|\sum_{\|\alpha\|_1\le k} c_{\alpha}\,x^{\alpha}\right| \le 1.
\end{equation}
By the Fenchel--Rockafellar theorem, strong duality holds (see \cite[Prop.~13]{duval2015exact} for details):
\[
\|\mu^*\|_{\mathrm{TV}} = \operatorname{val}\eqref{pb:moment_standard} = \operatorname{val}\eqref{pb:dual}.
\]
Let $\mathbf{c}^* = (c^*_{\alpha})_{\|\alpha\|_1\le k}$ be a solution of \eqref{pb:dual}. By H\"older's inequality, we have
\[
\operatorname{val}\eqref{pb:dual} \le \|\mathbf{c}^*\|_1 \, \|\mathbf{z}\|_{\infty}.
\]
Moreover,
\[
\sup_{x\in \Omega}\left|\sum_{\|\alpha\|_1\le k} c^*_{\alpha}\,x^{\alpha}\right| \le 1.
\]
Since $\Omega$ contains $[-r,r]^d$, it follows from Lemma~\ref{lem:poly_coef} that
\[
\|\mathbf{c}^*\|_1 \le e^{\frac{2dk}{r}}.
\]
Therefore, the conclusion follows.
\end{proof}


\subsection{Results from approximation theory}

\begin{lem}[Jackson's Theorem in $\R^d$ \cite{newman1964jackson}]\label{lem:Jackson}
   For any \(L\)-Lipschitz function \( v \) defined on \( [-1,1]^d \) and any $k\geq 0$, there exists a multivariable polynomial \( p_k \) of degree less than \( k \) such that
\[
\|v - p_k\|_{\mathcal{C}([-1,1]^d)} \leq \frac{C_d\, L}{2k},
\]
where \( C_d \) is a constant depending only on the dimension \( d \).
\end{lem}

\begin{cor}\label{cor:approx_poly}
Let $\Omega= [-R,R]^d$ for some $R>0$. For any function \( v \in \mathcal{C}(\Omega) \) satisfying \(\textnormal{Lip}(v) \leq 1\) and any $k\geq 0$, there exists a multivariable polynomial \( p_k \) of degree less than \( k \) such that:
\[
\|v - p_k\|_{\mathcal{C}(\Omega)} \leq \frac{C_d \, R}{2k},
\]
where \( C_d \) is a constant depending only on the dimension \( d \).
\end{cor}
\begin{proof}
  It suffices to apply Lemma~\ref{lem:Jackson} to the rescaled function \(\bar{v}\colon [-1,1]^d\to \R, \, x \mapsto 
  v (R\, x )\).
\end{proof}

\begin{lem}\label{lem:poly_coef}
    Let \( f \) be any multivariable polynomial of degree less than \( k \).
    Assume that for $r>0$, \( |f(x)| \leq 1 \) for all \(x \in [-r,r]^d\). Then, the following holds:
\[
\sum_{\|\alpha\|_1\leq k }|c_\alpha| \leq e^{\frac{2dk}{r}},
\]
where \( c_\alpha \) are the coefficients of \( f \).
\end{lem}

\begin{proof}
  Fix any multi-index $\alpha = (\alpha_1,\dots,\alpha_d) \in \mathbb{Z}_+^d$ with $\|\alpha\|_1 \le k$. Recall that the Taylor coefficient of $f$ at $0$ corresponding to $\alpha$ is given by
\[
c_{\alpha} = \frac{1}{\alpha!}\,\frac{\partial^\alpha f(0)}{\partial x^\alpha}
= \frac{1}{\alpha!}\,\frac{\partial^{\alpha_1}\partial^{\alpha_2}\cdots \partial^{\alpha_d} f(0)}{\partial x_1^{\alpha_1}\partial x_2^{\alpha_2}\cdots \partial x_d^{\alpha_d}}.
\]

\medskip

\noindent \textbf{Step 1} (Reduction to a univariate polynomial). 
Fix any $(x_1,\dots,x_{d-1})\in [-r,r]^{d-1}$ and consider $f$ as a univariate function in the variable $x_d$. Since 
\[
|f(x)| \le 1 \quad \text{for all } x \in [-r,r]^d,
\]
we apply Bernstein's inequality for higher derivatives (see, e.g., \cite[Sec.~5.2.E.5]{borwein2012polynomials}) to deduce that for any fixed $(x_1,\dots,x_{d-1})$ 
\[
\left|\frac{\partial^{\alpha_d} f}{\partial x_d^{\alpha_d}}(x_1,x_2,\dots,x_{d-1},0)\right| \le \left(\frac{2\alpha_d}{r}\right)^{\alpha_d}.
\]


\noindent \textbf{Step 2} (Induction on the number of variables).
Now, fix $x_d=0$, and define
\[
g(x_1,\dots,x_{d-1}) = \frac{\partial^{\alpha_d} f}{\partial x_d^{\alpha_d}}(x_1,\dots,x_{d-1},0).
\]
Then $g$ is a polynomial in $(x_1,\dots,x_{d-1})$ of total degree at most $k-\alpha_d$ and
\[ \|g\|_{\mathcal{C}([-r,r]^{d-1})} \leq \left(\frac{2\alpha_d}{r}\right)^{\alpha_d}.\]
Applying the same argument as in Step 1, we 
\[
\left| \frac{\partial^{\alpha_{d-1} } g}{\partial x_{d-1}^{\alpha_{d-1}}} (x_1,\ldots, x_{d-2},0)\right| \leq \left(\frac{2k}{r}\right)^{\alpha_d} \left(\frac{2(k-\alpha_d)}{r}\right)^{\alpha_{d-1}}.
\]
Proceeding inductively over the remaining variables yields:
\[
|c_{\alpha}| \le \frac{(2k)^{\alpha_d} (2(k-\alpha_d))^{\alpha_{d-1}} \cdots \Bigl(2\Bigl(k-\sum_{j=2}^d \alpha_j\Bigr)\Bigr)^{\alpha_1}}{ r^{\|\alpha\|_1}\, \alpha_1! \, \alpha_2! \cdots \alpha_d!}.
\]
It follows that
\[
|c_{\alpha}| \le \frac{(2k)^{\alpha_1+\alpha_2+\cdots+\alpha_d}}{r^{\|\alpha\|_1}\,\alpha!} = \frac{1}{\alpha!} \left(\frac{2k}{r} \right)^{\|\alpha\|_1}.
\]

\medskip

\noindent \textbf{Step 3} (Summing over all multi-indices). 
Summing these estimates over all $\alpha$ with $\|\alpha\|_1 \le k$, we have
\[
\sum_{\|\alpha\|_1 \le k} |c_\alpha| \le \sum_{\|\alpha\|_1 \le k}\frac{1}{\alpha!} \left(\frac{2k}{r} \right)^{\|\alpha\|_1}= \sum_{j=0}^k \sum_{\|\alpha\|_1 = j} \frac{1}{\alpha!}\left(\frac{2k}{r} \right)^{j}.
\]
A standard combinatorial identity shows that
\[
\sum_{\|\alpha\|_1 = j} \frac{1}{\alpha!} = \frac{d^j}{j!},
\]
so that
\[
\sum_{\|\alpha\|_1 \le k} |c_\alpha| = \sum_{j=0}^k \frac{1}{j!}\left(\frac{2dk}{r} \right)^{j} \le e^{\frac{2dk}{r}}.
\]
Thus, the proof is complete.
\end{proof}

\begin{lem}\label{lem:Stirling}
For any $k \geq 1$ and $T > 0$, we have
\[
\sum_{j=0}^{\lfloor k/2 \rfloor} \frac{k^j (k-1)^j}{j!} \, T^j 
\leq 
 \sqrt{\frac{k}{\pi}} \, \exp\left( k + \frac{k}{2} \ln k \right)
\max \left\{ T^{\lfloor k/2 \rfloor}, \, 1 \right\}.
\]
\end{lem}

\begin{proof}
By H\"older's inequality, we have
\[
\sum_{j=0}^{\lfloor k/2 \rfloor} \frac{k^j (k-1)^j}{j!} \, T^j
\leq 
\max\left\{ T^{\lfloor k/2 \rfloor}, \, 1 \right\} \sum_{j=0}^{\lfloor k/2 \rfloor} \frac{k^j (k-1)^j}{j!}.
\]
It remains to bound the sum
\[
S := \sum_{j=0}^{\lfloor k/2 \rfloor} \frac{k^j (k-1)^j}{j!}.
\]
Let us first consider the case where $k$ is even. Let \( k = 2m \). Then
\[
S \leq 1 + m \cdot \frac{k^m (k-1)^m}{m!}.
\]
Using Stirling's lower bound
\[
n! \geq \sqrt{2\pi n} \left( \frac{n}{e} \right)^n, \quad \text{for } n \in \mathbb{Z}_+,
\]
we obtain
\[
\frac{k^m (k-1)^m}{m!}
\leq 
\frac{k^m (k-1)^m}{\sqrt{2\pi m} \left( \frac{m}{e} \right)^m }
=
\frac{1}{\sqrt{2\pi m}} \left( \frac{e^2 k (k-1)}{m^2} \right)^m.
\]
Since \( m = k/2 \), we have
\[
\frac{k^m (k-1)^m}{m!}
\leq 
\frac{1}{\sqrt{\pi k}} (2e(k-1))^{k/2}
=
\frac{1}{\sqrt{\pi k}} \exp\left( \frac{k}{2} \ln(2e(k-1)) \right).
\]
Therefore,
\[
S \leq 1 + \frac{1}{2} \sqrt{\frac{k}{\pi}} \exp\left( k + \frac{k}{2} \ln(k - 1) \right), \quad \text{for even } k.
\]
Then for the odd case \( k = 2m + 1 \),  a similar argument gives
\[
S \leq 1 + m \cdot \frac{k^m (k-1)^m}{m!}
\leq 1 + \frac{1}{2} \sqrt{\frac{k-1}{\pi}} \exp\left( k - 1 + \frac{k-1}{2} \ln k \right), \quad \text{for odd } k \geq 3.
\]
In both cases, we can bound uniformly for all \( k \geq 2 \) by
\[
S \leq 1 + \frac{1}{2} \sqrt{\frac{k}{\pi}} \exp\left( k + \frac{k}{2} \ln k \right) \leq \sqrt{\frac{k}{\pi}} \exp\left( k + \frac{k}{2} \ln k \right).
\]
One easily checks that the inequality also holds for \( k = 1 \). Therefore, the desired result follows.
\end{proof}


\section{Conclusion and perspectives}
In this article, we introduced a moment-based approach to the inverse source identification problem for the heat equation, a classically ill-posed problem. The key idea is to reformulate the original problem via a moment system, which mitigates the time-related ill-posedness of the backward heat equation.
The proposed scheme proceeds in two main steps: 
\begin{enumerate}
    \item inversion of the moment system to recover the moments of the initial distribution from noisy measurements;
    \item reconstruction of the initial source by minimizing the total variation under the recovered moment constraints.  
\end{enumerate}
We further established an error estimate for the reconstructed distribution in the Kantorovich distance, which depends on the moment order, terminal time, and observation noise.

From an algorithmic perspective, we detailed how moments at terminal time can be estimated using quadrature techniques, and discussed the discretization and numerical solution of the resulting constrained optimization problem. Numerical experiments demonstrate the effectiveness of our approach. In particular, our method achieves robust recovery of the initial data for terminal times up to \(T = 100\), significantly improving over existing benchmarks in the literature, which are typically limited to very small times (e.g., \(T \approx 0.01\)).

\medskip

\textit{Perspectives.} Here are some directions for future work related to this article:

\begin{enumerate}
  \item (Heat equation with boundary conditions). 
    When the heat equation \eqref{eq:heat} is posed with boundary conditions (for example, the Dirichlet condition \(u(x,t)=0\) on \(\partial\Omega\)), the ODE system \eqref{eq:ODE_moments} no longer accurately captures the evolution of the moments.  
    One alternative is to replace the raw moments by the modal coefficients
    \[
      a_m(t) \;=\;\int_{\Omega}u(x,t)\,\varphi_m(x)\,\mathrm{d}x,
    \]
    where \(\{\varphi_m\}\) are the Dirichlet eigenfunctions on \(\Omega\).  These coefficients satisfy a closed (though non-nilpotent) ODE system, but its inversion is typically less stable in time than the boundary-free moment method we have developed.  A more pragmatic approach is simply to apply our moment method while ignoring the boundary conditions.  For short time horizons (\(T\) small), the influence of the boundaries is mild, and this ``unadjusted" method can still yield accurate numerical results.

   \item(Advection-Diffusion Dynamics). 
A natural extension of the heat equation is the advection-diffusion process: 
\[
\begin{cases}
\displaystyle \partial_t m - \text{div}\,\bigl(D\,\nabla m - v\,m\bigr) = 0, 
& \text{for }(x,t)\in\mathbb{R}^n \times \mathbb{R}_+, \\[6pt]
m(0,x) = m_0(x), 
&\text{for } x\in\mathbb{R}^n,
\end{cases}
\]
where \(D\) is a positive-definite diffusion matrix and \(v\) is the advection (drift) vector.  The density \(m(t,x)\) describes the law of the stochastic process
\[
\begin{cases}
dX_t = v\,dt + \sqrt{2}\,D^{1/2}\,dW_t,\\
X_0\sim m_0,
\end{cases}
\]
with \(\{W_t\}_{t\ge0}\) a standard Brownian motion.  The initial source identification problem seeks to recover the distribution \(m_0\) by some information of \(m(T)\).  Our moment method is especially effective when \(D\) and \(v\) are spatially invariant and piecewise constant in time. In this setting, the resulting system of moment ODEs is closed and nilpotent.
For space-dependent $D$ and $v$,  the problem becomes significantly more complex and remains a subject for future investigation.
\end{enumerate}


