\section{\bf Collision between degenerate and non-degenerate solitons}
 %\subsection{Asymptotic analysis}
To investigate the shape-changing behavior of a non-degenerate soliton induced by its collision with a degenerate soliton, we consider a special form of the two-soliton solution that includes both degenerate and non-degenerate solitons. Such a two-soliton solution can be obtained by applying a partial non-degenerate (or partial degenerate) limit: $k_1\neq l_1$ and $k_2=l_2$, in Eqs. (\ref{A.2a})-(\ref{A.2d}) with $N=2$. The resulting solution is referred to as the partial non-degenerate two-soliton solution. Consequently, it becomes important to investigate the collision dynamics between degenerate and non-degenerate solitons. As we know, the non-degenerate fundamental soliton exists in two distinct forms, leading to two possible types of collision dynamics: (i) collision between a degenerate soliton and a ($1,1,1$)-non-degenerate soliton, and (ii) collision between a degenerate soliton and a ($1,1,2$)-non-degenerate soliton. However, we intend to analyse the former only for brevity. 

 To explore the degenerate bright soliton collision induced shape changing behaviour of the ($1,1,1$) non-degenerate soliton, we intend to analyse the partial non-degenerate two-soliton solution in the limits $t\rightarrow \pm \infty$. In these limits, the asymptotic forms associated with the non-degenerate and degenerate solitons can be deduced by substituting the respective asymptotic behavior of their corresponding wave variables $\eta_{1R}=k_{1R}(t-2k_{I1}z)$, $\xi_{1R}=l_{1R}(t-2k_{1I}z)$, and $\eta_{2R}=k_{2R}(t-2k_{2I}z)$ in the obtained partially non-degenerate two-soliton solution. In the latter,  the variables $\eta_{1R}$ and $\xi_{1R}$ represent the non-degenerate soliton and  $\eta_{2R}$ denotes the degenerate soliton. To deduce their asymptotic expressions, we consider the parametric choices, $k_{jR},l_{1R}>0$,  $k_{1I}=l_{1I}<k_{2I}$.  For this choice, the wave variables behave asymptotically as follows: (i) ($1,1,1$)-non-degenerate soliton $\mathsf{S}_1$: $\eta_{1R},\xi_{1R}\simeq0$, $\eta_{2R}\rightarrow \pm\infty$ as $t\rightarrow \mp\infty$ (ii) degenerate soliton $\mathsf{S}_2$: $\eta_{2R}\simeq 0$, $\eta_{1R}, \xi_{1R} \rightarrow\pm \infty$ as $t\rightarrow\pm \infty$.We have deduced the following expressions to describe the structural changes that occur in non-degenerate and degenerate solitons during the collision process.\\
 \underline{(a) Before collision}: $t\rightarrow -\infty$\\
  \underline{Non-degenerate soliton}: The asymptotic forms of the nondegenerate soliton $\mathsf{S}_1$, which is present in both the short-wave components as well as in the long-wave component, before collision are obtained as
 \begin{subequations}
 	\bea
 	&&S^{(1)}\simeq\frac{1}{D_1}\big(e^{i\eta_{1I}}d_{11}\cosh(\xi_{1R}+\Phi_1^-)+e^{i\xi_{1I}}d_{12}\cosh(\eta_{1R}+\Phi_2^-)\big),\\
 	&&S^{(2)}\simeq\frac{1}{D_1}\big(e^{i\eta_{1I}}d_{21}\cosh(\xi_{1R}+\Phi_6^-)+e^{i\xi_{1I}}d_{22}\cosh(\eta_{1R}+\Phi_7^-)\big),\\
 	&&L\simeq\frac{1}{D_1^2}\bigg(4k_{1R}^2\nu_{11}\cosh(2\xi_{1R}+\Phi_8^-)+4l_{1R}^2\nu_{11}\cosh(2\eta_{1R}+\Phi_{9}^-)+2(k_{1R}-l_{1R})^2\nu_{12}\cosh\Phi_{5}^-\nonumber\\
 	&&\hspace{0.5cm}\times[\cos\theta\cosh(\eta_{1R}-\xi_{1R}+\Phi_{4}^-)+i\sin\theta\sinh(\eta_{1R}-\xi_{1R}+\Phi_{4}^-)]+2(k_{1R}-l_{1R})^2\nu_{13}\nonumber\\
 	&&\hspace{0.5cm}\times \cosh(\eta_{1R}+\xi_{1R}+\Phi_8^-)e^{\frac{\eta_{1R}+\xi_{1R}}{2}}[\cosh\Phi_5^-\cos\theta+i\sinh\Phi_5^-\sin\theta]+\nu_{14}\bigg),\\
 	&&D_1=d_{13}\cosh(\eta_{1R}+\xi_{1R}+\Phi_3^-)+d_{14}\cosh(\eta_{2R}-\xi_{2R}+\Phi_4^-)\nonumber\\
 	&&\hspace{0.5cm}+d_{15}[\cosh\Phi_5^-\cos\theta+i\sinh\Phi_5^-\sin\theta],
 \end{eqnarray}
\end{subequations}
where $\theta=(k_{1R}^2-l_{1R}^2)t$. The constants such as $d_{ij}$'s, $\nu_{11}$, $\nu_{12}$, $\nu_{13}$, $\nu_{14}$, $\Phi_j^-$, $i=1,2$, $j=1,2,...,9$, appearing above are defined in Appendix B.\\
 \underline{Degenerate soliton}: The asymptotic form of the degenerate soliton, deduced from the partially non-degenerate soliton solution (Eqs. (\ref{A.2a})-(\ref{A.2d}) with $N=2$, $k_l\neq l_1$ and $k_2=l_2$), is given by
 \begin{eqnarray}
 	\hspace{-0.5cm}S^{(l)}\simeq\begin{pmatrix}
