&&\hspace{-0.9cm}\Lambda_7=[\sigma_1(k_2^{*2}-l_1^2)|k_1-k_2|^2|k_1+k_2|^2|\alpha_2^{(1)}|^2+\sigma_2|k_1-k_2^*|^2|k_1+k_2^*|^2(k_2^{2}-l_1^2)|\alpha_2^{(2)}|^2].
\eea
