\DisplayProof

\bigskip

\AxiomC{}
\LeftLabel{Ind$^t_{\forall x\,\phi}$}
\UnaryInfC{${\sim}\phi(0), \exists x\,(\phi(x)\wedge {\sim}\phi(Sx)), \phi(t)$}
