\bigskip

\AxiomC{$\phi(t,\mu xX.\, \phi)$}
\LeftLabel{Cl$_{t\in\mu xX.\,\phi}$}
\RightLabel{where $\phi[x\mapsto t][X\mapsto \mu xX. \phi]$ is a permitted substitution}
\UnaryInfC{$t\in \mu xX.\,\phi$}
\DisplayProof

