\LeftLabel{Ind$^t_{\mu xX\,\phi, \psi(y)}$}
\UnaryInfC{$\exists x\,(\phi(x,\psi(y))\wedge {\sim}\psi(x)), t\not\in \mu xX\,\phi, \psi(t)$}
\DisplayProof

where $\phi[X\mapsto \psi]$, $\psi[y\mapsto x]$, and $\psi[y\mapsto t]$ are permitted substitutions

