\noLine
\UnaryInfC{$[\Theta_\sigma[Z\mapsto\mu xX.\phi],\phi(k,\mu xX.\phi)]^{n\in\mu xX.\phi,\epsilon\top},\Theta_\sigma[Z\mapsto\psi],\phi(k,\psi) ,\exists x\, \phi(x,\psi)\wedge{\sim}\psi(x)$}
\LeftLabel{\scriptsize{$\mathrm{Read}^{\mathsf{ID}^{\infty,+}_1}_{[\Theta'_{\sigma\top L}]^{n\in\mu xX.\phi, \epsilon\top} }$}}
\UnaryInfC{$[\Theta_\sigma[Z\mapsto\mu xX.\phi]]^{n\in\mu xX.\phi,\epsilon},\Theta_\sigma[Z\mapsto\psi],\phi(k,\psi) ,\exists x\, \phi(x,\psi)\wedge{\sim}\psi(x)$}
\AxiomC{$d_{\psi(k)}$}
\noLine
\UnaryInfC{$\vdots$}
\noLine
\UnaryInfC{$\psi(k),{\sim}\psi(k)$}
\LeftLabel{I$\wedge$}
\BinaryInfC{$[\Theta_\sigma[Z\mapsto\mu xX.\phi]]^{n\in\mu xX.\phi,\epsilon},\Theta_\sigma[Z\mapsto\psi],\exists x\, \phi(x,\psi)\wedge{\sim}\psi(x),\phi(k,\psi)\wedge{\sim}\psi(k)$}
\LeftLabel{I$\exists$}
\UnaryInfC{$[\Theta_\sigma[Z\mapsto\mu xX.\phi]]^{n\in\mu xX.\phi,\epsilon},\Theta_\sigma[Z\mapsto\psi],\exists x\, \phi(x,\psi)\wedge{\sim}\psi(x)$}
\DisplayProof

\bigskip

and set $\Theta_{\sigma\top L}=\Theta_\sigma\cup\{\eta_\top\}$ (where $\eta_\top$ is $\phi(k,\psi)$ by definition). (Note that $\psi(k)$ is, again by definition, contained in $\Theta_\sigma[Z\mapsto\psi]$.)

\end{proof}

\begin{theorem}\label{thm:id1_embedding}
  Let $d$ be a deduction in $\mathsf{ID}_1$ so that $\Gamma(d)$ has free variables contained in $x_1,\ldots,x_n$. There is some $k$ so that, for any numerals $m_1,\ldots,m_n$, there is a proof tree $d^\infty$ in $\mathsf{ID}_{1,<k}^\infty$ with $\Gamma(d^\infty)\subseteq\Gamma(d)[x_i\mapsto m_i]$.
\end{theorem}
\begin{proof}
  We proceed by induction on $d$. If $d$ is $\mathrm{Def}_\phi$ then $\phi[x_i\mapsto m_i]$ is a true quantifier-free formula whose only atomic formulas have the form $\dot{R}t_1\cdots t_n$, and therefore there is a proof of $\phi[x_i\mapsto m_i]$ even in $\mathsf{ID}_{1}^{\infty,+}$.

  If $d$ is $\mathrm{Ax}_\eta$ then either $\eta[x_i\mapsto m_i]$ has the form $\dot{R}t_1\cdots t_n$, in which case $\mathrm{True}_{\eta[x_i\mapsto m_i]}$ suffices, or $\eta[x_i\mapsto m_i]$ has the form $n\in\mu xX.\phi$, in which case the deduction $d_{n\in\mu xX.\phi}$ is given above.  When the final inference rule of $d$ is $\wedge$I, $\vee$I, $\exists$I, $\mathrm{Cl}$, or $\mathrm{Cut}$, the claim follows immediately from the inductive hypothesis. (In the case of $\exists$I and $\mathrm{Cut}$, the premises may have additional free variables; we substitute these free variables with $0$'s to apply the inductive hypothesis.)

  When the final inference rule of $d$ is $\forall^y_{\forall x\,\phi}$I, we have a premise $d'$ concluding $\Gamma(d),\phi(y)$ where $y$ is not free in $\Gamma(d)$. For each $n$, the inductive hypothesis gives a deduction of $(\Gamma(d),\phi(n))[x_i\mapsto m_i]$, and we may apply an $\omega$ rule to obtain the desired deduction.

  When $d$ is $\mathrm{Ind}^t_{\forall x\,\phi}$, we let $n$ be $\overline{t[x_i\mapsto m_i]}$ and proceed by induction on $n$. For notational convenience, let $\phi'$ be $\phi[x_i\mapsto m_i]$. When $n=0$, we may apply the previous lemma to obtain a deduction $d^\infty_0$ with $\Gamma(d^\infty_0)\subseteq \phi'(0),{\sim}\phi(0)$. So suppose we have a deduction $d^\infty_n$ with $\Gamma(d^\infty_n)\subseteq {\sim}\phi'(0), \exists x\,\phi'(x)\wedge{\sim}\phi'(Sx)\, \phi'(n)$. Then we may take $d^\infty_{n+1}$ to be

  \AxiomC{$d^\infty_n$}
  \noLine
  \UnaryInfC{$\vdots$}
  \noLine
  \UnaryInfC{$ {\sim}\phi'(0), \exists x\,\phi'(x)\wedge{\sim}\phi'(Sx), \phi'(n)$}
  \AxiomC{$d_{\phi'(n+1)}$}
  \noLine
  \UnaryInfC{$\vdots$}
  \noLine
  \UnaryInfC{${\sim}\phi'(n+1),\phi'(n+1)$}
  \BinaryInfC{$ {\sim}\phi'(0), \exists x\,\phi'(x)\wedge{\sim}\phi'(Sx), \phi'(n)\wedge{\sim}\phi'(n+1), \phi'(n+1)$}
  \UnaryInfC{$ {\sim}\phi'(0), \exists x\,\phi'(x)\wedge{\sim}\phi'(Sx),\phi'(n+1)$}
  \DisplayProof

  The novel case is when $d$ is $\mathrm{Ind}^t_{\mu xX\, \phi,\psi(y)}$. Again, let us write $\phi'$ for $\phi[x_i\mapsto m_i]$, $t'$ for $t[x_i\mapsto m_i]$, and $\psi'$ for $\psi[x_i\mapsto m_i]$. In this case we may use an $\Omega^\flat$ inference rule applied to the function $\mathrm{Subst}^{t'\in \mu xX.\phi'\mapsto \psi'}$ from the previous lemma.
\end{proof}

\subsection{Cut Elimination}

We next show that it is possible to eliminate cuts from deductions in $\mathsf{ID}_1^\infty$. The proof is essentially standard; we need only check that the new rules do not interfere with the usual arguments. 

\begin{lemma}[$\bot$ Inversion]
  Let $\eta$ be an atomic formula of the form $\dot{R}m_1\cdots m_n$ and let $\phi\in\{\eta,\neg\eta\}$ be false. If $d$ is a $\mathsf{ID}^\infty_{1,0}$ proof tree then $\phi\not\in\Gamma(d)$.
\end{lemma}
\begin{proof}
Immediate, since no rule in $\mathsf{ID}^\infty_{1,0}$ can introduce a false literal of this form.
\end{proof}

\begin{lemma}[$\wedge$ Inversion]\label{thm:and_inversion}
  For any formulas $\phi_L,\phi_R$ with rank $< n$ and $i\in\{L,R\}$ and any $\mathsf{ID}^\infty_{1,<n}$ proof tree $d$, there is a $\mathsf{ID}^\infty_{1,<n}$ proof tree $\mathrm{Inverse}^\wedge_{\phi_L,\phi_R, i}(d)$ with $\Gamma(\mathrm{Inverse}^\wedge_{\phi_L,\phi_R, i}(d))\subseteq(\Gamma(d)\setminus\{\phi_L\wedge\phi_R\})\cup\{\phi_i\}$.%
\end{lemma}
\begin{proof}
  We define $\mathrm{Inverse}^\wedge_{\phi_L,\phi_R, i}(d)(\sigma)$ by induction on $\sigma$, and simultaneously define a function $\pi:\dom(\mathrm{Inverse}^\wedge_{\phi_L,\phi_R, i}(d))\rightarrow\dom(d)$. %

  We set $\pi(\langle\rangle)=\langle\rangle$.  Let $\pi(\sigma)$ be defined. If $\phi_L\wedge\phi_R\not\in\Delta(d(\pi(\sigma))$, we set $\mathrm{Inverse}^\wedge_{\phi_L,\phi_R, i}(d)(\sigma)=d(\pi(\sigma))$ and, for each $\iota\in|\mathrm{Inverse}^\wedge_{\phi_L,\phi_R, i}(d)(\sigma)|$, $\pi(\sigma\iota)=\pi(\sigma)\iota)$.

  Suppose $\phi_L\wedge\phi_R\in\Delta(d(\pi(\sigma)))$. If $d(\pi(\sigma))$ is $\wedge\mathrm{I}_{\phi_L\wedge\phi_R}$ then we set $\mathrm{Inverse}^\wedge_{\phi_L,\phi_R, i}(d)(\sigma)=\mathrm{Rep}$ and $\pi(\sigma\top)=\pi(\sigma)i$.

  The only other rule in $\mathsf{ID}^\infty_{1,<n}$ with $\phi_L\wedge\phi_R\in\Delta(d(\pi(\sigma))$ is $\mathrm{Read}^{\mathsf{ID}^{\infty,+}_1}_{[\Theta]^{n\in\mu xX.\phi,\epsilon}}$ with $\phi_L\wedge\phi_R\in\Delta(\epsilon)\setminus\Theta$. We set $\mathrm{Inverse}^\wedge_{\phi_L,\phi_R, i}(d)(\sigma)=\mathrm{Read}^{\mathsf{ID}^{\infty,+}_1}_{[\Theta\cup\{\phi_L\wedge\phi_R\}]^{n\in\mu xX.\phi,\epsilon}}$ and, for all $\mathcal{R}$, $\pi(\sigma\mathcal{R})=\pi(\sigma)\mathcal{R}$.
\end{proof}

\begin{lemma}[$\forall$ Inversion]\label{thm:all_inversion}
  For any formula $\phi(y)$ with rank $< n$ whose only free variable is $y$, any $m\in\mathbb{N}$, and any $\mathsf{ID}^\infty_{1,<n}$ proof tree $d$, there is a $\mathsf{ID}^\infty_{1,<n}$ proof tree $\mathrm{Inverse}^\forall_{\phi(y),m}(d)$ with $\Gamma(\mathrm{Inverse}^\forall_{\phi(y),m} (d))\subseteq(\Gamma(d)\setminus \{\forall x\,\phi(x)\})\cup\{\phi(m)\}$.%
\end{lemma}
\begin{proof}
  We define $\mathrm{Inverse}^\forall_{\phi(y),m} (d)(\sigma)$ by induction on $\sigma$, and simultaneously define a function $\pi:\dom(\mathrm{Inverse}^\forall_{\phi(y),m} (d))\rightarrow\dom(d)$. %

  We set $\pi(\langle\rangle)=\langle\rangle$.  Let $\pi(\sigma)$ be defined. If $\forall x\,\phi(x)\not\in\Delta(d(\pi(\sigma)))$ then we set $\mathrm{Inverse}^\forall_{\phi(y),m} (d) (\sigma)=d(\pi(\sigma))$ and, for each $\iota\in|\mathrm{Inverse}^\forall_{\phi(y),m} (d) (\sigma)|$, $\pi(\sigma\iota)=\pi(\sigma)\iota)$.

  If $d(\pi(\sigma))$ is $\omega_{\forall x\,\phi}$ then we set $\mathrm{Inverse}^\forall_{\phi(y),m} (d) (\sigma)=\mathrm{Rep}$ and $\pi(\sigma\top)=\pi(\sigma)m$.

  The only other rule with $\forall x\,\phi(x)\in\Delta(d(\pi(\sigma)))$ is $\mathrm{Read}^{\mathsf{ID}^{\infty,+}_1}_{[\Theta]^{n\in\mu xX.\phi,\epsilon}}$ with $\forall x\,\phi(x)\in\Delta(\epsilon)\setminus\Theta$. We set $\mathrm{Inverse}^\forall_{\phi(y),m} (d)(\sigma)=\mathrm{Read}^{\mathsf{ID}^{\infty,+}_1}_{[\Theta\cup\{\forall x\,\phi\}]^{n\in\mu xX.\phi,\epsilon}}$ and, for all $\mathcal{R}$, $\pi(\sigma\mathcal{R})=\pi(\sigma)\mathcal{R}$.
\end{proof}

\begin{lemma}[$\vee$ Elimination]\label{thm:or_elimination}
  For any formulas $\phi_L,\phi_R$ with rank $< n$ and any $\mathsf{ID}^\infty_{1,<n}$ proof trees $d_\wedge$ and $d_\vee$, there is a $\mathsf{ID}^\infty_{1,<n}$ proof tree $\mathrm{Elim}^\vee_{\phi_L,\phi_R}(d_\vee,d_\wedge)$ with $\Gamma(\mathrm{Elim}^\vee_{\phi_L,\phi_R}(d_\vee,d_\wedge))\subseteq (\Gamma(d_\wedge)\setminus\{\phi_L\wedge\phi_R\})\cup(\Gamma(d_\vee)\setminus\{{\sim}\phi_L\vee{\sim}\phi_R\})$.%
\end{lemma}
\begin{proof}

  We define a partial function $\pi:\dom(\mathrm{Elim}^\vee_{\phi_L,\phi_R}(d_\vee,d_\wedge))\rightarrow\dom(d_\vee)$.  We define $\pi(\langle\rangle)=\langle\rangle$. %
  Suppose we have defined $\pi(\sigma)$. If ${\sim}\phi_L\vee{\sim}\phi_R\not\in\Delta(d_\vee(\pi(\sigma)))$ then we set $\mathrm{Elim}^\vee_{\phi_L,\phi_R}(d_\vee,d_\wedge)(\sigma)=d_\vee(\pi(\sigma))$ and, for all $\iota\in|\mathrm{Elim}^\vee_{\phi_L,\phi_R}(d_\vee,d_\wedge)(\sigma)|$, $\pi(\sigma\iota)=\pi(\sigma)\iota$.

  If $d_\vee(\pi(\sigma))$ is $\vee\mathrm{I}^i_{{\sim}\phi_L\vee{\sim}\phi_R}$, we set $\mathrm{Elim}^\vee_{\phi_L,\phi_R}(d_\vee,d_\wedge)(\sigma)=\mathrm{Cut}_{\phi_i}$. We set $\pi(\sigma R)=\pi(\sigma)$, and for all $\upsilon\in\dom(\mathrm{Inverse}^\wedge_{\phi_L,\phi_R,i}(d_\wedge))$, we set $\mathrm{Elim}^\vee_{\phi_L,\phi_R}(d_\vee,d_\wedge)(\sigma L\upsilon)=\mathrm{Inverse}^\wedge_{\phi_L,\phi_R,i}(d_\wedge)(\upsilon)$.%

  If $d_\vee(\pi(\sigma))$ is $\mathrm{Read}^{\mathsf{ID}^{\infty,+}_1}_{[\Theta]^{n\in\mu xX.\phi,\epsilon}}$ with ${\sim}\phi_L\vee{\sim}\phi_R\in\Delta(\epsilon)\setminus\Theta$ then we set $\mathrm{Elim}^\vee_{\phi_L,\phi_R}(d_\vee,d_\wedge)(\sigma)=\mathrm{Read}^{\mathsf{ID}^{\infty,+}_1}_{[\Theta\cup\{{\sim}\phi_L\vee{\sim}\phi_R\}]^{n\in\mu xX.\phi,\epsilon}}$ and, for all $\mathcal{R}$, $\pi(\sigma\mathcal{R})=\pi(\sigma)\mathcal{R}$.
\end{proof}


\begin{lemma}[$\exists$ Elimination]\label{thm:exists_elimination}
  For any formula $\phi(y)$ with rank $< n$ whose only free variable is $y$ and any $\mathsf{ID}^\infty_{1,<n}$ proof trees $d_\forall$ and $d_\exists$, there is a $\mathsf{ID}^\infty_{1,<n}$ proof tree $\mathrm{Elim}^\exists_{\phi(y)}(d_\exists,d_\forall)$ with $\Gamma(\mathrm{Elim}^\exists_{\phi(y)}(d_\exists,d_\forall))\subseteq (\Gamma(d_\forall)\setminus\{\forall y\,\phi(y)\})\cup(\Gamma(d_\exists)\setminus\{\exists y\,{\sim}\phi(y))$.%
\end{lemma}
\begin{proof}

  We define $\pi(\langle\rangle)=\langle\rangle$.  %
  Suppose we have defined $\pi(\sigma)$. If $\exists\mathrm{I}^t_{\exists y\,{\sim}\phi}$ is not in $\Delta(d_\exists(\pi(\sigma)))$ then we set $\mathrm{Elim}^\exists_{\phi(y)}(d_\exists,d_\forall)(\sigma)=d_\exists(\pi(\sigma))$ and, for all $\iota\in|\mathrm{Elim}^\exists_{\phi(y)}(d_\exists,d_\forall)(\sigma)|$, $\pi(\sigma\iota)=\pi(\sigma)\iota$.

  If $d_\exists(\pi(\sigma))$ is $\exists\mathrm{I}^t_{\exists y\,{\sim}\phi}$ then, since $t$ is closed, $t=m$ for some numeral $m$. We set $\mathrm{Elim}^\exists_{\phi(y)}(d_\exists,d_\forall)(\sigma)=\mathrm{Cut}_{\phi(m)}$. We set $\pi(\sigma R)=\pi(\sigma)\top$ and, for all $\upsilon\in\dom(\mathrm{Inverse}^\forall_{\phi(y),m}(d_\forall))$, we set $\mathrm{Elim}^\exists_{\phi(y)}(d_\exists,d_\forall)(\sigma L\upsilon)=\mathrm{Inverse}^\forall_{\phi(y),m}(d_\forall)(\upsilon)$.%

  If $d_\exists(\pi(\sigma))$ is $\mathrm{Read}^{\mathsf{ID}_1^{\infty,+}}_{[\Theta]^{n\in\mu xX.\phi,\epsilon}}$ with $\exists y\,{\sim}\phi\in\Delta(\epsilon)\setminus\Theta$ then we set $\mathrm{Elim}^\exists_{\phi(y)}(d_\exists,d_\forall)(\sigma)=\mathrm{Read}^{\mathsf{ID}_1^{\infty,+}}_{[\Theta\cup\{\exists y\,{\sim}\phi\}]^{n\in\mu xX.\phi,\epsilon}}$ and, for all $\mathcal{R}$, $\pi(\sigma\mathcal{R})=\pi(\sigma)\mathcal{R}$.
\end{proof}

\begin{lemma}[$\mu$ Elimination]\label{thm:mu_elimination}
For any atomic formula of the form $n\in\mu xX.\phi$ and any $\mathsf{ID}_{1,<0}^{\infty}$ proof trees $d_\mu$ and $d_\neg$, there is a $\mathsf{ID}_{1,<0}^\infty$ proof tree $\mathrm{Elim}^\mu_{n\in\mu xX.\phi}(d_\mu,d_\neg)$ with $\Gamma(\mathrm{Elim}^\mu_{n\in\mu xX.\phi}(d_\mu,d_\neg))\subseteq(\Gamma(d_\mu)\setminus\{n\in \mu xX.\phi\})\cup(\Gamma(d_\neg)\setminus\{n\not\in\mu xX.\phi\})$.%
\end{lemma}
\begin{proof}
  We define $\pi(\langle\rangle)=\langle\rangle$. %

  Suppose we have defined $\pi(\sigma)$. If $n\not\in\mu xX.\phi\not\in\Delta(d_\neg(\pi(\sigma)))$ then we set $\mathrm{Elim}^\mu_{n\in\mu xX.\phi}(d_\mu,d_\neg) (\sigma)=d_\neg(\pi(\sigma))$ and, for all $\iota\in|\mathrm{Elim}^\mu_{n\in\mu xX.\phi}(d_\mu,d_\neg) (\sigma)|$, $\pi(\sigma\iota)=\pi(\sigma)\iota$.

  If $n\not\in\mu xX.\phi\in\Delta(d_\neg(\pi(\sigma)))$ then if $d_\neg(\pi(\sigma))$ is $\Omega^\flat_{n\not\in\mu xX.\phi}$, we set $\mathrm{Elim}^\mu_{n\in\mu xX.\phi}(d_\mu,d_\neg) (\sigma)=\mathrm{Cut}\Omega^\flat_{n\not\in\mu xX.\phi}$, $\pi(\sigma R)=\pi(\sigma)\top$, and $\mathrm{Elim}^\mu_{n\in\mu xX.\phi}(d_\mu,d_\neg)(\sigma L \upsilon)=d_\mu(\upsilon)$.%

  The final case is that $d_\neg(\pi(\sigma))$ is $\mathrm{Read}^{\mathsf{ID}_1^{\infty,+}}_{[\Theta]^{m\in yY.\phi,\epsilon}}$ with $n\not\in\mu xX.\phi\in\Delta(\epsilon)\setminus\Theta$. In this case we set $\mathrm{Elim}^\mu_{n\in\mu xX.\phi}(d_\mu,d_\neg) (\sigma)=\mathrm{Read}^{\mathsf{ID}_1^{\infty,+}}_{[\Theta\cup\{n\not\in\mu xX.\phi\}]^{m\in yY.\phi,\epsilon}}$ and, for all $\mathcal{R}$, $\pi(\sigma\mathcal{R})=\pi(\sigma)\mathcal{R}$.
\end{proof}

\begin{theorem}
If $d$ is a proof tree in $\mathsf{ID}_{1,<n+1}^{\infty}$ then there is a proof tree $\mathrm{Reduce}_n(d)$ in $\mathsf{ID}_{1,<n}^\infty$ with $\Gamma(\mathrm{Reduce}_n(d))\subseteq\Gamma(d)$.%
\end{theorem}
\begin{proof}
  For every $\tau\in\dom(d)$, we need to define a proof tree $\mathrm{Reduce}_n(d,\tau)$, which represents beginning the cut reduction process above the position $\tau$.%

  As always, we define $\mathrm{Reduce}_n(d,\tau)(\sigma)$ by induction on $\sigma$ while simultaneously defining a partial function $\pi_\tau:\dom(\mathrm{Reduce}_n(d,\tau))\rightarrow\dom(d)$. Initially, we set $\pi_\tau(\langle\rangle)=\tau$.%

If $d(\pi_\tau(\sigma))$ is any rule other than a $\mathrm{Cut}_\phi$ with $rk(\phi)=n$, we set $\mathrm{Reduce}_n(d,\tau)(\sigma)=d(\pi(\sigma))$ and $\pi_\tau(\sigma\iota)=\pi_\tau(\sigma)\iota$ for all $\iota\in|d'(\sigma)|$.

  So suppose $d(\pi_\tau(\sigma))$ is $\mathrm{Cut}_\phi$ with $rk(\phi)=n$. We set $\mathrm{Reduce}_n(d,\tau)(\sigma)=\mathrm{Rep}$ and consider cases on $\phi$. Without loss of generality, we assume $\phi$ is either an atomic formula, a conjunction, or a universal formula. (Otherwise $\phi$ is the negation of such a formula and we apply the same arguments after swapping the input branches.)

  If $\phi$ is an atomic formula $\dot{R}t_1\cdots t_n$ then $\phi$ is either true or false. If $\phi$ is false, we define $\mathrm{Reduce}_n(d,\tau)(\sigma \top\upsilon)=\mathrm{Reduce}_n(d, \pi_\tau(\sigma)L)(\upsilon)$ for all $\upsilon$. If $\phi$ is true, so $\neg \phi$ is false, we define $\mathrm{Reduce}_n(d,\tau)(\sigma\top\upsilon)=\mathrm{Reduce}_n(d, \pi_\tau(\sigma)R)(\upsilon)$.%


  If $\phi$ is a conjunction $\phi_L\wedge\phi_R$ (respectively, a universal $\forall x\,\phi(x)$ or atomic formula $t\in\mu xX.\phi$), we take $\mathrm{Reduce}_n(d,\tau)(\sigma\top\upsilon)$ to be
  \[\mathrm{Elim}^\vee_{\phi_L,\phi_R}(\mathrm{Reduce}_n(d,\tau \pi_\tau(\sigma)R),\mathrm{Reduce}_n(d, \pi_\tau(\sigma)L))(\upsilon)\]
  or
  \[\mathrm{Elim}^\exists_{\phi(x)}(\mathrm{Reduce}_n(d,\pi_\tau(\sigma)R),\mathrm{Reduce}_n(d, \pi_\tau(\sigma)L))(\upsilon)\]
  or
  \[\mathrm{Elim}^\mu_{t\in\mu xX.\phi}(\mathrm{Reduce}_n(d, \pi_\tau(\sigma)R),\mathrm{Reduce}_n(d,\pi_\tau(\sigma) L))(\upsilon).\]
\end{proof}

\subsection{Collapsing}

We define when a $\mu$-expression appears positively or negatively in a formula.
\begin{definition}
  We say $\mu xX.\phi$ \emph{appears positvely} (resp. negatively) in a $\mathcal{L}_\mu$ formula $\psi$ if there are $\psi', Z$ so that $\psi=\psi'[Z\mapsto \mu xX.\phi]$ is a permissible substitution, $Z\in FV(\psi')$ and $Z\in pos(\psi')$ (resp. $Z\in neg(\psi')$).

  We say $\mu xX.\phi$ appears positively (resp. negatively) in a set $\Gamma$ if there is some $\psi$ in $\Gamma$ so that $\mu xX.\phi$ appears positively (resp. negatively) in $\psi$.

  We say $\mu xX.\phi$ appears positively (resp. negatively) in $[\Theta]^{n\in\mu yY.\psi,\epsilon}$ if $\mu xX.\phi$ appears negatively (resp. positively) in $\Theta$.
\end{definition}
Note that $[\Theta]$ ``swaps the polarity'' of occurences---something appears positively in $[\Theta]$ if it appears \emph{negatively} in $\Theta$.

\begin{theorem}\label{thm:id1_collapsing}
  Suppose $d$ is a proof tree in $\mathsf{ID}_{1,<0}^\infty$ so that no $n\in\mu xX.\phi$ appears negatively in $\Gamma(d)$. Then there is a proof tree $\mathcal{D}(d)$ in $\mathsf{ID}^{\infty,+}_1$ with $\Gamma(\mathcal{D}(d))\subseteq\Gamma(d)$.
\end{theorem}
\begin{proof}
  We need to define $\mathcal{D} (d)(\sigma)$ by induction on $|\sigma|$ for all $d$ satisfying the assumptions simultaneously, and we simultaneously define partial functions $\pi_d:\dom(\mathcal{D}(d))\rightarrow \dom(d)$. We also need to ensure that, for all $\sigma\in\dom(\mathcal{D}(d))$ for which $\pi_d(\sigma)$ is defined, $\Gamma(d,\pi_d(\sigma))$ does not contain $n\not\in\mu xX.\phi$ or $[\Sigma]^{n\in\mu xX.\phi,\epsilon}$.  As usual, we set $\pi_d(\langle\rangle)=\langle\rangle$.

  Suppose we have defined $\pi_{d}(\sigma)$. Observe that $d(\pi_d(\sigma))$ cannot be $\mathrm{Read}$ or $\Omega^\flat$. So if $d(\pi_d(\sigma))$ is any rule other than $\mathrm{Cut}\Omega^\flat$, it must be a rule in $\mathsf{ID}^{\infty,+}_1$, so we can set $\mathcal{D} (d)(\sigma)=d(\pi_d(\sigma))$ and, for $\iota\in |\mathcal{D} (d)(\sigma)|$, $\pi_d(\sigma\iota)=\pi_d(\sigma)\iota$.

  So suppose $d(\pi_d(\sigma))=\mathrm{Cut}\Omega^\flat_{n\in\mu xX.\phi}$. We will set $\mathcal{D} (d)(\sigma)=\mathrm{Rep}$ and, for all $\upsilon$, $\mathcal{D} (d)(\sigma\top \upsilon)=\mathcal{D} (\bar d_\bot(\mathcal{D} (d_\top)))(\upsilon)$.   Note that this is well-defined using the inductive hypothesis since $|\upsilon|<|\sigma\top\upsilon|$ and $\mathcal{D} (\bar d_\bot(\mathcal{D} (d_\top)))(\upsilon)$ depends only on $\bar d_\bot(\mathcal{D} (d_\top))(\upsilon')$ with $|\upsilon'|\leq|\upsilon|$, which in turn depends on $\mathcal{D} (d_\top)(\upsilon'')$ for $\upsilon''$ with $|\upsilon''|\leq|\upsilon'|\leq|\upsilon|<|\sigma\top\upsilon|$.
\end{proof}

\subsection{Ordinal Terms}\label{sec:id1_ordinal_terms}

Putting together the results in the previous subsections, we may take a proof in $\mathsf{ID}_1$ whose conclusion does not contain negative occurences of $\mu$ formulas and obtain a proof tree $\mathcal{D} (\mathrm{Reduce}_{n}(\cdots\mathrm{Reduce}_0(d^\infty)\cdots ))$ in $\mathsf{ID}_1^{\infty,+}$ with the same conclusion. In order for this to be of use, we need to ensure that the proof tree we get at the end of this process is actually well-founded.

This is complicated by the fact that $d^\infty$ is typically \emph{not} well-founded. Nevertheless, it has an ordinal bound of a more general sort, and we can extract an ordinal notation which will let us demonstrate this by careful inspection of the proof.

The distinctive feature of the approach to ordinal notations here is the need to give suitable ordinal bounds for $\mathcal{D} (d)$---in particular, when $d(\langle\rangle)=\mathrm{Cut}\Omega^\flat$, we need the ordinal $\mathcal{D} (d)$ to bound the ordinal of $\mathcal{D} (\bar d_\bot(\mathcal{D} (d_\top)))$. This, in turn, requires us to make sense of the ordinal $\bar d_\bot(\mathcal{D} (d_\top))$---that is, to think of $d_\bot$, as being assigned, not an ordinal, but a function on ordinals.

To handle this, we will assign ``ordinal terms'' to nodes in our proof trees. Ordinal terms will be allowed to contain variables---specifically, if $[\Sigma]^{n\in\mu xX.\phi,\epsilon}\in\Gamma(d,\sigma)$ then the ordinal bound at $\sigma$ will be allowed to contain a variable $v_{n\in\mu xX.\phi,\epsilon}$. The symbol $\Omega_1$ (written as just $\Omega$ in this context) acts as a sort of ``meta-variable'' that bounds all other variables.








\begin{definition}\label{ref:ordinal_terms_id1}
We define several notions simultaneously---we will define the ordinal terms, $\mathrm{OT}$, together with some special classes of ordinal terms $\mathbb{V}\subseteq\mathbb{SC}\subseteq\mathbb{H}\subseteq\mathrm{OT}$, and the notion of a free variable.

The \emph{ordinal terms}, $\mathrm{OT}$, are given as follows:
\begin{enumerate}
\item if $\{\alpha_0,\ldots,\alpha_{n-1}\}$ is a finite multi-set of ordinal terms in $\mathbb{H}$ and $n\neq 1$ then $\#\{\alpha_0,\ldots,\alpha_{n-1}\}$ is an ordinal term,
\item $\Omega$ is an ordinal term in $\mathbb{V}$,
\item for any $n\in\mu xX.\phi,\epsilon$, $v_{n\in\mu xX.\phi,\epsilon}$ are ordinal terms in $\mathbb{V}$,
\item if $\alpha$ is an ordinal term then $\omega^\alpha$ is an ordinal term in $\mathbb{H}$,
\item if $\alpha$ is an ordinal term with $FV(\alpha)\subseteq\{\Omega\}$ then $\vartheta\alpha$ is an ordinal term in $\mathbb{SC}$.
\end{enumerate}

We define the free variables in a term:
\begin{itemize}
\item $FV(\#\{\alpha_i\})=\bigcup_iFV(\alpha_i)$,
\item $FV(\Omega)=\{\Omega\}$,
\item $FV(v_{n\in\mu xX.\phi,\epsilon})=\{v_{n\in\mu xX.\phi,\epsilon}\}$,
\item $FV(\omega^\alpha)=FV(\alpha)$,
\item $FV(\vartheta\alpha)=FV(\alpha)\setminus\{\Omega\}$.
\end{itemize}
We say $\alpha$ is closed if $FV(\alpha)=\emptyset$.



We define the ordering on ordinal terms by:
\begin{itemize}
\item $\#\{\alpha_0,\ldots,\alpha_{m-1}\}<\#\{\beta_0,\ldots,\beta_{n-1}\}$ if there is a $\gamma\in \{\beta_0,\ldots,\beta_{n-1}\}\setminus \{\alpha_0,\ldots,\alpha_{m-1}\}$ so that, for all $\delta\in \{\alpha_0,\ldots,\alpha_{m-1}\}\setminus \{\beta_0,\ldots,\beta_{n-1}\}$, $\delta<\gamma$,
\item when $\beta\in\mathbb{H}$, $\#\{\alpha_0,\ldots,\alpha_{m-1}\}<\beta$ if, for each $i$, $\alpha_i<\beta$,
\item when $\beta\in\mathbb{H}$, $\beta<\#\{\alpha_0,\ldots,\alpha_{m-1}\}$ if there is some $i$ so that $\beta\leq\alpha_i$,
\item $\omega^\alpha<\omega^\beta$ if $\alpha<\beta$,
\item if $\gamma\in\mathbb{SC}$ then $\omega^\alpha<\gamma$ if $\alpha<\gamma$,
\item if $\gamma\in\mathbb{SC}$ then $\gamma<\omega^\alpha$ if $\gamma\leq \alpha$,
\item $\vartheta\alpha<\vartheta\beta$ if either:
  \begin{itemize}
  \item $\alpha<\beta$ and for all $\gamma\in K\alpha$, $\gamma<\vartheta\beta$,
  \item $\beta<\alpha$ and there is a $\gamma\in K\alpha$ so that $\vartheta\beta\leq\gamma$.
  \end{itemize}
\item $\vartheta\alpha<v_{m\in\mu xX.\phi,\epsilon}$,
\item $\vartheta\alpha<\Omega$,
\item $v_{m\in\mu xX.\phi,\epsilon}<v_{n\in\mu yY.\psi,\epsilon'}$ if and only if $m\in\mu xX.\phi$ and $n\in\mu yY.\psi$ are identical and $\epsilon'\sqsubset\epsilon$,
\item $v_{m\in\mu xX.\phi,\epsilon}<\Omega$.
\end{itemize}

We define $K\alpha$ by:
\begin{itemize}
\item $K\#\{\alpha_0,\ldots,\alpha_{n-1}\}=\bigcup_i K\alpha_i$,
\item $K\Omega=\emptyset$,
\item $Kv_{n\in\mu xX.\phi,\epsilon}=\emptyset$,
\item $K\omega^\alpha=K\alpha$,
\item $K\vartheta\alpha=\{\vartheta\alpha\}$.
\end{itemize}


We say $\alpha\ll_\gamma\beta$ if $\alpha<\beta$ and, for all $\delta\in K\alpha$, we have $\delta<\max\{\vartheta\beta,\gamma\}$.







\end{definition}

We adopt the abbreviation $0$ for $\#\emptyset$, and give $\alpha\#\beta$ the natural interpretation---if $\alpha,\beta\in\mathbb{H}$ then $\alpha\#\beta$ is $\{\alpha,\beta\}$; if $\alpha=\#\{\alpha_0,\ldots,\alpha_{n-1}\}$ then $\alpha\#\beta$ is $\#\{\alpha_0,\ldots,\alpha_{n-1},\beta\}$, and similarly if $\beta\not\in\mathbb{H}$. When $k$ is finite, we write $\alpha\cdot k$ for the $\#$ sum of $k$ copies of $\alpha$.







\begin{definition}
  When $\gamma$ is closed in $\mathbb{SC}$, we define $\vartheta_\gamma(\alpha)=\vartheta(\omega^{\Omega\#\alpha}\#\gamma)$.
\end{definition}

\begin{lemma}
  If $\alpha\ll_\gamma\beta$ with $FV(\alpha)\cup FV(\beta)\subseteq\{\Omega\}$ then we have $\vartheta_\gamma(\alpha)<\vartheta_\gamma(\beta)$.
\end{lemma}
\begin{proof}
  We have $\omega^{\Omega\#\alpha}\#\gamma<\omega^{\Omega\#\beta}\#\gamma$, so consider some $\vartheta\zeta\in K(\omega^{\Omega\#\alpha}\#\gamma)=K\gamma\cup K\alpha$. We must show that $\vartheta\zeta<\vartheta_\gamma(\beta)$.

  If $\vartheta\zeta\in K\gamma$ then we have $\vartheta\zeta\in K(\omega^{\Omega\#\beta}\#\gamma)$, and therefore $\vartheta\zeta<\vartheta_\gamma(\beta)$. So we may assume $\vartheta\zeta\in K\alpha$ with $\gamma<\vartheta\zeta$ (since, similarly, $\gamma<\vartheta_\gamma(\beta)$). We have $\vartheta\zeta<\vartheta\beta<\vartheta(\omega^{\Omega\#\beta}\#\gamma)$, as needed.
\end{proof}

We define substitution of free variables other than $\Omega$ in the usual way. We write $\alpha[v\mapsto \beta]$ for replacing the variable $v$ with $\beta$, and when $f$ is a function from variables to ordinal terms, we simply write $\alpha[f]$ to indicate replacing each $v\in\dom(f)$ with $f(x)$. We always assume that such substitutions are order-preserving.

\begin{lemma}
  If $\alpha\ll_\gamma\beta$ and $f$ is a substitution whose range is $\leq\delta$ where $\delta$ is closed then $\alpha[f]\ll_{\max\{\gamma,\delta\}}\beta[f]$.
\end{lemma}
\begin{proof}
  First we show that $\alpha[f]<\beta[f]$ by induction on $\alpha$ and $\beta$. Most cases follow immediately from either the inductive hypothesis or the fact that $f$ is order-preserving, as well as the fact that we don't make further substitutions inside a $\vartheta\alpha'$ subterm.

Now consider some $\theta\in K\alpha[f]$; we have $\theta\in K\alpha\cup\rng(f)$, so $\theta<\max\{\vartheta\beta,\gamma,\delta\}$.
\end{proof}



\begin{lemma}\label{thm:id1_D_bound}
  Suppose $\alpha\ll_\gamma\beta$ with $FV(\alpha)\cup FV(\beta)\subseteq\{\Omega\}$ and suppose $\delta\ll_\gamma\beta$ with $FV(\delta)\subseteq\{\Omega,v\}$. Then $\vartheta_{\vartheta_\gamma(\alpha)}(\delta[v\mapsto \vartheta_\gamma(\alpha)])<\vartheta_\gamma(\beta)$.
\end{lemma}
\begin{proof}
  Since $\delta[v\mapsto \vartheta_\gamma(\alpha)]<\beta$ by the previous lemma, we have $\omega^{\Omega\#\delta[v\mapsto \vartheta_\gamma(\alpha)]}\#\vartheta_{\gamma}(\alpha)<\omega^{\Omega\#\beta}\#\gamma$ as needed.


  We also have $\vartheta_\gamma(\alpha)<\vartheta_\gamma(\beta)$. If $\zeta\in K(\omega^{\Omega\#\delta[v\mapsto \vartheta_\gamma(\alpha)]}\#\vartheta_\gamma(\alpha))$ then either $\zeta=\vartheta_\gamma(\alpha)<\vartheta_\gamma(\beta)$ or $\zeta\in K(\delta[v\mapsto \vartheta_\gamma(\alpha)])$, so $\zeta\in K\delta\cup\{\vartheta_\gamma(\alpha)\}$ (because $v$ cannot appear in an element of $K\delta$), so again $\zeta<\vartheta_\gamma(\beta)$.
\end{proof}













\begin{definition}

When $d$ is a proof tree in $\mathsf{ID}_1^{\infty}$, an \emph{ordinal bound above $\gamma$} on $d$ is a function $o^d:\dom(d)\rightarrow \mathrm{OT}$ such that
  \begin{itemize}
  \item for all $\sigma\in\dom(d)$, if $v_{n\in\mu xX.\phi,\epsilon}\in FV(o^d(\sigma))$ then $[\Theta]^{n\in\mu xX.\phi,\epsilon}\in\Gamma(d,\sigma)$ for some $\Theta$,
  \item if $\sigma\sqsubset\tau$ then $o^d(\tau)\ll_\gamma o^d(\sigma)$.
  \end{itemize}

  We say $d$ \emph{is bounded by $\alpha$ above $\gamma$} if there is an ordinal bound above $\gamma$, $o^d$, with $o^d(\langle\rangle)\lleq_\gamma\alpha$.%

\end{definition}
Note that when $d$ is bounded by $\alpha$ with $\alpha$ closed, the range of $o^d$ must be closed terms, and $\ll$ is equivalent to $<$. In this case we may simply say $d$ is bounded by $\alpha$.


\begin{lemma}
  Let $F$ be bounded by $\alpha$ above $\gamma$ and let $d$ be bounded by a closed ordinal term $\beta$ above $\gamma$. Then $\bar F(d)$ is bounded by $\alpha[v_{n\in\mu xX.\phi,\langle\rangle}\mapsto\beta]$ above $\max\{\gamma,\beta\}$.

\end{lemma}
\begin{proof}
  For each $\sigma$, we define $o^{\bar F(d)}(\sigma)=o^{F}(h(\sigma))[v_{n\in\mu xX.\phi,\epsilon}\mapsto o^d(\epsilon)]$.

  Consider any $\sigma\sqsubset\tau$. We have $o^{\bar F(d)}(\sigma)=o^F(h(\sigma)) [v_{n\in\mu xX.\phi,\epsilon}\mapsto o^d(\epsilon)]\ll_{\max\{\gamma,\beta\}}o^F(h(\tau)) [v_{n\in\mu xX.\phi,\epsilon}\mapsto o^d(\epsilon)]=o^{\bar F(d)}(\tau)$.
\end{proof}



\subsection{Ordinal Bounds}

\begin{lemma}
  The proof tree $d_{n\in\mu xX.\phi}$ given by Lemma \ref{thm:identity} is bounded by $\Omega$.
\end{lemma}
\begin{proof}
  We define $o^{d_{n\in\mu xX.\phi}}(\langle\rangle)=\Omega$.  Given $\sigma$ such that $d_{n\in\mu xX.\phi}(\sigma)=\mathrm{Read}^{\mathsf{ID}_1^{\infty,+}}_{[n\in\mu xX.\phi]^{n\in\mu xX.\phi,\epsilon}}$, we set $o^{d_{n\in\mu xX.\phi}}(\sigma)=v_{n\in\mu xX.\phi,\epsilon}\#1$ and, for each $\mathcal{R}$, $o^{d_{n\in\mu xX.\phi}}(\sigma\mathcal{R})=v_{n\in\mu xX.\phi,\epsilon}$.
\end{proof}

\begin{lemma}
For any $\phi$, the proof tree $d_\phi$ given by Lemma \ref{thm:ax} is bounded by $\Omega\# (rk(\phi)\cdot 2)$.
\end{lemma}
\begin{proof}
  A straightforward induction on $\phi$.
\end{proof}

\begin{lemma}\label{thm:substitution_bound}
  The proof tree $\mathrm{Subst}^{n \in \mu xX. \phi\mapsto \psi(n)}$ given by Lemma \ref{thm:substitution} is bounded by $\Omega\# rk(\psi)\cdot 2\# v_{n\in \mu xX.\phi,\langle\rangle}\# 2$ above $0$.
\end{lemma}
\begin{proof}
  We construct an ordinal bound $o^{\mathrm{Subst}^{n \in \mu xX. \phi\mapsto \psi(n)}}$ on $\dom(\mathrm{Subst}^{n \in \mu xX. \phi\mapsto \psi(n)})$ as follows.

  For any $\sigma$ such that $\mathrm{Subst}^{n \in \mu xX. \phi\mapsto \psi(n)}(\sigma)=\mathrm{Read}^{\mathsf{ID}_1^{\infty,+}}_{[\Theta_\sigma[Z\mapsto \mu xX.\phi]]^{n\in\mu xX.\phi,\epsilon,r}}$, we set $o^{\mathrm{Subst}^{n \in \mu xX. \phi\mapsto \psi(n)}}(\sigma)=rk(\psi)\cdot 2\# v_{n\in\mu xX.\phi,\epsilon}\# 2$. If $\mathcal{R}$ is any rule other than $\mathrm{Cl}_{k\in\mu xX.\phi}$ with $Z k\in\Theta_\sigma$ then we may assign $o^{\mathrm{Subst}^{n \in \mu xX. \phi\mapsto \psi(n)}}(\sigma\ulcorner\mathcal{R}\urcorner)=rk(\psi)\# v_{n\in\mu xX.\phi,\epsilon}$. (Since we have assigned $o^{\mathrm{Subst}^{n \in \mu xX. \phi\mapsto \psi(n)}}(\sigma\ulcorner\mathcal{R}\urcorner\iota)=rk(\psi)\# v_{n\in\mu xX.\phi,\epsilon\iota}\# 2$, the comparison is satisfied.)

  If $\mathcal{R}=\mathrm{Cl}_{k\in\mu xX.\phi}$ with $Z k\in\Theta_\sigma$ then we may set (recall that, above $\sigma\ulcorner\mathcal{R}\urcorner$, we have the proof tree shown in the proof of Lemma \ref{thm:substitution}):
  \begin{itemize}
  \item  $o^{\mathrm{Subst}^{n \in \mu xX. \phi\mapsto \psi(n)}}(\sigma\ulcorner\mathcal{R}\urcorner)=rk(\psi)\# v_{n\in\mu xX.\phi,\epsilon}\# 1$,
  \item $o^{\mathrm{Subst}^{n \in \mu xX. \phi\mapsto \psi(n)}}(\sigma\ulcorner\mathcal{R}\urcorner\top)=rk(\psi)\# v_{n\in\mu xX.\phi,\epsilon}$
  \item $o^{\mathrm{Subst}^{n \in \mu xX. \phi\mapsto \psi(n)}}(\sigma\ulcorner\mathcal{R}\urcorner\top \mathrm{R}\upsilon)=o^{d_{\psi(k)}}(\upsilon)$.
  \end{itemize}
  The branch $o^{\mathrm{Subst}^{n \in \mu xX. \phi\mapsto \psi(n)}}(\sigma\ulcorner\mathcal{R}\urcorner\top \mathrm{L})$ is handled as above since $\mathrm{Subst}^{n \in \mu xX. \phi\mapsto \psi(n)}(\sigma\ulcorner\mathcal{R}\urcorner\top \mathrm{L})$ is a $\mathrm{Read}$ rule.
\end{proof}

\begin{lemma}
  For any $d$ in $\mathsf{ID}_1$, the proof tree $d^\infty$ given by Theorem \ref{thm:id1_embedding} is bounded by $\Omega\cdot 2\# \omega\# n$ above $0$ for some natural number $n$.
\end{lemma}
\begin{proof}
  We define $o^{d^\infty}$ by induction on $d$. Since $d$ is finite, the induction is straightforward. In the base cases, a bound can be constructed directly or by using the previous lemma.
\end{proof}

\begin{lemma}
  \begin{enumerate}
  \item If $d$ is bounded by $\alpha$ above $\gamma$ then $\mathrm{Inverse}^\wedge_{\phi_L,\phi_R,i}(d)$ is bounded by $\alpha$ above $\gamma$.
  \item If $d$ is bounded by $\alpha$ above $\gamma$ then $\mathrm{Inverse}^\forall_{\phi(y),m}(d)$ is bounded by $\alpha$ above $\gamma$.
  \item If $d_\wedge$ is bounded by $\alpha$ above $\gamma$ and $d_\vee$ is bounded by $\beta$ above $\gamma$ then $\mathrm{Elim}^\vee_{\phi_L,\phi_R}(d_\vee,d_\wedge)$ is bounded by $\alpha\# \beta$ above $\gamma$.
  \item If $d_\forall$ is bounded by $\alpha$ above $\gamma$ and $d_\exists$ is bounded by $\beta$ above $\gamma$ then $\mathrm{Elim}^\forall_{\phi(y)}(d_\exists,d_\forall)$ is bounded by $\alpha\# \beta$ above $\gamma$.
  \item If $d_\mu$ is bounded by $\alpha$ above $\gamma$ and $d_\neg$ is bounded by $\beta$ above $\gamma$ then $\mathrm{Elim}^\mu_{n\in\mu xX.\phi}(d_\mu,d_\neg)$ is bounded by $\alpha\# \beta$ above $\gamma$.
  \item If $d$ is bounded by $\alpha$ above $\gamma$ then $\mathrm{Reduce}_n(d)$ is bounded by $\omega^\alpha$ above $\gamma$.
  \end{enumerate}
\end{lemma}
\begin{proof}
  For (1), we may take $o^{\mathrm{Inverse}^\wedge_{\phi_L,\phi_R, i}(d)}(\sigma)=o^d(\pi(\sigma))$. Similarly for (2).

  For (3), when $\pi(\sigma)$ is defined, we again set $o^{\mathrm{Elim}^\vee_{\phi_L,\phi_R}(d_\vee,d_\wedge)}(\sigma)=\alpha+o^{d_\vee}(\pi(\sigma))$. If $\pi(\sigma)$ is not defined then $\sigma$ has the form $\sigma' L\upsilon$ where $d_\vee(\pi(\sigma'))$ is $\vee\mathrm{I}^i_{{\sim}\phi_L\vee{\sim}\phi_R}$ and $\upsilon\in\dom(d_\wedge)$; in this case we set $o^{\mathrm{Elim}^\vee_{\phi_L,\phi_R}(d_\vee,d_\wedge)}(\sigma' L\upsilon)=o^{d_\wedge}(\upsilon)$. (4) and (5) are similar.

  For (6), we need to define $o^{\mathrm{Reduce}_n(d,\tau)}$ for all $\tau$ simultaneously. When $\pi_\tau(\sigma)$ is defined, we will take $o^{\mathrm{Reduce}_n(d,\tau)}(\sigma)=\omega^{o^d(\pi_\tau(\sigma))}$. Since $\alpha\ll_\gamma\beta$ implies $\omega^\alpha\ll_\gamma\omega^\beta$, this immediately ensures the order preserving property when $d(\pi_\tau(\sigma))$ is anything other than $\mathrm{Cut}_\phi$ with $rk(\phi)=n$.

  If $d(\pi_\tau(\sigma))$ is $\mathrm{Cut}_\phi$ with $rk(\phi)=n$, if $\phi$ is $\dot{R}t_1\cdots t_n$ then we take $o^{\mathrm{Reduce}_n(d,\tau)}(\sigma \top\upsilon)=o^{\mathrm{Reduce}_n(d,\pi_\tau(\sigma) b)}(\upsilon)$ for all $\upsilon$ (with $b=\top$ if $\phi$ is false and $b=\bot$ if $\phi$ is true). Since $o^{\mathrm{Reduce}_n(d,\tau) }(\sigma \top)=o^{\mathrm{Reduce}_n(d,\pi_\tau(\sigma) b)}(\langle\rangle)=\omega^{o^d(\pi_\tau(\sigma) b)}\ll_\gamma \omega^{o^d(\tau)}=o^{\mathrm{Reduce}_n(d,\tau)}(\sigma)$, the order preserving property holds. (The case where $\phi$ is $\neg\dot{R}t_1\cdots t_n$ is identical.)

  If $\phi$ is a conjunction, we take $o^{\mathrm{Reduce}_n(d,\tau)}(\sigma \top\upsilon)=o^{\mathrm{Elim}^\vee_{\phi_L,\phi_R}(\mathrm{Reduce}_n(d,\pi_\tau(\sigma) R),\mathrm{Reduce}_n(d,\pi_\tau(\sigma) L))}(\upsilon)$. We have
  \begin{align*}
    o^{\mathrm{Reduce}_n(d,\tau)}(\sigma\top)
    &=o^{\mathrm{Elim}^\vee_{\phi_L,\phi_R}(\mathrm{Reduce}_n(d,\pi_\tau(\sigma) R),\mathrm{Reduce}_n(d,\pi_\tau(\sigma) L))}(\langle\rangle)\\
    &=o^{\mathrm{Reduce}_n(d,\pi_\tau(\sigma) L)}(\langle\rangle)+o^{\mathrm{Reduce}_n(d,\pi_\tau(\sigma) R)}(\langle\rangle)\\
    &=\omega^{o^d(\pi_\tau(\sigma) L)}\#\omega^{o^d(\pi_\tau(\sigma) R)}\\
    &\ll_\gamma\omega^{o^d(\pi_\tau(\sigma))}\\
    &=o^{\mathrm{Reduce}_n(d,\tau)}(\sigma)
  \end{align*}
  as needed.
\end{proof}

\begin{lemma}\label{thm:id1_collapsing_ordinal}
  If $d$ is bounded by $\alpha$ above $\gamma$ then $D(d)$ is bounded by $\vartheta_\gamma(\alpha)$.
\end{lemma}
\begin{proof}
  When $\pi_d(\sigma)$ is defined, we set $o^{D(d)}(\sigma)=\vartheta_\gamma(o^d(\pi_d(\sigma)))$. When $d(\pi_d(\sigma))$ is not a $\mathrm{Cut}\Omega^\flat$, we have $o^d(\pi_d(\sigma\iota))\ll_\gamma o^d(\pi_d(\sigma))$, so also $o^{D(d)}(\sigma\iota)=\vartheta_\gamma(o^d(\pi_d(\sigma\iota)))< \vartheta_\gamma (o^d(\sigma))=o^{D(d)}(\sigma)$.

  When $d(\pi_d(\sigma))$ is a $\mathrm{Cut}\Omega^\flat$ rule, observe that $\bar d_\bot(D(d_\top))$ is bounded by $o^{d}(\pi_d(\sigma)\bot)[v_{n\in\mu xX.\phi,\langle\rangle}\mapsto \vartheta_\gamma(o^d(\pi_d(\sigma)\top))]$ above $\vartheta_\gamma(o^d(\pi_d(\sigma)\top))$, and therefore we may set
  \[o^{D(d)}(\sigma\top\upsilon)=\vartheta_{\vartheta_\gamma(o^d(\pi_d(\sigma)\top))}\left(o^{d}(\pi_d(\sigma)\bot\upsilon)[v_{n\in\mu xX.\phi,\langle\rangle}\mapsto \vartheta_\gamma(o^d(\pi_d(\sigma)\top))]\right).\]
  By Lemma \ref{thm:id1_D_bound}, we have $o^{D(d)}(\sigma\top)<o^{D(d)}(\sigma)$ as needed.
\end{proof}

\begin{theorem}
  If $d$ is a proof in $\mathsf{ID}_1$ whose conclusion does not contain negative occurences of $\mu xX.\phi$ then there is a proof tree $d'$ in $\mathsf{ID}_{1,<0}^{\infty,+}$ with $\Gamma(d')\subseteq\Gamma(d)$ bounded by $\vartheta \omega_k^{\Omega\cdot 2\#\omega\#n}$ for some finite $k,n$.
\end{theorem}



\section{Cut-Elimination for $\mathsf{ID}_{<\omega}$}

We can extend these methods to $\mathsf{ID}_{<\omega}$ with only a little more effort. That is, we now allow $\mu xX.\phi$ for formulas $\phi$ which themselves contain $\mu yY.\psi$ subexpressions, but we do not allow $X$ to occur free in such subexpressions.

\subsection{Infinitary Theory}

The new complication can be seen in $\mathsf{ID}_2$. In the previous section, we only applied functions to proof trees in which $\mu xX.\phi$ appeared positively---in particular, where the input proof tree did not itself contain functions.

Now, however, we might apply a function to a proof of $\mu xX. \phi(\mu yY. \psi)$ which itself contains a proof of $n\not\in\mu yY.\psi$, necessarily derived by applying an $\Omega^\flat$ rule to proof tree representing a function.



We will want to restrict ourselves to formulas in $\mathcal{L}^1_\mu$, which would lead us to a problem when defining the $\mathrm{Read}$ rule for proofs of $\mu xX.\phi(\mu yY.\psi)$. To address this, we need to modify the $\mathrm{Read}$ rule slightly.


{\tiny
\AxiomC{$\Delta(\mathcal{R})\setminus\Theta, \{[\Theta']^{n\in\mu xX.\phi,\epsilon\iota}\mid \iota\in|\mathcal{R}|, \Theta\subseteq\Theta'\}$\quad $(\mathcal{R}\in\mathfrak{T})$}
\AxiomC{$m\in\mu yY.\psi$ \quad $(m\not\in\mu yY.\psi\in\Theta, \Omega^\flat_{m\not\in\mu yY.\psi}\not\in\mathfrak{T})$}
\LeftLabel{$\mathrm{Read}^{\mathfrak{T}}_{[\Theta]^{n\in\mu xX.\phi,\epsilon}}$}
\BinaryInfC{$\Delta(\epsilon)\setminus\Theta,[\Theta]^{n\in\mu xX.\phi,\epsilon}$}
\DisplayProof}

That is, we will now sometimes have $m\not\in\mu yY.\psi\in\Theta$ while $\Omega^\flat_{m\not\in\mu yY.\psi}$ is not in the theory $\mathfrak{T}$; in this case, we need some special handling in the definition of $\bar F$, and we record a proof of $m\in\mu yY.\psi$ in an extra branch to support this.

We consider these new branches to be labeled by the conclusion $\ulcorner m\in\mu yY.\psi\urcorner$, so $|\mathrm{Read}^{\mathfrak{T}}_{[\Theta]^{n\in\mu xX.\phi,\epsilon}}|=\mathfrak{T}\cup\{m\in\mu xX.\phi\mid m\not\in\mu xX.\phi\in\Theta\text{ and }\Omega^\flat_{m\not\in\mu xX.\phi}\not\in\mathfrak{T}\}$ (with $\ulcorner \cdot\urcorner$ braces attached to all elements).





We therefore need a hierarchy of infinitary theories. All formulas in all these theories are $\mathsf{ID}_{<\omega}$ formulas.
\begin{itemize}
\item the base theory $\mathsf{ID}_0^\infty=\mathsf{ID}_0^{\infty,+}$ contains True, $\mathrm{Cut}$ over formulas of depth $0$, $\wedge\mathrm{I}$, $\vee^L\mathrm{I}$, $\vee^R\mathrm{I}$, $\omega$, $\exists\mathrm{I}$, $\mathrm{Cl}$, and Rep for $\mathsf{ID}_{<\omega}$ formulas.
\item $\mathsf{ID}_{c+1}^{\infty,+}$ extends $\mathsf{ID}_c^{\infty,+}$ by
  \begin{itemize}
  \item $\mathrm{Cut}$ for formulas of depth $c+1$,
  \item $\Omega^\flat_{n\not\in\mu xX.\phi}$ where $\phi$ has depth $c$,
  \item $\mathrm{Read}^{\mathsf{ID}_{0,<0}^{\infty,+}}_{[\Theta]^{n\in\mu xX.\phi,\epsilon}}$ rules where $\Theta\subseteq\mathcal{L}_\mu$ and $\phi$ has depth $c$,
  \end{itemize}
\item $\mathsf{ID}_{c+1}^\infty$ extends $\mathsf{ID}_c^{\infty}$ by $\mathrm{Cut}\Omega^\flat_{n\not\in\mu xX.\phi}$ where $\phi$ has depth $c$.
\end{itemize}

Note that this definition of $\mathrm{ID}^{\infty}_1$ does not quite match that in the previous section.


\subsection{Ordinal Terms}

We give this section as a somewhat informal extension of Section \ref{sec:id1_ordinal_terms}, since we will give a more formal account (of a larger system) later.

\begin{definition}
  \begin{enumerate}
  \item if $\{\alpha_0,\ldots,\alpha_{n-1}\}$ is a finite multi-set of ordinal terms in $\mathbb{H}$ and $n\neq 1$ then $\#\{\alpha_0,\ldots,\alpha_{n-1}\}$ is an ordinal term,
  \item for $c>0$, $\Omega_c$ is an ordinal term in $\mathbb{C}$,
  \item for any $n\in\mu xX.\phi,\epsilon$, $v_{n\in\mu xX.\phi,\epsilon}$ are ordinal terms in $\mathbb{V}_c$ where $c=dp(\mu xX.\phi)$,
  \item for any $\mu xX.\phi$, $v_{\mu xX.\phi}$ is an ordinal term in $\mathbb{C}$,
  \item if $\alpha$ is an ordinal term then $\omega^\alpha$ is an ordinal term in $\mathbb{H}$,
  \item if $c>0$ and $\alpha$ is an ordinal term with $FV_c(\alpha)=\emptyset$ then $\vartheta_c\alpha$ is an ordinal term in $\mathbb{SC}$.
  \end{enumerate}

  We define $FV_c(\alpha)$ to be those terms from $\bigcup_{c'\geq c}\mathbb{V}_c$ appearing in $\alpha$. We have $(\mathbb{C}\cup\bigcup_c\mathbb{V}_c)\subseteq\mathbb{SC}\subseteq\mathbb{H}$.
\end{definition}


\begin{definition}
  For $0<c$, $K_c\alpha$ is defined inductively by:
  \begin{itemize}
  \item $K_c\#\{\alpha_0,\ldots,\alpha_{n-1}\}=\bigcup_i K_c\alpha_i$,
  \item $K_c\Omega_{c'}=\left\{\begin{array}{ll}
                                 \{\Omega_{c'}\}&\text{if }c'< c\\
                                 \emptyset&\text{if }c\leq c'
                               \end{array}\right.$,
  \item $K_cv_{n\in\mu xX.\phi,\epsilon}=\left\{\begin{array}{ll}
                                 \{v_{n\in\mu xX.\phi,\epsilon}\}&\text{if }dp(\mu xX.\phi)< c\\
                                 \emptyset&\text{if }c\leq c'
                               \end{array}\right.$,
  \item $K_cv_{\mu xX.\phi}=\left\{\begin{array}{ll}
                                 \{v_{\mu xX.\phi}\}&\text{if }dp(\mu xX.\phi)\leq c\\
                                 \emptyset&\text{if }c< c'
                               \end{array}\right.$,
  \item $K_c\omega^\alpha=K_c\alpha$,
  \item $K_c\vartheta_{c'}\alpha=\left\{\begin{array}{ll}
                                          \{\vartheta_{c'}\alpha\}&\text{if }c'\leq c\\
                                          K_c\alpha&\text{if }c<c'
                                          \end{array}\right.$
  \end{itemize}

\end{definition}

The order is defined as before, noting that:
\begin{itemize}
\item $\Omega_{c'}<\Omega_c$ exactly when $c'<c$,
\item for $v\in\mathbb{V}_{c'}$, $v<\Omega_c$ if and only if $c'\leq c$,
\item for $v\in\mathbb{V}_{c'}$, $\Omega_c<v$ if and only if $c<c'$,
\item when $dp(\mu xX.\phi)=c$, $v_{\mu xX.\phi}<\Omega_c$,
\item when $dp(\mu xX.\phi)=c$ and $c'<c$, $\Omega_{c'}<v_{\mu xX.\phi}$,
\item $\vartheta_{c'}\alpha<\Omega_c$ if and only if $c'\leq c$,
\item $\Omega_c<\vartheta_{c'}\alpha$ if and only if $c<c'$.
\end{itemize}

The following definition is slightly stronger than the usual one, but useful for our purposes.
\begin{definition}
  We write $\alpha\ll^c_\gamma\beta$ if $\alpha<\beta$ and, for each $c'\leq c$ and all $\delta\in K_{c'}\alpha$, there is some $\theta\in K_{c'}\beta\cup K_{c'}\gamma$ with $\delta\leq\theta$.

  When $c=0$, we take $\ll^c_\gamma$ to simply be $<$.
\end{definition}

\begin{lemma}
  If $FV_c(\gamma)=FV_c(\delta)=\emptyset$, $\gamma,\delta<\Omega_c$, $\alpha\ll^c_\gamma\beta$, and $f:\mathbb{V}_c\rightarrow\mathbb{SC}$ is order-preserving (from $<$ to $\ll^{c-1}_0$) and has range $\lleq^{c-1}_0$-bounded by $\delta$ then $\alpha[f]\ll^c_{\gamma\#\delta}\beta[f]$.
\end{lemma}
\begin{proof}
  First we show that $\alpha[f]<\beta[f]$ by induction. The main case is when $\alpha=\vartheta_{c'}\alpha'$ and $\beta=\vartheta_{c'}\beta'$.

  If $c'\leq c$ then $\alpha',\beta'$ may not contain any elements of $\mathbb{V}_c$, so $\alpha[f]=\alpha$ and $\beta[f]=\beta$, so $\alpha<\beta$ immediately implies $\alpha[f]<\beta[f]$.

  So suppose $c<c'$. Say $\alpha'<\beta'$; by the inductive hypothesis, $\alpha'[f]<\beta'[f]$ as well. If $\zeta\in K_{c'}\alpha'[f]$ then either $\zeta=\zeta'[f]$ with $\zeta'\in K_{c'}\alpha'$ or $\zeta=\theta$ for some $\theta\in\rng(f)$. In the former case, the inductive hypothesis applies since $\zeta<\vartheta_{c'}\beta'$. In the latter case, we have $\theta\leq\delta<\Omega_c$, so $\theta<\vartheta_{c'}\beta'[f]$, as needed.

  Otherwise, $\beta'<\alpha'$, and again by the inductive hypothesis, $\beta'[f]<\alpha'[f]$. There is a $\zeta\in K_{c'}\alpha'$ so that $\vartheta_{c'}\beta'\leq \zeta$, and then by the inductive hypothesis, $\vartheta_{c'}\beta'[f]\leq\zeta[f]$.

  Now we strengthen this to $\alpha[f]\ll^c_{\max\{\gamma,\delta\}}\beta[f]$. Take $c'\leq c$ and suppose $\delta\in K_{c'}\alpha[f]$. Then $\delta\in K_{c'}\alpha\cup \bigcup_v K_{c'}f(v)$, and so is bounded by $K_{c'}\beta\cup K_{c'}\gamma\cup K_{c'}\delta$.
\end{proof}

\begin{definition}
  $\vartheta_{c,\gamma}(\alpha)=\vartheta_c(\omega^{\Omega_c\#\alpha}\#\gamma)$.
\end{definition}

\begin{lemma}
  When $FV_c(\gamma)=\emptyset$, $\gamma<\Omega_c$, $\gamma\in\mathbb{SC}$ and $\alpha\ll^c_\gamma\beta$ with $FV_c(\alpha)\cup FV_c(\beta)=\emptyset$, we have $\vartheta_{c,\gamma}(\alpha)\ll^{c-1}_0\vartheta_{c,\gamma}(\beta)$.
\end{lemma}
\begin{proof}
  We certainly have $\omega^{\Omega_c\#\alpha}\#\gamma<\omega^{\Omega_c\#\beta}\#\gamma$.

  Consider $\vartheta_c\zeta\in K_c(\omega^{\Omega_c\#\alpha}\#\gamma)=K\alpha\cup K\gamma$. Then this is bounded by some element of $K_c\beta\cup K_c\gamma$, and therefore by $\vartheta_{c,\gamma}(\beta)$.

  Now consider $\zeta\in K_{c'}\vartheta_{c,\gamma}(\alpha)$ with $c'<c$. We have $\zeta\in K_{c'}\alpha\cup K_{c'}\gamma$ as well, so again this is bounded in $K_{c'}\vartheta_{c,\gamma}(\beta)=K_{c'}\beta\cup K_{c'}\gamma$.
\end{proof}

\begin{lemma}
  When $FV_c(\gamma)=\emptyset$, $\gamma<\Omega_c$, $\gamma\in\mathbb{SC}$, $\alpha\ll^c_\gamma\beta$, $\delta\ll^c_\gamma\beta$ with $FV_c(\alpha)\cup FV_c(\beta)=\emptyset$ and $FV_c(\delta)\subseteq\{v\}$ where $v\in\mathbb{V}_c$, we have $\vartheta_{c,\vartheta_{c,\gamma}(\alpha)}(\delta[v\mapsto\vartheta_{c,\gamma}(\alpha)])\ll^{c-1}_0\vartheta_{c,\gamma}(\beta)$.
\end{lemma}
\begin{proof}
  Observe that $\delta[v\mapsto\vartheta_{c,\gamma}(\alpha)]<\beta$, since $\delta<\beta$.  Therefore we also have $\omega^{\Omega_c\#\delta[v\mapsto\vartheta_{c,\gamma}(\alpha)]}\#\gamma<\omega^{\Omega_c\#\beta}\#\gamma$.

  Any $\zeta\in K_{c} \omega^{\Omega_c\#\delta[v\mapsto\vartheta_{c,\gamma}(\alpha)]}\#\gamma$ is in $K_c\delta\cup K_c\gamma\cup\{\vartheta_{c,\gamma}(\alpha)\}$ (recall that we do not substitute inside elements of $K_c\delta$), and therefore bounded by $\vartheta_{c,\gamma}(\beta)$.

  Similarly, any element of $K_{c'}\vartheta_{c,\vartheta_{c,\gamma}(\alpha)}(\delta[v\mapsto\vartheta_{c,\gamma}(\alpha)])$ is in $K_{c'}\delta\cup K_{c'}\gamma\cup K_{c'}\vartheta_{c,\gamma}(\alpha)$, so also bounded in $K_{c'}\vartheta_{c,\gamma}(\beta)$.
\end{proof}

\begin{definition}
When $d$ is a proof tree in $\mathsf{ID}^\infty_c$, an \emph{ordinal bound above $\gamma$} on $d$ is a function $o^d:\dom(d)\rightarrow\mathrm{OT}$ so that
  \begin{itemize}
  \item if $s\sqsubseteq t$ then $o^d(t)\ll^c_\gamma o^d(s)$,
  \item for all $\sigma\in\dom(d)$, if $v_{n\in\mu xX.\phi,\epsilon}\in \bigcup_{c'}FV_{c'}(o^d(\sigma))$ then $[\Theta]^{n\in\mu xX.\phi,\epsilon}\in\Gamma(d,\sigma)$ for some $\Theta$,
  \item for all $\sigma\in\dom(d)$, if $v_{\mu xX.\phi}$ is a subterm of $o^d(\sigma)$ then some $m\not\in\mu xX.\phi$ appears as a subformula of an element of $\Gamma(d,\sigma)$.
  \end{itemize}

  We say $d$ is bounded by $\alpha$ above $\gamma$ if there is an ordinal bound above $\gamma$, $o^d$, with $o^d(\langle\rangle)\lleq_\gamma^c\alpha$.
\end{definition}

\subsection{Embedding and Cut Elimination}

Having set up our theories properly, we can now carry out the steps from the previous section with almost no change.

\begin{lemma}
  For every $\mathsf{ID}_{<\omega}$ formula $\phi$, there is a deduction $d_\phi$ in $\mathsf{ID}^{\infty,+}_{C_0}$ with $\Gamma(d_\phi)\subseteq\{\phi,{\sim}\phi\}$ bounded by $\Omega_{c}+rk(\phi)$ where $c=dp(\phi)$.
\end{lemma}
\begin{proof}
  The only new step is producing a proof of $\{n\in\mu xX.\phi,n\not\in\mu xX.\phi\}$ when $dp(\mu xX.\phi)>1$. The proof is similar to Lemma \ref{thm:identity}, except that when $d_{n\in\mu xX.\phi}(\sigma)=\mathrm{Read}^{\mathsf{ID}_0^{\infty,+}}_{[\Gamma]^{n\in\mu xX.\phi,\epsilon}}$, we could have $m\not\in\mu yY.\psi\in\Gamma$ where $dp(\mu yY.\psi)<dp(\mu xX.\phi)$. In this case we set $d_{n\in\mu xX.\phi}(\sigma\ulcorner m\in\mu yY.\psi\urcorner\tau)=d_{m\in\mu yY.\psi}(\tau)$ for all $\tau$.
\end{proof}

\begin{lemma}\label{thm:substitution2}
  For any formula $\psi(y)$ of depth $\leq C_0$ with only the free variable $y$ and $\mu xX.\phi$ of depth $c$, there is a proof tree $\mathrm{Subst}^{n\in\mu xX.\phi\mapsto\psi(n)}$ in $\mathsf{ID}^{\infty}_{\max\{c,C_0\}}$ with conclusion
  \[[n\in\mu xX.\phi]^{n\in\mu xX.\phi,\langle\rangle,\mu xX.\phi},\psi(n),\exists y\,\phi(y,\psi)\wedge{\sim}\psi(y)\]
and bounded by $\Omega_{C_0}\# rk(\psi)\cdot 2\# v_{n\in\mu xX.\phi,\langle\rangle}\# 2$.
\end{lemma}
\begin{proof}
  This is unchanged from Lemma \ref{thm:substitution} since the theory the $\mathrm{Read}$ rules branch over is essentially unchanged. (Note that we never have any $n\not\in\mu xX.\phi\in\Theta'_\sigma$.)
\end{proof}





\begin{theorem}\label{thm:idomega_embedding}
  Let $d$ be a deduction in $\mathsf{ID}_{<\omega}$ so that $\Gamma(d)$ has free variables contained in $x_1,\ldots,x_n$. There are some $C_0,k$ so that, for any numerals $m_1,\ldots,m_n$, there is a proof tree $d^\infty$ in $\mathsf{ID}^\infty_{C_0,<k}$ with $\Gamma(d^\infty)\subseteq\Gamma(d)[x_i\mapsto m_i]$ and bounded by $\Omega_{C_0}\cdot 3\#\omega\# k$.
\end{theorem}
\begin{proof}
  As in the proof of Theorem \ref{thm:id1_embedding}. 
\end{proof}

\begin{theorem}
  \begin{enumerate}
  \item   Let $\eta$ be an atomic formula of the form $\dot{R}m_1\cdots m_n$ and let $\phi\in\{\sigma,\neg\sigma\}$ be false. If $d$ is a $\mathsf{ID}^\infty_{<\omega,0}$ proof tree then $\phi\not\in\Gamma(d)$.
  \item   For any formulas $\phi_L,\phi_R$ with rank $\leq n$ and $i\in\{L,R\}$ and any $\mathsf{ID}^\infty_{c,<n}$ proof tree $d$ with bound $\alpha$, there is a $\mathsf{ID}^\infty_{c,<n}$ proof tree $\mathrm{Inverse}^\wedge_{\phi_L,\phi_R,i}(d)$ with $\Gamma(\mathrm{Inverse}^\wedge_{\phi_L,\phi_R,i}(d))\subseteq(\Gamma(d)\setminus\{\phi_L\wedge\phi_R\})\cup\{\phi_i\}$ and bounded by $\alpha$.
  \item   For any formula $\phi(y)$ with rank $\leq n$ whose only free variable is $\phi$, any $m\in\mathbb{N}$, and any $\mathsf{ID}^\infty_{c,<n}$ proof tree $d$ with bound $\alpha$, there is a $\mathsf{ID}^\infty_{c,<n}$ proof tree $\mathrm{Inverse}^\forall_{\phi(y),m}(d)$ with $\Gamma(\mathrm{Inverse}^\forall_{\phi(y),m}(d))\subseteq(\Gamma(d)\setminus \{\forall x\,\phi(x)\})\cup\{\phi(m)\}$ and bounded by $\alpha$
  \item   For any formulas $\phi_L,\phi_R$ with rank $\leq n$ and any $\mathsf{ID}^\infty_{c,<n}$ proof trees $d_\wedge$ and $d_\vee$ bounded by $\alpha,\beta$ respectively, there is a $\mathsf{ID}^\infty_{c,<n}$ proof tree $\mathrm{Elim}^\vee_{\phi_L,\phi_R}(d_\vee,d_\wedge)$ with $\Gamma(\mathrm{Elim}^\vee_{\phi_L,\phi_R}(d_\vee,d_\wedge))\subseteq (\Gamma(d_\wedge)\setminus\{\phi_L\wedge\phi_R\})\cup(\Gamma(d_\vee)\setminus\{{\sim}\phi_L\vee{\sim}\phi_R\})$ and bounded by $\alpha\# \beta$.
  \item   For any formula $\phi(y)$ with rank $\leq n$ and any $\mathsf{ID}^\infty_{c,<n}$ proof trees $d_\forall$ and $d_\exists$ bounded by $\alpha,\beta$ respectively, there is a $\mathsf{ID}^\infty_{c,<n}$ proof tree $\mathrm{Elim}^\exists_{\phi(y)}(d_\exists,d_\forall)$ with $\Gamma(\mathrm{Elim}^\exists_{\phi(y)}(d_\exists,d_\forall))\subseteq (\Gamma(d_\wedge)\setminus\{\forall x\,\phi(x)\})\cup(\Gamma(d_\vee)\setminus\{\exists x\,{\sim}\phi(x))$ and bounded by $\alpha\#\beta$.
  \item For any atomic formula of the form $n\in\mu xX.\phi$ with depth $\leq c$ and $\mathsf{ID}_{c,<0}^{\infty}$ proof trees $d_\mu$ and $d_\neg$ bounded by $\alpha,\beta$ respectively, there is a $\mathsf{ID}_{c,<0}^\infty$ proof tree $\mathrm{Elim}^{\mu}_{n\in\mu xX.\phi}(d_\mu,d_\neg)$ with $\Gamma(\mathrm{Elim}^{\mu}_{n\in\mu xX.\phi}(d_\mu,d_\neg))\subseteq(\Gamma(d_\mu)\setminus\{n\in \mu xX.\phi\})\cup(\Gamma(d_\neg)\setminus\{n\not\in\mu xX.\phi\})$ and bounded by $\alpha\#\beta$. \label{case_elim}
  \item If $d$ is a proof tree in $\mathsf{ID}_{c,<n+1}^{\infty}$ bounded by $\alpha$ then there is a proof tree $\mathrm{Reduce}_n(d)$ in $\mathsf{ID}_{c,<n}^\infty$ with $\Gamma(\mathrm{Reduce}_n(d))\subseteq\Gamma(d)$ and bounded by $\omega^\alpha$.
  \end{enumerate}
\end{theorem}
\begin{proof}
  The proofs are largely unchanged except for (\ref{case_elim}).

  In the definition of $\mathrm{Elim}^\mu_{n\in\mu xX.\phi}(d_\mu,d_\neg)$, we need to address the possibility that $n\not\in\mu xX.\phi\in\Delta(d_\neg(\pi(\sigma)))$ but $d_{\neg}(\pi(\sigma))$ is not $\Omega^\flat_{n\not\in\mu xX.\phi}$, because $d_\neg(\pi(\sigma))$ could now be $\mathrm{Read}^{\mathsf{ID}_{0,<0}^{\infty}}_{[\Theta]^{m\in\mu yY.\psi,\epsilon'}}$ with $n\not\in\mu xX.\phi\in\Delta(\epsilon')\setminus\Theta$.

  In this case, we set $\mathrm{Elim}^\mu_{n\in\mu xX.\phi}(d_\mu,d_\neg)(\sigma)=\mathrm{Read}^{\mathsf{ID}_{0,<0}^{\infty}}_{[\Theta,n\not\in\mu xX.\phi]^{m\in\mu yY.\psi,\epsilon'}}$. For each $\iota\in|\mathrm{Read}^{\mathsf{ID}_{0,<0}^{\infty}}_{[\Theta]^{m\in\mu yY.\psi,\epsilon'}}|$ we set $\pi(\sigma\iota)=\pi(\sigma)\iota$ and continue as before.

  However there is a new element $\ulcorner n\in\mu xX.\phi\urcorner\in|\mathrm{Read}^{\mathsf{ID}_{0,<0}^{\infty}}_{[\Theta]^{m\in\mu yY.\psi,\epsilon'}}|\setminus|\mathrm{Read}^{\mathsf{ID}_{0,<0}^{\infty}}_{[\Theta]^{m\in\mu yY.\psi,\epsilon'}}|$; we set $\mathrm{Elim}^\mu_{n\in\mu xX.\phi}(d_\mu,d_\neg)(\sigma\ulcorner n\in\mu xX.\phi\urcorner\tau)=d_\mu(\tau)$ for all $\tau$.

\end{proof}

\subsection{Lifting}

Consider what collapsing, the analog of Theorem \ref{thm:id1_collapsing}, will look like. We will begin with a proof tree in $\mathsf{ID}_{c+1,<0}^{\infty}$ and need to collapse $\mathrm{Cut}\Omega^\flat$ rules. After collapsing, we get a proof in $\mathsf{ID}_{c,<0}^{\infty}$---we expect to still have $\mathrm{Read}$ and $\Omega^\flat$ inferences, both for lower depth formulas (because there might be lower depth $\mathrm{Cut}\Omega^\flat$ rules) and because we will now allow negative occurences even of depth $c+1$ formulas.

When we wish to collapse a $\mathrm{Cut}\Omega^\flat$ rule, this presents a problem---on the left, collapsing only gives us a proof tree in $\mathsf{ID}_{c,<0}^{\infty}$, while on the right we have a function which expects a proof tree in $\mathsf{ID}_{0,<0}^{\infty,+}$ as input.

The solution is that we will just apply our function anyway, having it act as the identity whenever it encounters ``unexpected'' rules. We will need this technique again, so we isolate it in general---when we have a locally defined function defined on a theory $\mathfrak{T}$, we can \emph{lift} the function to some $\mathfrak{T}'\supseteq\mathfrak{T}$, and the new function will have the same conclusion under reasonable assumptions. In the definition below, we further assume that $\mathfrak{T}'$ includes new $\Omega^\flat$ rules, and that we want to modify our behavior on those.

We can write this as a transformation on proof trees, though the result is long and rather technical; it is more convenient (and clearer) to describe the translation directly on the function:

\[\bar F^{\uparrow\mathfrak{T}^*}(\{d_{\epsilon}\})=
  \left\{\begin{array}{l}
           \mathrm{Rep}(\bar F_{d_{\epsilon_0}(\langle\rangle)}(\{d_\epsilon\}\cup\{d_{\epsilon_0\iota}\}_\iota))\\
           \quad \quad \quad \quad\text{if }F(\langle\rangle)=\mathrm{Read}^{\mathfrak{T}}_{[\Theta]^{n\in\mu xX.\phi,\epsilon_0}}\text{ and }d_{\epsilon_0}(\langle\rangle)\in\mathfrak{T}\\
           \mathcal{R}(\{\bar F(\{d_\epsilon\}_{\epsilon\neq\epsilon_0}\cup\{\epsilon_0\mapsto d_{\epsilon_0\iota}\})\}_{\iota\in|\mathcal{R}|}) \\
           \quad \quad \quad \quad\text{if }F(\langle\rangle)=\mathrm{Read}^{\mathfrak{T}}_{[\Theta]^{n\in\mu xX.\phi,\epsilon_0}}\text{, and}\\
           \quad \quad \quad \quad d_{\epsilon_0}(\langle\rangle)=\mathcal{R}\not\in\mathfrak{T}, \\
           \quad \quad \quad \quad \text{and }\mathcal{R}\text{ is not a Read or }\Omega^\flat_{n\in\mu xX.\phi}\text{ rule with }n\not\in\mu xX.\phi\in\Theta\\
           \mathrm{Read}^{\mathfrak{T}''}_{[\Theta''\cup\Theta]^{m\in\mu yY.\psi,\rho}}(\{\bar F(\{d_\epsilon\}_{\epsilon\neq\epsilon_0}\cup\{\epsilon_0\mapsto d_{\epsilon_0\iota}\})\}_{\iota\in|\mathrm{Read}^{\mathfrak{T}''}_{[\Theta''\cup\Theta]^{m\in\mu yY.\psi,\rho}}|}) \\
           \quad \quad \quad \quad\text{if }F(\langle\rangle)=\mathrm{Read}^{\mathfrak{T}}_{[\Theta]^{n\in\mu xX.\phi,\epsilon_0}}\text{, and}\\
           \quad \quad \quad \quad d_{\epsilon_0}(\langle\rangle)=\mathrm{Read}^{\mathfrak{T''}}_{[\Theta'']^{m\in\mu yY.\psi,\rho}}\not\in\mathfrak{T}\\
\mathrm{Cut}\Omega^\flat(\bar F_{n\in\mu xX.\phi}(\{d_\epsilon\}_{\epsilon}),\bar F(\{d_\epsilon\}_{\epsilon\neq\epsilon_0}\cup\{\epsilon_0\mapsto d_{\epsilon_0\bot}\})) \\
           \quad \quad \quad \quad\text{if }F(\langle\rangle)=\mathrm{Read}^{\mathfrak{T}}_{[\Theta]^{n\in\mu xX.\phi,\epsilon_0}}\text{, and}\\
           \quad \quad \quad \quad d_{\epsilon_0}(\langle\rangle)=\Omega^\flat_{n\in\mu xX.\phi}\not\in\mathfrak{T}\text{ with }n\not\in\mu xX.\phi\in\Theta\\           
           \mathcal{R}(\{\bar F_\iota(\{d_\epsilon\})\}_\iota) \\
           \quad \quad \quad \quad\text{if }F(\langle\rangle)=\mathcal{R}\neq \mathrm{Read}^{\mathfrak{T}}_{[\Theta]^{n\in\mu xX.\phi,\epsilon_0}}
         \end{array}\right..\]

In the new cases---the second through fourth---note that $\bar F$ (and $\bar F_{n\in\mu xX.\phi}$) have the same set of inputs $\Upsilon_{n\in\mu xX.\phi}(\bar F)$, but we are now using the branch $d_{\epsilon_0\iota}$ for the input labeled by $\epsilon_0$.


Note that the range of $F^{\uparrow\mathfrak{T}^*}$ can grow (beyond just adjusting the Read rules used): it now includes all $\mathrm{Cut}\Omega^\flat_{n\in\mu xX.\phi}$ axioms such that $\Omega^\flat_{n\in\mu xX.\phi}\in\mathfrak{T}^*$ and $n\not\in\mu xX.\phi$ is removed by some $\mathrm{Read}$ rule in the proof.





\begin{definition}
  We say $\mathfrak{T}^*$ is \emph{rule-for-rule conservative} over $\mathfrak{T}$ in $F$ if, for all $\mathcal{R}\in\mathfrak{T}^*\setminus\mathfrak{T}$ other than $\mathrm{Read}$ rules and all $\sigma\in\dom(F)$ so that $F(\sigma)=\mathrm{Read}^{\mathfrak{T}}_{[\Theta]^{\phi_F}}$, we have $\Delta(\mathcal{R})\cap\Theta=\emptyset$.
\end{definition}

\begin{lemma}
  If $F$ is a locally defined function from $\mathfrak{T}$ to $\mathfrak{T}'$ and $\mathfrak{T}^*\supseteq\mathfrak{T}$ is rule-for-rule conservative over $\mathfrak{T}$ then $\Gamma(F^{\uparrow\mathfrak{T}^*})\cap\mathcal{L}_\mu\subseteq\Gamma(F)$.
\end{lemma}
The behavior of bracketed formulas is slightly more complicated, but will not matter for the cases we need.
\begin{proof}
  Suppose $\phi\in\Gamma(F^{\uparrow\mathfrak{T}^*})$, so there is some $\sigma$ with $\phi\in\Delta(F^{\uparrow\mathfrak{T}^*}(\sigma))$ and, for all $\tau\iota\sqsubseteq\sigma$, $\phi\not\in\Delta_\iota(F^{\uparrow\mathfrak{T}^*}(\tau))$. If $F^{\uparrow\mathfrak{T}^*}(\sigma)=F(\pi(\sigma))$ then we certainly have $\phi\in\Gamma(F)$, so the case we need to consider is where $F^{\uparrow\mathfrak{T}^*}(\sigma)\neq F(\pi(\sigma))$, and therefore $\sigma=\sigma' \ulcorner\mathcal{R}\urcorner$ where $F^{\uparrow\mathfrak{T}^*}(\sigma')$ is $\mathrm{Read}^{\mathfrak{T}^*}_{[\Theta]^{\phi_F,\rho_\sigma(\epsilon)}}$ rule $\mathcal{R}\in\mathfrak{T}^+\setminus\mathfrak{T}$.

  If $\mathcal{R}$ is not a $\mathrm{Read}$ rule then we have $F^{\uparrow\mathfrak{T}^*}(\sigma' \ulcorner\mathcal{R}\urcorner)=\mathcal{R}$ and $\Delta(\mathcal{R})\cap\Theta=\emptyset$ because $\mathfrak{T}^*$ is rule-for-rule conservative. If $\mathcal{R}$ is a $\mathrm{Read}$ rule then we have $\Delta(F^{\uparrow\mathfrak{T}^*}(\sigma' \ulcorner\mathcal{R}\urcorner))\cap\Theta=\emptyset$ by the construction. In either case, $\phi\in\Delta_{\ulcorner\mathcal{R}\urcorner}(F^{\uparrow\mathfrak{T}^*}(\sigma'))$, contradicting the choice of $\sigma$.
\end{proof}


\begin{lemma}
If $F$ is bounded by $\alpha$ then $F^{\uparrow}$ is bounded by $\alpha$ as well.
\end{lemma}
\begin{proof}
Fix some ordinal bound $o^F$ on $F$. We define an ordinal bound $o^{F^{\uparrow}}$ on $F^{\uparrow}$ by setting $o^{F^\uparrow}(\sigma)=o^F(\pi(\sigma))[v_{\epsilon}\mapsto v_{\rho_\sigma(\epsilon)}]$.
\end{proof}




\subsection{Collapsing}


Allowing $\mu$-expressions to appear negatively even after collapsing creates a new complications. For instance, even with $\mathsf{ID}^\infty_{m}$ proof trees, the collapsed tree will not be well-founded if the conclusion contains some $n\not\in\mu xX.\phi$ formula. However we still wish to represent some improvement in our ordinal bounds---in particular, our commitment that the proof tree not contain $\mathrm{Cut}\Omega^\flat$ rules.

We use the new variables $v_{\mu xX.\phi}$ for this purpose: after collapsing, we require that $\Omega_c$ no longer appear free, but do permit $v_{\mu xX.\phi}$. It follows that, as we collapse, we have to replace $\Omega_c$ with $\Omega_c\#{\scalebox{1.5}{\#}}\{v_{\mu xX.\phi}\}$ where the $\#$ ranges over those $\mu xX.\phi$ of depth $c$ appearing negatively in $\Gamma(d)$.

\begin{theorem}\label{thm:idomega_collapsing}
  Suppose $d$ is a proof tree in $\mathsf{ID}_{c+1,<0}^\infty$ bounded by $\alpha$ above $\gamma$. Let $\beta$ be the ordinal term $\Omega_{c+1}\#{\scalebox{1.5}{\#}}\{v_{\mu xX.\phi}\}$ where the $\scalebox{1.5}{\#}$ ranges over those $\mu xX.\phi$ of depth $c+1$ appearing negatively in $\Gamma(d)$.  Then there is a proof tree $D_{c}(d)$ in $\mathsf{ID}^\infty_{c,<0}$ with $\Gamma(D_{c+1}(d))\subseteq\Gamma(d)$ and bounded by $\vartheta_{c+1,\gamma}(\alpha[\Omega_{c+1}\mapsto\beta])$ above $0$.
\end{theorem}
\begin{proof}
  As in the proof of Theorem \ref{thm:id1_collapsing}, we define $D_c(d)(\sigma)$ by induction on $|\sigma|$ for all $d$ simultaneously, as well as partial functions $\pi_d:\dom(D_c(d))\rightarrow\dom(d)$. The assignment of ordinals, $o^{D_c(d)}$, is similar to Lemma \ref{thm:id1_collapsing_ordinal}, setting $o^{D_c(d)}(\sigma)=\vartheta_{c+1,\gamma} o^d(\sigma)[\Omega_{c+1}\mapsto\beta]$ when $\pi_d(\sigma)$ is defined, and copying over $o^{D_c(d)}(\sigma\top\upsilon)=o^{D_c(\bar d^{\uparrow \mathsf{ID}^\infty_{c,<0}}_\bot(D_m(d_\top)))}(\upsilon)$ after removing a $\mathrm{Cut}\Omega^\flat$ at $d(\pi_d(\sigma))$.

  When $d(\pi_d(\sigma))$ is not $\mathrm{Cut}\Omega^\flat_{n\in\mu xX.\phi}$ where $\phi$ has depth $c+1$, we need to check that $o^{D_m(d)}(\sigma\iota)=\vartheta_{c+1,\gamma}(o^d(\pi_d(\sigma\iota))[\Omega_{c+1}\mapsto\beta])\ll^{c}_0\vartheta_{c+1,\gamma} (o^d(\pi_d(\sigma))[\Omega_{m+1}\mapsto\beta])=o^{D_c(d)}(\sigma)$.

  The significant case is when $d(\pi_d(\sigma))=\mathrm{Cut}\Omega^\flat_{n\in\mu xX.\phi}$ where $\phi$ has depth $c+1$. We set $D_m(d)(\sigma)=\mathrm{Rep}$ and $D_c(d)(\sigma\top\upsilon)=D_c(\bar d^{\uparrow \mathsf{ID}^\infty_{c,<0}}_\bot(D_c(d_\top)))(\upsilon)$---the only difference is that $\bar d_\bot$ is only a function on proofs in $\mathsf{ID}^{\infty,+}_{c+1,<0}$, and we use lifting to extend it to a function on proofs in $\mathsf{ID}^{\infty,+}_{c+1,<0}\cup\mathsf{ID}^\infty_{c,<0}$ as needed.

  The ordinal bound $o^{D_c(d)}(\sigma\top)\ll^{c}_0 o^{D_m(d)}(\sigma)$ is as above. We can then check that
  \[o^{D_c(d)}(\sigma\top)=\vartheta_{c+1,\gamma}\left( o^d(\pi_d(\sigma)\bot)[v_{n\in\mu xX.\phi,\langle\rangle}\mapsto \vartheta_{m+1,\gamma} o^{D_m(d)}(\sigma\top)[\Omega_{c+1}\mapsto\beta],\Omega_{c+1}\mapsto\beta]\right)\]
  is $\ll^{c}_0 o^{D_c(d)}(\sigma)$.
\end{proof}

\begin{theorem}
    If $d$ is a proof in $\mathsf{ID}_c$ whose conclusion does not contain negative occurences of any $\mu xX.\phi$ then there is a proof tree $d'$ in $\mathsf{ID}_{0,<0}^{\infty,+}$ with $\Gamma(d')\subseteq\Gamma(d)$ bounded by $\vartheta_{0,0} \omega_k^{\Omega_c\cdot 2\#\omega\#n}$ for some finite $k,n$.
\end{theorem}

\section{$\mathsf{ID}_{<\bOmega+\omega}$}

\subsection{Theories}

As a final stepping stone, we consider a theory that really requires our new machinery: the theory $\mathsf{ID}_{<\bOmega+\omega}$ which allows formulas like 
\[n\in \mu xX. \phi(x,X,\mu yY. \phi'(x,y,X,Y))\]
where $\phi$ has depth $<\omega$. Here, and throughout this section, we adopt the convention that when $\mu xX.\phi$ is a $\mu$-expression with depth $\bOmega$, we write $\phi'$ for the nested $\mu$-expression. (We adopt the---harmless---restriction that there is always a single such $\phi'$, since any $\mu$-expression of depth $\bOmega+n$ is equivalent to one of this form.)

More precisely, we fix a natural number $C_0$ and consider the theory $\mathsf{ID}_{<\bOmega+C_0}$ in which we allow formulas of depth $[0,C_0)\cup[\bOmega,\bOmega+C_0)$. The theories $\mathsf{ID}_{\bOmega+C_0}$, of course, exhaust $\mathsf{ID}_{<\bOmega+\omega}$. (A single nested fixed point $\mu xX. \phi(x,X,\mu yY. \phi'(x,y,X,Y))$, where $\phi,\phi'$ each have depth $0$, already suffices to capture the full strength of the theory---the substantive part of the restriction to $C_0$ is that it prohibits nesting of induction rules which would violate the bound.)

\begin{definition}\ 
  \begin{itemize}
  \item $\mathsf{ID}_0^{\infty,+}$ is the arithmetic part: the theory containing True, $\mathrm{Cut}$ for formulas of depth $0$, $\wedge\mathrm{I}$, $\vee^L\mathrm{I}$, $\vee^R\mathrm{I}$, $\omega$, $\exists\mathrm{I}$, $\mathrm{Cl}$, and Rep for closed proper formulas of depth either $<C_0$ in $[\bOmega,C_0)$,
\item $\mathsf{ID}_{c+1}^{\infty,+}$ extends $\mathsf{ID}_c^{\infty,+}$ by
  \begin{itemize}
  \item $\mathrm{Cut}$ for formulas of depth $c+1$,
  \item $\Omega^\flat_{n\not\in\mu xX.\phi}$ where $\mu xX.\phi$ has depth $c+1$,
  \item $\mathrm{Read}^{\mathsf{ID}_{0,<0}^\infty}_{[\Theta]^{n\in\mu xX.\phi,\epsilon}}$ rules where $\phi$ has depth $c$ and $\Theta\subseteq\mathcal{L}_\mu$,
  \end{itemize}
\item $\mathsf{ID}_{\bOmega}^{\infty,+}=\mathsf{ID}_{C_0-1}^{\infty,+}$,
\item $\mathsf{ID}^{\infty}_{\bOmega}$ extends $\mathsf{ID}_{C_0-1}^{\infty,+}\cup\mathsf{ID}_{\bOmega+C_0-1}^{\infty,+}$ by
  \begin{itemize}
  \item $\Omega^\flat_{n\not\in\mu xX.\phi}$ and $\mathrm{Cut}\Omega^\flat_{n\not\in\mu xX.\phi}$ where $\mu xX.\phi$ has depth $\bOmega$,
  \item $\mathrm{Read}^{\mathsf{ID}_{\bOmega+C_0-1,<0}^{\infty,+}}_{[\Theta]^{n\in\mu xX.\phi,\epsilon}}$ rules where $\mu xX.\phi$ has depth $\bOmega$ and $\Theta\subseteq\mathcal{L}^1_\mu$.%
  \end{itemize}
\item for $c$ a successor, $\mathsf{ID}_c^\infty$ extends $\mathsf{ID}_{c-1}^\infty\cup \mathsf{ID}_c^{\infty,+}$ by $\mathrm{Cut}\Omega^\flat_{n\not\in\mu xX.\phi}$ where $\phi$ has depth $c-1$.
\end{itemize}
\end{definition}

\subsection{Substitution}

\begin{lemma}
  For every proper closed formula $\phi$, there is a proof tree $d_\phi$ in $\mathsf{ID}^\infty_0$ with $\Gamma(d_\phi)\subseteq\{\phi,{\sim}\phi\}$.
\end{lemma}

For successor $c$, we have the same substitution function from Lemma \ref{thm:substitution2}. For $c=\bOmega$, we need some additional work.

\begin{lemma}\label{thm:substitution3}
  For any formula $\psi(y)$ with only the free variable $y$ and $\mu xX.\phi$ of depth $\bOmega$ such that $\phi(\psi)$ has depth $<\bOmega+C_0$, there is a proof tree $\mathrm{Subst}^{n \in \mu xX. \phi\mapsto \psi(n)}$ in $\mathsf{ID}^\infty_{\bOmega+C_0-1}$ with conclusion
  \[[n\in \mu xX.\phi]^{n\in\mu xX.\phi,\langle\rangle},\psi(n),\exists y\,\phi(y,\psi)\wedge{\sim}\psi(y).\]

\end{lemma}
The first new situation that is forced on us is that we might have to change an $\Omega^\flat$ rule:

\AxiomC{$d'$}
\noLine
\UnaryInfC{$\vdots$}
\noLine
\UnaryInfC{$[n\in\mu yY.\rho(\mu xX.\phi)]^{n\in\mu yY.\rho(\mu xX.\phi),\langle\rangle}$}
\LeftLabel{$\Omega^\flat$}
\UnaryInfC{$n\not\in\mu yY.\rho(\mu xX.\phi)$}
\DisplayProof
$\mapsto$
\AxiomC{$\mathrm{IH}(d')\}$}
\noLine
\UnaryInfC{$\vdots$}
\noLine
\UnaryInfC{$[n\in\mu yY.\rho(\psi)]^{n\in\mu yY.\rho(\psi),\langle\rangle}$}
\LeftLabel{$\Omega^\flat$}
\UnaryInfC{$n\not\in\mu yY.\rho(\psi)$}
\DisplayProof

On the one hand, this is a simple change, replacing a rule with a different case of the same rule. On the other hand, it forces a substantial further complication on us: we might now have bracketed formulas which need to be replaced. This means we also need to apply the substitution operation to $\mathrm{Read}$ rules, replacing them with alternate $\mathrm{Read}$ rules. We would like to take a step that looks like this:

\AxiomC{$d'_{\mathcal{R}}$}
\noLine
\UnaryInfC{$\vdots$}
\noLine
\UnaryInfC{$\Delta(\mathcal{R})\setminus\Upsilon (\mu xX.\phi),\{[\Upsilon'(\mu xX.\phi)]^{n\in\mu yY.\rho(\mu xX.\phi),\nu\iota}\}$}
\LeftLabel{$\mathrm{Read}^{\mathsf{ID}^{\infty,+}_{<\bOmega+c'+1}}_{[\upsilon(\mu xX.\phi)]^{n\in\mu yY.\rho(\mu xX.\phi),\nu}}$}
\UnaryInfC{$\Delta(\nu)\setminus\Upsilon(\mu xX.\phi), [\upsilon(\mu xX.\phi)]^{n\in\mu yY.\rho(\mu xX.\phi),\nu}$}
\DisplayProof

and convert it to one that looks like this:

\AxiomC{$\mathrm{IH}(d'_{???})$}
\noLine
\UnaryInfC{$\vdots$}
\noLine
\UnaryInfC{$\Delta(\mathcal{R})\setminus\upsilon(\psi),\{[\upsilon'(\psi)]^{n\in\mu yY.\rho(\psi),\nu'\iota}\}$}
\LeftLabel{$\mathrm{Read}^{\mathsf{ID}^{\infty,+}_{<c+c
      +1}}_{[\Upsilon(\psi)]^{n\in\mu yY.\rho(\psi),\nu'}}$}
\UnaryInfC{$\Delta(\nu')\setminus\upsilon(\psi), [\upsilon(\psi)]^{n\in\mu yY.\rho(\mu xX.\phi),\nu'}$}
\DisplayProof

This leads to a yet further complication (the last one, fortunately): the branches of our new $\mathrm{Read}$ rule do not directly align to the branches of our old $\mathrm{Read}$ rule---we do not necessarily want to use $\mathrm{IH}(d'_{\mathcal{R}})$ for the branch indexed by $\mathcal{R}$: the rule $\mathcal{R}$ might introduce a formula in $\Delta'(\psi)$, in which case we want to instead use $\mathrm{IH}(d'_{\mathcal{R}'})$, where $\mathcal{R}'$ introduces the corresponding formula in $\Delta'(\mu xX.\phi)$.

\begin{proof}
  The proof is very similar to Lemma \ref{thm:substitution2} (and therefore \ref{thm:substitution}), with some extra accounting to deal with the new cases.

  The relationship between the formulas we are removing and those we are replacing them with is no longer quite as simple, so we replace $\Theta_\sigma[Z\mapsto\mu xX.\phi]$ with $\Theta_\sigma^{\mathrm{old}}$ and $\Theta_\sigma[Z\mapsto\psi]$ with $\Theta_\sigma^{\mathrm{new}}$. We still have $\Theta'_\sigma=\Theta_\sigma^{\mathrm{old}}\setminus\Theta_\sigma^{\mathrm{new}}$.


  Once again, we need to consider the case where $\mathrm{Subst}^{n \in \mu xX. \phi\mapsto \psi(n)}(\sigma)=\mathrm{Read}^{\mathsf{ID}^{\infty,+}_{C_0-1,<0}}_{[\Theta'_\sigma]^{n\in\mu xX.\phi,\epsilon}}$ and we need to consider the possible choices for $\mathcal{R}\in \mathsf{ID}^{\infty,+}_{C_0-1,<0}$. If $\Delta(\mathcal{R})\cap\Theta'_\sigma=\emptyset$, the argument remains unchanged.

  Suppose $\mathcal{R}$ is an $\Omega^\flat_{m\not\in\mu yY.\phi'[Z\mapsto\mu xX.\phi]}$ with $\Delta(\mathcal{R})\cap\Theta'_\sigma\neq\emptyset$. In this case we may take $\mathrm{Subst}^{n \in \mu xX. \phi\mapsto \psi(n)}(\sigma\ulcorner\mathcal{R}\urcorner)=\Omega^\flat_{m\not\in\mu yY.\phi'[Z\mapsto\psi]}$. We then set $\Theta^{\mathrm{old}}_{\sigma\ulcorner\mathcal{R}\urcorner\bot}=\Theta^{\mathrm{old}}_\sigma\cup\{[m\in\mu yY.\phi']^{m\in\mu yY.\phi'(\mu xX.\phi),\langle\rangle}\}$ and $\Theta^{\mathrm{new}}_{\sigma\ulcorner\mathcal{R}\urcorner\bot}=\Theta^{\mathrm{new}}_\sigma\cup\{[m\in\mu yY.\phi'(\psi)]^{m\in\mu yY.\phi'(\psi),\langle\rangle}\}$, and then we may set $\mathrm{Subst}^{n \in \mu xX. \phi\mapsto \psi(n)}(\sigma\ulcorner\mathcal{R}\urcorner\bot)=\mathrm{Read}^{\mathsf{ID}^{\infty,+}_{<\bOmega}}_{[\Theta'_{\sigma\ulcorner\mathcal{R}\urcorner\iota}]^{n\in\mu xX.\phi,\epsilon\bot}}$.

  The presence of $[m\in\mu yY.\phi'(\mu xX.\phi)]^{m\in\mu yY.\phi'(\mu xX.\phi),\langle\rangle}$ in $\Theta_\sigma$ means that we further have the possibility that $\Delta(\mathcal{R})\cap\Theta'_\sigma\neq\emptyset$ because $\mathcal{R}$ is some $\mathrm{Read}^{\mathsf{ID}^{\infty}_{0,<0}}_{[\Upsilon]^{m\in\mu yY.\phi'(\mu xX.\phi),\nu}}$ rule with $[\Upsilon]^{m\in\mu yY.\phi'(\mu xX.\phi),\nu}\in\Theta'_\sigma$. There is a corresponding $[\Upsilon']^{m\in\mu yY.\phi'(\psi),\nu'}$ in $\Theta_\sigma^{\mathrm{new}}$. We will maintain inductively that there is an $\Upsilon^*$ so that $\Upsilon=\Upsilon^*[Z\mapsto\mu xX.\phi]$ while $\Upsilon'=\Upsilon^*[Z\mapsto\psi]\cup\Upsilon^+$ with $\Upsilon^+\subseteq\Theta_\sigma^{\mathrm{new}}$.

  We set $\mathrm{Subst}^{n \in \mu xX. \phi\mapsto \psi(n)}(\sigma\ulcorner\mathcal{R}\urcorner)=\mathrm{Read}^{\mathsf{ID}^{\infty}_{0,<0}}_{[\Upsilon']^{m\in\mu yY.\phi'[Z\mapsto\psi],\theta(\nu)}}$

  We face an additional complication: we can no longer simply identify the premises of $\mathrm{Subst}^{n \in \mu xX. \phi\mapsto \psi(n)}(\sigma\ulcorner\mathcal{R}\urcorner)$ with the premises of $\mathcal{R}$. So we need a more complicated argument that matches our new premises to suitable old premises. %

  We first consider the rule premises. Consider some $\mathcal{R}'$ in $\mathsf{ID}_{0,<0}^{\infty,+}$.

  First, suppose $\Delta(\mathcal{R}')\cap \Upsilon^*[Z\mapsto\psi]\neq\emptyset$. Since $\mathcal{R}'$ is from $\mathsf{ID}_{0,<0}^{\infty,+}$, the conclusion is a single formula $\upsilon[Z\mapsto \psi]$. Moreover, we cannot have $\upsilon[Z\mapsto \psi]$ be ${\sim}\psi(m')$---if that were the case, we would have had $m'\not\in\mu xX.\phi$ in $\Upsilon=\Upsilon^*[Z\mapsto\mu xX.\phi]$, and $\mathcal{R}$ could not have been a $\mathrm{Read}$ rule.

  This means that there is a rule $\mathcal{R}^{\leftarrow}$ with $\Delta(\mathcal{R}^{\leftarrow})=\{\upsilon[Z\mapsto\mu xX.\phi]\}$ and $|\mathcal{R}^{\leftarrow}|=|\mathcal{R}|$. We take $\Theta^{\mathrm{old}}_{\sigma\ulcorner\mathcal{R}\urcorner\ulcorner\mathcal{R}'\urcorner}=\Theta^{\mathrm{old}}_\sigma\cup[\Upsilon\cup\{\upsilon'_\iota[Z\mapsto\mu xX.\phi]\}]^{m\in\mu yY.\rho,\nu\iota}$ and $\Theta^{\mathrm{new}}_{\sigma\ulcorner\mathcal{R}\urcorner\ulcorner\mathcal{R}'\urcorner}=\Theta^{\mathrm{new}}_\sigma\cup[\Upsilon'\cup\{\upsilon'_\iota[Z\mapsto\psi]\}]^{m\in\mu yY.\rho,\nu\iota}$ (where $\upsilon'_\iota[Z\mapsto \mu xX.\phi]$ is the unique formula in $\Delta_\iota(\mathcal{R}^{\leftarrow})$) and we can set $\mathrm{Subst}^{n \in \mu xX. \phi\mapsto \psi(n)}(\sigma\ulcorner\mathcal{R}\urcorner\ulcorner\mathcal{R}'\urcorner)=\mathrm{Read}^{\mathsf{ID}^{\infty,+}_{0,<0}}_{[\Theta'_{\sigma\ulcorner\mathcal{R}\urcorner\ulcorner\mathcal{R}'\urcorner}]^{n\in\mu xX.\phi,\epsilon\ulcorner\mathcal{R}^{\leftarrow}\urcorner}}$.

  Next, suppose $\Delta(\mathcal{R}')\cap \Upsilon^+\neq\emptyset$. Then, since $\Upsilon^+\subseteq\Theta_\sigma^{\mathrm{new}}$, we may set $\mathrm{Subst}^{n \in \mu xX. \phi\mapsto \psi(n)}(\sigma\ulcorner\mathcal{R}\urcorner\ulcorner\mathcal{R}'\urcorner)=\mathcal{R}'$ and, for each $\iota$, set $\Theta^{\mathrm{old}}_{\sigma\ulcorner\mathcal{R}\urcorner\ulcorner\mathcal{R}'\urcorner\iota}=\Theta^{\mathrm{old}}_\sigma$ and $\mathrm{Subst}^{n \in \mu xX. \phi\mapsto \psi(n)}(\sigma\ulcorner\mathcal{R}\urcorner\ulcorner\mathcal{R}'\urcorner\iota)=\mathrm{Read}^{\mathsf{ID}^{\infty,+}_{0,<0}}_{[\Theta'_{\sigma\ulcorner\mathcal{R}\urcorner\ulcorner\mathcal{R}'\urcorner\iota}]^{n\in\mu xX.\phi,\epsilon\mathrm{Rep}}}$.

  Next, suppose $\Delta(\mathcal{R}')\cap(\Upsilon'\setminus\Upsilon^+)\neq\emptyset$---that is, we have $m\not\in\mu xX.\phi$ appearing in $\Upsilon$ while ${\sim}\psi(m)$ appears in $\Upsilon'$. We will simply copy rules introducing ${\sim}\psi(m)$, and use the side branch of the $\mathrm{Read}$ rule we are reading to cut it away. We set $\mathrm{Subst}^{n\in\mu xX.\phi\mapsto\psi(n)}(\sigma\ulcorner\mathcal{R}\urcorner\ulcorner\mathcal{R}'\urcorner)=\mathrm{Cut}_{\psi(m)}$.

  We define $\Theta^{\mathrm{old}}_{\sigma\ulcorner\mathcal{R}\urcorner\ulcorner\mathcal{R}'\urcorner\mathrm{L}}=\Theta^{\mathrm{old}}_\sigma\cup\{m\in\mu xX.\phi\}$, $\Theta^{\mathrm{new}}_{\sigma\ulcorner\mathcal{R}\urcorner\ulcorner\mathcal{R}'\urcorner\mathrm{L}}=\Theta^{\mathrm{new}}_\sigma\cup\{\psi(m)\}$, and then set $\mathrm{Subst}^{n\in\mu xX.\phi\mapsto\psi(n)}(\sigma\ulcorner\mathcal{R}\urcorner\ulcorner\mathcal{R}'\urcorner\mathrm{L})=\mathrm{Read}^{\mathsf{ID}^{\infty,+}_{0,<0}}_{[\Theta'_{\sigma\ulcorner\mathcal{R}\urcorner\mathrm{L}}]^{n\in\mu xX.\phi,\epsilon(m\in\mu xX.\phi)}}$.

  We set $\mathrm{Subst}^{n\in\mu xX.\phi\mapsto\psi(n)}(\sigma\ulcorner\mathcal{R}\urcorner\ulcorner\mathcal{R}'\urcorner\mathrm{R})=\mathcal{R}'$ and, for each $\iota$, $\Theta^{\mathrm{old}}_{\sigma\ulcorner\mathcal{R}\urcorner\ulcorner\mathcal{R}'\urcorner\mathrm{R}\iota}=\Theta^{\mathrm{old}}_\sigma$, $\Theta^{\mathrm{new}}_{\sigma\ulcorner\mathcal{R}\urcorner\ulcorner\mathcal{R}'\urcorner\mathrm{R}\iota}=\Theta^{\mathrm{new}}_\sigma\cup\{{\sim}\psi(m)\}$, and then set $\mathrm{Subst}^{n\in\mu xX.\phi\mapsto\psi(n)}(\sigma\ulcorner\mathcal{R}\urcorner\ulcorner\mathcal{R}'\urcorner\mathrm{R}\iota)=\mathrm{Read}^{\mathsf{ID}^{\infty,+}_{0,<0}}_{[\Theta'_{\sigma\ulcorner\mathcal{R}\urcorner\mathrm{Rep}}]^{n\in\mu xX.\phi,\epsilon(m\in\mu xX.\phi)}}$.


  Otherwise $\Delta(\mathcal{R}')\cap\Upsilon'=\emptyset$ and we may take $\mathrm{Subst}^{n \in \mu xX. \phi\mapsto \psi(n)}(\sigma\ulcorner\mathcal{R}\urcorner\ulcorner\mathcal{R}'\urcorner)=\mathcal{R}'$ and, for each $\iota$, set $\Theta^{\mathrm{old}}_{\sigma\ulcorner\mathcal{R}\urcorner\ulcorner\mathcal{R}'\urcorner\iota}=\Theta^{\mathrm{old}}_\sigma$ and $\mathrm{Subst}^{n \in \mu xX. \phi\mapsto \psi(n)}(\sigma\ulcorner\mathcal{R}\urcorner\ulcorner\mathcal{R}'\urcorner\iota)=\mathrm{Read}^{\mathsf{ID}^{\infty,+}_{0,<0}}_{[\Theta'_{\sigma\ulcorner\mathcal{R}\urcorner\ulcorner\mathcal{R}'\urcorner\iota}]^{n\in\mu xX.\phi,\epsilon\ulcorner\mathrm{Rep}\urcorner}}$. (That is, in this case we simply copy over the rule, since it is harmless, and we ``simulate'' a $\mathrm{Rep}$ rule on the function we have been given as an input.) If $\Delta(\mathcal{R}')\cap\Upsilon^+=\emptyset$, we take $\Theta^{\mathrm{new}}_{\sigma\ulcorner\mathcal{R}\urcorner\ulcorner\mathcal{R}'\urcorner\iota}=\Theta^{\mathrm{new}}_\sigma$; if $\Delta(\mathcal{R}')\cap\Upsilon^+\neq\emptyset$, we instead take $\Theta^{\mathrm{new}}_{\sigma\ulcorner\mathcal{R}\urcorner\ulcorner\mathcal{R}'\urcorner\iota}\cup\{[\Upsilon'\cup\Delta_\iota(\mathcal{R}')]^{m\in\mu yY.\phi'(\psi),\nu'\iota}\}$.

  Because of our modification to the Read rule, there may be additional premises indexed by a formula $m\in\mu yY. \theta$ because $m\not\in\mu yY.\theta$ appears in $\Upsilon'$. We may set $\Theta^{\mathrm{old}}_{\sigma\ulcorner\mathcal{R}\urcorner\ulcorner m\in\mu yY.\theta(\mu xX.\phi)\urcorner}=\Theta^{\mathrm{old}}_\sigma$, $\Theta^{\mathrm{new}}_{\sigma\ulcorner\mathcal{R}\urcorner\ulcorner m\in\mu yY.\theta(\psi)\urcorner}=\Theta^{\mathrm{new}}_\sigma$, and set $\mathrm{Subst}^{n\in\mu xX.\phi\mapsto\psi(n)}(\sigma\ulcorner\mathcal{R}\urcorner\ulcorner m\in\mu yY.\theta\urcorner)=\mathrm{Read}^{\mathsf{ID}^{\infty,+}_{0,<0}}_{[\Theta'_{\sigma\ulcorner\mathcal{R}\urcorner\ulcorner m\in\mu yY.\theta(\psi)\urcorner}]^{n\in\mu xX.\phi,\epsilon\ulcorner m\in\mu yY.\theta(\mu xX.\phi)\urcorner}}$.



\end{proof}










\begin{lemma}
  Let $d$ be a deduction in $\mathsf{ID}_{<\bOmega+\omega}$ so that $\Gamma(d)$ has free variables contained in $x_1,\ldots,x_n$. There are some $C_0,k,a$ so that, for any numerals $m_1,\ldots,m_n$, there is a proof tree $d^\infty$ in $\mathsf{ID}^\infty_{\bOmega+C_0,<k}$ with $\Gamma(d^\infty)\subseteq\Gamma(d)[x_i\mapsto m_i]$.
\end{lemma}

 \subsection{Ordinal Terms}























 We use the ordinal notation $\mathrm{OT}_{\omega+\Xi+\omega}$ introduced in \cite{towsner2025polymorphicordinalnotations}. This system has ``cardinal'' symbols
 \[\Omega_1<\Omega_2<\cdots<\Xi<\Omega_{\bOmega+1}<\cdots<\Omega_{\bOmega+n}.\]
 For any $C_0$, we may consider the restriction to terms in which the only $\Omega_n,\Omega_{\bOmega+n}$ appearing are those with $n<C_0$, and then extend this by variables for each cardinal symbol. We refer to this restriction as $\mathrm{OT}_{C_0+\Xi+C_0}$.

\begin{definition}
  When $d$ is a proof tree in $\mathsf{ID}^\infty_c$ with conclusion $\Gamma$ and $\gamma$ is an ordinal term, an \emph{ordinal bound above $\gamma$ on $d$} is a function $o^d:\dom(d)\rightarrow \mathrm{OT}_{C_0+\Xi+C_0}$ such that:
  \begin{itemize}
  \item for all $\sigma\in\dom(d)$, if $v_{n\in\mu xX.\phi,\epsilon}\in \mathrm{FV}(o^d(\sigma))$ then $[\Theta]^{n\in\mu xX.\phi,\epsilon}\in\Gamma(d,\sigma)$ for some $\Theta$,
  \item for all $\sigma\in\dom(d)$, if $v_{\mu xX.\phi}\in \mathrm{FV}(o^d(\sigma))$ then some $m\not\in\mu xX.\phi$ appears as a subformula of an element of $\Gamma(d,\sigma)$
  \item if $\sigma\sqsubset\tau$ then $o^d(\tau)\ll_\gamma o^d(\sigma)$.
  \end{itemize}
\end{definition}

\subsection{Bounds}

\begin{lemma}
  The proof tree $d_{n\in\mu xX.\phi}$ of $\{n\in\mu xX.\phi,n\not\in\mu xX.\phi\}$ is bounded by $\Xi^{(0)}(\Omega^{(0)}_c)$ where $c$ is the depth of $\mu yY.\phi'(\mu xX.\phi)$.
\end{lemma}
\begin{proof}
  We set $o^{d_{n\in\mu xX.\phi}}(\langle\top\rangle)=v_{n\in\mu xX.\phi,\langle\rangle}(v_{\mu yY.\phi'})\#1$. In general, at some $\sigma$ deducing
  \[[\Gamma,[\Delta_1]^{m_1\in\mu yY.\phi',\epsilon_1},\ldots, [\Delta_k]^{m_k\in\mu yY.\phi',\epsilon_k}]^{n\in\mu xX.\phi,\epsilon},\Gamma, [\Delta_1]^{m_1\in\mu yY.\phi',\epsilon_1},\ldots, [\Delta_k]^{m_k\in\mu yY.\phi',\epsilon_k},\]
  we set $o^{d_{n\in\mu xX.\phi}}(\sigma)=v_{n\in\mu xX.\phi,\epsilon}(v_{\mu yY.\phi'},v_{m_1\in\mu yY.\phi',\epsilon_1},\ldots, v_{m_k\in\mu yY.\phi',\epsilon_k})$.
\end{proof}

\begin{lemma}
  For every proper closed formula $\phi$, there is a proof tree $d_\phi$ in $\mathsf{ID}^\infty_0$ with $\Gamma(d_\phi)\subseteq\{\phi,{\sim}\phi\}$ bounded by $\#_{0< c<C_0}\{\Omega_{c},\Omega^{(0)}_{\bOmega+c},\Xi^{(0)}(\Omega^{(0)}_{\bOmega+c})\}\#rk(\phi)$.
\end{lemma}

The same bound on the substitution function works---for successor $c$, the substitution function is bounded by
\[\#_{0< c<C_0}\{\Omega_{c},\Omega^{(0)}_{\bOmega+c},\Xi^{(0)}(\Omega^{(0)}_{\bOmega+c})\}\#rk(\psi)\cdot 2\#v_{n\in\mu xX.\phi,\langle\rangle}\#2\]
while the new substitution function for depth $\bOmega$ is bounded by
  \[\#_{0< c<C_0}\{\Omega_{c},\Omega^{(0)}_{\bOmega+c},\Xi^{(0)}(\Omega^{(0)}_{\bOmega+c})\}\#rk(\psi)\#w_{n\in\mu xX.\phi,\langle\rangle}(\Omega^{(0)}_c)\#2\]
where $c$ is the depth of $\mu yY.\phi'(\psi)$.

\begin{lemma}
  Let $d$ be a deduction in $\mathsf{ID}_{<\bOmega+\omega}$ so that $\Gamma(d)$ has free variables contained in $x_1,\ldots,x_n$. There are some $C_0,k,a$ so that, for any numerals $m_1,\ldots,m_n$, there is a proof tree $d^\infty$ in $\mathsf{ID}^\infty_{\bOmega+C_0,<k}$ with $\Gamma(d^\infty)\subseteq\Gamma(d)[x_i\mapsto m_i]$ and bounded by
  \[\#_{0< c<C_0}\{\Omega_{c},\Omega^{(0)}_{\bOmega+c},\Xi^{(0)}(\Omega^{(0)}_{\bOmega+c})\}\cdot 2\#\omega\#a.\]
\end{lemma}

The bounds on the cut elimination operations are unchanged. (Indeed, the cut elimination operations can, themselves, be written as proof trees with the usual bounds and then extended to suitable domains by lifting, so in a precise sense, the cut elimination operations on $\mathsf{ID}_{<\bOmega+C_0}$ are identical to those on smaller systems.)

Collapsing at successors is also essentially unchanged.
\begin{lemma}
  Suppose $d$ is a proof tree in $\mathsf{ID}_{c+1,<0}^\infty$ with $c$ either $0$ or a successor bounded by $\alpha$ above $\gamma$. Let $\beta=\Omega_{c+1}\#{\scalebox{1.5}{\#}}\{v_{\mu xX.\phi}\#1\}$ where $\#$ ranges over those $\mu xX.\phi$ appearing negatively in $\Gamma(d)$.  Then there is a proof tree $D_{c+1}(d)$ in $\mathsf{ID}^\infty_{c,<0}$ with $\Gamma(D_{c+1}(d))\subseteq\Gamma(d)$ and bounded by $\vartheta_{c+1,\gamma}(\alpha[\Omega_{c+1}\mapsto\beta])$.
\end{lemma}

\begin{theorem}
  Suppose $d$ is a proof tree in $\mathsf{ID}_{\bOmega+1,<0}^\infty$ bounded by $\alpha$ above $\gamma$ whose conclusion does not contain negative occurences of $\mu$-expressions of depth $\bOmega$. Then there is a proof tree $D_{\bOmega}(d)$ in $\mathsf{ID}^{\infty}_{C_0-1,<0}$ with $\Gamma(D_{\bOmega}(d))\subseteq\Gamma(d)$ and bounded by $\vartheta_{\bOmega,\gamma}(\alpha)$.
\end{theorem}
\begin{proof}
  The argument is essentially the same as before. Once again we define $D_{\bOmega}(d)(\sigma)$ by induction on $|\sigma|$ for all $d$ simultaneously along with the partial function $\pi_d:\dom(D_{\bOmega}(d))\rightarrow\dom(d)$. We can then define the ordinal assignment $o^{D_{\bOmega}(d)}:\dom(D_{\bOmega}(d))\rightarrow\dom(d)$. Naturally we begin by setting $\pi_d(\langle\rangle)=\langle\rangle$.

  As long as $d(\pi_d(\sigma))$ is anything other than a $\mathrm{Cut}\Omega^\flat_{n\in\mu xX.\phi}$ where $n\in\mu xX.\phi$ has depth $\bOmega$, we may set $D_{\bOmega}(d)(\sigma)=d(\pi_d(\sigma))$ and set $\pi_d(\sigma\iota)=\pi_d(\sigma)\iota$.

  The main case is when $d(\pi_d(\sigma))$ is a $\mathrm{Cut}\Omega^\flat_{n\in\mu xX.\phi}$ where $n\in\mu xX.\phi$ has depth $\bOmega$. As always, we set $D_{\bOmega}(d)(\sigma)=\mathrm{Rep}$ and $D_{\bOmega}(d)(\sigma\top\upsilon)=D_{\bOmega}(\overline{d}^{\uparrow \mathsf{ID}^{\infty}_{C_0-1,<0}}_{\pi_d(\sigma)\bot}(D_{\bOmega}(d_{\pi_d(\sigma)\top})))(\upsilon)$.

  When $\pi_d(\sigma)$ is defined, we set $o^{D_{\bOmega}(d)}(\sigma)=\vartheta_{\bOmega,\gamma}(o^d(\pi_d(\sigma)))$. Otherwise we copy over $o^{D_{\bOmega}(d)}(\sigma\top\upsilon)=o^{D_{\bOmega}(\overline{d}^{\uparrow \mathsf{ID}^{\infty}_{C_0-1,<0}}_{\pi_d(\sigma)\bot}(D_{\bOmega}(d_{\pi_d(\sigma)\top})))}(\upsilon)$.

  When $d(\pi_d(\sigma))$ is not $\mathrm{Cut}\Omega^\flat_{n\in\mu xX.\phi}$, we have $o^{D_d(d)}(\sigma\iota)=\vartheta_{\bOmega,\gamma}o^d(\pi_d(\sigma\iota))$, and since $o^d(\pi_d(\sigma\iota))\ll_\gamma o^d(\pi_d(\sigma))$, we have $o^{D_d(d)}(\sigma\iota)\ll_0\vartheta_{\bOmega,\gamma}o^d(\pi_d(\sigma))=o^{D_d(d)}(\sigma)$.

  When $d(\pi_d(\sigma))$ is $\mathrm{Cut}\Omega^\flat_{n\in\mu xX.\phi}$ we have
  \[o^{D_d}(\sigma\top)=o^{D_{\bOmega}(\overline{d}^{\uparrow \mathsf{ID}^{\infty}_{C_0-1,<0}}_{\pi_d(\sigma)\bot}(D_{\bOmega}(d_{\pi_d(\sigma)\top})))}(\langle\rangle)=\vartheta_{\bOmega,\vartheta_{\bOmega,\gamma}(o^d(\pi_d(\sigma)\top))}(o^d(\pi_d(\sigma)\top)[v_{n\in\mu xX.\phi,\langle\rangle}\mapsto \vartheta_{\bOmega,\gamma}(o^d(\pi_d(\sigma)\top))]).\]
Since $o^d(\pi_d(\sigma)\top)\ll_{\gamma} o^d(\pi_d(\sigma))$ and $o^d(\pi_d(\sigma)\bot)\ll_{\bOmega,\gamma} o^d(\pi_d(\sigma))$, we have $o^{D_d}(\sigma\top)\ll_0o^{D_d}(\sigma)$ as needed.


\end{proof}

\begin{theorem}
  If $d$ is a proof in $\mathsf{ID}_{\bOmega+\omega}$ whose conclusion does not contain negative occurences of any $\mu xX.\phi$ then there is a proof tree $d'$ in $\mathsf{ID}_{0,<0}^{\infty,+}$ with $\Gamma(d')\subseteq\Gamma(d)$ bounded by $\vartheta_{0,0}(\omega_k^{\#_{0< c<C}\{\Omega_{c},\Omega^{(0)}_{\bOmega+c},\Xi^{(0)}(\Omega^{(0)}_{\bOmega+c})\}\cdot 2\#\omega\#a})$ for some finite $C,k,a$.
\end{theorem}

