\textbf{Notation.} We use the standard notation $\N$, $\Z$, $\R$, and $\C$ to denote the set of natural numbers, the ring of integers, and the fields of real and complex numbers, respectively. For any $z \in \C$, we write $\Re z$ and $\Im z$ for the real and imaginary parts of $z$. Throughout this article, the symbols $C$, $C_1$, $C_2$, etc., will denote positive constants, which may vary from line to line. We write $X \lesssim Y$ (respectively, $X \gtrsim Y$) to mean that there exists a constant $C > 0$ such that $X \leq CY$ (respectively, $X \geq CY$). The notation $X \asymp Y$ indicates that both $X \lesssim Y$ and $X \gtrsim Y$ hold.



\section{Preliminaries}\label{sec_preliminaries}
Here, we review some general facts and necessary preliminaries regarding semisimple Lie groups and harmonic analysis on Riemannian symmetric spaces of noncompact type. Most of this information is already known and can be found in \cite{GV88, Hel08}. We will use the standard notation from \cite{Ion03, KRZ_23}. To keep the article self-contained, we will include only the results necessary for this article.
\subsection{Riemannian symmetric spaces} Let $G$ be a connected, noncompact, real semisimple Lie group with a finite center, and let $\mathfrak{g}$ be its Lie algebra. Let  $\theta$ be a Cartan involution of $\mathfrak{g}$, inducing the decomposition   $\mathfrak{g} = \mathfrak{k} \oplus \mathfrak{p}$. Let $K= \exp \mathfrak{k} $ be a maximal compact subgroup of $G$, and let $\mathbb{X} = G / K$ be an associated symmetric space with origin $\mathbf{0} = \{eK\}$. The Killing form of $\mathfrak{g}$ induces a $K$-invariant inner product  $\left\langle \cdot, \cdot \right\rangle$ on $ \mathfrak{p}$ and therefore a $G$-invariant Riemannian metric on $\X$. 

    Let $\mathfrak{a}$ be a maximal abelian subalgebra of $\mathfrak{p}$. The dimension of $\mathfrak{a}$ determines the rank of the symmetric space $\mathbb{X}$, denoted by $l$. Using the  inner product $\left\langle \cdot, \cdot \right\rangle$ inherited from  $\mathfrak{p}$, we identify  $\mathfrak{a}$ with $\mathbb{R}^l$. Let $\mathfrak{a}^*$ and $\mathfrak{a}_{\mathbb{C}}^*$ denote the real and complex duals of $\mathfrak{a}$, respectively. For any $\lambda \in \mathfrak{a}^*$, let $H_{\lambda}$ be the unique element of $\mathfrak{a}$ such that
    \begin{align*}
    \lambda(H) = \left\langle H_{\lambda}, H \right\rangle, \quad \text{for all } H \in \mathfrak{a}.
    \end{align*}
   With this, we transfer the inner product $\left\langle \cdot, \cdot \right\rangle$ from $\mathfrak{a}$ to $\mathfrak{a}^*$, and, by abuse of notation, denote it again by $\left\langle \cdot, \cdot \right\rangle$, defined by the rule
    \begin{align*}
    \left\langle \lambda, \lambda' \right\rangle= \left\langle H_{\lambda}, H_{\lambda'} \right\rangle, \quad \text{for all }  \lambda, \lambda' \in \mathfrak{a}^*.
\end{align*}
We identify $\fa$ with its dual $\fa^*$ by
means of the inner product defined above. We further extend the inner product on $\mathfrak{a}^*$ to a $\mathbb{C}$-bilinear form on $\mathfrak{a}_{\mathbb{C}}^*$.

Let $\Sigma \subset \mathfrak{a}^*$ be the set of restricted roots for the pair $(\mathfrak{g}, \mathfrak{a})$. Let $M$ denote the centralizer of $\mathfrak{a}$ in $K$, and let $W$ represent the Weyl group associated with $\Sigma$. For each $\alpha \in \Sigma$, let $\mathfrak{g}_\alpha$ be the corresponding root space, with $m_\alpha = \dim \mathfrak{g}_\alpha$. We choose a system of positive roots $\Sigma^+$ and define the associated positive Weyl chamber as $\mathfrak{a}^+ = \{H \in \mathfrak{a} : \alpha(H) > 0 \text{ for all } \alpha \in \Sigma^+\}$. Let $\Sigma_0^+$ denote the set of positive indivisible roots. The half-sum of all positive roots, counted with their multiplicities, is given by
$\rho = \frac{1}{2} \sum_{\alpha \in \Sigma^+} m_\alpha \alpha. $ 

Let $n$ represent the dimension of $\mathbb{X}$ and $\nu$ the pseudo-dimension (or dimension at infinity) of $\mathbb{X}$. These quantities are given by the following expressions
\begin{align*} n = l + \sum_{\alpha \in \Sigma^+} m_\alpha, \qquad \nu = l + 2 | \Sigma_0^+ |. \end{align*}
For example, $\nu=3$ while $n\geq 2 $ is arbitrary in the rank one case and $\nu=n$ if $G$ is complex.
In general, we have $l \geq 1$, $n \geq 2$, and $\nu \geq 3$. We denote by $-\mathcal{L}$ the positive Laplace-Beltrami operator on $\X$, and it is known that $|\rho|^2$ is the bottom of its $L^2$-spectrum.

By $\mathfrak{n} = \bigoplus_{\alpha \in \Sigma^+} \mathfrak{g}_\alpha$, we denote the nilpotent Lie subalgebra of $\mathfrak{g}$ associated with $\Sigma^+$, and by $N$ and $A$ the corresponding Lie subgroups of $\mathfrak{n}$ and $\mathfrak{a}$, respectively, in $G$. The Iwasawa decomposition of $G$ is given by $G = KAN$, meaning each element $g \in G$ can be uniquely expressed as \begin{align*} g = K(g) \exp(H(g))N(g), \quad K(g) \in K,\, H(g) \in \mathfrak{a}, \, N(g) \in N. \end{align*} Let $A^{+} = \exp(\mathfrak{a}^+)$, and let $\overline{A^{+}}$ denote the closure of $A^{+}$ in $G$. We then obtain the polar decomposition $G = K \overline{A^{+}} K$. As usual, on the compact group $K$ (respectively on $B=K/M$), we fix the normalized Haar
measure $dk$ (respectively the normalized measure  $db$). Under the Cartan decomposition, the Haar measure on $G$ can be expressed as follows.
\begin{equation*}
\begin{aligned}
\int_G f(g) d g & =\int_K \int_{\mathfrak{a}^{+}} \int_K f\left(k_1 (\exp H^+) k_2\right) \delta(H^+) \, d k_1\, d H^+\, d k_2,
\end{aligned}
\end{equation*}
where  $K$ is equipped with its normalized Haar measure, the density function $\delta(H^+)=C_0 \prod_{\alpha \in \Sigma^{+}}(\sinh \alpha(H^+))^{m_\alpha} $.
 If $f$ is a function on $\mathbb{X} = G / K$, it can be viewed as a right $K$-invariant function on $G$. Moreover, a function $f $ is called a $K$-biinvaraint if $f(x)= f(\exp x^+)$ for all $x \in G$, where $x^+$ denotes the component of $x$ in $\overline{A^{+}}$ under the Cartan decomposition. 



\subsection{Fourier transform on Riemannian symmetric spaces}
The Fourier transform $\widetilde{f}$ of a smooth, compactly supported function $f$ on $\mathbb{X}$ is defined on $\mathfrak{a}_{\mathbb{C}} \times B$ and is given by (see \cite[page 199]{Hel08}):
\begin{equation}\label{defn:hft}
\widetilde{f}(\lambda,b) = \int_{G} f(g) e^{(i\lambda- \rho)H(g^{-1}b)} dg,\:\:\:\:\:\:  \lambda \in \mathfrak{a}_{\mathbb{C}}, b \in B,
\end{equation}
where $B= K/ M$. It is known that if $f \in L^1(\mathbb{X})$, then $\widetilde{f}(\lambda, b)$ is continuous with respect to $\lambda \in \mathfrak{a}$ for almost every $b \in B$ (and is, in fact, holomorphic in $\lambda$ on a domain containing $\mathfrak{a}$). Furthermore, if $\widetilde{f} \in L^1(\mathfrak{a} \times B, |\bfc(\lambda)|^{-2}  \,d\lambda \,db)$, the following Fourier inversion formula holds for almost every $gK \in \mathbb{X}$ (\cite[Ch. III]{Hel08})
\begin{align*}
f(gK)= \frac{1}{|W|} \int_{\fa} \int_B \widetilde{f}(\lambda, b)~e^{-(i\lambda+\rho)H(g^{-1}b)} ~ |\bfc(\lambda)|^{-2}\,d\lambda~db,
\end{align*}
 where $\bfc(\lambda)$ is the Harish-Chandra's $\bfc$-function. Moreover, the Plancherel theorem states \cite[Ch. III, Theorem 1.5]{Hel08}
\begin{align}\label{Planc}
    \int_{\X} f_1(x) \overline{f_2(x)} \,dx= \frac{1}{|W|} \int_{\fa} \int_B \widetilde{f_1}(\lambda,b) \overline{\widetilde{f_2}(\lambda,b)}  |\bfc(\lambda)|^{-2} \, db \, d\lambda,
\end{align}
for all $f_1, f_2 \in C_c^{\infty}(\X)$. We also require the following estimates \cite[(2.2)]{CGM93} (see also \cite[Ch. IV, prop 7.2]{Hel00})
\begin{equation}\label{est_c-2,hr}
\begin{aligned}
    |\bfc(\lambda)|^{-2} \leq C |\lambda|^{\nu -l} (1+ |\lambda|)^{n-\nu}, \quad \text{for all } \lambda \in \mathfrak{a}.
\end{aligned}
\end{equation}
If $f$ is $K$-biinvariant, 
%meaning  $f(k_1gk_2)=f(g)$ for all  $k_1, k_2\in K$ and $g \in G$,
then  $\widetilde{f}$ does not depend on $B$ and  it reduces to spherical transform. In this case, the formula \eqref{defn:hft} simplifies to
\begin{equation}\label{eqn_sph_trans}
\widetilde{f}(\lambda, b)=\widehat{f}(\lambda)=\int_G f(g) \varphi_{-\lambda}(g) \,d g,
\end{equation}
for all $\lambda \in \mathfrak{a}, b \in B$, where
\begin{align*}
\varphi_\lambda(g)=\int_K e^{-(i \lambda+\rho)H(g^{-1} k)} d k, \quad \lambda \in \mathfrak{a}_{\mathbb{C}},
\end{align*} is the Harish-Chandra's elementary spherical function \cite{HC58}. In the rank one case, it is known that spherical analysis can be naturally embedded into the broader framework of Jacobi analysis developed by Koornwinder \cite{Koo84} (see also \cite{Koo75, ADY96}).
This connection between spherical analysis and Jacobi Fourier analysis enables the translation of many problems on Riemannian symmetric spaces into a setting where classical tools, such as special function estimates, weighted norm inequalities, and operator theory, can be effectively employed.
We will come back to this in Section \ref{sec_jac_base}, where we briefly recall some facts related to the Jacobi transform.


Now we like to recall some results from \cite{KRZ_23,RR24} which will be useful for us.  We can write from  \cite[Theorem 1.8]{RR24} the following mixed norm version of the Hausdorff-Young inequality on $\X$.
\begin{theorem}[{{\cite[Theorem 1.8]{RR24}}}]\label{thm_HY_UD}
     Let $\X$ be a general symmetric space of noncompact type, and let $1\leq p\leq 2 $. Then, for $1 < p \leq 2$ and all $f \in C_c^{\infty}(\X)$, we have the inequality
\begin{align}\label{eqn_HY_X,n}
    \left( \frac{1}{|W|}\int_{\mathbb{\fa}} \left(\int_B|\widetilde{f}(\lambda, b)|^{2} \, db\right)^{\frac{p'}{2}} |\bfc(\lambda)|^{-2} \,d \lambda \right)^{\frac{1}{p'}} \leq  \|f\|_{L^p(\X)}.
\end{align}  
For $p = 1$, we have the following analogue of a restriction estimate
%from \cite[(3.1)]{RR24}
     \begin{align}\label{f_L2K<L1_pre}
         \left( \int_B  \left| \widetilde{f}(\lambda,b)\right|^2 \,db \right)^{\frac{1}{2}}  & \leq  \|f\|_{L^1(\X)}.
         \end{align}
Moreover, if $p \geq 2$, then for all $f \in C_c^{\infty}(\X)$ we have the reverse inequality
%Moreover, if $p \geq 2$, then we have for all $f\in C_c^{\infty}(\X)$
\begin{align}\label{eqn_HYP_dual-int}
     \|f\|_{L^p(\X)} \leq   \left( \frac{1}{|W|}\int_{\mathbb{\fa}} \left(\int_B|\widetilde{f}(\lambda, b)|^{2} \, db\right)^{\frac{p'}{2}} |\bfc(\lambda)|^{-2} \,d \lambda \right)^{\frac{1}{p'}} .
\end{align}
\end{theorem}
We also recall from \cite[Theorem 1.9]{RR24} the following analogue of Paley's inequality \cite[Theorem 1.10]{Hor60} in the context of noncompact type symmetric spaces, which can also be seen as a weighted version of Plancherel’s formula for $L^p(\X)$ with $1 < p \leq 2$.
\begin{theorem}[{{\cite[Theorem 1.9]{RR24}}}]\label{thm_paley_uni}  Let $\X$ be a general symmetric space of noncompact type and let $1<p\leq 2$.
 Assume that $u$ is a positive function on $\fa$ satisfying the following condition 
	\begin{align*}
	 	 \|u\|_{c,\infty} := \sup_{\alpha>0} \alpha  \int\limits_{\substack{\{\lambda \in \fa : u(\lambda)>\alpha\} }} |\bfc(\lambda)|^{-2} \,d\lambda <\infty.
	 \end{align*}
  Then we have for all $f\in C_c^{\infty}(\X)$
  \begin{align*}
       \left( \int_{\mathbb{\fa}} \left(\int_B|\widetilde{f}(\lambda, b)|^{2} \, db\right)^{\frac{p}{2}} u(\lambda)^{2-p} |\bfc(\lambda)|^{-2} \,d \lambda \right)^{\frac{1}{p}} \leq C_p  \|u\|_{c,\infty}^{\frac{2}{p}-1}\|f\|_{L^p(\X)}.
  \end{align*}
\end{theorem}
We have the following from \cite[Corollary 1.8]{KRZ_23}.
\begin{corollary}\label{cor_pitt_KRZ,0}
    Let $\X$ be a symmetric space of dimension $n\geq 2$ and pseudo-dimension $\nu \geq 3$. Suppose that $0< \sigma< \nu$ and $f \in C_c^{\infty}(\X)$. Then, the inequality 
    \begin{align}\label{inq_pit_p,2}
     \left(   \int_{\fa} \int_{B}|\widetilde{f}(\lambda, b)|^2 |\lambda|^{-2\sigma} |\bfc(\lambda)|^{-2} \,db\, d\lambda \right)^{\frac{1}{2}} \leq C \left( \int_{\X}|f(x)|^p |x|^{\kappa p}\,dx \right)^{\frac{1}{p}}
    \end{align}
    holds for $1\leq   p<2$ if and only if   $0\leq \kappa\leq \sigma<{\nu}/{2}$, $\kappa<{n}/{p'}$ (when $p=1$, $\kappa=0$), and $\sigma-\kappa \geq n\left( {1}/{p}-{1}/{2}\right)$. Moreover, the inequality \eqref{inq_pit_p,2} holds for $p=2$ if and only if $\kappa=\sigma<\min\{\frac{\nu}{2},\frac{n}{2}\}$.
\end{corollary}




\subsection{Mixed norm interpolation theory}\label{subsec: mix_norm}
 Let $\left(X_j, dx_j\right), j=0,1$, be two $\sigma$-finite measure spaces and $(X, dx)$ their product measure space. For an ordered pair $P=\left(p_0, p_1\right) \in[1, \infty] \times[1, \infty]$ and a measurable function $f\left(x_0, x_1\right)$ on $(X, \mu)$,  we define the mixed norm $\left(p_0, p_1 \right)$ of $f$ as
\begin{align}\label{defn_mix_norm}
\|f\|_P=\|f\|_{{\left(p_0, p_1\right)}}=\left(\int_{X_0}\left(\int_{X_1}\left|f\left(x_0, x_1\right)\right|^{p_0} d x_1\right)^{p_1 / p_0} d x_0\right)^{1 / p_1} .
\end{align}
 For two such ordered pairs $P=\left(p_0, p_1\right)$ and $Q=\left(q_0, q_1\right)$, we write $1 / R=(1-\theta) / P+\theta / Q$, $0<\theta<1$ to mean $1 / r_0=(1-\theta) / p_0+\theta / q_0$ and $1 / r_1=(1-\theta) / p_1+\theta / q_1$, where $R=\left(r_0, r_1\right)$. We have the following analytic interpolation for the mixed norm spaces.

Let us consider two product measure spaces $X=X_0 \times X_1$ and $Y=Y_0 \times Y_1$. Let $d x$ and $d y$ denote respectively the (product) measures on $X$ and $Y$. Let $T_z $ be an analytic family of linear operators between $X$ and $Y$ of admissible growth, defined in the strip $\{ z \in \C : 0 \leq  \Re z \leq 1 \}$. We suppose that for all finite linear combinations of characteristic functions of rectangles of finite measures $f$ on $X$:
\begin{align*}
\left\|T_{j+ i \xi}(f)\right\|_{Q_j} \leq A_j(\xi)\|f\|_{P_j} 
\end{align*}
for $P_j, Q_j \in[1, \infty] \times[1, \infty]$ such that $\log \left|A_j(\xi)\right| \leq A e^{a|\xi|}, a<\pi, j=0, 1$. Let $1 / R=(1-\theta) / P_0+\theta / P_1$ and $1 / S=(1-\theta) / Q_0+\theta / Q_1, 0<\theta<1$. Then it follows similarly as in \cite[Page 313, Theorem 1]{BP61} (see also \cite[Theorem 1]{Ste56}) that
\begin{align}\label{eqn_ana_int}
\left\|T_\theta(f)\right\|_S \leq A_{\theta}\|f\|_R.
\end{align}
We refer the reader to \cite{BP61} for more details about the mixed norm spaces. However, we would like to mention that the order in which the mixed norms are taken in this article differs from that in \cite{BP61}. Following the calculation as a mixed norm space version of the  Stein-Weiss interpolation theory \cite[Theorem 2]{Ste56}, which can be derived using \eqref{eqn_ana_int}; see \cite[Corollary 7.3]{RR24} for more details.  
\begin{lemma}\label{cor_sw_ana}  
Let $1 \leq p, q_j, \tilde{q}_j \leq \infty$, and let $T$ be a linear operator defined on simple functions on the product space $X = X_0 \times X_1$, mapping into measurable functions on $Y = Y_0 \times Y_1$. Suppose ${w}_j: Y_0 \rightarrow \mathbb{R}^+$ and ${v}_j: X_0 \rightarrow \mathbb{R}^+$ are non-negative weight functions that are integrable over every subset of finite measure, for $j = 0, 1$. We further assume that for all functions $f$ that are finite linear combinations of characteristic functions of rectangles with finite measure in $X$, the following holds
\begin{align}\label{hyp_T_z_SW}
\|T (f)\cdot { w}_j \|_{L^{Q_j} (Y, dy)} \leq A_j \|f\cdot v_j\|_{L^{P_j}(X,dx)}
\end{align}
where $j = 0, 1$, and $ Q_j = (2,q_j),$ and $ P_j=(p_j,p_j).$ Then we have 
     \begin{align*}
        \|T (f)\cdot  {w}_{\theta}\|_{L^{Q_{\theta}} (Y, dy)} \leq A_{\theta} \|f\cdot v_{\theta} \|_{L^{P_\theta}(X, dx)}
    \end{align*}
    for all simple functions $f$ of finite measure support, $0<\theta<1$, where $Q_{\theta}= (2,q_{\theta})$, $P_{\theta}=(p_{\theta},p_{\theta})$ with 
    \begin{equation}\label{theta_exp_again}
    \begin{aligned}
       &\frac{1}{p_\theta}=  \frac{1-\theta}{p_0}+\frac{\theta}{p_1}, \qquad \quad \quad &&\frac{1}{q_{\theta}}= \frac{1-\theta}{q_0}+\frac{\theta}{q_1},\\
       & v_{\theta} = v_0^{ (1-\theta)} v_1^{ \theta} , \qquad \quad    && {w}_{\theta} = w_0^{ (1-\theta)} w_1^{ \theta} .
       \end{aligned}
       \end{equation}
\end{lemma} 
\section{Shifted Pitt's inequality on noncompact type symmetric spaces}\label{sec_pitt_X}
In this section, we prove Theorem \ref{thm_pitt_X_n}. We begin by establishing the following analogue of the classical Hardy–Littlewood–Paley inequality, as stated in \cite[Theorem 4.3]{Sad79}.
\begin{lemma}[Hardy-Littlewood-Paley's inequality]\label{lem_plaey_inq}
        Let $\X$ be a symmetric space of dimension $n\geq 2$, pseudo-dimension $\nu \geq 3$, and $1<p\leq 2$. Suppose that $ \zeta \geq 0, \sigma>0$, then for all $f \in C_c^{\infty}(\X)$ we have the  following inequality 
  \begin{align}\label{eqn_inq_paley_lem} 
\left( \int_{\mathbb{\fa}} \left(\int_B|\widetilde{f}(\lambda, b)|^{2} \, db\right)^{\frac{p}{2}} (|\lambda|^2+\zeta^2)^{-\frac{\sigma p}{2}} |\bfc(\lambda)|^{-2} \, d\lambda \right)^{\frac{1}{p}}
\leq C_p \left( \int_{\X}|f(x)|^p \,dx \right)^{\frac{1}{p}},
\end{align}
which holds for  $\zeta > 0$ if $\sigma \geq n(2/p-1)$, and  for $\zeta = 0$ if $n (2/p-1) \leq \sigma \leq \nu(2/p-1)$.

\end{lemma}
\begin{proof}
     For a fixed $\zeta\geq 0$, let us consider $u_{\sigma, \zeta}(\lambda):=(|\lambda|^2+\zeta^2)^{-\frac{\sigma}{2}}$, for $\sigma > 0$. 
  We will determine for which values of $\sigma$, $u_{\sigma,\zeta}$ will satisfy the hypothesis of Theorem \ref{thm_paley_uni}. First, we consider the case $\zeta=0$. The distribution function of $u_{\sigma,0}= u_\sigma$ with respect to the Plancherel measure $d\mu (\lambda):=|\bfc(\lambda)|^{-2} d\lambda$ is given by
 \begin{align*}
    \hspace{1.2cm} d_{u_{\sigma}}(\gamma)=  \mu\{\lambda \in \fa:   |\lambda|^{-\sigma} >\gamma\} = \mu\{\lambda \in \fa:   |\lambda|^{\sigma} < 1/\gamma\} = \mu\{\lambda \in \fa:   |\lambda| < \left( 1/\gamma\right)^{\frac{1}{\sigma}}\}.
 \end{align*}
 When $1<\gamma<\infty$, we can write using  \eqref{est_c-2,hr}
\begin{align*}
      d_{u_{\sigma}}(\gamma) \leq C \int_{0}^{\left( 1/\gamma\right)^{\frac{1}{\sigma}}}  s^{\nu-l} s^{l-1} \,ds \leq C \gamma^{-\frac{\nu}{\sigma}}.
\end{align*}
 For $0< \gamma\leq 1 $,  we have
 \begin{align*}
     d_{u_{\sigma}}(\gamma)\asymp \int_{0}^{1} s^{\nu -1}    ds +  \int_{1}^{\left( 1/\gamma\right)^{\frac{1}{\sigma}}} s^{n-l} s^{l-1} \,ds \leq C {\gamma^{-\frac{n}{\sigma}}}.
 \end{align*}
Thus, utilizing the estimates above, we obtain that for $\zeta=0$, if $n \leq \sigma\leq \nu$, then
\begin{align}\label{inq_u,L1}
     \sup_{\gamma>0} \gamma  \int\limits_{\substack{\{\lambda \in \fa : u_{\sigma, \zeta}(\lambda)>\gamma\} }} |\bfc(\lambda)|^{-2} \,d\lambda <\infty.
\end{align}  
For $\zeta > 0$, we observe that when $\gamma$ is sufficiently large, $d_{u_{\sigma, \zeta}}(\gamma)$ vanishes. More precisely, if $\gamma \geq (1/\zeta^2)^{\sigma/2}$, then 
\begin{align*}
    d_{u_{\sigma, \zeta}}(\gamma)=  \mu\{\lambda \in \fa:   {(|\lambda|^2+\zeta^2)}^{-\frac{\sigma}{2}} >\gamma\}  = \mu\{\lambda \in \fa:   |\lambda|^2 < \left( 1/\gamma\right)^{\frac{2}{\sigma}}-\zeta^2\}=\mu\{\emptyset \} \equiv 0.
\end{align*} 
Consequently, by performing a similar computation, we deduce that inequality \eqref{inq_u,L1} holds for $\zeta > 0$ whenever $\sigma \geq n$. Therefore, applying Theorem \ref{thm_paley_uni}, we obtain the following inequality for $1 < p \leq 2$:
\begin{align*} 
\left( \int_{\mathbb{\fa}} \left(\int_B|\widetilde{f}(\lambda, b)|^{2} \, db\right)^{\frac{p}{2}} (|\lambda|^2+\zeta^2)^{-\frac{\sigma p}{2}} |\bfc(\lambda)|^{-2} \, d\lambda \right)^{\frac{1}{p}}
\leq C \left( \int_{\X}|f(x)|^p \,dx \right)^{\frac{1}{p}}.
\end{align*}
This inequality holds in the case $\zeta = 0$ provided that $\sigma$ satisfies $n(2/p - 1) \leq \sigma \leq \nu(2/p - 1)$, and in the case $\zeta \neq 0$ whenever $\sigma \geq n(2/p - 1)$.
\end{proof}
\begin{remark}\label{rem_prob_lam_0}
\begin{enumerate}
    \item We note that unless $\nu \geq n$, it may not be possible to find any $\sigma \geq 0$ for which the Hardy–Littlewood–Paley inequality \eqref{eqn_inq_paley_lem} holds with $\zeta = 0$. As justification, we observed in the rank one case (see Remark \ref{rem_after_J_pit}) that \eqref{eqn_inq_paley_lem} may not hold for all $1 < p \leq 2$ when $\zeta = 0$, unless the condition $n \leq \nu$ is satisfied.

Furthermore, in higher rank cases, we recall from Corollary \ref{cor_pitt_KRZ,0} that in order for unshifted Pitt's inequality \eqref{inq_pit_p,2} to hold with $q = 2$ and $1 \leq p < 2$, it is necessary that $0 \leq \kappa \leq \sigma < \nu/2$, $\kappa p' < n$, and $n(1/p - 1/2) \leq \sigma - \kappa$. These conditions together imply $n(1/p - 1/2) < \nu/2$. From this, it follows that if $n > \nu$, then for some $p$ sufficiently close to 1, inequality \eqref{inq_pit_p,2} may fail. Therefore, to ensure that the unshifted Pitt's inequality holds for all $1 < p \leq q < \infty$, the condition $n \leq \nu$ is essential.  This justifies our assumption $\min\{n, \nu\} = n$ in Theorem \ref{thm_pitt_X_n} for the case $\zeta = 0$, and ensures the existence of some $\sigma \geq 0$ for which \eqref{eqn_inq_paley_lem} holds.
\item We recall that one of the most distinctive features of symmetric spaces of noncompact type is the holomorphic extension of the Fourier transform. This motivates the study of Fourier inequalities not merely on $\fa$, but over the entire domain of holomorphic extension, something without a direct analogue in $\R^N$.  Particularly, in the rank one case, it is natural to investigate the Hardy–Littlewood–Paley inequality (see Lemma \ref{lem_plaey_inq}) for $L^p$-functions ($1\leq p<2$)  whose Fourier transform is defined on the tube domain $S_p = \fa + i\mathrm{co}(W \cdot \rho_p)$, where $\rho_p := |2/p - 1||\rho|$.

In this direction, using the Paley inequality on non-unitary duals from \cite[Theorem 1.1, Remark 5.2 (2)]{RR24} and a similar argument as in Lemma \ref{lem_plaey_inq}, we obtain the following version of the Hardy–Littlewood–Paley inequality on non-unitary duals in rank one cases: Let $\X$ be a rank one symmetric space of dimension $n \geq 2$, and let $1 < p \leq 2$.  Then for any $q_0$ with $p \leq q_0 \leq p'$, we have the  following inequality for all $f \in C_c^\infty(\X)$ 
  \begin{align*}
\left( \int_{\mathbb{\fa}} \left( \int_B  \left|\widetilde {f}(\lambda +i\rho_{q_0} , b) \right|^{q_0}   \,  db \right)^{\frac{p}{q_0}} (|\lambda|^2+\zeta^2)^{-\frac{\sigma p}{2}} |\bfc(\lambda)|^{-2} \, d\lambda \right)^{\frac{1}{p}}
\leq C_p \left( \int_{\X}|f(x)|^p \,dx \right)^{\frac{1}{p}},
\end{align*}
which holds for  $\zeta > 0$ if $\sigma >n(2/p-1)$, and  for $\zeta = 0$ if $n (2/p-1) < \sigma < 3(2/p-1)$. We also note that $\nu = 3$ for all rank one symmetric spaces.
\end{enumerate}
\end{remark}
We require the following lemma, which follows from \cite[Theorem 1.2]{KRZ_23} by taking $\beta = 0$, $q = 2$, and $\zeta > 0$, and then applying the Plancherel theorem.
\begin{lemma}\label{cor_pitt_KRZ>0}
     Let $\X$ be symmetric space of dimension $n\geq 2$ and $ \zeta > 0$. Suppose that $\sigma >0$ and $f \in C_c^{\infty}(\X)$. Then, the inequality 
    \begin{align}\label{inq_pit_p,2_n}
     \left(   \int_{\fa} \int_{B}|\widetilde{f}(\lambda, b)|^2 (|\lambda|^2+\zeta^2)^{-{\sigma}} |\bfc(\lambda)|^{-2} \, db\, d\lambda \right)^{\frac{1}{2}} \leq C \left( \int_{\X}|f(x)|^p |x|^{\kappa p}\,dx \right)^{\frac{1}{p}}
    \end{align}
    holds for $1\leq  p\leq 2$ if and only if  $0\leq \kappa\leq \sigma$, $\kappa<{n}/{p'}$ (when $p=1$, $\kappa=0$), and $\sigma-\kappa \geq n\left( {1}/{p}-{1}/{2}\right)$. 
\end{lemma}
With the Hardy–Littlewood–Paley inequality and the preceding lemma in place, we are now prepared to prove one of our main results on shifted Pitt's inequality on noncompact type symmetric spaces. Our approach is inspired by the mixed-norm version (Lemma \ref{cor_sw_ana}) of Stein’s interpolation theory developed in \cite{Ste56}. However, a key novelty of our method lies in how we handle the presence of shifted weights on the Fourier transform side. The shifted structure in our setting necessitates a careful modification of the interpolation framework. To accommodate this, we adapt the interpolation argument by introducing a modified inequality that captures the interaction between the weight and the spectral shift. This refinement is crucial for establishing the desired Pitt-type inequalities in our setting.

\begin{proof}[\textbf{Proof of Theorem \ref{thm_pitt_X_n}}]
We will prove the theorem for the case $p > 1$; when $p = 1$, the parameter $\kappa$ equals zero, and the theorem can be established using a similar argument. So, let us assume $p > 1$ and recall the Hardy–Littlewood–Paley inequality from \eqref{eqn_inq_paley_lem}, which we now rewrite for $1 < r \leq 2$
\begin{align}\label{inq_paley_pol} 
\left( \int_{\mathbb{\fa}} \left(\int_B|\widetilde{f}(\lambda, b)|^{2} \, db\right)^{\frac{r}{2}} (|\lambda|^2+\zeta^2)^{-\frac{\delta r}{2}} |\bfc(\lambda)|^{-2} \, d\lambda \right)^{\frac{1}{r}}
\lesssim \left( \int_{\X}|f(x)|^r \,dx \right)^{\frac{1}{r}},
\end{align}
which holds for $\zeta = 0$ if $n (2/r-1) \leq \delta \leq \nu(2/r-1)$, and for $\zeta > 0$ if $\delta \geq n(2/r-1)$. \par
     First, we will handle the case when $\zeta \neq 0$. For this, we recall from \eqref{inq_pit_p,2_n} that
 \begin{align}\label{inq_pit_p,2_rec>0}
     \left(   \int_{\fa} \int_{B}|\widetilde{f}(\lambda, b)|^2 (|\lambda|^2 +\zeta^2)^{-{\beta} } |\bfc(\lambda)|^{-2} \, db\, d\lambda \right)^{\frac{1}{2}} \lesssim  \left( \int_{\X}|f(x)|^2 |x|^{2\alpha }\,dx \right)^{\frac{1}{2}}.
    \end{align} 
        holds for if   $0\leq \alpha\leq \beta$ and $\alpha<{n}/{2}$.
      \par
    \textbf{Case I.} $1<p=q\leq 2$.   
    We choose $\theta$ such that 
    $1/p= (1-\theta)/r +\theta/2$, where we will vary $r$ between $1$ to $p$. Applying Lemma \ref{cor_sw_ana} with the following
    \begin{align*}
        p_0=q_0=r,\,  p_1=q_1=2, \quad v_0 =1,v_1=|x|^{\alpha}, \quad w_0=(|\lambda|^2+\zeta^2)^{-\frac{\delta}{2}} , w_1=(|\lambda|^2+\zeta^2)^{-\frac{\beta}{2}},
    \end{align*}
    and interpolating \eqref{inq_paley_pol}, \eqref{inq_pit_p,2_rec>0}, we obtain
    \begin{align}\label{pitt_p=q<2,X}
          \left(   \int_{\fa} \left(\int_{B}|\widetilde{f}(\lambda, b)|^2 db\right)^{\frac{p}{2}} (|\lambda|^2 +\zeta^2)^{-\frac{\sigma p}{2}} |\bfc(\lambda)|^{-2} \, d\lambda \right)^{\frac{1}{p}} \lesssim \left( \int_{\X}|f(x)|^p |x|^{\kappa p }\,dx \right)^{\frac{1}{p}}
    \end{align}
    where 
    \begin{align*}
        \kappa= \theta \alpha, \qquad \sigma =(1-\theta) \delta +\theta \beta.
    \end{align*}
    By putting the value $\theta = (1/r-1/p)/(1/r-1/2)$ and $(1-\theta) = (1/p-1/2)/(1/r-1/2)$, the equation above transforms into 
  \begin{align*}
        \kappa=   \frac{\left( \frac{1}{r}-\frac{1}{p} \right)}{ \left( \frac{1}{r}-\frac{1}{2} \right)} \alpha, \qquad \sigma = \frac{\left( \frac{1}{p}-\frac{1}{2} \right)}{ \left( \frac{1}{r}-\frac{1}{2} \right)} \delta+  \frac{\left( \frac{1}{r}-\frac{1}{p} \right)}{ \left( \frac{1}{r}-\frac{1}{2} \right)} \beta .
    \end{align*}
    Since $\alpha \in [0,n/2)$, and we can choose $r \in (1,p)$ arbitrarily, so \eqref{pitt_p=q<2,X} holds for  all  $0 \leq \kappa <n/{p'} $. Additionally, we observe that since $\beta \geq \alpha$, and \eqref{inq_paley_pol}  holds for all $\delta \geq n(2/r-1) $, therefore, we have shown that  \eqref{pitt_p=q<2,X} holds for all $\kappa$ and $\sigma$ such that 
    \begin{align*}
        0\leq \kappa < \frac{n}{p'}, \quad \text{and} \quad \sigma \geq n\left(\frac{2}{p}-1 \right)+\kappa.
    \end{align*}
\par 
    \textbf{Case II.} $1<p\leq 2 <q=p'$. We choose $\theta$ such that $1/p= (1-\theta)+\theta/2$.\\
   \noindent We have the following restriction inequality from \eqref{f_L2K<L1_pre}
    \begin{align}\label{f_L2K<L1}
        \left( \int_B  \left| \widetilde{f}(\lambda,b)\right|^2 \,db \right)^{\frac{1}{2}}  & \leq  \|f\|_{L^1(\X)}.
    \end{align}
 We now apply Lemma \ref{cor_sw_ana} with 
    \begin{align*}
        p_0=1, q_0=\infty,\,  p_1=q_1=2, \quad v_0 =1,v_1=|x|^{\alpha}, \quad w_0=1, w_1=(|\lambda|^2+\zeta^2)^{-\frac{\beta}{2}},
    \end{align*}
    and interpolating \eqref{inq_pit_p,2_rec>0} with \eqref{f_L2K<L1}, we obtain
     \begin{align}\label{pitt_p<2<p',X}
          \left(   \left(\int_{\fa} \int_{B}|\widetilde{f}(\lambda, b)|^2  \,db \right)^{\frac{p'}{2}}(|\lambda|^2 +\zeta^2)^{-\frac{\gamma p'}{2}} |\bfc(\lambda)|^{-2} \, d\lambda \right)^{\frac{1}{p'}} \lesssim \left( \int_{\X}|f(x)|^p |x|^{\kappa p }\,dx \right)^{\frac{1}{p}},
    \end{align}
    where 
    \begin{align*}
        \kappa=   \frac{2\alpha}{p'}, \qquad \gamma =\frac{2\beta}{p'}.
    \end{align*}
    Since \eqref{inq_pit_p,2_rec>0} holds for all  $0\leq \alpha\leq \beta$ and $\alpha<{n}/{2}$, thus we have shown that \eqref{pitt_p<2<p',X} holds for all  $\kappa$ and $\gamma$ such that 
    \begin{align*}
        0\leq \kappa < \frac{n}{p'}, \quad \text{and} \quad \gamma \geq \kappa,
    \end{align*}
    where $1\leq p\leq 2$.
         \par

    \textbf{Case III.} $1<p\leq 2, p\leq q \leq p'$. We can rewrite \eqref{pitt_p=q<2,X} as 
       \begin{align}\label{pitt_p=q<2,X_nw}
          \left(   \int_{\fa} \left( \int_{B}|\widetilde{f}(\lambda, b)|^2 db\right)^{\frac{p}{2}} (|\lambda|^2 +\zeta^2)^{-\frac{\vartheta p}{2}} |\bfc(\lambda)|^{-2} \, d\lambda \right)^{\frac{1}{p}} \lesssim  \left( \int_{\X}|f(x)|^p |x|^{\kappa p }\,dx \right)^{\frac{1}{p}},
    \end{align}
    which holds for $1<p\leq 2$, $0\leq \kappa<n/{p'}$, and $\vartheta \geq n( {2}/{p}-1)+\kappa.$ Let us choose $\theta$ such that $1/q= (1-\theta)/{p}+ \theta/{p'}$. Applying Lemma \ref{cor_sw_ana} with the following
    \begin{align*}
        p_0= q_0= p,\,  p_1=p, q_1=p', \quad v_0 =|x|^{\kappa},v_1=|x|^{\kappa}, \quad w_0=(|\lambda|^2+\zeta^2)^{-\frac{\vartheta}{2}} , w_1=(|\lambda|^2+\zeta^2)^{-\frac{\gamma}{2}},
    \end{align*}
    and interpolating \eqref{pitt_p=q<2,X_nw}, \eqref{pitt_p<2<p',X}, we get
    \begin{align}\label{pitt_p<2,p<q,X}
          \left(   \int_{\fa} \left( \int_{B}|\widetilde{f}(\lambda, b)|^2 \,db\right)^{\frac{q}{2}} (|\lambda|^2 +\zeta^2)^{-\frac{\sigma q}{2}} |\bfc(\lambda)|^{-2} \, d\lambda \right)^{\frac{1}{q}} \lesssim \left( \int_{\X}|f(x)|^p |x|^{\kappa p }\,dx \right)^{\frac{1}{p}},
    \end{align}
    where 
    \begin{align*}
        0\leq \kappa< \frac{n}{p'}, \qquad \sigma =(1-\theta) \vartheta +\theta  \gamma. 
    \end{align*}
  Now using the range of $ \vartheta$ and $\gamma $ (as in \eqref{pitt_p=q<2,X_nw}, \eqref{pitt_p<2<p',X}) and putting the value of $\theta = (1/p-1/q)/(2/p-1) $, we can say that the inequality \eqref{pitt_p<2,p<q,X} holds for all $0\leq \kappa <n/p'$ and for all $\sigma$ such that
  \begin{align}
      \sigma\geq (1-\theta)  \left( n\left(\frac{2}{p}-1 \right)+\kappa\right)+\theta  \kappa = n\left(  \frac{1}{p}+\frac{1}{q}-1\right) +\kappa. 
  \end{align}
  This concludes the sufficient part of Theorem~\ref{thm_pitt_X_n} for $\zeta>0$.


    \vspace{3mm}
    Now we will handle the case $\zeta=0$.  In this case, we assume that $\nu\geq n$.  Then we  recall the Hardy-Littlewood-Paley's inequality from \eqref{eqn_inq_paley_lem}  for $1<r\leq 2$
\begin{align}\label{inq_paley_pol_0} 
\left( \int_{\mathbb{\fa}} \left(\int_B|\widetilde{f}(\lambda, b)|^{2} \, db\right)^{\frac{r}{2}} |\lambda|^{-{\delta r}} |\bfc(\lambda)|^{-2} \, d\lambda \right)^{\frac{1}{r}}
\lesssim \left( \int_{\X}|f(x)|^r \,dx \right)^{\frac{1}{r}},
\end{align}
which holds for $\zeta = 0$ if $n (2/r-1) \leq \delta \leq \nu(2/r-1)$.  We have from  \eqref{inq_pit_p,2} that
 \begin{align}\label{inq_pit_p,2_0}
     \left(   \int_{\fa} \int_{B}|\widetilde{f}(\lambda, k)|^2 |\lambda|^{-2\alpha} |\bfc(\lambda)|^{-2} \, db\, d\lambda \right)^{\frac{1}{2}} \lesssim \left( \int_{\X}|f(x)|^2 |x|^{2\alpha }\,dx \right)^{\frac{1}{2}}.
    \end{align} 
        holds for if and only if $\alpha<n/2$. Next, we will follow a similar strategy as in the case $\zeta \neq 0$.

        \textbf{Case I.} $1<p=q\leq 2$.  
   By choosing $\theta$ such that 
    $1/p= (1-\theta)/r +\theta/2$, and following a similar calculation as in \eqref{pitt_p=q<2,X}, except we make use of \eqref{inq_paley_pol_0} and \eqref{inq_pit_p,2_0} to obtain 
    \begin{align}\label{pitt_p=q<2,X_0}
          \left(   \int_{\fa} \left(\int_{B}|\widetilde{f}(\lambda, b)|^2 db\right)^{\frac{p}{2}} |\lambda| ^{-\sigma p} |\bfc(\lambda)|^{-2} \, d\lambda \right)^{\frac{1}{p}} \lesssim \left( \int_{\X}|f(x)|^p |x|^{\kappa p }\,dx \right)^{\frac{1}{p}},
    \end{align}
    where 
    \begin{align*}
        \kappa= \theta \alpha, \qquad \sigma =(1-\theta) \delta +\theta \alpha.
    \end{align*}
    By putting the value $\theta = (1/r-1/p)/(1/r-1/2)$, and observing that we can choose any $r\in (1,\infty) $, we can derive that \eqref{pitt_p=q<2,X_0} holds for all $\kappa$ and $\sigma$ such that 
    \begin{align}
        0\leq \kappa < \frac{n}{p'} \quad \text{and} \quad n\left(\frac{2}{p}-1 \right)\leq  \sigma-\kappa \leq \nu\left(\frac{2}{p}-1 \right).
    \end{align}
  \par
   \textbf{Case II.} $1<p\leq 2 <q=p'$. Following the exact same calculation as in \eqref{pitt_p<2<p',X}, except that we use \eqref{inq_pit_p,2_0} instead of \eqref{inq_pit_p,2_rec>0} to obtain the following 
    \begin{align}\label{pitt_p<2<p',X_0}
          \left(  \int_{\fa} \left( \int_{B}|\widetilde{f}(\lambda, b)|^2  db \right)^{\frac{p'}{2}}|\lambda|^{-\kappa p'} |\bfc(\lambda)|^{-2} \, d\lambda \right)^{\frac{1}{p'}} \lesssim \left( \int_{\X}|f(x)|^p |x|^{\kappa p }\,dx \right)^{\frac{1}{p}}
    \end{align}
    holds for all $ 0\leq \kappa < {n}/{p'}$. 


    \textbf{Case III.} $1<p\leq 2, p\leq q\leq p'$. We can rewrite \eqref{pitt_p=q<2,X_0} as 
       \begin{align}\label{pitt_p=q<2,X_nw_0}
          \left(   \int_{\fa} \left( \int_{B}|\widetilde{f}(\lambda, b)|^2 \, db\right)^{\frac{p}{2}} |\lambda|^{-\vartheta p} |\bfc(\lambda)|^{-2} \, d\lambda \right)^{\frac{1}{p}} \lesssim \left( \int_{\X}|f(x)|^p |x|^{\kappa p }\,dx \right)^{\frac{1}{p}},
    \end{align}
    which holds for $1<p\leq 2$, $0\leq \kappa<n/{p'}$, and $n( {2}/{p}-1) \leq \vartheta-\kappa \leq \nu( {2}/{p}-1).$ Now by choosing $\theta$ such that $1/q= (1-\theta)/{p}+ \theta/{p'}$ and interpolating between \eqref{pitt_p=q<2,X_nw_0} and \eqref{pitt_p<2<p',X_0}, we obtain
    \begin{align}\label{pitt_p<2,p<q,X_0}
          \left(   \int_{\fa} \left( \int_{B}|\widetilde{f}(\lambda, k)|^2 \,db\right)^{\frac{q}{2}} |\lambda|^{-{\sigma q}} |\bfc(\lambda)|^{-2} \, d\lambda \right)^{\frac{1}{q}} \lesssim \left( \int_{\X}|f(x)|^p |x|^{\kappa p }\,dx \right)^{\frac{1}{p}},
    \end{align}
    where 
    \begin{align*}
        0\leq \kappa< \frac{n}{p'}, \qquad \sigma =(1-\theta) \vartheta +\theta  \gamma. 
    \end{align*}
  Now using the range of $ \vartheta$ and $\gamma $  and putting the value of $\theta = (1/p-1/q)/(2/p-1) $, we can say that the inequality \eqref{pitt_p<2,p<q,X_0} holds for all $0\leq \kappa <n/p'$ and for all $\sigma$ such that
  \begin{align}
      n\left(  \frac{1}{p}+\frac{1}{q}-1\right) \leq \sigma -\kappa \leq  \nu\left(  \frac{1}{p}+\frac{1}{q}-1\right). 
  \end{align}
This concludes the proof of the sufficiency part of Theorem~\ref{thm_pitt_X_n} for all $\zeta \geq 0$.

The necessity part of Theorem~\ref{thm_pitt_X_n} in the rank one case follows from Theorem~\ref{thm_nec_pitt_n}, which will be established in Section~\ref{sec_jac_transform}
\end{proof}
\begin{remark}
   To address the case $q > p'$, Stein \cite{Ste56} used the Hardy–Littlewood–Paley inequality for $2 < p = q < \infty$ with $\sigma = 0$ in \eqref{Clss_Pitt_Rn_pw}. In the setting of rank one symmetric spaces of noncompact type, we have shown that establishing a similar inequality (for $2 < p = q < \infty$ and $\sigma = 0$ in \eqref{inq_pitt_pol}) requires the introduction of additional exponential weights on the function side. More generally, Theorem~\ref{thm_nec_pitt_n} shows that for the shifted Pitt's inequality \eqref{inq_pitt_pol} to hold, a necessary condition is $p \leq 2$, due to the exponential volume growth of these spaces. 
   Since the present work focuses on Pitt-type inequalities with polynomial weights, consistent with the classical framework, we leave the investigation of exponential-weighted versions and the case $q > p'$ on symmetric spaces to future research.
\end{remark}


\section{Shifted Pitt's inequality for Jacobi transforms}\label{sec_jac_transform}
We now turn our focus to shifted Pitt's inequality in the setting of the Jacobi transform, which generalizes spherical analysis on rank one symmetric spaces \cite{Koo84}. Unlike the higher rank case, the Jacobi functions that define the Fourier transform in this context exhibit a rich set of special properties. We leverage these features to establish not only sufficient conditions but also necessary ones for the validity of the shifted Pitt's inequality. In contrast to Theorem \ref{thm_pitt_X_n}, where our method relied on mixed-norm interpolation techniques, the proof here follows a different strategy tailored specifically to the Jacobi setting and adapted to handle the range $q >p'$, which was not accessible in the symmetric space case.


 We begin by reviewing some general facts and necessary preliminaries regarding Jacobi transforms. Most of this information is already known and can be found in \cite{FJT73,Koo75,Koo84, GLT18}.
 %; see also \cite{FJT79, BP97, BP08}. 
 We will use the standard notation from \cite{Koo84, GLT18}. To keep the article self-contained, we will include only the results necessary for this article, following the preliminaries outlined in \cite{Koo84,GLT18}.
\subsection{Basic properties of Jacobi transforms}\label{sec_jac_base} The Jacobi functions are defined by
\begin{align*}
    \varphi_{\lambda}^{(\alpha, \beta)}(t) =\, _2F_1\left( \frac{\rho+i\lambda}{2},\frac{\rho-i\lambda}{2};\alpha
    +1; -(\sinh t)^2\right), \quad t\geq 0,\, \alpha, \beta, \lambda\in \C,
\end{align*}
where $\rho= \alpha+\beta+1$ and $_2F_1(a,b;c;z) $ is the hypergeometric Gauss function defined as in \cite[(2.1)]{Koo84}. We consider the case
\begin{align}\label{eqn_rel_a,b}
    \alpha\geq \beta \geq -\frac{1}{2}, \quad \alpha>-\frac{1}{2}.
\end{align}
Equivalently, the Jacobi function $\varphi_{\lambda}^{(\alpha,\beta)}$ can be defined as the unique even $C^{\infty}$ function on $\R$ such that $\varphi(0)=1$ and 
\begin{align*}
   \left( \mathcal{L}_{\alpha, \beta} +\lambda^2+\rho^2 \right)\varphi=0,
\end{align*}
where 
\begin{align}\label{defn_of_L_Jac}
   \mathcal{L}_{\alpha, \beta}:= \frac{d^2}{dt^2} +(2\alpha+1)\coth t+(2\beta+1)\tanh t)\frac{d}{dt}.
\end{align}
We have the following estimate of $\varphi_{0}^{(\alpha,\beta)}$ (see
 \cite[(3.5)]{ADY96} and \cite[Prop. 8.1]{GLT18} for instance):
\begin{align}\label{eqn_est_phi_0}
\varphi_0^{(\alpha,\beta)}(t) \asymp \left(1+t\right)e^{-\rho t}, \quad t\geq 0.
\end{align}
From now on, we fix $\alpha$ and $\beta$ satisfying \eqref{eqn_rel_a,b}, and for simplicity of notation, we will write $\varphi_{\lambda}$ instead of $\varphi_{\lambda}^{(\alpha,\beta)}$ and $\mathcal{L}$ instead of $\mathcal{L}_{\alpha,\beta}$.
% From now onward, we fix $\alpha, \beta$, which satisfy \eqref{eqn_rel_a,b} and to simplify notation we will write $\varphi_{\lambda}$ instead $\varphi_{\lambda}^{(\alpha,\beta)}$.
\subsubsection{Standard Jacobi transforms}   For suitable functions $f,F$ on $\R_+$, the direct Jacobi transform is defined by 
\begin{align*} 
\mathcal{J}f(\lambda) =  \int_0^{\infty} f(t) \varphi_{\lambda}^{(\alpha,\beta)}(t) m(t) \,dt, \quad \lambda \geq 0,
\end{align*}
and the inverse Jacobi transform defined by
\begin{align*}
    \mathcal{I}F(t) =  \int_0^{\infty} F(\lambda) \varphi_{\lambda}^{(\alpha,\beta)}(t) n(\lambda) d\lambda, \quad t\geq 0,
\end{align*}
where 
\begin{equation}\label{def_m(t)}
\begin{aligned}
     m(t)= (2\pi)^{-\frac{1}{2}} \Delta(t), \qquad & \Delta(t)= 2^{2\rho}(\sinh t)^{2\alpha+1}(\cosh t)^{2\beta+1},\\
     n(\lambda) =(2\pi)^{-\frac{1}{2}}|\bfc(\lambda)|^{-2}, \qquad& \bfc(\lambda)=\frac{2^{\rho-i\lambda} \Gamma(\alpha+1)\Gamma(i\lambda)}{\Gamma\left( \frac{\rho+i\lambda}{2}\right)\Gamma\left( \frac{\rho+i\lambda}{2}-\beta\right)}.
\end{aligned}
\end{equation}
The Jacobi transform $\mathcal{J}$ establishes a bijection between the space of even, infinitely differentiable functions with compact support and the space of even entire functions of exponential type exhibiting rapid decay; see \cite[Theorem 3.4]{Koo75}. It also extends to an isometric isomorphism between the spaces $L^2(dm(t))$ and $L^2(dn(\lambda))$, and satisfies the corresponding Plancherel theorems
\begin{align}\label{eqn_planc_J}
  \left(\int_0^{\infty}|f(t)|^2 m(t)\, dt \right)^{\frac{1}{2}} &=\left( \int_0^{\infty} |\mathcal{J}f(\lambda)|^2 n(\lambda) \, d\lambda \right)^{\frac{1}{2}},\\
  \label{eqn_planc_I}
     \left( \int_0^{\infty}|F(\lambda)|^2 n(\lambda) \, d\lambda \right)^{\frac{1}{2}}&= \left(\int_0^{\infty} |\mathcal{I}F(t)|^2 m(t)\, dt \right)^{\frac{1}{2}}.
\end{align}
When $\alpha = \beta$, the Jacobi transform is commonly referred to as the Mehler–Fock transform. In particular, when $\alpha = \beta = -{1}/{2}$, the Jacobi transform reduces to the classical cosine transform. For a detailed study of Pitt's inequality in the context of the cosine transform, we refer the reader to \cite[Sec. 7]{GLT18}.
\begin{remark}
\begin{enumerate}
    \item    We remark that the definition of $\mathcal{J}f(\lambda)$ coincides precisely with the spherical Fourier transform \eqref{eqn_sph_trans} when the parameters $\alpha$ and $\beta$ correspond to geometric cases. More precisely, as shown in \cite[(4.6)]{Koo84}, if $\X$ is a rank one symmetric space of noncompact type, then $\alpha = (n-1)/2$ and $\beta =(m_2-1)/2$,    where $m_2$ is a constant depending on  $\X$.
    \item In the Euclidean setting, the authors in \cite{BH03, He84} employed the method of non-increasing rearrangements to prove Pitt's inequality. However, in the Jacobi setting, this approach does not seem to be very effective for polynomial weights, as the exponential growth of the measure dominates and essentially ignores the polynomial decay at infinity (see Remark \ref{rem_after_J_pit} \eqref{rem_problem_exp_space}).  To address this limitation, we introduce a suitable weight into the Jacobi transform, thereby modifying the function space to reflect polynomial growth. More precisely, following Gorbachev et al. \cite{GLT18}, we define a modified Jacobi transform by adjusting the underlying measure. This leads to a setting with doubling volume growth, where the rearrangement method becomes applicable and more accurately captures the interplay between the geometry of the space and the behavior of polynomial weights.
    \end{enumerate}

\end{remark}
 \subsubsection{Modified Jacobi transforms}
The modified Jacobi transforms are defined by the relations
\begin{align*} 
\tilde{\mathcal{J}}f(\lambda) &=  \int_0^{\infty} f(t) \tilde{\varphi}_{\lambda}^{(\alpha,\beta)}(t) \tilde{m}(t) \,dt, \,\,\,\quad \lambda \geq 0,\\
    \tilde{\mathcal{I}}F(t) &=  \int_0^{\infty} F(\lambda) \tilde{\varphi}_{\lambda}^{(\alpha,\beta)}(t) n(\lambda) \, d\lambda, \quad t\geq 0,
\end{align*}
where
\begin{align*}
    \tilde{\varphi}_{\lambda}(t)=  \tilde{\varphi}_{\lambda}^{\alpha, \beta}(t):=\frac{\varphi_{\lambda}(t)}{\varphi_0(t)}, \qquad \tilde{m}(t)= \varphi_0^2(t) m(t).
\end{align*}
 It follows from \eqref{def_m(t)} and the estimate of $\varphi_0$ \eqref{eqn_est_phi_0}  that
\begin{align}\label{est_sharp_mtil}
    \tilde{m}(t)\asymp \begin{cases}
        t^{2\alpha+1} &\quad t\leq 1,\\
        t^{2} & \quad  t \geq 1.
    \end{cases}
\end{align}
On the other hand, we have from   \cite[(8.20)]{GLT18}
\begin{align}\label{est_sharp_n}
    n(\lambda)\asymp \begin{cases}
        \lambda^{2} &\quad \lambda\leq 1,\\
        \lambda^{2\alpha+1} & \quad  \lambda \geq 1. 
    \end{cases}
\end{align}
  We have the following relation  between the transforms
 \begin{align}\label{eqn_rel_J_mJ}
      \tilde{\mathcal{J}} f(\lambda) = \mathcal{J}(f\cdot \varphi_0)(\lambda), \qquad \tilde{\mathcal{I}}F(t) = \varphi_0(t)^{-1}\mathcal{I}F(t).
 \end{align}
 Also, we have from \eqref{eqn_planc_J} and \eqref{eqn_planc_I} that
 \begin{align}\label{eqn_plac_mJ,I}
     \|f\|_{L^2(\tilde{m})} = \|\mathcal{J}f\|_{L^2(n)}, \qquad  \|F\|_{L^2({n})} = \|\mathcal{I}F\|_{L^2(\tilde{m})}. 
 \end{align}
 The authors  \cite[Theorem 8.2]{GLT18} proved the following unshifted Pitt's inequality for piecewise power weights. However, we are going the state the result for the usual power weights. 
 %We refer the reader to Section \ref{sec_Jacobi} or \cite[Theorem 8.2]{GLT18}   for any unexplained notations.
\begin{theorem}[{{\cite[Theorem 8.2]{GLT18}}}]\label{thm_pitt_Jac}
 Suppose $1<p \leq q<\infty$.
 \begin{enumerate}
     \item[(A)] Let $\sigma$ and $\kappa$ be \textbf{dual} and $(\sigma, \kappa) \in \mathbf{D_{p, q}}(2\alpha+1, 2)$; then,
\begin{align}\label{Pitt_pow_J_int}
  \left( \int_0^{\infty} |\tilde{\mathcal{J}} f(\lambda)|^q  \lambda^{-\sigma q} {n}(\lambda)\, d\lambda \right)^{1/q} \lesssim   \left( \int_0^{\infty} | f(t)|^p  t ^{\kappa p} \Tilde{m}(t) \, dt \right)^{1/p}  
\end{align}
for the direct transform. If $({\sigma}, \kappa) \in \mathbf{D_{p, q}}(2, 2\alpha+1)$, then
\begin{align}\label{Pitt_pow_J-1_int}
\left( \int_0^{\infty} |\tilde{\mathcal{I}} F(t)|^q  t^{-\sigma q} \Tilde{m}(t)\, dt \right)^{1/q} \lesssim   \left( \int_0^{\infty} | F(\lambda)|^p  \lambda ^{\kappa p} {n}(\lambda) \, d\lambda \right)^{1/p}  
\end{align}
for the inverse one.
\item[(B)] Then, for the modified Jacobi transform $\tilde{\mathcal{J}}$, the following conditions
\begin{equation}
\begin{aligned}
2\left(\alpha+1\right)\left(\frac{1}{p}+\frac{1}{q}-1\right)\leq \sigma-\kappa  \leq 3\left(\frac{1}{p}+\frac{1}{q}-1\right),\\
\sigma \geq (2\alpha+1)\left(\frac{1}{q}-\frac{1}{2}\right) +\frac{1}{q}-\frac{1}{p^{\prime}}, \qquad \kappa \geq 2\left(\frac{1}{p^{\prime}}-\frac{1}{2}\right) +\frac{1}{p^{\prime}}-\frac{1}{q}
\end{aligned}
\end{equation}
are necessary for Pitt's inequality \eqref{Pitt_pow_J_int} to be valid. For the inverse modified Jacobi transform $\tilde{\mathcal{I}}$ the following conditions 
\begin{equation}
\begin{aligned}
3\left(\frac{1}{p}+\frac{1}{q}-1\right)\leq \sigma-\kappa  \leq 2\left(\alpha+1\right) \left(\frac{1}{p}+\frac{1}{q}-1\right), \\
\sigma  \geq 2 \left(\frac{1}{q}-\frac{1}{2}\right) +\frac{1}{q}-\frac{1}{p^{\prime}}, \qquad \kappa  \geq (2\alpha+1)\left(\frac{1}{p^{\prime}}-\frac{1}{2}\right) +\frac{1}{p^{\prime}}-\frac{1}{q},
\end{aligned}
\end{equation}
are necessary for Pitt's inequality \eqref{Pitt_pow_J-1_int}  to be valid.

\end{enumerate}
\end{theorem}
\begin{remark}
\begin{enumerate}
    \item We refer the reader to \cite[Def. 5.1]{GLT18} for the definition of the \textbf{dual}, and to \cite[p. 1974, Figure 5.2]{GLT18} for the explicit, but highly intricate, definition of the set $\mathbf{D_{p,q}}(v_1,v_2)$. Due to the numerous auxiliary conditions and technical subtleties involved, we do not reproduce the definition here. However, we emphasize that the sufficient condition derived from their approach, namely $(\sigma, \kappa) \in \mathbf{D_{p,q}}(2\alpha+1,2)$, does not coincide with the necessary condition; see \cite[p. 1981]{GLT18} for further discussion. One of the main objectives of this work is to refine both the sufficient and necessary conditions for Pitt-type inequalities so that they coincide.
    \item We also note that in \cite[Theorem 8.2]{GLT18}, the authors applied a general framework for spaces with polynomial growth to derive necessary conditions for modified Jacobi transforms. However, their analysis was limited to the unshifted Pitt’s inequality, involving Fourier weights of the form $\lambda^{-\sigma}$, and may not extend to the \textit{shifted} version with weights of the form $(\lambda^2 + \zeta^2)^{-\sigma/2}$ considered in our work. Furthermore, their necessary conditions for the modified Jacobi transform may not apply to the standard Jacobi transform. Motivated by these distinctions, we now proceed to establish sharper and more natural necessary conditions tailored to the setting of the standard Jacobi transform and the shifted Pitt’s inequality.


\end{enumerate}  
\end{remark}

\subsection{Necessary conditions for shifted Pitt's inequality for Jacobi transforms}
The exponential volume growth inherent in the Jacobi setting requires substantial modifications to the classical assumptions from the Euclidean case. This makes it crucial to carefully determine the precise limitations and range of validity for such inequalities. In Euclidean spaces, the existence of a dilation structure allows for simple scaling arguments to establish the necessity of the \textit{balance condition} \eqref{k-s=N_equiv}. However, no such dilation structure exists in the Jacobi setting. To address this, we will instead rely on a key property of the Jacobi functions. 
\begin{lemma}
 Suppose $0<\theta_0<\pi/2$ is a constant. Then, the following holds 
    \begin{align}\label{eqn_sph_low}
        \varphi_\lambda(t) \asymp_{\theta_0}  \varphi_0 (t) \quad \text{whenever } \lambda t \leq \theta_0.
    \end{align}
\end{lemma}
\begin{proof} By using Mehler's integral representation (see \cite[p. 47]{Koo84}, also \cite[(2.16)]{Koo75}), and using similar technique as in \cite[Prop. 4.2]{KPRS24}, the lemma follows.
\end{proof}
Let us consider the following class of operators for $\zeta \geq 0$ and $\kappa,\sigma \in \R$:
\begin{align*}
    \mathcal{J}^{\zeta}&= \left\{\mathcal{J}^{\zeta}_{\kappa,\sigma}f(\lambda) =(\lambda^2+\zeta^2)^{-\frac{\sigma}{2}}  \int_0^{\infty}t^{-\kappa}f(t) \varphi_{\lambda}^{(\alpha,\beta)}(t) m(t) \,dt, \quad f\in C_c^{\infty}(\R_+) \right\},\\
    \mathcal{I}^{\zeta}&= \left\{\mathcal{I}^{\zeta}_{\kappa,\sigma}F(t) =t^{-\sigma}  \int_0^{\infty}(\lambda^2+\zeta^2)^{-\frac{\kappa}{2}}F(\lambda) \varphi_{\lambda}^{(\alpha,\beta)}(t) n(\lambda) d\lambda, \quad F\in C_c^{\infty}(\R_+) \right\}.
\end{align*}
\begin{theorem}\label{thm_nec_pitt_n}
Let $1<p,q<\infty$ and $\kappa,\sigma \in \R$. Suppose the following Pitt-type inequality holds:
\begin{align}\label{eqn_pit_nec,n}
   \left( \int_0^{\infty} |\mathcal{J}^{\zeta}_{\kappa,\sigma}f(\lambda)|^q  n(\lambda) d\lambda\right)^{\frac{1}{q}}\leq C \left( \int_0^{\infty} |f(t)|^p m(t) dt \right)^{\frac{1}{p}}
\end{align}
for all $f \in C_c^{\infty}(\R^+)$. Then it is necessary that $p \leq 2$, and the following conditions hold
\begin{enumerate}
 \item \label{it_stanJ1} if $\zeta \neq 0$, then $\kappa p'<{2(\alpha+1)}$ and
     \begin{align}\label{nec_stan_s-k>}
            \sigma-\kappa \geq 2(\alpha+1)\left( \frac{1}{p}+\frac{1}{q}-1\right);
     \end{align}
     \item   if  $\zeta \neq 0$ and $p=2$, then $\kappa <{(\alpha+1)}$, \eqref{nec_stan_s-k>} and  $\kappa \geq 3(1/2-1/q)$. Additionally, if $p=q=2$, then $ 0\leq \kappa <{\alpha+1}$ and $\kappa \leq  \sigma$;
     \item if $\zeta=0$,   then $\kappa p'<{2(\alpha+1)}$,  $\sigma q<3$ and \eqref{nec_stan_s-k>};
     \item if  $\zeta=0$ and $p=2$, then $\kappa <{(\alpha+1)}$,   \eqref{nec_stan_s-k>}, $\sigma q<3$, and $\sigma-\kappa \leq 3(1/q-1/2) $. Additionally, if 
     $p=q=2$, then  $\kappa=\sigma<{\min\{2(\alpha+1),3\}}/{2}$.
\end{enumerate}
\end{theorem}
\begin{proof}
  First, we will show that the condition $\kappa<2(\alpha+1)/{p'} $ is necessary for all $\zeta\geq 0$. To that end, assume that the inequality \eqref{eqn_pit_nec,n} holds with $\kappa= 2(\alpha+1)/{p'}+\epsilon $ for some $\epsilon\geq 0$. By a standard density argument, it follows that the operator $\mathcal{J}^{\zeta}_{\kappa,\sigma}$ is bounded from $L^p(dm)$ to $L^q(dn)$. Now, consider the function 
\begin{align}
f_0(t) =  \Chi_{(0,1)}(t)  t^{-\frac{2(\alpha+1)}{p}} \quad t\in (0,\infty),
\end{align} 
where $\Chi_{(a,b)}$ is the characteristic function on the interval $(a,b)$. It is straightforward to verify that $f_0 \in L^p(dm)$. Then, for all $0 \leq \lambda \leq 1$, using \eqref{eqn_sph_low}, we can write: 
\begin{equation}\label{eqn_jf>c}
\begin{aligned}
(\lambda^2+\zeta^2)^{\frac{\sigma}{2}} \mathcal{J}^{\zeta}_{\kappa,\sigma} f_0(\lambda) &\geq \int_0^1 t^{-\kappa} f_0(t) \varphi_{\lambda}(t) m(t) \,dt \\ 
&\gtrsim \int_0^1 t^{-\frac{2(\alpha+1)}{p'}-\epsilon} t^{-\frac{2(\alpha+1)}{p}} \varphi_0(t)  t^{2\alpha+1} \,dt \\
& \gtrsim \int_0^1 t^{- 1-\epsilon} \,dt. 
\end{aligned}
\end{equation}
We observe that the integral in the last line above diverges for all $\epsilon\geq 0$, contradicting the boundedness of $\mathcal{J}_{\kappa,\sigma}$. Hence, we conclude that the condition $\kappa<2(\alpha+1)/{p'} $ is necessary. Assuming $\kappa<2(\alpha+1)/{p'} $, it follows from \eqref{eqn_jf>c} that for $\zeta=0$
\begin{align}\label{eqn_nec_sigm}
\int_0^{\infty} | \mathcal{J}^{0}_{\kappa,\sigma} f_0(\lambda) |^q n(\lambda) \, d\lambda \gtrsim  \int_0^1 \lambda^{-\sigma q} \lambda^2 \, d\lambda, 
\end{align} where, in the final line, we used the sharp estimate \eqref{est_sharp_n} of $n(\lambda)$ near $\lambda = 0$. We note that the integral on the right-hand side is finite only if $\sigma < 3/q$. It is worth mentioning that when $\zeta > 0$, the condition $\sigma q < 3$ may not be necessary.

Having established that $\kappa p' < 2(\alpha+1)$ is necessary for $\zeta \geq 0$, and that the additional condition $\sigma < 3/q$ is required when $\zeta = 0$, we now assume that inequality \eqref{eqn_pit_nec,n} holds for such values of $\kappa$ and $\sigma$. We define the following function, for $0 <s\leq  1$
\begin{align}
    f_1(t) =   t^{-\frac{\kappa}{p-1}} \varphi_{0}^{\frac{1}{p-1}}(t)\Chi_{(0,s)}(t).
\end{align}
 Since $\kappa p' < {2(\alpha+1)}$, the function $f_1$ is locally $L^p$-integrable, particularly near zero. We now bound the left-hand side of
\eqref{eqn_pit_nec,n} in the following way
 \begin{align*}
      \int_0^{\infty} | \mathcal{J}_{\kappa,\sigma} f_1(\lambda) |^q n(\lambda) \, d\lambda \geq   \int_1^{1/{s}}  \lambda^{-\sigma q}  \left| \int_0^{s}t^{-\kappa(1+\frac{1}{p-1})} \varphi_{0}^{\frac{1}{p-1}} \varphi_{\lambda}(t) m(t) \,dt \right|^q n(\lambda)d\lambda,
    \end{align*}
    where we used the fact $f_1$ is supported on the interval $(0,s)$. Using \eqref{eqn_sph_low}, the inequality above
    reduced to
 \begin{align}\label{eqn_jf1>}
      \int_0^{\infty} | \mathcal{J}_{\kappa,\sigma} f_1(\lambda) |^q n(\lambda) \, d\lambda \geq C  \left( \int_0^{s}t^{-\kappa p'} \varphi_{0}(t)^{p'} m(t) \,dt \right)^q  \left(\int_1^{{1}/{s}}  \lambda^{-\sigma q}  n(\lambda)d\lambda \right).
    \end{align}
By substituting $f = f_1$ into \eqref{eqn_pit_nec,n} and combining it with the inequality preceding \eqref{eqn_jf1>}, we derive
\begin{align*}
  \left( \int_0^{s}t^{-\kappa p'} \varphi_{0}(t)^{p'} m(t) \,dt \right)  \left( \int_1^{{1}/{s}}  \lambda^{-\sigma q}   n(\lambda)\,d\lambda\right)^{\frac{1}{q}}\leq C \left( \int_0^{s}t^{-\kappa p'} \varphi_{0}(t)^{p'} m(t) \,dt \right)^{\frac{1}{p}}.
\end{align*}
Since the constant $C$ is independent of $s$ and was chosen arbitrarily, we can conclude that
\begin{align}\label{eqn_pitt_nec1}
    \sup_{0<s\leq 1} \left( \int_0^{s}t^{-\kappa p'} \varphi_{0}(t)^{p'} m(t) \,dt \right)^{\frac{1}{p'}}  \left( \int_1^{{1}/{s}}  \lambda^{-\sigma q}   n(\lambda)\,d\lambda\right)^{\frac{1}{q}}<\infty.
\end{align}
Similarly for $s>1$, by considering 
\begin{align}\label{eqn_defn_f2}
     f_2(t) =   t^{-\frac{\kappa}{p-1}} \varphi_{0}^{\frac{1}{p-1}}(t)\Chi_{(1,s)}(t),
\end{align}
  we can prove that
  \begin{align}\label{eqn_pitt_nec>1}
    \sup_{s>1} \left( \int_1^{s}t^{-\kappa p'} \varphi_{0}(t)^{p'} m(t) \,dt \right)^{\frac{1}{p'}}  \left( \int_0^{{1}/{s}}  \lambda^{-\sigma q}   n(\lambda)\,d\lambda\right)^{\frac{1}{q}}<\infty.
\end{align}
We will now use \eqref{eqn_pitt_nec1} and \eqref{eqn_pitt_nec>1} to derive more necessary conditions. In fact, we have for $s>1$ from \eqref{est_sharp_n} that
\begin{align}\label{eqn_n(l)>0}
    \left( \int_0^{{1}/{s}}  \lambda^{-\sigma q}   n(\lambda)\,d\lambda\right)^{\frac{1}{q}} \geq C s^{\sigma -\frac{3}{q}},
\end{align}
On the other hand utilizing the estimate \eqref{eqn_est_phi_0} of  $\varphi_0(t)$  and $m(t)$ near infinity, we can write  for $s>1$ 
\begin{align}\label{eqn_tk>1}
   \left( \int_1^{s}t^{-\kappa p'} \varphi_{0}(t)^{p'} m(t) \,dt \right)^{\frac{1}{p'}}   \geq  C \left( \int_1^{s}t^{p'-\kappa p'}e^{\rho t(2-p')}  \,dt \right)^{\frac{1}{p'}} \geq C \min\{s^{1-\kappa},1\}   e^{{\rho s(\frac{2}{p'}-1)}}.
\end{align}
We claim that for Pitt-type inequality in this exponential volume growth setting, it is necessary that $p\leq 2$. More precisely, if $p>2$, then $p'<2$ and plugging the inequality above in \eqref{eqn_n(l)>0}, we get for all $\sigma>0$
\begin{align}\label{eqn_p<2_nec}
    \sup_{s>1} \left( \int_1^{s}t^{-\kappa p'} \varphi_{0}(t)^{p'} m(t) \,dt \right)^{\frac{1}{p'}}  \left( \int_0^{{1}/{s}}  \lambda^{-\sigma q}   n(\lambda)\,d\lambda\right)^{\frac{1}{q}} \geq C \sup_{s>1} e^{{\rho s(\frac{2}{p'}-1)}} s^{\sigma -\frac{3}{q}}=\infty.
\end{align}
This contradicts \eqref{eqn_pitt_nec>1}, therefore $p\leq 2$ is necessary.

We will now proceed to establish that the condition in \eqref{nec_stan_s-k>} is necessary for all $\zeta \geq 0$. However, before doing that, we note that if $\sigma q \geq 2(\alpha + 1)$, then together with the necessary condition $\kappa p' < 2(\alpha + 1)$, we already have \eqref{nec_stan_s-k>}. Thus, it is sufficient to consider the case where $\sigma q < 2(\alpha + 1)$. For $0 < s < 1$, using the estimates of $\varphi_0(t)$ and $m(t)$ near zero, as well as the estimates of $n(\lambda)$ near infinity, we can deduce that 
\begin{multline*}
    \sup_{0<s\leq 1} \left( \int_0^{s}t^{-\kappa p'} \varphi_{0}(t)^{p'} m(t) \,dt \right)^{\frac{1}{p'}}  \left( \int_1^{{1}/{s}}  \lambda^{-\sigma q}   n(\lambda)\,d\lambda\right)^{\frac{1}{q}}\\ 
        \gtrsim \sup_{0<s\leq 1} \left( \int_0^{s}t^{-\kappa p'} t^{2\alpha+1} \,dt \right)^{\frac{1}{p'}}  \left( \int_1^{{1}/{s}}  \lambda^{-\sigma q}   \lambda^{2\alpha+1}\,d\lambda\right)^{\frac{1}{q}}.
\end{multline*}
 Then we bound below the right-hand side of the inequality above  by
\begin{align}\label{eqn_nec_0}
\sup_{0<s\leq 1} s^{\sigma-\kappa+2(\alpha+1)\left(\frac{1}{p'}-\frac{1}{q}\right)},
\end{align}
which will be finite if and only if \eqref{nec_stan_s-k>} holds. Thus \eqref{nec_stan_s-k>} is necessary for all $\zeta \geq 0$.  Moreover,
when $p\leq 2$ and $q=2$, we derive from \eqref{nec_stan_s-k>}  that $\kappa\leq \sigma$ is also necessary for all $\zeta \geq 0$. 
Additionally for $\zeta=0$, utilizing \eqref{eqn_n(l)>0} we can write 
\begin{align}\label{eqn_nec>1_sJ}
 \sup_{s>1}\left( \int_1^{s}t^{- 2 \kappa } \varphi_{0}(t)^{2} m(t) \,dt \right)^{\frac{1}{2}}   \left( \int_0^{{1}/{s}}  \lambda^{-\sigma q }   n(\lambda)\,d\lambda\right)^{\frac{1}{q}}  \geq C \sup_{s>1} s^{\frac{3}{2}-\kappa} s^{\sigma-\frac{3}{q}},
\end{align}
which will be finite if and only if 
\begin{align*}
    \sigma- \kappa \leq 3 \left(\frac{1}{q}-\frac{1}{2}\right).
\end{align*}
Thus for $p=q=2$ and $\zeta =0$ case, it is necessary that $\kappa=\sigma<{\min\{2(\alpha+1),3\}}/{2}$.  
Similarly, when $\zeta \neq 0$ and $p = 2$, we can show that $\kappa \geq 3\left(\frac{1}{2} - \frac{1}{q}\right)$ is a necessary condition. In particular, for $p = q = 2$, we also find that $\kappa \geq 0$ is necessary.
\end{proof}

\begin{theorem}\label{thm_nec_inv_pitt_n}
   Let $1<p,q<\infty$. Suppose the following Pitt-type inequality holds:
\begin{align}\label{eqn_pit_nec,n_I}
   \left( \int_0^{\infty} |\mathcal{I}_{\kappa,\sigma}F(t)|^q  m(t) \,dt \right)^{\frac{1}{q}}\leq C \left( \int_0^{\infty} |F(\lambda)|^{p} n(\lambda) d\lambda \right)^{\frac{1}{p}}
\end{align}
for all $f \in C_c^{\infty}(\R_+)$.  Then it is necessary that $q\geq 2$, and the following conditions hold
\begin{enumerate}
\item if $\zeta \neq 0$, then $\sigma  q<{2(\alpha+1)}$ and
\begin{align}\label{eqn_nec_bal_I,ks}
    \sigma- \kappa\leq  2\left(\alpha+1 \right)\left(\frac{1}{p}+\frac{1}{q}-1\right).
\end{align}
\item if  $\zeta \neq 0$ and $q=2$, then $\sigma <{\alpha+1}$,   \eqref{eqn_nec_bal_I,ks}, and $\sigma \geq 3(1/p-1/2)$. Additionally, if $p=q=2$, then $ 0\leq \sigma <{\alpha+1}$ and $\sigma \leq  \kappa$;
\item if $\zeta=0$,   then $\sigma q<{2(\alpha+1)}$,  $\kappa p'<3$, and \eqref{eqn_nec_bal_I,ks};
\item\label{it_sJ4} if $\zeta=0$ and $q=2$,   then $\sigma q<{2(\alpha+1)}$,  $\kappa p'<3$,  \eqref{eqn_nec_bal_I,ks} and $\sigma -\kappa \geq 3(1/p-1/2) $. Additionally, if $p=q=2$, then  $\sigma=\kappa<{\min\{2(\alpha+1),3\}}/{2}$.
\end{enumerate}
\end{theorem}
\begin{proof}
   By considering the function
    \begin{align}
        F_0(\lambda)= \Chi_{(0,1)}(\lambda)  \lambda^{-\frac{3}{p}} ,\qquad \lambda\in (0,\infty),
    \end{align}
    and following similar calculations as outlined in equations $ \eqref{eqn_jf>c} $ and $ \eqref{eqn_nec_sigm} $, we can demonstrate that the condition $ \sigma q < 2(\alpha + 1) $ is necessary for all $ \zeta \geq 0 $. Additionally, when $ \zeta = 0 $, the condition $ \kappa p' < 3 $ is also  necessary.

Next, considering the function for $0<s<1$
\begin{align*}
    F_1(\lambda) = \Chi_{(0,s)}(\lambda)  \lambda^{\frac{\kappa}{1-p}} ,\qquad \lambda\in (0,\infty),
\end{align*}
we get 
    \begin{align*}
     \left( \int_0^{\infty} |\mathcal{I}_{\kappa,\sigma}F_1(t)|^q  m(t) \,dt \right)^{\frac{1}{q}} & \geq \left( \int_0^{\infty} t^{-\sigma q}  \left|\int_0^{\infty}\lambda^{-\kappa}F_1(\lambda) \varphi_{\lambda}(t) n(\lambda) \,d\lambda \right|^q m(t) \,dt\right)^{\frac{1}{q}}\\
     &\geq \left( \int_1^{1/s} t^{-\sigma q}  \left(\int_0^{s}\lambda^{-\kappa p'} \varphi_{0}(t) n(\lambda) \,d\lambda \right)^q m(t)\, dt\right)^{\frac{1}{q}}\\
     &\geq \left( \int_1^{1/s} t^{-\sigma q} \varphi_{0}(t)^{q}   m(t) \,dt\right)^{\frac{1}{q}} \left(\int_0^{s}\lambda^{-\kappa p'}  n(\lambda)\, d\lambda \right).
    \end{align*}
    Putting the estimate above in \eqref{eqn_pit_nec,n_I} implies the following
    \begin{align}\label{eqn_I<1_nec}
       \sup_{0<s\leq 1}  \left(\int_0^{s}\lambda^{-\kappa p'}  n(\lambda)\, d\lambda \right)^{\frac{1}{p'}} \left( \int_1^{1/s} t^{-\sigma q} \varphi_{0}(t)^{q}   m(t) \,dt\right)^{\frac{1}{q}} <\infty.
    \end{align}
    Similarly for $s>1$, by considering 
    \begin{align*}
    F_2(\lambda) = \Chi_{(1,s)}(\lambda)  \lambda^{\frac{\kappa}{1-p}} ,\qquad \lambda\in (0,\infty),
\end{align*}
we derive the following
\begin{align}\label{eqn_I>_nec}
       \sup_{s>1}  \left(\int_1^{s}\lambda^{-\kappa p'}  n(\lambda)\, d\lambda \right)^{\frac{1}{p'}} \left( \int_0^{1/s} t^{-\sigma q} \varphi_{0}(t)^{q}   m(t) \,dt\right)^{\frac{1}{q}} <\infty.
    \end{align}
    Following a similar calculation as in \eqref{eqn_p<2_nec}, and using \eqref{eqn_I<1_nec}, we can derive that in this case $q\geq 2$ is necessary. Moreover, using \eqref{eqn_I>_nec} and following the calculation as in \eqref{eqn_nec_0}, we can derive that \eqref{eqn_nec_bal_I,ks} is necessary, that is 
    \begin{align}\label{eqn_nec_InvJ}
        \sigma-\kappa \leq 2(\alpha+1)\left(\frac{1}{p}+\frac{1}{q}-1 \right).
    \end{align}
    Moreover, it follows from above that for $q\geq p'$, $\sigma\leq \kappa <{3}/{p'}$ is also necessary. Additionally, for the $q=2$ case, we can write for $\zeta =0$ case
    \begin{align} 
       \sup_{0<s\leq 1}  \left(\int_0^{s}\lambda^{-\kappa p' }  n(\lambda)\, d\lambda \right)^{\frac{1}{p'}} \left( \int_1^{1/s} t^{-2\sigma } \varphi_{0}(t)^{2}   m(t) \,dt\right)^{\frac{1}{2}} \geq C  \sup_{0<s\leq 1} s^{-\kappa+\frac{3}{p'}}s^{\sigma-\frac{3}{2}}.
    \end{align}
   The right hand side of the inequality above will be finite if and only if $$ \sigma - \kappa \geq 3\left( \frac{1}{2}-\frac{1}{p'}\right)= 3\left(\frac{1}{p}-\frac{1}{2} \right).$$ In particular, for the $p=q=2$ case, we can say that its necessary that $\sigma=\kappa<\min\{3, 2(\alpha+1)\}/2$. The calculation for $\zeta \neq 0$ is similar.
\end{proof}
\begin{remark}
When $p < 2$, the presence of the exponentially decaying term $e^{\rho(2-p')t}$ on the left-hand side of \eqref{eqn_pitt_nec>1} prevents us from directly applying the argument used in \eqref{eqn_nec>1_sJ} to formulate a necessary condition, since the supremum may remain finite irrespective of the polynomial weight. However, when $p = 2$ and $q > 1$, using \eqref{eqn_n(l)>0}, we  establish that the condition $\sigma - \kappa \leq 3\left( {1}/{q} - {1}/{2} \right)$ is necessary for the inequality \eqref{eqn_pit_nec,n} to hold. In the next section, we will see that the absence of the exponential factor in the modified Jacobi transform allows us to derive additional necessary conditions, which coincide with those of the standard Jacobi transform when $p = 2$ and $q > 1$. 
\end{remark}

 \subsection{Necessary conditions for shifted Pitt's inequality for modified Jacobi transforms}


Here we will consider the following class of operators
\begin{align*}
    \tilde{\mathcal{J}^{\zeta}}&= \left\{\tilde{\mathcal{J}}^{\zeta}_{\kappa,\sigma}f(\lambda) =(\lambda^2+\zeta^2)^{-\frac{\sigma}{2}}  \int_0^{\infty}t^{-\kappa}f(t) \tilde{\varphi}_{\lambda}^{(\alpha,\beta)}(t) m(t) \,dt, \quad f\in C_c^{\infty}(\R_+) \right\},\\
    \tilde{\mathcal{I}}^{\zeta}&= \left\{\tilde{\mathcal{I}}^{\zeta}_{\kappa,\sigma}F(t) =t^{-\sigma}  \int_0^{\infty}(\lambda^2+\zeta^2)^{-\frac{\kappa}{2}}F(\lambda) \tilde{\varphi}_{\lambda}^{(\alpha,\beta)}(t) n(\lambda) \,d\lambda, \quad F\in C_c^{\infty}(\R_+) \right\}.
\end{align*}
\begin{theorem}\label{thm_nec_modJ}
    Suppose that the following inequality holds for $1<p,q<\infty$
\begin{align}\label{eqn_nec_modJ}
   \left( \int_0^{\infty} |\tilde{\mathcal{J}}^{\zeta}_{\kappa,\sigma}f(\lambda)|^q  n(\lambda) d\lambda\right)^{\frac{1}{q}}\leq C \left( \int_0^{\infty} |f(t)|^p m(t) dt \right)^{\frac{1}{p}}
\end{align}
for all $f \in C_c^{\infty}(\R^+)$.
Then, the following conditions are necessary:
\begin{enumerate}
     \item\label{it_modJ2}  if  $\zeta \neq 0$, then $\kappa p' < 2(\alpha+1)$,  \eqref{nec_stan_s-k>}, and
     \begin{align}\label{eqn_nec_mJ,k>}
         \kappa \geq 3\left( 1-\frac{1}{p}-\frac{1}{q}\right);
     \end{align}

       \item\label{it_modJ4} if  $\zeta=0$, then $\kappa p' <  2(\alpha+1)$, $\sigma q<3$, \eqref{nec_stan_s-k>}, and 
       \begin{align}\label{eqn_nec_s-k<}
            \sigma-\kappa \leq 3\left( \frac{1}{p}+\frac{1}{q} -1\right).
       \end{align}
\end{enumerate}
\end{theorem}
\begin{proof}
We follow the approach outlined in Theorem \ref{thm_nec_pitt_n}. In fact, by repeating a similar argument, we find that the condition $\kappa p' < 2(\alpha + 1)$ and inequality \eqref{nec_stan_s-k>} are necessary for all $\zeta \geq 0$. Moreover, when $\zeta = 0$, the additional condition $\sigma q < 3$ is also required. To demonstrate that \eqref{eqn_nec_s-k<} is necessary in the case $\zeta = 0$, we consider the function $f_2$ defined in \eqref{eqn_defn_f2}. Using \eqref{eqn_nec_modJ}, we derive the following analogue of \eqref{eqn_pitt_nec>1} 
\begin{align}\label{eqn_pitt_nec-mj>1}
    \sup_{s>1} \left( \int_1^{s}t^{-\kappa p'} \tilde{m}(t) \,dt \right)^{\frac{1}{p'}}  \left( \int_0^{{1}/{s}}  \lambda^{-\sigma q}   n(\lambda)\,d\lambda\right)^{\frac{1}{q}}<\infty.
\end{align}
We observe that if $\kappa p'\geq 3$, then \eqref{eqn_nec_s-k<} automatically satisfied. So let us assume that $\kappa p' < \min\{3, 2(\alpha+1)\}$. Then, using the estimate \eqref{est_Delta} for $\tilde{m}(t)$, we obtain the lower bound 
\begin{align}\label{est_lower_vk} \int_1^s t^{-\kappa p'} \tilde{m}(t) \, dt \gtrsim s^{-\kappa p'+3}. 
\end{align} Combining the lower bound \eqref{est_lower_vk} with \eqref{eqn_n(l)>0}, we find that 
\begin{align*} \sup_{s>1} \left( \int_1^{s}t^{-\kappa p'} \tilde{m}(t) \,dt \right)^{\frac{1}{p'}} \left( \int_0^{{1}/{s}} \lambda^{-\sigma q} n(\lambda)\,d\lambda\right)^{\frac{1}{q}} \gtrsim \sup_{s>1} s^{\sigma -\frac{3}{q}+ \frac{3}{p'}-\kappa}. 
\end{align*} The right-hand side is finite if and only if condition \eqref{eqn_nec_s-k<} holds, thus establishing \eqref{it_modJ4}.

The case \eqref{it_modJ2} follows by noting that when $\zeta\neq  0$, the term $\lambda^2 + \zeta^2$ is bounded below by a positive constant for small $\lambda$, which ensures that the relevant integral remains finite.
\end{proof}


\begin{theorem}\label{thm_nec_modI}
    Suppose that the following inequality holds for $1<p,q<\infty$
\begin{align}\label{eqn_nec_modI}
   \left( \int_0^{\infty} |\tilde{\mathcal{I}}^{\zeta}_{\kappa,\sigma}F(t)|^q  \tilde{m}(t)\, dt \right)^{\frac{1}{q}}\leq C \left( \int_0^{\infty} |F(\lambda)|^p n(\lambda) \,  d\lambda \right)^{\frac{1}{p}}
\end{align}
for all $f \in C_c^{\infty}(\R^+)$.
Then, the following conditions are necessary:
\begin{enumerate}
     \item  if  $\zeta \neq 0$, then $\sigma q <  2(\alpha+1)$,  \eqref{eqn_nec_bal_I,ks}, and
     \begin{align}\label{eqn_nec_con_mI,s>}
         \sigma \geq 3\left( \frac{1}{p}+\frac{1}{q}-1\right);
     \end{align}
     %\item if $\zeta=0$ and $\sigma q \geq 3$, then \eqref{eqn_nec_bal_I,ks} and $\kappa p'<3$;
       \item if  $\zeta=0$, then $\sigma q < 2(\alpha+1)$,  $\kappa p'<3$, \eqref{eqn_nec_bal_I,ks}, and 
       \begin{align}\label{eqn_nec_s-k>_mI}
            \sigma-\kappa \geq 3\left( \frac{1}{p}+\frac{1}{q} -1\right).
       \end{align}
\end{enumerate}
\end{theorem}
\begin{proof}
    The proof follows by applying arguments similar to those used in Theorems \ref{thm_nec_inv_pitt_n} and \ref{thm_nec_modJ}.
\end{proof}


\subsection{Sufficient conditions for shifted Pitt's inequality for Jacobi transforms} In this section, we will establish the shifted Pitt's inequality for the Jacobi transforms. To that end, we first develop a general framework for weighted boundedness of sublinear operators.

Throughout this section, $u$ and $v$ will denote non-negative measurable functions defined on $\mathbb{R}_+$. Since we will be working with the non-increasing rearrangement of functions on $\mathbb{R}_+$ with respect to two different measures, namely $n(\lambda)\,d\lambda$ and $\tilde{m}(t)\,dt$, we adopt the following notation: the rearrangement of $u$ with respect to $n(\lambda)\,d\lambda$ is denoted by $u^{\star}$, while the rearrangement of $v$ with respect to $\tilde{m}(t)\,dt$ is written as $v^*$.
We also let $v_* = [(1/v)^*]^{-1}$. For $g\geq 0$, let us define for non-negative locally integrable functions 
\begin{align*}
    P_x g=\int_0^x g(y) dy, \quad Q_x g=\int_x^{\infty} g(y) dy,
\end{align*}
which are known as the Hardy and Bellman operators, respectively. Then, for non-negative locally integrable functions $u$ and $v$, one can consider the following Hardy inequalities for $1\leq p\leq q<\infty$,
\begin{align}\label{H_ineq_P}
    \|P_x g\|_{q,u}\lesssim \|g\|_{p,v}
\end{align}
and
\begin{align}\label{H_ineq_Q}
    \|Q_x g\|_{q,u}\lesssim \|g\|_{p,v}.
\end{align}
It is known that \cite{Bra78} inequality \eqref{H_ineq_P} holds if and only if, for each $r>0$,
\begin{align*}
    (Q_ru)^{1/q}(P_r v^{1-p'})^{1/p'} \lesssim 1.
\end{align*}
Similarly \eqref{H_ineq_Q} holds if and only if for each $r>0$,
\begin{align*}
    (P_r u)^{1/q} (Q_r v^{1-p'})^{1/p'} \lesssim 1.
\end{align*}
We consider the following measure spaces $X= (\R_+, d\tilde{m}(t))$ and $Y= (\R_+, dn(\lambda) )$.
\begin{theorem}\label{thm_pitt_subl}
Let $1 < p \leq q < \infty$, and let $T$ be a sublinear operator from $X$ to $Y$ that maps $C_c^{\infty}(\R_+)$ into measurable functions on $\R_+$. Suppose that $T$ is of type $(1,\infty)$ and type $(2,2)$, and let $u, v$ be weight functions satisfying the condition
 \begin{align}\label{hyp_on_gen_wts}
        \sup_{r>0} \left(P_{1/r}{u^{\star}}^q \right)^{1/q}\left(P_r v_{*}^{-p'} \right)^{1/{p'}}<\infty.
    \end{align}
    Then the following weighted inequality holds:
 \begin{align}\label{eqn_pitt_gent}
        \|Tf\cdot u\|_{L^q(Y)} \leq C \|f\cdot v\|_{L^p(X)}
    \end{align}
    for all $f \in C_c^{\infty}(\R_+)$.    
    Moreover, an analogous result holds if the roles of $X$ and $Y$ are interchanged, with the corresponding adjustments to the hypothesis \eqref{hyp_on_gen_wts} on the weights.
\end{theorem}
\begin{proof}
   The proof follows similar techniques to those employed in \cite[Theorem 2.4]{He84} and \cite[Proposition 2.6]{He84} for the case when both $p, q$ are not equal to 2, where we use \eqref{H_ineq_P} and \eqref{H_ineq_Q}. In fact, in \cite[Theorem 1.3]{KPRS24}, the first author established an analogue of \cite[Theorem 2.4]{He84} in a comparable setting, from which the proof of the theorem directly follows when both $p, q$ are not equal to  $2$.

For the case $p = q = 2$, a similar approach to that in \cite[Theorem (3.1) B]{GLT18} can be applied; (see also \cite[Theorem 1(i)]{BH03}). While the underlying methods can easily be extended to a broader context, we include a sketch of the proof for the case $p = q = 2$ for the sake of completeness. Suppose $T$ is a sublinear operator of   type $(1, \infty)$ and  type $(2, 2)$. Then, following the calculation as in \cite[Theorem 4.6, p. 260]{JT70}, we obtain 
\begin{align*}
\int_{0}^{x} (Tf)^{\star}(t)^2 \,dt \lesssim \int_0^{x} \left( \int_0^{1/t}f^*(s)\, ds \right)^2 dt.
\end{align*} Using this inequality and applying a similar argument as in \cite[Theorem B]{GLT18}, we can show that inequality \eqref{eqn_pitt_gent} holds.
\end{proof}
Next, we apply Theorem \ref{thm_pitt_subl} to the modified Jacobi transform. To do so, we first need to estimate the non-increasing rearrangement of the associated polynomial weights.
\subsubsection{Weights and their non-increasing rearrangement}
\begin{enumerate}
   \item\label{exm-triv} \textit{(Trivial weight)}  We denote by $w_0$ the weight that is identically $1$. It is easy to verify that the non-increasing rearrangement with respect to an infinite measure is the constant function $1$.
    \item\textit{(Rearrangement w.r.t. the measure $\tilde{m}(t) dt$)} For $\kappa\geq 0$, let us consider the weight $v_{\kappa}(s):= s^{\kappa}, s\geq 0$. We first find the non-increasing rearrangement of the function $1/v_{\kappa}$ for $ \kappa>0$ with respect to the measure $\tilde{m}(t)dt$. The $\kappa=0$ case follows from the previous case \eqref{exm-triv}. For $\kappa>0$, the distribution function of $1/v_\kappa$ is 
\begin{align*}
    d_{1/v_{\kappa}}(\gamma)&=\mu \left(\left\{s \geq 0: v_{\kappa}^{-1}(s) >\gamma \right\}\right)\\
    &=  \mu \left(\left\{s \geq 0: s^{-\kappa} >\gamma \right\}\right)\\&= \mu \left( \left\{s:s <(1/\gamma)^{\frac{1}{\kappa}} \right\}\right).
\end{align*}
For $1 < \gamma < \infty$, using 
\begin{align}\label{est_Delta}
 \tilde{m}(s) \asymp \begin{cases}
                s^{2\alpha+1}  \quad &\text{if } 0\leq s\leq 1,\\
                   s^2 \quad  & \text{if } 1< s <\infty,
                   \end{cases}
\end{align}
 we get
\begin{align*}
     d_{1/v_{\kappa}}(\gamma)\asymp \int_0^{(1/\gamma)^{\frac{1}{\kappa}}} s^{2\alpha+1}\, dt \asymp \gamma^{-\frac{2(\alpha+1)}{\kappa}}.
\end{align*}
When $0<\gamma\leq 1$, 
\begin{align*}
     d_{1/v_{\kappa}}(\gamma)\asymp \int_{0}^{1} s^{2\alpha+1}ds + \int_1^{\gamma^{-\frac{1}{\kappa}}}s^2\,ds
    \asymp \gamma^{-\frac{3}{\kappa}}.
\end{align*}
Thus the non-increasing rearrangement $(1/v_{\kappa})^{*}$ of $1/v_{\kappa}$ is given by
\begin{align*}
     {(1/v_{\kappa})}^{*}(t) & = \inf\{\gamma>0: d_{1/v_{\kappa}}(\gamma)\leq t\} \\
                   & =  \min\{ \inf\{0<\gamma\leq 1: d_{{1/v_{\kappa}}}(\gamma) \leq t\}, \, \inf\{1<\gamma < \infty: d_{{1/v_{\kappa}}}(\gamma) \leq t\}\}.
\end{align*}
Now we make use of the estimate of $d_{1/v_{\kappa}}(\gamma)$ for $\gamma$ near zero and away from zero to derive the following
\begin{align*}
    (1/v_{\kappa})^*(t) & \asymp \min\{ \inf\{0<\gamma\leq 1: \gamma^{-\frac{3}{\kappa}} \lesssim t\}, \, \inf\{1<\alpha < \infty: \gamma^{-\frac{2(\alpha+1)}{\kappa}} \lesssim t\}\}.
\end{align*}
This gives
\begin{align*}
     (1/v_{\kappa})^*(t) & \asymp  \min\left\{ \inf\left\{0<\gamma\leq 1:  \gamma \geq   t ^{-\frac{\kappa}{3}} \right\}, \, \inf\left\{1<\gamma < \infty: \gamma \geq  t^{-\frac{\kappa}{2(\alpha+1)}} \right\}\right\}.
\end{align*}
Hence, by considering $t$ is near and away from zero, we obtain from the above
\begin{align}\label{est_1/vk*}
     (1/v_{\kappa})^*(t) \asymp &\begin{cases}
         t^{-\frac{\kappa}{(2(\alpha+1)}} &\text{if  } 0\leq t\leq 1,\\
        t^{-\frac{\kappa}{3}} &\text{if }1 <t<\infty.
     \end{cases}
\end{align}

    \item  \textit{((Rearrangement w.r.t. the measure $n(\lambda)d\lambda$)}
 For $\sigma \geq 0$ and $\zeta\geq 0$, we consider the weight $u_{\zeta, \sigma}$ given by 
 \begin{equation*}
u_{\zeta,\sigma}(\lambda)=(\lambda^2+\zeta^2)^{-\frac{\sigma}{2}}, \qquad \text{for all $\lambda>0$.}
\end{equation*} 
Using a similar computation as in Lemma \ref{lem_plaey_inq}, together with the estimate for $n(\lambda)$ provided in \eqref{est_sharp_n}
 \begin{equation}\label{est_c-2_d}
 \begin{aligned}
        n(\lambda)\asymp \begin{cases}
            \lambda^2 \qquad &\text{if } 0\leq \lambda\leq 1,\\
            \lambda^{2\alpha+1} \qquad &\text{if } \lambda > 1,
        \end{cases}
    \end{aligned}
    \end{equation}
    we arrive at the following inequality for $\zeta=0$
  \begin{align}
      d_{u_{0,\sigma}}(\gamma)\leq C \begin{cases}
          \gamma^{-\frac{2(\alpha+1)}{\sigma}} \quad &\text{for } 0<\gamma\leq 1,\\
          \gamma^{-\frac{3}{\sigma}} \quad &\text{for } \gamma>1.
      \end{cases}
  \end{align}  
  When $\zeta \neq 0$,
   \begin{align}
      d_{u_{\zeta,\sigma}}(\gamma)\leq C \begin{cases}
          \gamma^{-\frac{2(\alpha+1)}{\sigma}}  \quad &\text{for } 0<\gamma<\left(\frac{1}{\zeta^2}\right)^{\frac{\sigma}{2}},\\
          0 \quad &\text{for } \gamma \geq \left(\frac{1}{\zeta^2}\right)^{\frac{\sigma}{2}}.
      \end{cases}
  \end{align} 
Thus, from the definition of $ u_{0,\sigma}^{\star}$, we have
\begin{align*}
    u_{0,\sigma}^{\star}(t) & = \inf\{\gamma>0: d_{u_{0,\sigma}}(\gamma)\leq t\} \\
                   &\lesssim \min\{ \inf\{0<\gamma\leq 1: {\gamma^{-\frac{2(\alpha+1)}{\sigma}}}\lesssim t\}, \, \inf\{1< \gamma< \infty: \gamma^{-\frac{3}{\sigma}} \lesssim t\}\}\\
    & \lesssim \min\{ \inf\{0<\gamma\leq 1: {\gamma \gtrsim  t^{-\frac{\sigma}{2(\alpha+1)}}}\}, \, \inf\{1< \gamma< \infty: \gamma \gtrsim t^{-\frac{\sigma}{3}}\}\}.
\end{align*}
Therefore,  we have obtained the following
\begin{align}\label{est_u_s^*}
     u_{0,\sigma}^{\star}(t)\lesssim
 \begin{cases}
        t^{-\frac{\sigma}{3}} \qquad &\text{if } 0 \leq t\leq 1,\\
        t^{-\frac{\sigma}{2(\alpha+1)}} \qquad & \text{if } 1<t< \infty.\\
        \end{cases}
\end{align}
Similarly, for $\zeta \neq 0$, we can show that
\begin{align}\label{est_u_s^*z>0}
     u_{\zeta,\sigma}^{\star}(t)\lesssim
 \begin{cases}
       1 \qquad &\text{if } 0 \leq t\leq 1,\\
        t^{-\frac{\sigma}{2(\alpha+1)}} \qquad & \text{if } 1<t< \infty.\\
        \end{cases}
\end{align}
\end{enumerate}
Now that we have obtained estimates for the non-increasing rearrangements of the weights, we apply Theorem \ref{thm_pitt_subl} to derive sufficient conditions on the weights $u_{\zeta, \sigma}$ and $v_{\kappa}$ for the  Pitt's inequality \eqref{eqn_pitts_modi} to hold for modified Jacobi transforms. Our first result in this direction is as follows.

\begin{theorem}\label{thm_pitt's_mod_J}
  Let $\zeta \geq 0$ and $1 < p \leq q < \infty$.   Assume that $\sigma, \kappa \geq 0$ such that $  \kappa p' < 2(\alpha + 1)$ and  \eqref{nec_stan_s-k>} is satisfied.    Then the following shifted Pitt's inequality holds   
    \begin{align}\label{eqn_pitts_modi}
         \left( \int_0^{\infty} |\tilde{\mathcal{J}} f(\lambda)|^q  (\lambda^2 +\zeta^2)^{-\frac{\sigma q}{2}} n(\lambda) \, d\lambda \right)^{1/q} \leq C   \left( \int_0^{\infty} | f(t)|^p  t^{\kappa p} \tilde{m}(t) \, dt \right)^{1/p},
    \end{align}
  provided one of the following additional conditions is satisfied
   \begin{enumerate}
       \item if $\zeta \neq 0$ and $\kappa p' \geq 3$;
       \item if  $\zeta \neq 0$ and $\kappa p' < \min\{3, 2(\alpha+1)\}$, then \eqref{eqn_nec_mJ,k>};
       \item if $\zeta=0$ and $\kappa p' \geq 3$, then $\sigma q<3$;
       \item if  $\zeta=0$ and $\kappa p' < \min\{3, 2(\alpha+1)\}$, then $\sigma q<3$ and  \eqref{eqn_nec_s-k<}; 
   \end{enumerate}
\end{theorem}
\begin{proof}
We recall from \eqref{eqn_plac_mJ,I} that the modified Jacobi transform $\tilde{\mathcal{J}}$ is a bounded operator from $L^2(d\tilde{m})$ to $L^2(dn)$. Moreover, its boundedness from $L^1(d\tilde{m})$ to $L^\infty(dn)$ follows directly from its definition. Therefore, we can apply Theorem \ref{thm_pitt_subl} with $T = \tilde{\mathcal{J}}$. It is thus sufficient to show that if the parameters $\sigma$ and $\kappa$ satisfy the conditions stated in the hypothesis of Theorem \ref{thm_pitt's_mod_J}, then the following inequality holds for all $1 < p \leq q < \infty$:
\begin{align*}
\sup_{r > 0} \left(P_{1/r} u_{\zeta, \sigma}^{\star q} \right)^{1/q} \left(P_r v_\kappa^{-p'} \right)^{1/p'} < \infty.
\end{align*}
Since the estimates of ${u_{\zeta, \sigma}^{\star}}(s) $ and $ {v_\kappa}_{*}(s)$ differ significantly when $s$ is near zero, and when it is away from zero, it is natural to consider these two cases separately. Let us first examine the case when $s$ is near zero.

\par\textbf{Case I: $0<r \leq 1 $.} We need to consider the cases $\alpha>1/2$ and $-1/2<\alpha\leq 1/2$ separately. First, let us consider $\alpha>1/2$ and $\zeta=0$.  For  $\sigma q<3$, we can write from  \eqref{est_u_s^*}
\begin{equation}\label{est_u,a>1/2}
\begin{aligned}
\left(\int_0^{1/r}{u_{0, \sigma}^{\star}}^qdt\right)^{\frac{1}{q}} & \asymp \left(\int_0^1t^{-\frac{\sigma q}{3}}dt+\int_1^{1/r}t^{-\frac{\sigma q}{2(\alpha+1)}}dt\right)^{\frac{1}{q}}\\
    & \lesssim (1+r^{\frac{\sigma}{2(\alpha+1)}-\frac{1}{q}}).
\end{aligned}
\end{equation}
 For the same range of $s$ as above  and $\kappa p'<2(\alpha+1)$, we get from  \eqref{est_1/vk*}
\begin{align*}
     \left(\int_0^r {v_{\kappa}}_{*}^{-p'}\,dt\right)^{\frac{1}{p'}} \leq C \left(\int_0^r t^{-\frac{\kappa p'}{2(\alpha+1)}}\,dt\right)^{\frac{1}{p'}} = C r^{-\frac{\kappa}{2(\alpha+1)}+\frac{1}{p'}}.
\end{align*}
Therefore, we have
\begin{align}\label{eqn_sufpitt<1}
   \sup_{0<r\leq 1}  \left(P_{1/r}{u_{0,\sigma}^{\star}}^q \right)^{1/q}\left(P_r {v_\kappa}_{*}^{-p'} \right)^{1/{p'}} \leq C \left(1+\sup_{0<r\leq 1} r^{-\frac{\kappa}{2(\alpha+1)}+\frac{1}{p'}+\frac{\sigma}{2(\alpha+1)}-\frac{1}{q}} \right).
\end{align}
The expression on the right-hand side of the inequality above is finite if and only if \begin{align}\label{cond_pitt<1}
\frac{\sigma}{2(\alpha+1)}  +\frac{1}{p'} \geq \frac{\kappa}{2(\alpha+1)}+ \frac{1}{q} \quad \Leftrightarrow \quad \sigma-\kappa \geq 2(\alpha+1)\left( \frac{1}{p}+\frac{1}{q}-1\right).
\end{align}
When $\alpha \leq 1/2$, that is, when $2(\alpha+1) \leq 3$, we observe that for $\sigma q < 2(\alpha+1)$, the computation remains same, and the left-hand side of \eqref{eqn_sufpitt<1} is finite whenever condition \eqref{cond_pitt<1} is satisfied.
In the case where $2(\alpha+1) \leq \sigma q < 3$, the assumption $\kappa p' < 2(\alpha+1)$ alone guarantees that the left-hand side of \eqref{eqn_sufpitt<1} remains finite.

Additionally, we note that for the case $\zeta > 0$, to derive the inequality \eqref{est_u,a>1/2},  we can use \eqref{est_u_s^*z>0} instead of  \eqref{est_u_s^*}. In this case, the condition $\sigma q < 3$ is not required, which ensures that the right-hand side of \eqref{est_u,a>1/2} is finite when $\zeta = 0$.



\par\textbf{Case II: $1<r<\infty$.}   We can write from \eqref{est_u_s^*} and  \eqref{est_u_s^*z>0} 
\begin{equation}\label{est_u*>1}
    \begin{aligned}
    \left(\int_0^{1/r}u_{\zeta, \sigma}(t)^qdt\right)^{\frac{1}{q}} & \lesssim \begin{cases}
        r^{\frac{\sigma}{3}-\frac{1}{q}}&\quad \text{if } \zeta=0, \text{ and } \sigma q<3,\\
        r^{-\frac{1}{q}} &\quad \text{if } \zeta \neq 0.
    \end{cases} 
\end{aligned}
\end{equation}
To estimate $P_r  {v_{\kappa}}_{*}^{-p'}$, we need to consider the ranges of $\kappa$ separately.  First, let us handle the case when $\kappa p'<3$, for which we can write from \eqref{est_1/vk*} 
\begin{equation}\label{est_v_*>1,<3}
\begin{aligned}
    \left(\int_0^r {v_{\kappa}}_{*}^{-p'}dt\right)^{\frac{1}{p'}} & \leq  C \left(\int_0^{1} t^{-\frac{ \kappa p'}{2(\alpha+1)}}\,dt+\int_{1}^s t^{-\frac{\kappa {p'}}{3}}\,dt\right)^{\frac{1}{p'}}\\
    %& \leq C  \left(1+\int_{1}^s  t^{-\frac{\kappa {p'}}{3}}dt\right)^{\frac{1}{p'}}\\
    & \leq C r^{\frac{1}{p'}-\frac{\kappa}{3}}.
\end{aligned}
\end{equation}
 Thus, for the above range of $\kappa$, we have obtained the following 
\begin{align}\label{eqn_est_suff_r>1}
      \sup_{r>1} \left(P_{1/r}{u_{\zeta, \sigma}^{\star}}^q \right)^{1/q}\left(P_r {v_\kappa}_{*}^{-p'} \right)^{1/{p'}} \leq C  \begin{cases}\sup_{r>1}
        r^{\frac{\sigma}{3}-\frac{\kappa}{3}+\frac{1}{p'}-\frac{1}{q}}&\quad \text{if } \zeta=0, \text{ and } \sigma q<3,\\
        \sup_{r>1} r^{\frac{1}{p'}-\frac{\kappa}{3}{-\frac{1}{q}} }&\quad \text{if } \zeta \neq 0.
    \end{cases}
\end{align}
Therefore, for the case $\kappa p'<3$, the left-hand side of the inequality above will be finite, provided the following conditions are met 
\begin{enumerate}
    \item if $\zeta=0$, then $\sigma q<3$, and $\sigma -\kappa \leq 3(1/q-1/p')$;
    \item if $\zeta \neq 0$, then $ \kappa \geq 3(1/p'-1/q)$.
\end{enumerate}


We now consider the case $\kappa p' \geq 3$. We first observe that if $\alpha \leq 1/2$, then the result follows exactly as in the case $\kappa p' < 3$, since in this situation, we have $\kappa p' < 2(\alpha+1) \leq  3$ by assumption. Therefore, it remains to address the case when $\alpha > 1/2$ to complete the proof.
Suppose $\alpha>1/2$ and   $3< \kappa p' < 2(\alpha+1)$, then from \eqref{est_1/vk*} we obtain
\begin{equation}\label{est_v_*>1,1}
\begin{aligned}
    \left(\int_0^r {v_{\kappa}}_{*}^{-p'}dt\right)^{\frac{1}{p'}} & \leq  C \left(\int_0^{1} t^{-\frac{ \kappa p'}{2(\alpha+1)}}\,dt+\int_{1}^s t^{-\frac{\kappa {p'}}{3}}\,dt\right)^{\frac{1}{p'}}\\
    %& \leq C  \left(1+\int_{1}^s  t^{-\frac{\kappa {p'}}{3}}dt\right)^{\frac{1}{p'}}\\
    & \leq C \left(1+ \frac{1}{\frac{\kappa p'}{3}-1}(1-s^{1-\frac{\kappa p'}{3}}) \right)^{\frac{1}{p'}}<C,
\end{aligned}
\end{equation}
where the constant $C$ is independent of $r$. Similarly, when $\kappa p'=3 $, we can show that 
\begin{align}\label{est_v_*>1,2}
     \left(\int_0^r {v_{\kappa}}_{*}^{-p'}dt\right)^{\frac{1}{p'}} & \leq  C (1+\log r).
\end{align}
Thus combining the inequalities \eqref{est_u*>1}, \eqref{est_v_*>1,1}, \eqref{est_v_*>1,2},  it follows that
\begin{align}\label{eqn_pr_p1/r>1}
 \sup_{r>1} \left(P_{1/r}{u_{\zeta, \sigma}^{\star}}^q \right)^{1/q}\left(P_r {v_\kappa}_{*}^{-p'} \right)^{1/{p'}} \leq C  \begin{cases}\sup_{r>1}
        r^{\frac{\sigma}{3}-\frac{1}{q}}&\quad \text{if } \zeta=0, \text{ and } \sigma q<3,\\
        \sup_{r>1} r^{-\frac{1}{q}} (1+\log r) &\quad \text{if } \zeta \neq 0.
        \end{cases}
\end{align}
We conclude the proof of the theorem by noting that the right-hand side of \eqref{eqn_pr_p1/r>1} is always finite when $\zeta \neq 0$, and also when $\zeta = 0$, provided that $\sigma q < 3$.
\end{proof}

\begin{theorem}\label{thm_pitt's_mod_J-1}
  Let $\zeta \geq 0$ and $1 < p \leq q < \infty$.   Assume that $\sigma, \kappa \geq 0$ such that $\sigma q<2(\alpha+1)$ and  \eqref{eqn_nec_bal_I,ks} is satisfied.
    Then the following shifted Pitt's inequality  holds
    \begin{align}\label{eqn_pitts_modi-1}
         \left( \int_0^{\infty} |\tilde{\mathcal{I}} F(t)|^q t^{-{\sigma q}} \tilde{m}(t) \, dt \right)^{1/q} \leq C   \left( \int_0^{\infty} |F(\lambda)|^p  (\lambda^2+\zeta^2)^{\frac{\kappa p}{2}} n(\lambda)\, d\lambda \right)^{1/p},
    \end{align}
 provided one of the following additional conditions is satisfied
   \begin{enumerate}
       \item if $\zeta\neq 0$ and $\sigma q \geq 3$;
       \item if  $\zeta \neq 0$ and $\sigma q <\min\{3, 2(\alpha+1)\}$,  then \eqref{eqn_nec_con_mI,s>};
       % \begin{align}\label{cond_pit_z0_mI}
       %     \sigma \geq 3\left(\frac{1}{p}+\frac{1}{q}-1 \right);
       % \end{align} 
       \item if $\zeta=0$ and $\sigma q \geq 3$, then $\kappa p'<3$;
       \item if  $\zeta=0$ and $\sigma q < \min\{3, 2(\alpha+1)\}$, then $\kappa p'<3$ and \eqref{eqn_nec_s-k>_mI}.
   \end{enumerate}
\end{theorem}
\begin{proof}We begin by recalling that the operator $\tilde{\mathcal{I}}$ is bounded from $L^1(dn)$ to $L^{\infty}(dm)$, as well as from $L^2(dn)$ to $L^2(dm)$. Therefore, to apply Theorem \ref{thm_pitt_subl}, it is enough to show that if the parameters $\sigma$ and $\kappa$ satisfy the hypothesis,, then the following inequality holds:
\begin{align*}
\sup_{r>0} \left(P_{1/r}(u_{\sigma}^{* q}) \right)^{1/q}\left(P_r \left({v_{\zeta,\kappa}}_{{\star}}^{-p'}\right) \right)^{1/{p'}}<\infty,
\end{align*}
where $u_{\sigma}(t) = t^{-\sigma}$ and $v_{\zeta, \kappa}(\lambda) = (\lambda^2 + \zeta^2)^{\kappa}$.

\par\textbf{Case I: $0<r \leq 1 $.} Using the hypothesis $\sigma q < 2(\alpha+1)$ and the estimate \eqref{est_1/vk*}, and by considering different cases, we obtain
\begin{equation}\label{est_u,a<1_mI_b}
\begin{aligned}
\left(\int_0^{1/r}{u_{ \sigma}^{*}}^qdt\right)^{\frac{1}{q}} & \lesssim 
\begin{cases}
  1+  r^{\frac{\sigma}{3}-\frac{1}{q}} \quad & \text{if } \sigma q <\min\{3, 2(\alpha+1)\},\\
    1+\log({\frac{1}{r}}) \quad & \text{if } \sigma q =3,\\
   1 \quad & \text{if } \sigma q >3.
\end{cases}
\end{aligned}
\end{equation}
Similarly, for $\kappa p'<3$ (when $\zeta=0$), we can derive the following from \eqref{est_u_s^*} and \eqref{est_u_s^*z>0}
\begin{equation}\label{est_v_z,k*<1_mI}
\begin{aligned}
     \left(\int_0^r {v_{\zeta,\kappa}}_{\star}^{-p'}\,dt\right)^{\frac{1}{p'}} \lesssim \begin{cases}
         r^{\frac{1}{p'}-\frac{\kappa}{3}} \quad & \text{if } \zeta=0,\\
         r^{\frac{1}{p'}} \quad & \text{if } \zeta\not=0.\\
     \end{cases}
\end{aligned}
\end{equation}
We observe the right-hand side of \eqref{est_v_z,k*<1_mI} is bounded for $0<r\leq 1$. Now let us first consider the case $\alpha\leq 1/2$ and $\zeta=0$. In this case, we obtain the following estimate
\begin{align}\label{eqn_sufpitt<1_mI}
   \sup_{0<r\leq 1}  \left(P_{1/r}{u_{\sigma}^{*}}^q \right)^{1/q}\left(P_r {v_{\zeta,\kappa}}_{\star}^{-p'} \right)^{1/{p'}} \lesssim \begin{cases}
       \left(1+\sup_{0<r\leq 1} r^{\frac{\sigma}{3}-\frac{1}{q}-\frac{\kappa}{3}+\frac{1}{p'}} \right) \quad & \text{if } \zeta=0,\\
        \left(1+\sup_{0<r\leq 1} r^{\frac{\sigma}{3}-\frac{1}{q}+\frac{1}{p'}} \right) \quad &\text{if } \zeta\not=0.\\
   \end{cases} 
\end{align} 
For $\zeta = 0$, the expression on the right-hand side of the inequality above is finite if condition \eqref{eqn_nec_s-k>_mI} holds. For $\zeta \neq 0$, it is finite if condition \eqref{eqn_nec_con_mI,s>} is satisfied.

Next, we consider the case $\alpha>1/2 $. If $\sigma q <\min\{3, 2(\alpha+1)\}$, then the calculation is same as in \eqref{eqn_sufpitt<1_mI}. However, if $\sigma q\geq 3$, then the condition $\kappa p'<3$ alone guarantees that the expression in \eqref{eqn_sufpitt<1_mI} is finite.


\par\textbf{Case II: $1<r<\infty$.}   We obtain the following estimate from \eqref{est_1/vk*} for $\sigma q<2(\alpha+1)$
\begin{equation}\label{est_u*>1_mI}
    \begin{aligned}
    \left(\int_0^{1/r}u_{ \sigma}^{*}(t)^qdt\right)^{\frac{1}{q}} & \lesssim  r^{\frac{\sigma}{2(\alpha+1)}-\frac{1}{q}}.
\end{aligned}
\end{equation}
For $\zeta > 0$, using the estimate \eqref{est_u_s^*z>0}, and for $\zeta = 0$, using \eqref{est_u_s^*} along with the assumption $\kappa p' < 3$, we obtain
\begin{equation}\label{est_u,a<1_mI}
\begin{aligned}
\left(\int_0^{r}{{v_{\zeta, \kappa}}_{\star}}^{-p'}dt\right)^{\frac{1}{q}} & \lesssim 
\begin{cases}
  1+  r^{-\frac{\kappa}{2(\alpha+1)}+\frac{1}{p'}} \quad & \text{if } \kappa p' <2(\alpha+1),\\
    1+\log({{r}}) \quad & \text{if } \kappa p' =2(\alpha+1),\\
   1 \quad & \text{if } \kappa p' \geq 2(\alpha+1).
\end{cases}
\end{aligned}
\end{equation}
Under the conditions $\sigma q < 2(\alpha + 1)$ and $\kappa p' < 2(\alpha + 1)$ when $\zeta \neq 0$ (with the additional assumption $\kappa p' < 3$ required when $\zeta = 0$), it follows from \eqref{est_u*>1_mI} and \eqref{est_u,a<1_mI} that
\begin{align}\label{eqn_P1/r,Pr>1_mJ}
      \sup_{r>1}  \left(P_{1/r}{u_{\sigma}^{*}}^q \right)^{1/q}\left(P_r {v_{\zeta,\kappa}}_{\star}^{-p'} \right)^{1/{p'}}  \lesssim \left(1+\sup_{r>1}
        r^{\frac{\sigma}{2(\alpha+1)}-\frac{\kappa}{2(\alpha+1)}+\frac{1}{p'}-\frac{1}{q}} \right).
\end{align}
The right-hand side of the inequality above is finite if \eqref{eqn_nec_bal_I,ks} holds. When $\kappa \geq 2(\alpha+1)$, we observe that the condition $\sigma q <2(\alpha+1)$ alone guarantees that  right hand of \eqref{eqn_P1/r,Pr>1_mJ} is finite.
\end{proof}
\begin{remark}\label{rem_nec_suff_mJ}
     If we assume that $\sigma, \kappa \geq 0$, a condition required for obtaining the non-increasing rearrangements of the weights, then the necessary conditions for the shifted Pitt's inequality for the modified Jacobi transforms (for $\tilde{\mathcal{J}}$ in Theorem~\ref{thm_nec_modJ} and $\tilde{\mathcal{I}}$ in Theorem~\ref{thm_nec_modI}) coincide with the sufficient conditions in Theorem~\ref{thm_pitt's_mod_J} and Theorem~\ref{thm_pitt's_mod_J-1}, respectively. This provides a complete characterization of the class of polynomial weights with non-negative exponents for which shifted Pitt's inequality holds in the setting of modified Jacobi transforms, thereby complementing the result of \cite[Theorem 8.2]{GLT18}. More precisely, we have the following corollary for the transform $\tilde{\mathcal{J}}$ (see also Figure~\ref{pitt_mJ_Fig}). A similar result also holds for $\tilde{\mathcal{I}}$.
\end{remark}
\begin{corollary}\label{cor_char_pitt_mJ}
      Let $\zeta \geq 0$ and $1 < p \leq q < \infty$.   Assume that $\sigma, \kappa \geq 0$.  Then the shifted Pitt's inequality  \eqref{eqn_pitts_modi} holds  if and only if 
      \begin{align*}
            \sigma-\kappa \geq 2(\alpha+1)\left( \frac{1}{p}+\frac{1}{q}-1\right),
      \end{align*}
 and one of the following conditions is met
 \begin{enumerate}
          \item  if  $\zeta \neq 0$, then $\kappa p' < 2(\alpha+1)$, and
     \begin{align*}
         \kappa \geq 3\left( 1-\frac{1}{p}-\frac{1}{q}\right);
     \end{align*}
       \item if  $\zeta=0$, then $\kappa p' <  2(\alpha+1)$, $\sigma q<3$, and 
       \begin{align*} 
            \sigma-\kappa \leq 3\left( \frac{1}{p}+\frac{1}{q} -1\right).
       \end{align*}
 \end{enumerate}
\end{corollary}

