We now use this result of shifted Pitt's inequality for the modified Jacobi transforms, along with sharp estimates of the Jacobi function $\varphi_0$, to establish shifted Pitt's inequality for the standard Jacobi transform.

\begin{theorem}\label{thm_pitt's_stand_J}
       Let $\zeta \geq 0$ and $1 < p \leq 2$ and $p\leq q < \infty$.   Assume that $\sigma, \kappa \geq 0$ are such that they satisfy the hypothesis of Theorem \ref{thm_pitt's_mod_J}. Then the following shifted Pitt's inequality holds 
    \begin{align}\label{eqn_pitts_stanJ}
         \left( \int_0^{\infty} |{\mathcal{J}} f(\lambda)|^q  (\lambda^2 +\zeta^2)^{-\frac{\sigma q}{2}} n(\lambda) \, d\lambda \right)^{1/q} \leq C   \left( \int_0^{\infty} | f(t)|^p  t^{\kappa p} {m}(t) \, dt \right)^{1/p}
    \end{align}
    for all $f \in C_c^{\infty}(\R_+)$.
    Moreover, in the special case when $p = q = 2$, we have the following result
    \begin{enumerate} 
    \item\label{en_pitt_J_2,2} Suppose $\zeta \neq 0$, then \eqref{eqn_pitts_stanJ} holds if and only if $0 \leq \kappa < \alpha + 1$ and $\sigma \geq \kappa$. 
    \item\label{en_pitt_J_2,2,0} Suppose $\zeta = 0$ and $\kappa \geq 0$, then \eqref{eqn_pitts_stanJ} holds if and only if $\kappa = \sigma < \min\{2(\alpha + 1), 3\}/2$. 
    \end{enumerate}
\end{theorem}
\begin{proof} We will show that for $1 < p \leq 2$, the inequality \eqref{eqn_pitts_modi} implies \eqref{eqn_pitts_stanJ}. As an application of Theorem \ref{thm_pitt's_mod_J}, the theorem will then follow. So, let us suppose that \eqref{eqn_pitts_modi} holds for all $f \in C_c^{\infty}(\mathbb{R}_+)$, that is,
\begin{align*}
   \left( \int_0^{\infty} |\tilde{\mathcal{J}} f(\lambda)|^q  (\lambda^2+\zeta^2)^{-\frac{\sigma q}{2}} n(\lambda) \, d\lambda \right)^{1/q} \lesssim   \left( \int_0^{\infty} | f(t)|^p  t ^{-\kappa p} \tilde{m}(t) \, dt \right)^{1/p} .  
\end{align*}
Now plugging relation $  \tilde{\mathcal{J}} f(\lambda) = \mathcal{J}\left(f\cdot \varphi_0\right)(\lambda)$  from \eqref{eqn_rel_J_mJ} in the equation above, it follows that
\begin{align*}
   \left( \int_0^{\infty} \left|\mathcal{J}\left(f\cdot \varphi_0 \right)(\lambda) \right|^q  (\lambda^2+\zeta^2)^{-\frac{\sigma q}{2}}  n(\lambda) \, d\lambda \right)^{1/q} \lesssim   \left( \int_0^{\infty} | f(t)|^p  t ^{-\kappa p} \tilde{m}(t) \, dt \right)^{1/p} , 
\end{align*}
which implies
\begin{align}\label{eqn_pit_mJ->J}
   \left( \int_0^{\infty} |\mathcal{J}f(\lambda) |^q  (\lambda^2+\zeta^2)^{-\frac{\sigma q}{2}}  n(\lambda) \, d\lambda  \right)^{1/q} \lesssim    \left( \int_0^{\infty} | f(t) |^p  t ^{-\kappa p} \varphi_0(t)^{-p} \tilde{m}(t) \, dt \right)^{1/p} . 
\end{align}
The asymptotic estimate of $\varphi_0 \asymp (1+t)e^{-\rho t}$, gives us the following for $1\leq p\leq 2$
\begin{align}\label{eqn_phi-p}
    \varphi_0(t)^{-p} \tilde{m}(t) \asymp \begin{cases}
        1\cdot t^{2\alpha+1} \asymp m(t), \quad &\text{if } t\leq 1,\\
         t^{2-p} e^{\rho p t} \lesssim e^{2\rho t }\asymp m(t), \quad &\text{if } t\geq 1.
    \end{cases} 
\end{align}
Plugging the estimate \eqref{eqn_phi-p} in \eqref{eqn_pit_mJ->J}, we obtain \eqref{eqn_pitts_stanJ}.

The sufficiency for the case $p = q = 2$ follows from Theorem \ref{thm_pitt's_mod_J} and the preceding calculations. Conversely, the necessity follows from Theorem \ref{thm_nec_pitt_n}.
\end{proof}
By following a similar line of calculation as in the previous theorem and using   $q \geq 2$, we can establish the following version of Pitt's inequality for the inverse Jacobi transform. 
\begin{theorem}\label{thm_pitt_inq_inv_J}
     Let $\zeta \geq 0$ and $1 < p\leq q<\infty$ and $ q \geq 2$.   Assume that $\sigma, \kappa \geq 0$ are such that they satisfy the hypothesis of Theorem \ref{thm_pitt's_mod_J-1}. Then the following shifted Pitt's inequality  
    \begin{align}\label{eqn_pitts_stanI}
         \left( \int_0^{\infty} |{\mathcal{I}} F(t)|^q   t^{-\kappa q} {m}(t) \, dt  \right)^{1/q} \leq C   \left( \int_0^{\infty} | F(\lambda)|^p (\lambda^2 +\zeta^2)^{-\frac{\sigma p}{2}} n(\lambda) \, d\lambda \right)^{1/p}
    \end{align}
   holds for all $F\in C_c^{\infty}(\R_+)$.
    Moreover, in the special case when $p = q = 2$, we have the following result
    \begin{enumerate} 
    \item\label{en_pitt_I_2,2} Suppose $\zeta \neq 0$, then \eqref{eqn_pitts_stanI} holds if and only if $0 \leq \sigma < \alpha + 1$ and $\sigma \leq \kappa$. 
    \item\label{en_pitt_I_2,2,0} Suppose $\zeta = 0$ and $\sigma \geq 0$, then \eqref{eqn_pitts_stanI} holds if and only if $\sigma = \kappa < \min\{2(\alpha + 1), 3\}/2$. 
    \end{enumerate}   
\end{theorem}


\begin{remark}\label{rem_after_J_pit}
\begin{enumerate}
\item We would like to mention that the shifted Pitt's inequality result for the case $p = q = 2$ in Theorem \ref{thm_pitt's_stand_J} can be extended to the range $1 < p \leq q \leq p'$  ($1 < p \leq 2$) using interpolation techniques similar to those employed in Theorem \ref{thm_pitt_X_n}. Specifically, by following the approach in Lemma \ref{lem_plaey_inq}, we can obtain a Hardy–Littlewood–Paley type inequality in the context of  the Jacobi transform for $1 < p \leq 2$: 
\begin{align}\label{eqn_paley_ineq_J}
\left( \int_0^{\infty} |\mathcal{J} f(\lambda)|^p (\lambda^2 + \zeta^2)^{-\frac{\sigma p}{2}} n(\lambda) \, d\lambda \right)^{1/p} \leq C \left( \int_0^{\infty} |f(t)|^p   m(t) \, dt \right)^{1/p}. \end{align} This inequality holds when $\zeta > 0$ provided that $\sigma \geq 2(\alpha + 1)(2/p - 1)$, and for $\zeta = 0$ if $2(\alpha + 1)(2/p - 1) \leq \sigma \leq 3(2/p - 1)$. 

By applying the interpolation method as in Theorem \ref{thm_pitt_X_n}, and interpolating the inequality above with the $p = q = 2$ case in Theorem \ref{thm_pitt's_stand_J} (\eqref{en_pitt_J_2,2} and \eqref{en_pitt_J_2,2,0}), one can derive the   Pitt-type inequalities for the range $1<p\leq q\leq p'$. However, this method does not extend to the case $q > p'$, as the analogue of the Hardy–Littlewood–Paley inequality cannot hold for $p > 2$.

\item From Theorem \ref{thm_nec_pitt_n}, we observe that for inequality \eqref{eqn_paley_ineq_J} to hold with $\zeta = 0$, it is necessary that $2(\alpha + 1)\left({2}/{p} - 1\right)\leq \sigma-\kappa < {3}/{p}$. This condition indicates that \eqref{eqn_paley_ineq_J} does not hold for all $1 < p \leq 2$ when $\zeta = 0$, unless $2(\alpha + 1) \leq 3$. In particular, for a rank one symmetric space of noncompact type with dimension $n$, this result implies that \eqref{eqn_inq_paley_lem} may fail to hold for all $1 < p \leq 2$ when $\zeta = 0$, unless $n \leq 3$.
\item\label{rem_problem_exp_space} 
We also point out that if the non-increasing rearrangement method were applied directly to the Jacobi transform without first modifying it to account for exponential volume growth,  we would be forced to impose an additional condition:
$ {\sigma} \leq 3( {1}/{p}  + {1}/{q}-1)$.
This arises because, in such a setting, for the weight function $v_\kappa(s) = s^{\kappa}$ $\kappa \geq 0$, the non-increasing rearrangement of $1/v_\kappa$ with respect to the measure $m(t)dt$ behaves like $(\log t)^{-\kappa}$ (instead of $t^{-\kappa/3}$ in the modified case). As a consequence, when attempting an analogous estimate to that in \eqref{eqn_est_suff_r>1}, the lack of polynomial decay in the rearrangement forces us to assume the additional hypothesis $ {\sigma} \leq 3( {1}/{p}  + {1}/{q}-1)$ in order to prove an analogue of Theorem \ref{thm_pitt's_stand_J}.
\item We conclude this section with a characterization of the weights for which the shifted Pitt's inequality holds for the standard Jacobi transform. This result follows as a corollary of Theorem~\ref{thm_nec_pitt_n} and Theorem~\ref{thm_pitt's_stand_J}. While a similar characterization also holds for the special case $p = 2 < q$, we state the result only for the range $1 < p \leq q \leq p'$ for simplicity and leave the remaining case to the interested reader. This corollary also recovers the result for rank one symmetric spaces in the $K$-biinvariant case, as presented in Corollary~\ref{cor_char_pitt_X<p'}.
\end{enumerate} 
\end{remark}
\begin{corollary}
     Let $\zeta >0$ and $1 < p \leq q\leq p'$.   Suppose that $\sigma \in \R, \kappa \geq 0$. Then the shifted   Pitt's inequality \eqref{eqn_pitts_stanJ} holds if and only  if $ p\leq 2$,
     \begin{align*}
            \sigma-\kappa \geq 2(\alpha+1)\left( \frac{1}{p}+\frac{1}{q}-1\right),
      \end{align*}
 and $\kappa p' < 2(\alpha+1)$.
\end{corollary}


\section{Heisenberg-Pauli-Weyl type uncertainty inequalities}\label{sec_uncn_principle} 
In this section, we develop a family of uncertainty principles on symmetric spaces of noncompact type, with particular emphasis on $L^p$ HPW-type inequalities. Motivated by earlier work on stratified Lie groups \cite{CRS07, CCR15}, we adapt and extend these ideas to the setting of symmetric spaces, where new phenomena arise due to the spectral gap of the Laplacian and the distinctive geometry at infinity. Our approach to $L^2$ HPW-type inequalities builds on shifted Pitt's inequality from  Section~\ref{sec_pitt_X} and Section \ref{sec_jac_transform}, while the $L^p$ analogues are derived using Hardy-type estimates involving the modified Laplacians $\mathcal{L}_{p_0}= \mathcal{L}+(|\rho|^2-|\rho_{p_0}|^2) I$, where we recall that $|\rho_{p_0}|=|2/{p_0}-1||\rho|$. Furthermore, we establish Landau–Kolmogorov-type inequalities for these operators, which allow us to formulate generalized HPW inequalities. We begin by proving the $L^2$ HPW inequality stated in Corollary~\ref{cor_unc_2,2_F} from the introduction.

\begin{proof}[\textbf{Proof of Corollary \ref{cor_unc_2,2_F}}] 
Suppose $p_0 \in [1,\infty)$ and $\gamma, \delta \in (0,\infty)$. Recalling from \eqref{inq_pit_p,2_n} and \eqref{inq_pit_p,2}, we note that the following inequality holds for all $f \in C_c^{\infty}(\X)$
\begin{align}\label{eqn_pitt's_p=q=2_n}
      \int_{\fa} \int_{B}|\widetilde{f}(\lambda,b)|^2  (|\lambda|^2+|\rho_{p_0}|^2)^{-{\sigma} } |\bfc(\lambda)|^{-2}\,db\, d\lambda \leq  \int_{\X} |x|^{2 \kappa} |f(x)|^2 dx
    \end{align}
   provided $\sigma \geq \kappa \geq 0$ and $\kappa < n/2$ when $p_0 \neq 2$, and $\sigma = \kappa < \min\{n/2,\nu/2\}$ when $p_0 = 2$. By applying Plancherel’s formula, we can write
     \begin{align*}
        \|f\|_{L^2(\X)}^2&=\frac{1}{|W|} \int_{\fa}   \int_{B} |\widetilde{f}(\lambda, b)|^2  |\bfc(\lambda)|^{-2}\, db \,d\lambda\\
        &= \frac{1}{|W|} \int_{\fa} \|\widetilde{f}(\lambda,\cdot)\|_{L^2(B)}^{\frac{2\gamma}{\gamma+\delta}} (|\lambda|^2+|\rho_{p_0}|^2)^{\frac{\gamma \delta}{(\gamma+\delta)}} \|\widetilde{f}(\lambda,\cdot)\|_{L^2(B)}^{\frac{2\delta}{2(\gamma+\delta)}} (|\lambda|^2+|\rho_{p_0}|^2)^{-\frac{\gamma \delta} {\gamma+\delta}}|\bfc(\lambda)|^{-2} d\lambda.
    \end{align*}
    Applying H\"older's inequality, we derive
    \begin{multline*}
          \|f\|_{L^2(\X)}^2\lesssim \left(\int_{\fa} \|\widetilde{f}(\lambda,\cdot)\|_{L^2(B)}^{2} (|\lambda|^2+|\rho_{p_0}|^2)^{{\delta} } |\bfc(\lambda)|^{-2}\, d\lambda\right)^{\frac{\gamma}{\gamma+\delta}} \\ \cdot \left(\int_{\fa} \|\widetilde{f}(\lambda,\cdot)\|_{L^2(B)}^{2} (|\lambda|^2+|\rho_{p_0}|^2)^{-{\gamma} } |\bfc(\lambda)|^{-2}\, d\lambda\right)^{\frac{\delta}{\gamma+\delta}} .
    \end{multline*}
    Now, taking $\sigma = \kappa = \gamma$ in \eqref{eqn_pitt's_p=q=2_n} and applying it to the second term on the right-hand side, we obtain the inequality  
    \begin{align}\label{eqn_unc_2,2_F_n} 
          \|f\|_{L^2(\X)} \leq C \| (|\lambda|^2+ |\rho_{p_0}|^2)^{\frac{\delta}{2}}\widetilde{f}\|_{L^2(\fa \times B, |\bfc(\lambda)|^{-2}d\lambda db)}^{\frac{\gamma} {\gamma+\delta}}  \| |x|^{\gamma} f\|_{L^2(\X)}^{\frac{\delta} {\gamma+\delta}} 
    \end{align}
    for $\gamma < n/2$ when $p_0 \neq 2$, and for $\gamma < \min\{n/2, \nu/2\}$ when $p_0 = 2$. 
To extend \eqref{eqn_unc_2,2_F_n} to the full range of $\gamma > 0$, we proceed as follows. Suppose $\gamma \geq \min\{n/2, \nu/2\}$, and choose any $\gamma_0 <\min\{n/2, \nu/2\}$.
%To extend \eqref{eqn_unc_2,2_F} to the remaining range of $\gamma$, we will proceed as follows. Suppose $\gamma \geq \min\{n/2, \nu/2\}$, then we choose any $\gamma_0 < \min\{n/2, \nu/2\}$. 
Then, for every $\epsilon > 0$, we have 
    \begin{align}
        \frac{|x|^{\gamma_0}}{\epsilon^{\gamma_0}}\leq 1+ \frac{|x|^{\gamma}}{\epsilon^{\gamma}},
    \end{align}
    from which it follows that 
    \begin{align*}
        \||x|^{\gamma_0}f\|_{L^2(\X)}\leq \epsilon^{\gamma_0} \|f\|_{L^2(\X)}+ \epsilon^{\gamma_0-\gamma} \||x|^{\gamma}f\|_{L^2(\X)}.
    \end{align*}
   Putting $\epsilon^{\gamma} = \||x|^{\gamma }f\|_{L^2(\X)}/\|f\|_{L^2(\X)}$  in the inequality above, yields that
     \begin{align*}
        \||x|^{\gamma_0}f\|_{L^2(\X)}\leq C   \|f\|_{L^2(\X)}^{1-\frac{\gamma_0}{\gamma}} \||x|^{\gamma}f\|_{L^2(\X)}^{\frac{\gamma_0}{\gamma}}.
    \end{align*}
    Substituting the estimate above into \eqref{eqn_unc_2,2_F_n} with $\gamma$ replaced by $\gamma_0$, we obtain
    \begin{align*}
        \|f\|_{L^2(\X)} \leq C \| (|\lambda|^2+ |\rho_p|^2)^{\frac{\delta}{2}}\widetilde{f}\|_{L^2(\fa \times B, |\bfc(\lambda)|^{-2}d\lambda dk)}^{\frac{\gamma_0} {\gamma_0+\delta}} \|f\|_{L^2(\X)}^{\left(1-\frac{\gamma_0}{\gamma} \right)\frac{\delta} {\gamma_0+\delta}} \||x|^{\gamma}f\|_{L^2(\X)}^{\frac{\gamma_0 \delta} {\gamma(\gamma_0+\delta)}} \, .
    \end{align*}
    Reorganizing the expression above, it follows that
    \begin{align*}
       \|f\|_{L^2(\X)}^{\frac{\gamma_0 (\gamma+\delta)} {\gamma(\gamma_0+\delta)}}  \leq C \| (|\lambda|^2+ |\rho_p|^2)^{\frac{\delta}{2}}\widetilde{f}\|_{L^2(\fa \times B, |\bfc(\lambda)|^{-2}d\lambda dk)}^{\frac{\gamma_0} {\gamma_0+\delta}} \||x|^{\gamma}f\|_{L^2(\X)}^{\frac{\gamma_0 \delta} {\gamma(\gamma_0+\delta)}},
    \end{align*}
    which gives the desired inequality \eqref{eqn_unc_2,2_F} for all $\gamma, \delta > 0$, concluding our result.
\end{proof}
Uncertainty inequalities of the form
 $\|f\|_{L^2}^2 \leq C \|v^{1/p}f\|_{L^p} \|w^{1/q} f\|_{q}$ are also of significant interest, where $v$ and $w$ are suitable weight functions and $1\leq p,q<\infty$; see \cite[p. 214]{FS97} and \cite{CP84} for further discussion. We now use the shifted Pitt's inequality to derive such an analogue of weighted uncertainty inequalities.




\begin{corollary}
Let $ \X$ be a symmetric space of noncompact type of dimension $n$. Let $1<p\leq 2$, $p\leq q'\leq p'$ and $\zeta \geq 0$.  Suppose $\zeta \neq 0$, $\sigma$, $\kappa\geq 0 $ be such that $ \kappa <n/p'$ and $\sigma -\kappa\geq n(1/p-1/q)$.  Then for every $f\in C_c^{\infty}(\X)$,
     \begin{align}\label{eqn_uncertain_2,p}
        \|f\|_{L^2(\X)}^2 &\leq C \left( \int_{\fa}\|\widetilde{f}(\lambda, \cdot)\|_{L^2(B)}^{q}   (|\lambda|^2+\zeta^2)^{\frac{\sigma q}{2}} |\bfc(\lambda)|^{-2}\,d\lambda \right)^{\frac{1}{q}}  \left(\int_{{\X}}{\left|  f(x)\right| }^p  |x|^{\kappa p} \,dx\right)^{\frac{1}{p}}.
    \end{align}
\end{corollary}
Furthermore the same statement will be true for $\zeta=0$, if in addition we assume $\sigma -\kappa \leq \nu(1/p-1/q) $.
\begin{proof}
    We can write from Plancherel's theorem and applying H{\"o}lder's inequality successively 
    \begin{align*}
        \|f\|_{L^2(\X)}^2&= \int_{\fa} \int_{B} \widetilde{f}(\lambda, k) \overline{\widetilde {f}(\lambda,k)} |\bfc(\lambda)|^{-2}\, dk \,d\lambda\\
        & = \int_{\fa} \|\widetilde{f}(\lambda, \cdot)\|_{L^2(B)}  (\lambda^2+ \zeta^2)^{\frac{\sigma}{2}} \|\widetilde {f}(\lambda,\cdot)\|_{L^2(B)} (\lambda^2+ \zeta^2)^{-\frac{\sigma}{2}} |\bfc(\lambda)|^{-2}\,d\lambda\\
        &\leq \left( \int_{\fa} \|\widetilde{f}(\lambda, \cdot)\|_{L^2(B)}^{q}  (\lambda^2+ \zeta^2)^{\frac{\sigma q}{2}}  |\bfc(\lambda)|^{-2}\,d\lambda \right)^{\frac{1}{q}} \\
        & \hspace{2cm} \cdot \left( \int_{\fa} \|\widetilde{f}(\lambda, \cdot)\|_{L^2(B)}^{q'}  (\lambda^2+ \zeta^2)^{-\frac{\sigma q'}{2}}  |\bfc(\lambda)|^{-2}\,d\lambda \right)^{\frac{1}{q'}}.
    \end{align*}
    By applying the shifted Pitt's inequality result from Theorem \ref{thm_pitt_X_n} to the second term on the right-hand side, we obtain \eqref{eqn_uncertain_2,p}
\end{proof}



\begin{corollary}
    Let $\zeta \neq 0$, $q\geq 2$, and $1<p\leq q'$. Suppose $\sigma, \kappa \geq 0$ be such that $ \kappa <n/p'$ and $\sigma \geq \kappa+n(1/p-1/q)$. Then we have for all $f \in C_c^{\infty}(\X)$
    \begin{align}\label{eqn_unc_p,q1_n}
        \|f\|_{L^q(\X)}^{q'} \leq C   \left( \int_{{\fa}} \left(\int_B|\widetilde{f}(\lambda, b)|^{2} \, db\right)^{\frac{q'}{2}} (|\lambda|^2+\zeta^2)^{\frac{\sigma q}{2}} |\bfc(\lambda)|^{-2} \,d \lambda \right)^{\frac{1}{q }}  \left( \int_{\X}|f(x)|^p  |x|^{\kappa p}\,dx \right)^{\frac{1}{p}}.
    \end{align}
\end{corollary}
\begin{proof}
    By using dual of Hausdorff-Young  inequality from \eqref{eqn_HYP_dual-int}, we get
    \begin{align*}
         \|f\|_{L^q(\X)} \leq   \left( \frac{1}{|W|}\int_{\mathbb{\fa}}  \|\widetilde{f}(\lambda, \cdot)\|_{L^2(B)}^{q'} |\bfc(\lambda)|^{-2} \,d \lambda \right)^{\frac{1}{q'}}.
    \end{align*}
    Writing $q'= \frac{1}{q-1}+1$ and applying H\"older's inequality, we get from the inequality above
    \begin{multline*}
         \|f\|_{L^q(\X)}^{q'} \leq   \left( \frac{1}{|W|}\int_{\mathbb{\fa}}  \|\widetilde{f}(\lambda, \cdot)\|_{L^2(B)}^{q'} (|\lambda|^2+\zeta^2)^{\frac{\sigma q}{2}}|\bfc(\lambda)|^{-2} \,d \lambda \right)^{\frac{1}{q}}\\
         \cdot \left( \frac{1}{|W|}\int_{\mathbb{\fa}} \ \|\widetilde{f}(\lambda, \cdot)\|_{L^2(B)}^{q'}  (|\lambda|^2+\zeta^2)^{-\frac{\sigma q'}{2}}|\bfc(\lambda)|^{-2} \,d \lambda \right)^{\frac{1}{q'}}.
    \end{multline*}
    Since $1<p\leq q'$,  using Theorem \ref{thm_pitt_X_n} we establish \eqref{eqn_unc_p,q1_n}.
\end{proof}
Using Theorem \ref{thm_pitt_X_n} with $q=p'$, $\zeta =|\rho_{p_0}|$, and taking $(-\mathcal{L}_{p_0})^{\sigma/2}f$ instead of $f$ in \eqref{inq_pitt_pol}, we obtain the following corollary.
\begin{corollary}
    Let $ \X$ be a symmetric space of noncompact type of dimension $n$, $p_0\in [1,2)$, and $p \in(1, 2],$. Suppose  that $0\leq \kappa <n/{p'}$. Then for any $\sigma \geq  \kappa$ , we have  the following inequality 
\begin{align}
         \left( \int_{{\fa}} \left(\int_B|\widetilde{f}(\lambda, b)|^{2} \, db\right)^{\frac{p'}{2}}   |\bfc(\lambda)|^{-2} \,d \lambda \right)^{\frac{1}{p'}}  \leq C \left( \int_{\X}|(-\mathcal{L}_{p_0})^{\sigma/2}f(x)|^p  |x|^{\kappa p}\,dx \right)^{\frac{1}{p}}
    \end{align}
    for all $f \in C_c^{\infty}(\X)$,
    which can be seen as a generalized version of the Hausdorff-Young inequality \eqref{eqn_HY_X,n}.
\end{corollary}



\subsection{$L^p$ Heisenberg-Pauli-Weyl uncertainty inequality}
We now proceed to establish the $L^p$-type HPW uncertainty inequality. We begin by recalling a class of Hardy-type inequalities for the modified Laplacians $\mathcal{L}_{p_0}$ in \cite{KRZ_23}.
For other forms of Hardy inequalities on symmetric spaces of noncompact type, see also \cite{BP22}. We have the following result from  \cite[Theorem 1.2]{KRZ_23} by putting $p=q$ and  $\alpha=0$. 
    \begin{lemma}\label{cor_hardy_inq_X}
    Let $\X$ be a general symmetric space of dimension $n\geq 2$ and pseudo-dimension $\nu \geq 3$. Suppose that $\zeta\geq 0$, $\sigma>0$ ($0<\sigma <\nu$ if $\zeta=0$) and $\beta \in \R$. Then the inequality 
    \begin{align}\label{eqn_hardy_inq_X}
    \| |\cdot |^{-\beta} (-\mathcal{L} - |\rho|^2 +\zeta^2))^{-\frac{\sigma}{2}} f \|_{L^{p}(\X)} \lesssim \|f\|_{L^p(\X)}    \quad \forall f\in L^p(\X),
    \end{align}
     holds if $1\leq p\leq \infty$, $\beta< {n}/{p}$ when $\beta>0$, $0\leq \beta \leq \sigma$, and one of the following conditions is met:
    \begin{enumerate}
        \item if $\zeta >|\rho|$;
        \item if $0 \leq \zeta \leq |\rho|$, then 
        \begin{align}\label{eqn_ran_of_p,c}
             \frac{1}{2}-\frac{\zeta}{2|\rho|}<\frac{1}{p}<\frac{1}{2}+\frac{\zeta}{2|\rho|}.
        \end{align}
        \item if $\zeta=0$ and $p=2$, then $\sigma<\nu/2$ and $\sigma\leq \beta$.
    \end{enumerate}
    \end{lemma}
\begin{lemma}\label{lem_Lp_unc_X_p_0}
 Let $\X$ be a general symmetric space of noncompact type and  $ 1\leq p_0<2$. Suppose that $\gamma_0, \delta_0 \in (0,\infty) $, $p>1$, $q\geq 1$, and $r\in (p_0,p_0')$, such that
\begin{align*}
    \delta_0 <\frac{n}{r_0} \quad  \text{and} \quad  \frac{\gamma_0+\delta_0}{p}= \frac{\delta_0}{q}+\frac{\gamma_0}{r}.
\end{align*}
Then for any $\sigma \geq \delta_0$, we have
\begin{align}\label{eqn_Lp_uncn_X_p_0}
    \|f\|_{L^{p}(\X)} \leq C \| |x|^{\gamma_0}f\|_{L^{q}(\X)}^{\frac{\delta_0}{\gamma_0+\delta_0}} \| (-\mathcal{L}_{p_0})^{\frac{\sigma}{2}}f\|_{L^{r}(\X)}^{\frac{\gamma_0}{\gamma_0+\delta_0}}
\end{align}
for all $f \in C_c^{\infty}(\X)$.
\end{lemma}
\begin{proof}
    Setting $\theta = \gamma_0/(\gamma_0 + \delta_0)$, we write
    \begin{align*}
        \int_{\X} |f(x)|^{p} \,dx=\int_{\X} \left(|x|^{\theta \delta_0} |f(x)|^{\theta} \right)^{p}  \left(|x|^{- {\theta \delta_0}} |f(x)|^{1-\theta} \right)^{p} \, dx.
    \end{align*}
   Let us  choose $s$ such that $q= \theta ps$, then $r =(1-\theta) p s'$. Applying H\"older’s inequality with exponent $s$ to the integrand and then taking the $p$th root, we obtain
   \begin{equation}\label{eqn_Lpf<xbf}
    \begin{aligned}
        \|f\|_{L^p(\X)} &\leq \left(\int_{\X} \left(|x|^{\theta \delta_0 } |f(x)|^{\theta} \right)^{ps }  \, dx\right)^{\frac{1}{ps}}  \left( \int_{\X}\left(|x|^{- {\theta \delta_0}} |f(x)|^{1-\theta} \right)^{ps'} \, dx \right)^{\frac{1}{ps'}}\\
        &= \||x|^{\gamma_0}f\|_{L^q(\X)}^{\frac{\delta_0}{\gamma_0+\delta_0}} \||x|^{-\delta_0}f\|_{L^r(\X)}^{\frac{\gamma_0}{\gamma_0+\delta_0}}.
    \end{aligned}
    \end{equation}
Now, applying \eqref{eqn_hardy_inq_X} with $\zeta =|\rho_{p_0}|$ and $\beta=\delta_0$, and using the assumption that $r \in (p_0, p_0')$, we deduce that the following inequality holds for any $\sigma \geq \delta_0$ and $r \in (p_0, p_0')$
 \begin{align*}
       \||x|^{-\delta_0}f\|_{L^r(\X)} \leq C   \| (-\mathcal{L}_{p_0})^{\frac{\sigma}{2}}f\|_{L^{r}(\X)},
 \end{align*}
 for all $f \in C_c^{\infty}(\X)$. Substituting the inequality above in \eqref{eqn_Lpf<xbf}, we establish \eqref{eqn_Lp_uncn_X_p_0}.
\end{proof}
\begin{remark}
   The conclusion of Lemma \ref{lem_Lp_unc_X_p_0} also holds without the additional condition $r \in (p_0, p_0')$ if we replace $-\mathcal{L}_{p_0}$ in \eqref{eqn_Lp_uncn_X_p_0} with $(-\mathcal{L} - |\rho|^2 + \zeta^2)$ for any $\zeta > |\rho|$. 
\end{remark}



We seek an analogue of the classical Landau–Kolmogorov inequality \cite{Kol39, Ste70} for the Laplacian on symmetric spaces of noncompact type. While similar results may be available in broader contexts, we present the full statement and proof here for the sake of completeness. Our approach builds on the method of \cite[Theorem 5.3]{CCR15}, along with sharp estimates for the imaginary powers of the Laplacian on symmetric spaces \cite{Ank90, CGM93, Ion02}. Moreover, to extend the Landau–Kolmogorov inequality beyond the standard Laplacian $\mathcal{L}$ to the more general $L^{p_0}$-Laplacians $\mathcal{L}_{p_0}$, we adapt and generalize the technique developed in  \cite[Theorem 5.3]{CCR15}.
\begin{lemma}\label{lem_LKP_p0_n}
Let $\X$ be a symmetric space of noncompact type, and let $1 \leq p_0 < 2$. Suppose $0 \leq \theta \leq 1$ and $p, q, r \in (p_0, p_0')$ are such that
\begin{align}\label{eqn_p,q,r_LKP}
\frac{1}{p} = \frac{\theta}{q} + \frac{1 - \theta}{r}.
\end{align}
Then, for all $\sigma > 0$, we have
    \begin{align}
        \|(-\mathcal{L}_{p_0})^{\frac{\sigma}{2}}f\|_{L^{p}(\X)} \leq C  \|(-\mathcal{L}_{p_0})^{\frac{\sigma}{2 \theta}}f\|_{L^{q}(\X)}^{\theta} \|f\|_{L^{r}(\X)}^{1-\theta} 
    \end{align}
    for all $f \in C_c^{\infty}(\X)$.
\end{lemma}
\begin{proof}
    Let us define the strip
    \begin{align*}
        S_{\sigma/\theta}= \left\{ z \in \C : 0\leq \Re z \leq {\sigma}/{\theta} \right\}.
    \end{align*}
Now, let us take arbitrary compactly supported function $g \in L^{p'}(\X)$. Then for $z \in S_{\sigma/\theta}$, we define
\begin{align*}
    g_z(x)= \|g\|_{L^{p'}(\X)}^{az+b}g(x) |g(x)|^{cz+d} \quad \text{for all }x\in \X,
\end{align*}
where 
\begin{align*}
    \sigma=\frac{\theta p'}{\sigma} \left(\frac{1}{q}-\frac{1}{p} \right), \quad b=-\frac{p'}{r'}, \quad c=\frac{\theta p'}{\sigma}\left(\frac{1}{p}-\frac{1}{q} \right), \quad \text{and} \quad d=\frac{p'}{r'}-1.
\end{align*}
When $\Re z= \eta$ and 
\begin{align}\label{rel_s_r,p,n}
    \frac{1}{s}= \frac{1}{r}-\frac{\theta \eta}{\sigma}\left(\frac{1}{p}-\frac{1}{q}\right),
\end{align}
then it follows that $\|g_z\|_{L^{s'}(\X)}^{s'}= \|g\|_{L^{p'}(\X)}^{s'(a\eta+b)+p'}=1$. Now let $ f \in C_c^{\infty}(\X) $ be fixed, and define the following analytic function $h: S_{\sigma/\theta} \rightarrow \C$ by
\begin{align}\label{defn_h_z}
    h(z) =e^{z^2}\int_{\X} (-\mathcal{L}_{p_0})^{\frac{z}{2}}f(x) g_z(x)dx.
\end{align}
It is easy to see that $h$ is well defined. For $s \in (p_0,p_0')$ and $y \in \R$,  the following estimate is known
\begin{align}\label{eqn_est_op_Lp_n}
        \|(-\mathcal{L}_{p_0})^{iy}\|_{L^s(\X) \rightarrow L^s(\X)} \leq C e^{\frac{2\pi}{3} |y|},
    \end{align}
 see for instance \cite[Cor. 4.2]{CGM93} \cite[Theorem 9 and (5.2)]{Ion02} (see also \cite{Ank90, Ion03}). We observe from \eqref{rel_s_r,p,n} that since $q,r \in (p_0,p_0')$, $s$ also lies in the interval $(p_0, p_0')$ whenever $0 \leq \eta \leq \sigma/\theta$. Therefore, applying the above estimate for $z = \eta + i y \in S_{\sigma/\theta}$, we get
\begin{align*}
    |h(z)| \leq e^{\eta^2-y^2}\|(-\mathcal{L}_{p_0})^{\frac{iy}{2}}(-\mathcal{L}_{p_0})^{\frac{\eta}{2}}f\|_{L^s(\X)} \|g_z\|_{L^{s'}(\X)}\leq C e^{-y^2+\frac{2\pi}{3} |y|} \| (-\mathcal{L}_{p_0})^{\frac{\eta}{2}}f\|_{L^s(\X)},
\end{align*}
where in the last step we used \eqref{eqn_est_op_Lp_n}. Thus we have obtained $|h(\eta+iy)| \leq C\| (-\mathcal{L}_{p_0})^{\frac{\eta}{2}}f\|_{L^s(\X)}$. Particular, we have from the inequality above and  \eqref{rel_s_r,p,n}
\begin{align*}
    |h(z)| \leq C\begin{cases}
        \|f\|_{L^r(\X)} \quad &\text{if }\Re z=0,\\
         \|(-\mathcal{L}_{p_0})^{\frac{\sigma}{2\theta}}f\|_{L^q(\X)} \quad &\text{if }\Re z=\frac{\sigma}{\theta}.
    \end{cases}
\end{align*}
By the Phragm{\'e}n-Lindel{\"o}f theorem, it follows that
\begin{align}
    |h(\sigma)|\leq C \|(-\mathcal{L}_{p_0})^{\frac{\sigma}{2\theta}}f\|_{L^q(\X)}^{\theta}  \|f\|_{L^r(\X)}^{1-\theta}.
\end{align}
Since
\begin{align*}
     h(\sigma) =e^{\sigma^2}\int_{\X} (-\mathcal{L}_{p_0})^{\frac{\sigma}{2}}f(x) g_{\sigma}(x)dx.
\end{align*}
and $g_{\alpha}$ is an arbitrary compactly supported  simple function on $\X$ with  $L^{p'}(\X)$-norm equal to one, this completes the proof. 
\end{proof}
\begin{remark}
We would like to point out that in the setting of rank one symmetric spaces, Ionescu \cite[Theorem 9]{Ion02} obtained the sharp estimate of $\|(-\mathcal{L}_{p_0})^{iy}\|_{L^s(\X) \rightarrow L^s(\X)}$ for all $s \in [p_0, p_0']$, improving upon an earlier result by Anker and Seeger, who had established similar estimates only for $s \in (p_0, p_0')$. Furthermore, using Ionescu’s result, we can extend the Landau–Kolmogorov inequality for $\mathcal{L}_{p_0}$ in Lemma~\ref{lem_LKP_p0_n} to the full range $p, q, r \in [p_0, p_0']$.
\end{remark}
As an application of the Landau–Kolmogorov inequality, we now extend the uncertainty inequalities from Lemma \ref{lem_Lp_unc_X_p_0} to prove Theorem \ref{thm_Lp_unc_x}. For the reader’s convenience, we restate the theorem below.
\begin{theorem}\label{thm_uncn_Lp_p0,n}
    Let $\X$ be a general symmetric space of noncompact type, and let $1 \leq p_0 < 2$. Suppose $\gamma, \delta  \in (0,\infty)$, and that the exponents $p,q$, and $r$ with $p, r \in (p_0, p_0')$ and $q\geq 1$, which satisfy 
    \begin{align}
          \frac{\gamma+\delta}{p}= \frac{\delta}{q}+\frac{\gamma}{r}.
    \end{align}
Then, for any $\sigma \geq \delta$, we have the following inequality
        \begin{align}\label{eqn_uncn_p0_thm}
            \|f\|_{L^p(\X)} \leq C \| |x|^{\gamma}f\|_{L^q(\X)}^{\frac{\delta}{\gamma+\delta}} \| (-\mathcal{L}_{p_0})^{\frac{\sigma}{2}}f\|_{L^r(\X)}^{\frac{\gamma}{\gamma+\delta}}
        \end{align}
        for all $f \in C_c^{\infty}(\X)$.
\end{theorem}
\begin{proof}
When $\delta < {n}/{r}$, the theorem follows directly from Lemma \ref{lem_Lp_unc_X_p_0}. So, suppose instead that $\delta \geq {n}/{r}$. In this case, choose $\theta \in (0, {n}/{r\delta})$ and define $\delta_0 = \theta \delta$. Then,  $\delta_0 < {n}/{r}$, and by a straightforward computation it follows that
\begin{align}\label{eqn_reln_d,g_n}
    \frac{\gamma+\delta_0}{p}=\frac{\delta_0}{q}+{\frac{\gamma}{r_0}}, \qquad \text{where } \quad \frac{1}{r_0}= \frac{\theta}{r}+\frac{1-\theta}{p}.
\end{align}
Now applying Lemma \ref{lem_Lp_unc_X_p_0}, we get that for any $\sigma \geq  \delta_0$  the following holds 
\begin{align}\label{eqn_unc_p,d<nr}
    \|f\|_{L^p(\X)} \leq C \| |x|^{\gamma}f\|_{L^q(\X)}^{\frac{\delta_0}{\gamma+\delta_0}} \| (-\mathcal{L}_{p_0})^{\frac{\sigma}{2}}f\|_{L^{r_0}(\X)}^{\frac{\gamma}{\gamma+\delta_0}}
\end{align}
for all $f \in C_c^{\infty}(\X)$. By using \eqref{eqn_reln_d,g_n} and applying the Landau–Kolmogorov inequality from Lemma \ref{lem_LKP_p0_n}, we obtain
\begin{align*}
     \|(-\mathcal{L}_{p_0})^{\frac{\sigma}{2}}f\|_{L^{r_0}(\X)} \leq C  \|(-\mathcal{L}_{p_0})^{\frac{\sigma}{2 \theta}}f\|_{L^{r}(\X)}^{\theta} \|f\|_{L^{p}(\X)}^{1-\theta}. 
\end{align*}
Substituting the inequality above into \eqref{eqn_unc_p,d<nr} and reorganizing the terms yields \eqref{eqn_uncn_p0_thm}, thereby completing the proof of the theorem.
\end{proof}
\subsection{Applications of shifted Pitt's inequality for Jacobi transforms}\label{sec_app_jac} We have similar applications of shifted Pitt's inequality for the Jacobi transform as in the previous section. We omit the proofs, as they follow the same arguments presented in earlier subsections,  relying on Theorem \ref{thm_pitt's_stand_J}.

\begin{corollary}
    Let $\gamma, \delta>0 $, and $\rho_p = |2/p-1| \rho$. Then we have the following 
    \begin{align}\label{eqn_unc_J2,2_F}
        \|f\|_{L^2(m)} \leq C \| t^{\gamma} f\|_{L^2(m)}^{\frac{\delta} {\gamma+\delta}}  \| (\lambda^2+ \rho_p^2)^{\frac{\delta}{2}}\mathcal{J}f\|_{L^2(\R_+, |\bfc(\lambda)|^{-2}d\lambda)}^{\frac{\gamma} {\gamma+\delta}}
    \end{align}
    for all $f \in C_c^{\infty}(\R_+)$. Equivalently, we have 
     \begin{align}\label{eqn_unc_J2,2_X}
        \|f\|_{L^2(m)} \leq C \| t^{\gamma} f\|_{L^2(m)}^{\frac{\delta} {\gamma+\delta}}  \|  (-\mathcal{L}_{p})^{\frac{\delta}{2}} f \|_{L^2(m)}^{\frac{\gamma} {\gamma+\delta}},
    \end{align}
    where $\mathcal{L}_{p}= \mathcal{L}+(|\rho|^2-|\rho_p|^2) I$ and $\mathcal{L}$ is the Jacobi Laplacian defined in \eqref{defn_of_L_Jac}. 
\end{corollary}

\begin{corollary}
Let $\zeta\neq 0$, $1<p\leq 2$, and $p\leq q'$.   Suppose  $\sigma,\kappa\geq 0$ be such that $3 (1/q-1/p) \leq \kappa <2(\alpha+1)/p'$ and $\sigma \geq \kappa+ 2(\alpha+1)(1/p-1/q)$.  Then for every $f\in C_c^{\infty}(\R_+)$,
     \begin{align}\label{eqn_uncertain_jac_2,p}
        \|f\|_{L^2(m)}^2 &\leq C \left( \int_{0}^{\infty} |\mathcal{J}f(\lambda)|^{q}   (\lambda^2+\zeta^2)^{\frac{\sigma q}{2}} |\bfc(\lambda)|^{-2}\,d\lambda \right)^{\frac{1}{q}}  \left(\int_{{0}}^{{\infty}}{\left|  f(t)\right| }^p  t^{\kappa p} m(t)\,dt\right)^{\frac{1}{p}}.
    \end{align}
\end{corollary}


\begin{corollary}
    Let $q\geq 2$,  $1<p\leq q'$ and $\zeta\neq 0$.   Suppose $\sigma$, $\kappa$ be such that $0\leq \kappa <2(\alpha+1)/p'$ and $\sigma \geq \kappa+2(\alpha+1)(1/p-1/q)$. Then we have for all $f \in C_c^{\infty}(\R_+)$
    \begin{align}\label{eqn_unc_p,q1}
        \|f\|_{L^q(m)}^{q'} \leq C   \left( \int_{0}^{\infty} |\mathcal{J}f(\lambda)|^{{q'}} (\lambda^2+\zeta^2)^{\frac{\sigma q}{2}} |\bfc(\lambda)|^{-2} \,d \lambda \right)^{\frac{1}{q}}  \left(\int_{{0}}^{{\infty}}{\left|  f(t)\right| }^p  t^{\kappa p} m(t)\,dt\right)^{\frac{1}{p}}.
    \end{align}
\end{corollary}
\begin{corollary}
Let $p \in (1,2]$ and  $p_0 \in [1,2)$.   Suppose that $0\leq \kappa <2(\alpha+1)/{p'}$, then for any $\sigma \geq  \kappa$, we have  the following inequality 
\begin{align}
         \left( \int_{0}^{\infty}  |\mathcal{J}f(\lambda)|^{p'}   |\bfc(\lambda)|^{-2} \,d \lambda \right)^{\frac{1}{p'}}  \leq C \left( \int_{0}^{\infty}|(-\mathcal{L}_{p_0})^{\sigma/2}f(t)|^p  t^{\kappa p} m(t) \,dt\right)^{\frac{1}{p}}
    \end{align}
    for all $f \in C_c^{\infty}(\R_+)$.
    \end{corollary}

\begin{remark}
Analogous applications for other types of Jacobi  transforms may be obtained using Theorem \ref{thm_pitt's_mod_J}, \ref{thm_pitt's_mod_J-1}, and \ref{thm_pitt_inq_inv_J}. Since the methods are similar, we omit the detailed statements and proofs.
\end{remark}
\section{Concluding remarks}
In conclusion, we would like to offer some observations and draw attention to a few open problems that, from our perspective, warrant further investigation.
\begin{enumerate}
    \item As in the Euclidean setting, it is also interesting to establish the Pitt-type inequality for the range $2 < p \leq q < \infty$. However, due to the exponential volume growth of symmetric spaces, it becomes necessary to incorporate exponential weights when $p > 2$. In fact, following a similar computation as in Theorem \ref{thm_nec_pitt_n}, we can show that for $p > 2$, the appropriate weight is $w_\delta = e^{2\rho \delta t}$ with $\delta$   greater than equal to  $({1}/{2} - {1}/{p})$. In this context, we also note that in the rank one case, Ray and Sarkar established a Hardy–Littlewood–Sobolev inequality for $p \geq 2$ in \cite[Theorem 4.11 (ii)]{RS09}. By interpolating their result with \eqref{inq_pit_p,2}, one can derive a version of the Pitt inequality for $p > 2$, albeit with exponential weights appearing on the function side.
    \item As noted earlier in Remark~\ref{rem_nec_suff_mJ}, we assumed $\sigma, \kappa \geq 0$  to compute the non-increasing rearrangement of polynomial weights. It is therefore natural to ask whether this condition is also necessary for the shifted Pitt's inequality to hold for $1 \leq  p \leq q < \infty$ in the setting of modified Jacobi transforms. Moreover, a complete characterization of admissible polynomial weights in shifted Pitt's inequality for Jacobi transforms, and, on Riemannian symmetric spaces, remains an important open problem.  
\end{enumerate}
