\begin{proof}
These are proven by direct calculation. 
We just demonstrate the calculation in a few examples for (o) and (h). 
Generators of $\mathcal{W}(q)$ (resp.~$\mathcal{W}(-q)$) acting on the $5$-th (resp.~$6$-th) component of 
$\mathbf{V}$  will be denoted by $e^{\pm \uu}, e^{\pm \ww}$ (resp. $e^{\pm \uu'}, e^{\pm \ww'}$)
as in the previous subsection. 
\\[1mm]
(o) For an in-state $\mathbf{i}=(i_1,i_2,i_3,i_4) \in V^{\otimes 4}$ and an out-state $\mathbf{j}=(j_1,j_2,j_3,j_4) \in V^{\otimes 4}$, \eqref{LM-o} is written as 
\begin{align}\label{mLM-o}
\sum_{k_1,k_2,k_3,k_4=0,1} \MM^{j_1 j_2}_{k_1 k_2} \MM^{j_3 j_4}_{k_3 k_4} 
\LL^{k_1k_3}_{i_1i_3} \LL^{k_2 k_4}_{i_2i_4}
=
\sum_{k_1,k_2,k_3,k_4=0,1} \LL^{j_2 j_4}_{k_2 k_4} \LL^{j_1 j_3}_{k_1 k_3} 
\MM^{k_3 k_4}_{i_3 i_4} \MM^{k_1 k_2}_{i_1 i_2}.
\end{align}
Let us see the case of $(\mathbf{i},\mathbf{j}) = (0,1,1,0,1,0,1,0)$. We have for the LHS of \eqref{mLM-o}
\begin{align*}
\MM^{10}_{01} \MM^{10}_{10} \LL^{01}_{01} \LL^{10}_{10} + \MM^{10}_{10} \MM^{10}_{01} \LL^{10}_{01} \LL^{01}_{10}
&= e^{-\ww'}f' e^{\uu'} g e^\uu f e^\uu + f'e^{\uu'} e^{-\ww'} e^{-\ww}(rse^\ww+fg e^{2\uu+\ww})
\\
&= f'e^{\uu'} e^{-\ww'} rs, 
\end{align*}
and for the RHS of \eqref{mLM-o}
\begin{align*}
\LL^{00}_{00} \LL^{11}_{11} \MM^{10}_{10} \MM^{10}_{01}
= rsf'e^{\uu'} e^{-\ww'}
\end{align*}
which equals to the LHS.
\\[1mm]
(h) For an in-state $\mathbf{i}=(i_1,i_2,i_3,i_4) \in V^{\otimes 4}$ and an out-state $\mathbf{j}=(j_1,j_2,j_3,j_4) \in V^{\otimes 4}$, \eqref{LM-h} is written as 
\begin{align}\label{mLM-h}
\sum_{k_1,k_2,k_3,k_4=0,1}  \MM^{k_1 k_2}_{i_1i_2} \MM^{j_3 j_4}_{k_3 k_4} \LL^{k_3 j_1}_{i_3 k_1} \LL^{k_4 j_2}_{i_4 k_2}  
=
\sum_{k_1,k_2,k_3,k_4=0,1}  \LL^{j_4 k_2}_{k_4 i_2} \LL^{j_3 k_1}_{k_3 i_1} \MM^{k_3 k_4}_{i_3 i_4} \MM^{j_1 j_2}_{k_1 k_2},
\end{align}
where we have applied the operation $[~~]_{\ast 6}$. 
For $(\mathbf{i},\mathbf{j}) = (0,1,1,0,1,0,1,0)$, the LHS of \eqref{mLM-h} becomes
\begin{align*}
\MM^{10}_{01} \MM^{10}_{10} \LL^{11}_{11} \LL^{00}_{00} + \MM^{01}_{01} \MM^{10}_{01} \LL^{01}_{10} \LL^{10}_{01}
&= e^{-\ww'} f' e^{\uu'} s r + g'e^{\uu'} e^{-\ww'} (rs e^\ww + fg e^{2\uu+\ww}) e^{-\ww} 
\\
&= sr e^{\uu'}e^{-\ww'}(g'-qf') + fg g'q^{-1}e^{\uu'}e^{-\ww'} e^{2\uu}
\end{align*}
and the RHS becomes 
\begin{align*}
\LL^{01}_{01} \LL^{10}_{10} \MM^{10}_{10} \MM^{10}_{01}
= g e^\uu f e^\uu f'e^{\uu'} e^{-\ww'}.
\end{align*}
Thus \eqref{mLM-h} reduces to $g' = q f'$.
For $(\mathbf{i},\mathbf{j}) = (0,1,0,1,0,0,1,1)$, \eqref{mLM-h} leads to
$$
\MM^{10}_{01} \MM^{11}_{11} \LL^{10}_{01} \LL^{10}_{10} = \LL^{10}_{01} \LL^{10}_{10} \MM^{10}_{01} \MM^{00}_{00} ,
$$
which reduces to $s' = r'$.
\end{proof}

