\draw [->] (-0.3,2.2) node[above]{$1$}-- (2.2,-0.3);
{\color{green} 
\draw [->] (-0.7,1.8) node[left]{$3$}-- (1.8,-0.7)[thick];
}
\draw (2.3,0.5) node {$\times \,r's'$}; 
\end{scope}
\end{tikzpicture}
\end{align}

\item[(I')] Reversed type: $[\mathcal{M}(r',s',f',q f';q) \mathcal{M}(s',r',f',qf';q)]_{\ast 3} = r' s' \cdot \mathrm{Id}$.
Here the subscript $\ast 3$ means that the multiplication in $\mathcal{W}(-q)$ is reversed. 
\begin{align}\label{M-I'}
