\begin{scope}[>=latex,xshift=0pt]
{\color{green} 
\draw [->] (-0.5,1.5) node[left]{$3$}-- (0,1.5) coordinate(A) to [out = 0, in = 90] (1.5,0) coordinate(B) -- (1.5,-0.5)[thick];
}
\draw [<-] (-0.5,2) node[above left]{$1$}-- (2,-0.5);
\draw [<-] (0,2) node[above]{$2$}-- (A) to [out=-90,in=180] (B) --(2,0); 
%
