\end{scope}
\begin{scope}[>=latex,xshift=135pt]
%
\draw [<-] (-0.5,2) node[above left]{$1$}-- (2,-0.5);
\draw [<-] (-0.3,2.2) node[above]{$2$}-- (2.2,-0.3);
{\color{green} 
\draw [->] (-0.7,1.8)node[left]{$3$} -- (1.8,-0.7)[thick];
}
\draw (2.3,0.5) node {$\times \,r's'$}; 
\end{scope}
\end{tikzpicture}
\end{align}
\end{itemize}
In other words, the operator $\MM$  satisfies the inversion relation of type (I) (resp. type (I')) if $r~=s'$ and $g'=q^{-1}f'$ (resp. $g'=q f'$).  
\end{lem}

\begin{proof}
(I) An equation $\mathcal{M}(r,s,f,g;q) \mathcal{M}(r',s',f',g';q) = r's' \cdot \mathrm{Id}$ leads to
\begin{align}
\label{inv-1}
&rr' = s s' = r's',
\\
\label{inv-2}
&g g'e^{2\uu'} + rs + fg e^{2\uu'+\ww'} e^{-\ww'} = r's',
\\
&g e^\uu (r's' e^{\ww'} + f'g' e^{2\uu'+\ww'})+ (rs e^{\ww'} + fg e^{2\uu'+\ww'})f'e^{\uu'} = 0,
\\
&g' e^{-\ww'} e^{\uu'} + f e^{\uu'} e^{-\ww'} = 0,
\\
\label{inv-5}
&e^{-\ww'}(r's' e^{\ww'} + f'g' e^{2\uu'+\ww'})+ff'e^{2\uu'} = r's',
\end{align}
and we obtain $r=s', ~s=r', ~f=q g'$ and $g=q^{-1}f'$.
This reduces to \eqref{M-I} by further setting $g' = q^{-1}f'$.
\\
(I') An equation $[\mathcal{M}(r,s,f,g;q) \mathcal{M}(r',s',f',g';q)]_{\ast 3} = r's' \cdot \mathrm{Id}$ leads to \eqref{inv-1}--\eqref{inv-5} but operators in \eqref{inv-2}--\eqref{inv-5} are in reverse order due to $[~~]_{\ast 3}$;
for example \eqref{inv-2} becomes 
$g g'e^{2\uu'} + rs + fg e^{-\ww'} e^{2\uu'+\ww'} = r's'$.
Thus we obtain $r=s', ~s=r', ~f=q^{-1} g'$ and $g=q f'$, and 
get \eqref{M-I'} by further setting $g' = q f'$.
\end{proof}

