\subsection{$RLLL$ relation}\label{sec:RLLL}

We briefly recall the $RLLL$ relation \eqref{RLLL} for the q-6v model studied in \cite[\S 7]{IKSTY}. See \cite{IKSTY} for the detail.
For three canonical pairs $\uu_i$ and $\ww_i$, and parameters $\mathscr{P}_i:=(a_i, b_i, c_i, d_i, e_i) \in \C^5$ satisfying $a_i+b_i+c_i+d_i+e_i=0$ for $i=1,2,3$, the $R$-operator $\mathscr{R}=\mathscr{R}(\mathscr{P}_1 ,\mathscr{P}_2 ,\mathscr{P}_3)$ is defined as
\begin{align}
\label{r123}
\mathscr{R} 
&= 
\Psi_q(\e^{-d_1-c_2-b_3+u_1+u_3+w_1-w_2+w_3})^{-1}
\Psi_q(\e^{-d_1-c_2-b_3-e_3+u_1-u_3+w_1-w_2+w_3})^{-1}
\nonumber\\
&\quad \times P_{123} 
\Psi_q(\e^{-b_1-a_2-d_3-e_3+u_1-u_3+w_1-w_2+w_3})
\Psi_q(\e^{-b_1-a_2-d_3+u_1+u_3+w_1-w_2+w_3}),
\\
P_{123} &=  
\e^{\tfrac{1}{\hbar}(u_3-u_2)w_1}
\e^{\tfrac{\lambda_0}{\hbar}(-w_1-w_2+w_3)}
\e^{\tfrac{1}{\hbar}(\lambda_1u_1+\lambda_2u_2+\lambda_3u_3)}\rho_{23}
%\in N_6 \rtimes \mathfrak{S}_6.
\label{pijk} 
\end{align}
Here $\Psi_q$ is the quantum dilogarithm, 
\begin{align}\label{Psiq}
\Psi_q(Y) = \frac{1}{(-qY; q^2)_\infty}, \quad (z;q)_\infty = \prod_{n=0}^\infty (1-zq^n),
\end{align}
$\rho_{23}$ is the permutation of the labels of the canonical pairs, and $\lambda_r=\lambda_r(\mathscr{P}_1,\mathscr{P}_2,\mathscr{P}_3)$
for $r=0$, $1$, $2$, $3$ are defined by 
\begin{align}\label{lad}
\lambda_0 = \frac{e_2-e_3}{2},\quad 
\lambda_1 = a_2-a_3+b_2-b_3 + \lambda_0,\quad
\lambda_2 = -a_1-b_2+b_3-\lambda_0,\quad
\lambda_3 = c_1-c_2+c_3.
\end{align}



\begin{thm}\cite[Theorem 7.1]{IKSTY}
\label{th:RLLL}
The $R$-operator \eqref{r123} and the operator $\mathscr{L}$ \eqref{L1} satisfy  the $RLLL$ relation \eqref{RLLL}, where we set $\mathscr{R}_{456} = \mathscr{R}$, $\mathscr{L}_{124} = \mathscr{L}(r_1,s_1,f_1,g_1;q)$,
$\mathscr{L}_{135}=\mathscr{L}(r_2,s_2,f_2,g_2;q)$ and $\mathscr{L}_{236}=\mathscr{L}(r_3,s_3,f_3,g_3;q)$ on the both sides of \eqref{RLLL}, and identify the parameters as
  \begin{equation}
%    \label{pXZrstw}
%    X_i = \e^{u_i}, \quad
%    Z_i = \e^{-w_i}, \quad
    r_i = \e^{c_i}, \quad
    s_i = \e^{a_i}, \quad
    f_i = \e^{-b_i}, \quad
    g_i = \e^{-d_i},
  \end{equation}
for $i=1,2,3$.
For $\mathscr{L}(r_i,s_i,f_i,g_i;q)$, we use the $q$-Weyl pair defined by a canonical pair $\uu_i$ and $\ww_i$ satisfying $[\uu_i,\ww_i] = \hbar$, which generates the $i$-th component of $\mathcal{W}(q)^{\otimes 3}$. 
\end{thm}

