$$
  s_x(k) = 
\begin{cases}
  1 & \text{if the $k$-th arrow is outgoing},
  \\
  -1 & \text{if the $k$-th arrow is incoming}.
\end{cases} 
$$
for $k=1,\ldots,m$, 
and for arrows on the north boundary define $s_y(k)$ for $k=1,\ldots,n$ in the same manner.
Under this setting, we have 
$\mathcal{T}_G(x,y) \in \mathrm{End}(V^{\otimes N}) \otimes \mathcal{W}_K(q)$.

As in the ordinary case, 
we define the transfer matrix $T_G(x,y)$ as $\Tr_{V^{\otimes N}} \mathcal{T}_G(x,y)$:
\begin{align}\label{T-Gg}
T_G(x,y) &= \mathrm{Tr}_{V^{\otimes N}}\left(\mathcal{T}_G(x,y)\right)
= \sum_{\mathbf{i} \in \{0,1\}^m, \,\mathbf{j} \in \{0,1\}^n} 
T^{\mathbf{i},\mathbf{j}}_{\mathbf{i}, \mathbf{j}} \,
x^{||\mathbf{i}||} y^{||\mathbf{j}||} \in \mathcal{W}_{K}(q),
\end{align}
where we set $||\mathbf{i}|| := \sum_{k=1,\ldots,m} s_x(k) i_k$ 
and $||\mathbf{j}|| := \sum_{k=1,\ldots,n} s_y(k) j_k$.
The following theorem is proved in the same manner as Theorem \ref{thm:TT1}.

\begin{thm}\label{thm:TT2}
If a wiring diagram $G$ on a torus with a fixed fundamental domain is admissible, then for any $x,y,u,w \in \C$, it holds that 
\begin{align}
[T_G(x,y), ~T_G(u,w)] = 0.
\end{align}
\end{thm} 

\begin{proof}
We just present some points different from the proof of Theorem \ref{thm:TT1}.
For an admissible $G$, an equality of diagrams similar to \eqref{pSTT=TTS} holds, 
where we set $r'=s'$ and $g' = qf'$ (resp. $r'=s'$ and $g' = q^{-1}f'$) in 
$\mathcal{M}$ \eqref{eq:M}, when we apply only the type B and C moves (resp. type A and C moves) to $G$. 
When the operators $x^{-h}$ or $y^{-h}$ are attached to arrows, Lemma \ref{lem:L-h} is applied in a form as 
$$
  x^{-h_1} y^{-h_2} \cdot \mathcal{L}\cdot (y/x)^{h_3} = (y/x)^{h_3} \cdot \mathcal{L} \cdot x^{-h_1} y^{-h_2}.
$$

For a vertex on the NE arrow, which has incoming arrow at the east or north boundary,  
we use the transpose $\overline{M}$ of $M$ \eqref{M} with respect to $V \otimes V$ instead of $M$. 
The operator $\overline{M}$ is written as $\sigma \cdot (1 \otimes A) \cdot M \cdot (A^{-1} \otimes 1) \cdot \sigma$, where $\sigma$ acts on $V\otimes V$ as $\sigma (v_i \otimes v_j) = v_{1-i} \otimes v_{1-j}$, and $A$ acts on $V$ as $A(v_i) = (q \alpha^2)^i \,v_i$. As both $\sigma$ and $A$ are invertible, the trace of the NE arrow gives an invertible operator: if the $k$-th vertex has $\overline{M}$, for example, we get
$$
\mathrm{Tr}_{\mathcal{V}_+}
\left(z^h M_1 \cdots \overline{M}_k \cdots M_N \right) = (\sigma \cdot 1 \otimes A)_k \cdot R(z) \cdot (A^{-1} \otimes 1 \cdot \sigma)_k,
$$
which is invertible. 
If we used only the type B and C moves (resp. type A and C moves) to $G$,
we set $\alpha=\pm q^{-1}$ (resp. $\alpha= \pm 1)$ for $M$ and $\overline{M}$. 
\end{proof} 

\begin{remark}\label{rmk:inho2}
The transfer matrix $T_G(x,y)$ for an admissible $G$ also allows the two types of inhomogeneous generalization as described in Remark \ref{re:inho},
which preserves the commutativity.
\end{remark}


The transfer matrix $T_G(x,y)$ has the following symmetries.

\begin{prop}\label{prop:inv}
%The transfer matrix $T_G(x,y)$ has the following properties.
\begin{itemize}
\item[(1)] 
The transfer matrix $T_G(x,y)$ is invariant under translation of the fundamental domain.
\item[(2)]
The $SL(2,\Z)$-action on the torus 
induces the following transformation of $T_G(x,y)$,
$$
  T_G(x,y) = \sum_{\mathbf{i},\,\mathbf{j}} 
T^{\mathbf{i},\mathbf{j}}_{\mathbf{i}, \mathbf{j}} x^{||\mathbf{i}||} y^{||\mathbf{j}||} \stackrel{M}{\longmapsto}
  T_G(x',y') = \sum_{\mathbf{i},\,\mathbf{j}} T^{\mathbf{i},\mathbf{j}}_{\mathbf{i}, \mathbf{j}} {x'}^{n_x} {y'}^{n_y},  
$$
for $S =\begin{pmatrix} a & b \\ c & d \end{pmatrix} \in SL(2,\Z)$. Here $(x',y')=(x^ay^b,x^cy^d)$ is the spectral parameters associated to the resulting fundamental domain, and $(n_x,n_y) := (||\mathbf{i}||,||\mathbf{j}||) S^{-1}.$
\end{itemize}
\end{prop}

\begin{proof}
(1) For $\mathbf{i}$ and $\mathbf{j}$ such that $\mathbf{i} \neq 0$ or $\mathbf{j} \neq 0$, take a configuration $W$ on $G$, which is contributing to $T^{\mathbf{i},\mathbf{j}}_{\mathbf{i}, \mathbf{j}}$. By Figure \ref{fig:6v}, $W$ consists of some oriented closed paths of weight $1$. Take one of them and write $p$ for this. Assume it respectively crosses the north and east boundary $k_y$ and $k_x$ times. Here we count the number of crossings with sign: $+1$ and $-1$ when the path is outgoing and incoming respectively. These numbers $k_x$ and $k_y$ are invariant to translation of the fundamental domain. When $\mathbf{i} = 0$ and $\mathbf{j} = 0$, it is trivial that $||\mathbf{i}||=||\mathbf{j}||=n_x=n_y=0$.
Consequently, the claim follows.
\\
(2) By $S = \begin{pmatrix} a & b \\ c & d \end{pmatrix} \in SL(2,\Z)$, the original fundamental domain spanned by $\vec{A} := (1,0)$ and $\vec{B} := (0,1)$ is transformed to that spanned by $\vec{A'}:=(1,0) S$ and $\vec{B'}:=(0,1) S$. Hence the spectral parameters are related by $(x',y') = (x^a y^b, x^c y^d)$. We compute how many times the oriented closed path $p$ (taken in (1)) crosses the new boundaries using the following pictures.

\begin{align*}
\begin{tikzpicture}
\begin{scope}[>=latex,xshift=0pt,yshift=30pt]
{\color{red}
\draw [->] (0,0)--(1,0) node[below left]{$\vec{A}$};
\draw [-] (0,1)--(1,1);
\draw [->] (0,0)--(0,1) node[below left]{$\vec{B}$};
\draw [-] (1,0)--(1,1);
}
\draw [->] (0.5,0.8)  --(0.5,1.3) node [above]{$k_y$};
\draw [->] (0.8,0.5)  --(1.3,0.5) node [right]{$k_x$};
%
\draw (2,0.5) node[right]{$\stackrel{S}{\longmapsto}$};
\end{scope}
\begin{scope}[>=latex,xshift=100pt]
{\color{red}
\draw [->] (0,0)--(3,2) node[below ]{$\vec{A'}$};
\draw [-] (1,1)--(4,3);
\draw [->] (0,0)--(1,1) node[left]{$\vec{B'}$};
\draw [-] (3,2)--(4,3);
}
\draw [->] (2.4,1.8)  --(2.6,2.4) node [above]{$k_y'$};
\draw [->] (3.3,2.4)  --(3.9,2.6) node [right]{$k_x'$};
%
\draw [-] (2,0)--(5,2)-- (5,0)--(2,0);
\draw [->] (3.4,0.7)  --(3.6,1.3) node [above]{$k_y'$};
\draw [->] (3.5,-0.3)node [below]{$a k_y$} --(3.5,0.3);
\draw [->] (4.7,1)  --(5.3,1) node [right]{$b k_x$};
%
\draw [-] (6,2)--(6,3)-- (7,3)--(6,2); 
\draw [->] (6.4,2.5)  --(6.9,2.7) node [right]{$k_x'$};
\draw [->] (6.5,2.8)  --(6.5,3.3) node [above]{$c k_y$};
\draw [->] (5.7,2.5)node [left]{$d k_x$} --(6.2,2.5);
\end{scope}
\end{tikzpicture}
\end{align*}
Due to the conservation of weights we have $a k_y = k'_y + b k_x$ and $d k_x = c k_y + k_x'$, thus we get $(k_x',k_y') = (k_x,k_y) S^{-1}$. By summing up all configurations contributing to $T^{\mathbf{i},\mathbf{j}}_{\mathbf{i}, \mathbf{j}}$, we obtain  $(n_x,n_y) := (||\mathbf{i}||,||\mathbf{j}||) S^{-1}$. 
Note that $x^{||\mathbf{i}||} y^{||\mathbf{j}||} = {x'}^{n_x} {y'}^{n_y}$. 
\end{proof}


